# --- V4.0 U-SCRIPT SETTING: Owner PIN + Lock By Mac + Device Setting ---
# ALL lock data lives INSIDE this script - NO external lock file.
# Only HASHES are stored here (never the PIN or MAC themselves).
LOCK_MAC_ENABLED="0"
LOCK_MAC_HASH=""
LOCK_MAC_PIN_ENABLED="0"
LOCK_MAC_PIN_HASH=""
LOCK_PIN_ENABLED="0"
LOCK_PIN_HASH=""
LOCK_SCRIPT_HASH=""
PINNED_DEVICE=""
# --- V21.1: backup destination - NO prompt at startup ---
# Startup is silent: saved value if it exists, else /media/hdd default.
# The HDD/USB question is asked ONLY inside Backup Manager (ask_backup_root).
if [ -f /etc/u-panel-backup-root.conf ]; then BACKUP_ROOT=$(cat /etc/u-panel-backup-root.conf 2>/dev/null); fi
[ -z "$BACKUP_ROOT" ] && BACKUP_ROOT="/media/hdd"
# V4.26 UI: Style + Color prefs (saved in /etc/u-panel-ui.conf, survive re-encode)
UI_STYLE="${UI_STYLE:-premium}"; UI_COLOR="${UI_COLOR:-gold}"
if [ -f /etc/u-panel-ui.conf ]; then _UIL=$(grep -E "^(UI_STYLE|UI_COLOR)=" /etc/u-panel-ui.conf 2>/dev/null | head -2); [ -n "$_UIL" ] && eval "$_UIL"; fi
case "$UI_STYLE" in premium|classic|compact|minimal) ;; *) UI_STYLE="premium";; esac
case "$UI_COLOR" in gold|blue|green|red|purple|mono) ;; *) UI_COLOR="gold";; esac
# V34 ONE-FOLDER: EVERYTHING the script owns lives in ONE folder: $UPANEL_ROOT/
#   Backups, Caches (Setup/Cross/Offline - separate, NO merge), CrossImage-Backups, Favourite, Custom Plugins,
#   Logs, Reports, Snapshots, Full-Image backups, Downloads - so the user sees ONE folder on the HDD
#   and never deletes the wrong file. Legacy top-level files are MOVED in once (upanel_migrate_to_folder).
UPANEL_ROOT="$BACKUP_ROOT/U-Panel"
mkdir -p "$UPANEL_ROOT" 2>/dev/null
upanel_migrate_to_folder() {
  mkdir -p "$UPANEL_ROOT" 2>/dev/null
  # NEVER move the script that is running right now (or the obfuscated file it came from) - a running script moved mid-run breaks every later save (PIN, MAC lock, ...)
  _SELF_P="$0"; case "$_SELF_P" in /*) ;; *) _SELF_P="$PWD/$_SELF_P";; esac
  _SELF_REAL="$(readlink -f "$_SELF_P" 2>/dev/null || echo "$_SELF_P")"
  _OBF_REAL=""
  if [ -n "$UPANEL_OBFUSCATED_PATH" ]; then _OBF_REAL="$(readlink -f "$UPANEL_OBFUSCATED_PATH" 2>/dev/null || echo "$UPANEL_OBFUSCATED_PATH")"; fi
  for _LEG in "$BACKUP_ROOT"/U-Panel-* "$BACKUP_ROOT"/CrossImage-* "$BACKUP_ROOT"/BeforeSetup-* "$BACKUP_ROOT"/backup-* "$BACKUP_ROOT"/my-backup-* "$BACKUP_ROOT"/GOLD-BACKUP-* "$BACKUP_ROOT"/Unversal* "$BACKUP_ROOT"/*.prev; do
    [ -e "$_LEG" ] || continue
    case "$_LEG" in "$UPANEL_ROOT"|"$UPANEL_ROOT/"*) continue;; esac
    _LEG_REAL="$(readlink -f "$_LEG" 2>/dev/null || echo "$_LEG")"
    [ "$_LEG_REAL" = "$_SELF_REAL" ] && continue
    [ -n "$_OBF_REAL" ] && [ "$_LEG_REAL" = "$_OBF_REAL" ] && continue
    _BASE="$(basename "$_LEG")"
    case "$_BASE" in backup-*|my-backup-*|GOLD-BACKUP-*) mkdir -p "$UPANEL_ROOT/Full-Image" 2>/dev/null; mv "$_LEG" "$UPANEL_ROOT/Full-Image/" 2>/dev/null && echo "[ONE-FOLDER] Moved: $_BASE -> U-Panel/Full-Image/";; *) mv "$_LEG" "$UPANEL_ROOT/" 2>/dev/null && echo "[ONE-FOLDER] Moved: $_BASE -> U-Panel/";; esac
  done
}
ask_backup_root() {
  echo "[BACKUP-ROOT] Current: $BACKUP_ROOT"
  echo "[BACKUP-ROOT] Where to store backups? 1) HDD (/media/hdd)  2) USB (/media/usb)  0) Keep current [$BACKUP_ROOT]: "
  read _br < /dev/tty 2>/dev/null || read _br
  case "$_br" in
    1) BACKUP_ROOT="/media/hdd" ;;
    2) if mount | grep -q " /media/usb "; then BACKUP_ROOT="/media/usb"; else echo "[BACKUP-ROOT] USB not mounted - keeping: $BACKUP_ROOT"; fi ;;
    *) echo "[BACKUP-ROOT] Kept: $BACKUP_ROOT" ;;
  esac
  echo "$BACKUP_ROOT" > /etc/u-panel-backup-root.conf 2>/dev/null
UPANEL_ROOT="$BACKUP_ROOT/U-Panel"; mkdir -p "$UPANEL_ROOT" 2>/dev/null; upanel_migrate_to_folder; BKDIR="$(get_files_backup_dir)"; LOG="$UPANEL_ROOT/Unversal_AllScript_V2-log.txt"; FAV_FILE="$UPANEL_ROOT-Favourite-$BK.conf"
  echo "[BACKUP-ROOT] Saved: $BACKUP_ROOT"
  LOG="$UPANEL_ROOT/Unversal_AllScript_V2-log.txt"

  BKDIR="$(get_files_backup_dir)"
  FAV_FILE="$UPANEL_ROOT-Favourite-$BK.conf"
}
LOG="$UPANEL_ROOT/Unversal_AllScript_V2-log.txt"

# ================= V4.0 - LOCK ENGINE (all data INSIDE this script) =================
# How it works:
#  - Owner PIN is NEVER stored. Only its sha256 hash (LOCK_PIN_HASH).
#  - MAC is NEVER stored. Only its sha256 hash (LOCK_MAC_HASH).
#  - Integrity: LOCK_SCRIPT_HASH = hash of THIS file EXCLUDING the LOCK_SCRIPT_HASH line itself.
#    Any edit changes the hash -> script stops unless the owner enters the PIN -> then it re-seals.
#  - Changing any lock setting rewrites THIS file (tmp + mv, atomic) and restarts the script.
#  - On the OBFUSCATED copy, $0 is a /tmp decoded file: Owner PIN can NEVER be
#    changed there. Device Setting + Lock By Mac CAN be changed there. The MAC
#    lock has its OWN PIN (MAC Lock PIN), set by the user of the copy - every
#    MAC lock change requires it, so a thief who takes the copy cannot rebind
#    the MAC and cannot run it. The loader re-encodes the file on exit so the
#    changes persist. The NORMAL copy is the master.
_lock_self() { _s="$0"; case "$_s" in /*) echo "$_s";; *) echo "$PWD/$_s";; esac; }
_lock_sha() { _s=$(echo -n "$1" | sha256sum 2>/dev/null | cut -d' ' -f1); [ -n "$_s" ] && { echo "$_s"; return; }; echo -n "$1" | md5sum 2>/dev/null | cut -d' ' -f1; }
_lock_hash_file() { grep -v '^LOCK_SCRIPT_HASH=' "$1" 2>/dev/null | sha256sum 2>/dev/null | cut -d' ' -f1; }
_lock_seal_tmp() { _f="$1"; [ -f "$_f" ] || return 1; _h=$(_lock_hash_file "$_f"); sed -i "s|^LOCK_SCRIPT_HASH=\".*\"|LOCK_SCRIPT_HASH=\"$_h\"|" "$_f"; grep -q "^LOCK_SCRIPT_HASH=\"$_h\"$" "$_f" || return 1; }
_lock_commit() {
  _self=$(_lock_self)
  if [ ! -f "$1" ]; then echo "[LOCK] ERROR - could not save (temp file missing) - NOTHING was saved"; return 1; fi
  chmod +x "$1" 2>/dev/null
  if ! mv "$1" "$_self" 2>/dev/null; then echo "[LOCK] ERROR - could not save to $_self - NOTHING was saved"; rm -f "$1"; return 1; fi
  echo "[LOCK] Saved - restarting script..."
  exec bash "$_self"
}
_lock_set_vars() { _self=$(_lock_self); _tmp="${_self}.tmp.$$"; if ! cp "$_self" "$_tmp" 2>/dev/null; then echo "[LOCK] ERROR - could not save (cannot read script file $_self) - NOTHING was saved"; return 1; fi; for _pair in "$@"; do _n="${_pair%%=*}"; _v="${_pair#*=}"; sed -i "s|^$_n=\".*\"|$_n=\"$_v\"|" "$_tmp"; done; _lock_seal_tmp "$_tmp" || { echo "[LOCK] ERROR - could not save (seal failed) - NOTHING was saved"; rm -f "$_tmp"; return 1; }; _lock_commit "$_tmp"; }
_lock_set_vars_unsealed() { _self=$(_lock_self); _tmp="${_self}.tmp.$$"; if ! cp "$_self" "$_tmp" 2>/dev/null; then echo "[LOCK] ERROR - could not save (cannot read script file $_self) - NOTHING was saved"; return 1; fi; for _pair in "$@"; do _n="${_pair%%=*}"; _v="${_pair#*=}"; sed -i "s|^$_n=\".*\"|$_n=\"$_v\"|" "$_tmp"; done; sed -i 's|^LOCK_SCRIPT_HASH=".*"|LOCK_SCRIPT_HASH=""|' "$_tmp"; _lock_commit "$_tmp"; }
_lock_is_temp() { case "$0" in *".upanel_v40_"*) return 0;; *) return 1;; esac; }
_lock_read_mac() { _m=$(cat /sys/class/net/eth0/address 2>/dev/null | tr 'A-Z' 'a-z' | tr -d ' \n'); [ -z "$_m" ] && _m=$(cat /sys/class/net/wlan0/address 2>/dev/null | tr 'A-Z' 'a-z' | tr -d ' \n'); echo "$_m"; }
_read_hidden() { # $1 = var name - read one line WITHOUT echoing (PIN entry), works under bash and sh
  if stty -echo 2>/dev/null; then read "$1" 2>/dev/null; stty echo 2>/dev/null; echo ""; else read "$1" 2>/dev/null; echo ""; fi
}
_lock_pin_verify() {
  if [ "$LOCK_PIN_ENABLED" != "1" ]; then return 1; fi
  _tries=0
  while [ $_tries -lt 3 ]; do
    printf "Enter Owner PIN: "; _read_hidden _p
    _h=$(_lock_sha "$_p"); _p=""
    if [ "$_h" = "$LOCK_PIN_HASH" ]; then echo "[PIN] OK - owner confirmed"; return 0; fi
    _tries=$((_tries+1)); echo "[PIN] Wrong ($((3-_tries)) tries left)"
  done
  echo "[PIN] Blocked - wrong PIN 3 times"; return 1
}
# V4.61 TAMPER-LOCK: if modified -> LOCKED, ask Owner PIN, NEVER auto-accept the edit.
lock_startup_check() {
  _self=$(_lock_self)
  if [ "$LOCK_MAC_ENABLED" = "1" ] && [ -n "$LOCK_MAC_HASH" ]; then
    _mac=$(_lock_read_mac)
    if [ -n "$_mac" ]; then
      _mh=$(_lock_sha "$_mac")
      if [ "$_mh" != "$LOCK_MAC_HASH" ]; then
        echo "=================================================="
        echo "[LOCK] *** SCRIPT IS LOCKED ***"
        echo "[LOCK] This script is locked to another device - MAC mismatch"
        echo "=================================================="
        if [ "$LOCK_PIN_ENABLED" != "1" ]; then echo "[LOCK] No Owner PIN set - cannot verify owner - STOP"; exit 1; fi
        echo "[LOCK] Owner PIN required to unlock ONE run (MAC lock stays ON)"
        if _lock_pin_verify; then echo "[LOCK] Owner confirmed - unlocking THIS RUN ONLY - MAC lock NOT changed"; else echo "[LOCK] STOP - not the owner"; exit 1; fi
      fi
    fi
  fi
  if [ -n "$LOCK_SCRIPT_HASH" ]; then
    _ch=$(_lock_hash_file "$_self")
    if [ "$_ch" != "$LOCK_SCRIPT_HASH" ]; then
      echo "=================================================="
      echo "[LOCK] *** SCRIPT IS LOCKED ***"
      echo "[LOCK] Script was MODIFIED - integrity check FAILED"
      echo "[LOCK] Script will NOT run until Owner PIN is entered"
      echo "=================================================="
      if [ "$LOCK_PIN_ENABLED" != "1" ]; then echo "[LOCK] No Owner PIN set - cannot verify owner - STOP"; echo "[LOCK] Fix: restore the original file, or set Owner PIN BEFORE editing"; exit 1; fi
      if ! _lock_pin_verify; then echo "[LOCK] STOP - not the owner"; exit 1; fi
      echo "[LOCK] Owner confirmed."
      echo "  1) Run ONCE only (do NOT accept the edit - next run will ask PIN again)"
      echo "  2) Accept edit + Re-seal (trust this modified version from now on)"
      echo "  3) Exit / Stay locked"
      printf "Your choice [1/2/3]: "; read _TAMPER_CHOICE
      case "$_TAMPER_CHOICE" in
        1) echo "[LOCK] Running ONCE - modification NOT accepted - seal unchanged"; return 0 ;;
        2) echo "[LOCK] Accepting edit - re-sealing to new version..."; _tmp="${_self}.tmp.$$"; cp "$_self" "$_tmp"; if _lock_seal_tmp "$_tmp"; then _lock_commit "$_tmp"; else echo "[LOCK] Re-seal FAILED - seal line could not be written - NOTHING saved"; echo "[LOCK] This happens when the file was obfuscated / reformatted - the LOCK_SCRIPT_HASH line no longer matches"; echo "[LOCK] Fix: use the clean (non-obfuscated) script file - obfuscation IS a modification, the seal can never accept it"; rm -f "$_tmp"; exit 1; fi ;;
        *) echo "[LOCK] Staying locked - exit"; exit 1 ;;
      esac
    fi
  fi
}
owner_pin_set() {
  if [ "$LOCK_PIN_ENABLED" = "1" ]; then echo "[PIN] Enter CURRENT PIN first:"; _lock_pin_verify || { echo "[PIN] Wrong PIN - PIN not changed"; return 1; }; fi
  printf "New Owner PIN (8+ chars - letters+numbers+symbol - NEVER share it): "; _read_hidden _np
  if [ ${#_np} -lt 8 ]; then echo "[PIN] Too short - use 8+ characters"; return 1; fi
  printf "Repeat PIN: "; _read_hidden _np2
  if [ "$_np" != "$_np2" ]; then echo "[PIN] Mismatch - PIN not changed"; _np=""; _np2=""; return 1; fi
  _h=$(_lock_sha "$_np"); _np=""; _np2=""
  echo "[PIN] Saving PIN as HASH ONLY (PIN itself is never stored) - script will restart"
  _lock_set_vars "LOCK_PIN_HASH=$_h" "LOCK_PIN_ENABLED=1"
}

_lock_pin_verify_mac() {
  if [ "$LOCK_MAC_PIN_ENABLED" != "1" ]; then return 1; fi
  _tries=0
  while [ $_tries -lt 3 ]; do
    printf "Enter MAC Lock PIN: "; _read_hidden _p
    _h=$(_lock_sha "$_p"); _p=""
    if [ "$_h" = "$LOCK_MAC_PIN_HASH" ]; then echo "[MAC-PIN] OK - MAC PIN confirmed"; return 0; fi
    _tries=$((_tries+1)); echo "[MAC-PIN] Wrong ($((3-_tries)) tries left)"
  done
  echo "[MAC-PIN] Blocked - wrong MAC PIN 3 times"; return 1
}

mac_pin_set() {
  if [ "$LOCK_MAC_PIN_ENABLED" = "1" ]; then echo "[MAC-PIN] Enter CURRENT MAC Lock PIN first:"; _lock_pin_verify_mac || { echo "[MAC-PIN] Wrong MAC PIN - MAC PIN not changed"; return 1; }; fi
  printf "New MAC Lock PIN (4+ chars - YOUR OWN password for the MAC lock): "; _read_hidden _np
  if [ ${#_np} -lt 4 ]; then echo "[MAC-PIN] Too short - use 4+ characters"; return 1; fi
  printf "Repeat MAC Lock PIN: "; _read_hidden _np2
  if [ "$_np" != "$_np2" ]; then echo "[MAC-PIN] Mismatch - MAC PIN not changed"; _np=""; _np2=""; return 1; fi
  _h=$(_lock_sha "$_np"); _np=""; _np2=""
  echo "[MAC-PIN] Saving MAC Lock PIN as HASH ONLY (PIN itself is never stored) - script will restart"
  _lock_set_vars "LOCK_MAC_PIN_HASH=$_h" "LOCK_MAC_PIN_ENABLED=1"
}

_mac_lock_auth() {
  if [ "$LOCK_MAC_PIN_ENABLED" = "1" ]; then _lock_pin_verify_mac; return $?; fi
  if [ "$LOCK_PIN_ENABLED" = "1" ]; then _lock_pin_verify; return $?; fi
  return 0
}
owner_pin_menu() {
  if _lock_is_temp; then echo "[U-SCRIPT SETTING] Owner PIN can NEVER be changed on this copy"; printf "Press ENTER... "; read _b; return 0; fi
  while true; do show_banner; menu_top; menu_head "Owner PIN"; menu_sep
    if [ "$LOCK_PIN_ENABLED" = "1" ]; then echo "  Owner PIN: SET (stored as hash only)"; else echo "  Owner PIN: NOT SET"; fi
    menu_item "1) Set / Change Owner PIN"; menu_item "2) Disable Owner PIN (unseals script)"; menu_item "B) Back"; menu_bot
    printf "Your choice: "; read _pm || return 0
    case "$_pm" in
      1) owner_pin_set ;;
      2) if [ "$LOCK_MAC_ENABLED" = "1" ]; then echo "[PIN] Disable MAC Lock FIRST - PIN protects the MAC lock"; printf "Press ENTER... "; read _b; continue; fi
         if [ "$LOCK_PIN_ENABLED" != "1" ]; then echo "[PIN] No PIN set"; printf "Press ENTER... "; read _b; continue; fi
         if _lock_pin_verify; then echo "[PIN] Disabling PIN + removing seal - script will restart"; _lock_set_vars_unsealed "LOCK_PIN_ENABLED=0" "LOCK_PIN_HASH="; else echo "[PIN] Wrong PIN - not disabled"; printf "Press ENTER... "; read _b; fi ;;
      4) mac_pin_set ;;
      b|B) return 0 ;; *) wrong_choice ;; esac
  done
}
