device_pin_confirm() {
  _slug="$1"; _dname=$(_device_model_name "$_slug")
  while true; do show_banner; menu_top; menu_head "Pin ur device"; menu_sep
    echo "  Pin device: $_dname ($_slug)"
    echo "  Detected was: $FULL_MACHINE"
    if [ -n "$PINNED_DEVICE" ]; then echo "  Currently pinned: $PINNED_DEVICE"; fi
    menu_item "1) Yes - Pin this device"; menu_item "B) Back"; menu_bot
    printf "Your choice: "; read _pc || return 0
    case "$_pc" in
      1) echo "[DEVICE] Pinning device: $_slug - script will restart"; _lock_set_vars "PINNED_DEVICE=$_slug" ;;
      b|B) return 0 ;;
      *) wrong_choice ;;
    esac
  done
}
