lock_mac_menu() {
  if _lock_is_temp; then
    while true; do show_banner; menu_top; menu_head "Lock By Mac"; menu_sep
      if [ "$LOCK_MAC_ENABLED" = "1" ]; then echo "  Lock By Mac: ENABLED (bound to this device - MAC stored as hash only)"; else echo "  Lock By Mac: DISABLED - every change here needs YOUR MAC Lock PIN"; fi
      if [ "$LOCK_MAC_PIN_ENABLED" = "1" ]; then echo "  MAC Lock PIN: SET (your own password protects the lock)"; else echo "  MAC Lock PIN: NOT SET - set your own PIN first"; fi
      menu_item "1) Enable Lock (bind to THIS device)"; menu_item "2) Disable Lock"; menu_item "3) Transfer to New Device"; menu_item "4) Set / Change MAC Lock PIN (your own password)"; menu_item "B) Back"; menu_bot
      printf "Your choice: "; read _lm || return 0
      case "$_lm" in
        1) if [ "$LOCK_MAC_ENABLED" = "1" ]; then echo "[MAC-LOCK] Already enabled on this device"; printf "Press ENTER... "; read _b; continue; fi
           if [ -n "$UPANEL_OBFUSCATED_PATH" ] && [ ! -w "$UPANEL_OBFUSCATED_PATH" ]; then echo "[MAC-LOCK] This copy is read-only - lock cannot be saved"; printf "Press ENTER... "; read _b; continue; fi
           if [ "$LOCK_MAC_PIN_ENABLED" != "1" ]; then echo "[MAC-LOCK] Set your own MAC Lock PIN FIRST - it protects the lock"; printf "Press ENTER... "; read _b; mac_pin_set; continue; fi
           _mac_lock_auth || { echo "[MAC-LOCK] Wrong PIN - lock NOT enabled"; printf "Press ENTER... "; read _b; continue; }
           _mac=$(_lock_read_mac); [ -z "$_mac" ] && { echo "[MAC-LOCK] No network MAC found (eth0/wlan0) - connect network and retry"; printf "Press ENTER... "; read _b; continue; }
           _mh=$(_lock_sha "$_mac"); echo "[MAC-LOCK] Binding lock to THIS device (MAC as hash only) - script will restart"; _lock_set_vars "LOCK_MAC_HASH=$_mh" "LOCK_MAC_ENABLED=1" ;;
        2) if [ "$LOCK_MAC_ENABLED" != "1" ]; then echo "[MAC-LOCK] Not enabled"; printf "Press ENTER... "; read _b; continue; fi
           _mac_lock_auth || { echo "[MAC-LOCK] Wrong PIN - lock stays ON"; printf "Press ENTER... "; read _b; continue; }
           echo "[MAC-LOCK] Disabling lock - script will restart"; _lock_set_vars "LOCK_MAC_ENABLED=0" "LOCK_MAC_HASH=" ;;
        3) if [ "$LOCK_MAC_ENABLED" != "1" ]; then echo "[MAC-LOCK] Not enabled - nothing to transfer"; printf "Press ENTER... "; read _b; continue; fi
           _mac_lock_auth || { echo "[MAC-LOCK] Wrong PIN - lock stays ON"; printf "Press ENTER... "; read _b; continue; }
           echo "[MAC-LOCK] Lock released - run the script on the NEW device and Enable Lock there - script will restart"; _lock_set_vars "LOCK_MAC_ENABLED=0" "LOCK_MAC_HASH=" ;;
        4) mac_pin_set ;;
        b|B) return 0 ;; *) wrong_choice ;; esac
    done
  fi
  while true; do show_banner; menu_top; menu_head "Lock By Mac"; menu_sep
    if [ "$LOCK_MAC_ENABLED" = "1" ]; then echo "  Lock By Mac: ENABLED (bound to this device - MAC stored as hash only)"; else echo "  Lock By Mac: DISABLED"; fi
    if [ "$LOCK_MAC_PIN_ENABLED" = "1" ]; then echo "  MAC Lock PIN: SET (your own password protects the lock)"; else echo "  MAC Lock PIN: NOT SET - set your own PIN first"; fi
    menu_item "1) Enable Lock (bind to THIS device)"; menu_item "2) Disable Lock"; menu_item "3) Transfer to New Device"; menu_item "4) Set / Change MAC Lock PIN (your own password)"; menu_item "B) Back"; menu_bot
    printf "Your choice: "; read _lm || return 0
    case "$_lm" in
      1) if [ "$LOCK_MAC_ENABLED" = "1" ]; then echo "[MAC-LOCK] Already enabled on this device"; printf "Press ENTER... "; read _b; continue; fi
         if [ "$LOCK_MAC_PIN_ENABLED" != "1" ] && [ "$LOCK_PIN_ENABLED" != "1" ]; then echo "[MAC-LOCK] Set your own MAC Lock PIN FIRST - it protects the lock"; printf "Press ENTER... "; read _b; mac_pin_set; continue; fi
         _mac_lock_auth || { echo "[MAC-LOCK] Wrong PIN - lock NOT enabled"; printf "Press ENTER... "; read _b; continue; }
         _mac=$(_lock_read_mac); [ -z "$_mac" ] && { echo "[MAC-LOCK] No network MAC found (eth0/wlan0) - connect network and retry"; printf "Press ENTER... "; read _b; continue; }
         _mh=$(_lock_sha "$_mac"); echo "[MAC-LOCK] Binding lock to THIS device (MAC as hash only) - script will restart"; _lock_set_vars "LOCK_MAC_HASH=$_mh" "LOCK_MAC_ENABLED=1" ;;
      2) if [ "$LOCK_MAC_ENABLED" != "1" ]; then echo "[MAC-LOCK] Not enabled"; printf "Press ENTER... "; read _b; continue; fi
         if _mac_lock_auth; then echo "[MAC-LOCK] Disabling lock - script will restart"; _lock_set_vars "LOCK_MAC_ENABLED=0" "LOCK_MAC_HASH="; else echo "[MAC-LOCK] Wrong PIN - lock stays ON"; printf "Press ENTER... "; read _b; fi ;;
      3) if [ "$LOCK_MAC_ENABLED" != "1" ]; then echo "[MAC-LOCK] Not enabled - nothing to transfer"; printf "Press ENTER... "; read _b; continue; fi
         if _mac_lock_auth; then echo "[MAC-LOCK] Lock released - run the script on the NEW device and Enable Lock there - script will restart"; _lock_set_vars "LOCK_MAC_ENABLED=0" "LOCK_MAC_HASH="; else echo "[MAC-LOCK] Wrong PIN - lock stays ON"; printf "Press ENTER... "; read _b; fi ;;
      b|B) return 0 ;; *) wrong_choice ;; esac
  done
}
# ================= V4.28 WEB CONTROL (mobile browser, no telnet) =================
# The web server (Python) is embedded here: web_write_py() writes /tmp/u-panel-web.py,
# web_start() runs it with U_PANEL_PATH=$0 (this copy) + the web PIN.
# LAN only (home WiFi), PIN protected. Destructive actions need a 2nd confirm click in the browser.
web_pin_file() { echo "/etc/u-panel-web-pin.conf"; }
web_bind_file() { echo "/etc/u-panel-web-bind.conf"; }
web_bind_get() { if [ -f "$(web_bind_file)" ]; then head -1 "$(web_bind_file)" 2>/dev/null; else echo "0.0.0.0"; fi; }
web_bind_set() {
  while true; do show_banner; menu_top; menu_head "Panel Listen Address - which network the Panel UI listens on"; menu_sep
    echo "  Current: $(web_bind_get)"
    echo "  LAN IP: $(web_ip)"
    echo "  VPN IP: $(ip -4 addr show tailscale0 2>/dev/null | grep -oE 'inet [0-9.]+' | cut -d' ' -f2; ip -4 addr show wg0 2>/dev/null | grep -oE 'inet [0-9.]+' | cut -d' ' -f2)"
    echo ""
    echo "  0.0.0.0 = All interfaces (LAN + VPN + any network) - default"
    echo "  LAN IP  = only devices on your home WiFi can open it"
    echo "  VPN IP  = only devices on your VPN (Tailscale/WireGuard) can open it - LAN devices CANNOT"
    echo "  127.0.0.1 = only from the receiver itself - nobody on the network can open it"
    echo "  NOTE: a bind address does NOT make the Panel UI reachable from the internet."
    echo "  From outside home you still need a VPN or a tunnel - binding only picks WHICH network listens."
    menu_item "1) All interfaces (0.0.0.0) - default"; menu_item "2) LAN IP only"; menu_item "3) VPN IP only (Tailscale / WireGuard)"; menu_item "4) Localhost only (127.0.0.1)"; menu_item "5) Type a custom IP"; menu_item "B) Back"; menu_bot
    printf "Your choice: "; read _wb || return 0
    case "$_wb" in
      1) echo "0.0.0.0" > "$(web_bind_file)" 2>/dev/null; echo "[WEB] Bind: 0.0.0.0 (all interfaces) - restart Panel Server to apply"; printf "Press ENTER... "; read _b; return 0 ;;
      2) _lip=$(web_ip); [ -n "$_lip" ] && echo "$_lip" > "$(web_bind_file)" 2>/dev/null && echo "[WEB] Bind: $_lip (LAN only) - restart Panel Server to apply" || echo "[WEB] No LAN IP found"; printf "Press ENTER... "; read _b; return 0 ;;
      3) _vip=$(ip -4 addr show tailscale0 2>/dev/null | grep -oE 'inet [0-9.]+' | cut -d' ' -f2); [ -z "$_vip" ] && _vip=$(ip -4 addr show wg0 2>/dev/null | grep -oE 'inet [0-9.]+' | cut -d' ' -f2); if [ -n "$_vip" ]; then echo "$_vip" > "$(web_bind_file)" 2>/dev/null; echo "[WEB] Bind: $_vip (VPN only) - restart Panel Server to apply"; else echo "[WEB] No VPN interface found (no tailscale0 / wg0) - start your VPN first, then pick this again"; fi; printf "Press ENTER... "; read _b; return 0 ;;
      4) echo "127.0.0.1" > "$(web_bind_file)" 2>/dev/null; echo "[WEB] Bind: 127.0.0.1 (localhost only) - restart Panel Server to apply"; printf "Press ENTER... "; read _b; return 0 ;;
      5) printf "Custom IP (example 192.168.1.50): "; read _cip; case "$_cip" in *.*.*.*) echo "$_cip" > "$(web_bind_file)" 2>/dev/null; echo "[WEB] Bind: $_cip - restart Panel Server to apply";; *) echo "[WEB] Not an IP - nothing changed";; esac; printf "Press ENTER... "; read _b; return 0 ;;
      b|B) return 0 ;; *) wrong_choice ;; esac
  done
}
web_pin_get() { if [ -f "$(web_pin_file)" ]; then head -1 "$(web_pin_file)" 2>/dev/null; else echo "1234"; fi; }
web_pin_set() {
  printf "New Panel PIN (4+ chars, used to login from the mobile browser): "; read _wp
  if [ "${#_wp}" -lt 4 ]; then echo "[WEB] Too short - PIN not changed"; printf "Press ENTER... "; read _b; return 0; fi
  echo "$_wp" > "$(web_pin_file)" 2>/dev/null; echo "[WEB] PIN saved - restart Panel Control for it to apply"; printf "Press ENTER... "; read _b
}
web_write_py() {
  cat > /tmp/u-panel-web.py <<'PYEOF'
#!/usr/bin/env python3
# U-Panel Control - mobile browser control for U-Panel (LAN only, PIN protected)
# Start from inside U-Panel: U-Panel Setting -> Panel Control -> Start
# Or standalone: U_PANEL_PATH=/path/to/U-Panel_MOD.sh U_PANEL_WEB_PIN=1234 python3 u-panel-web.py
import os, subprocess, threading, time, uuid, html, glob, shutil, tarfile
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlparse, parse_qs

def _mpeg_crc32(data):
    crc = 0xFFFFFFFF
    for b in data:
        crc ^= b << 24
        for _ in range(8):
            crc = ((crc << 1) ^ 0x04C11DB7) & 0xFFFFFFFF if crc & 0x80000000 else (crc << 1) & 0xFFFFFFFF
    return crc

def _ts_pat_pmt(vpid, apid, vtype, atype, pat_cc, pmt_cc):
    pat_sec = bytearray([0x00, 0xB0, 0x0D, 0x00, 0x01, 0xC1, 0x00, 0x00, 0x00, 0x01, 0xE1, 0x00])
    pat_sec += _mpeg_crc32(bytes(pat_sec)).to_bytes(4, "big")
    pat = bytearray([0x47, 0x40, 0x00, 0x10 | (pat_cc & 0x0F), 0x00]) + pat_sec
    pat += bytes(188 - len(pat))
    streams = []
    if vpid >= 0: streams.append((vtype, vpid))
    if apid >= 0: streams.append((atype, apid))
    pcr = vpid if vpid >= 0 else 0x1FFF
    sec_len = 9 + 5 * len(streams) + 4
    pmt_sec = bytearray([0x02, 0xB0 | ((sec_len >> 8) & 0x0F), sec_len & 0xFF, 0x00, 0x01, 0xC1, 0x00, 0x00,
                         0xE0 | ((pcr >> 8) & 0x1F), pcr & 0xFF, 0xF0, 0x00])
    for (st, pid) in streams:
        pmt_sec += bytes([st, 0xE0 | ((pid >> 8) & 0x1F), pid & 0xFF, 0xF0, 0x00])
    pmt_sec += _mpeg_crc32(bytes(pmt_sec)).to_bytes(4, "big")
    pmt = bytearray([0x47, 0x41, 0x00, 0x10 | (pmt_cc & 0x0F), 0x00]) + pmt_sec
    pmt += bytes(188 - len(pmt))
    return bytes(pat), bytes(pmt)

def _pes_detect(buf):
    es = {}
    for i in range(len(buf) // 188):
        p = buf[i*188:(i+1)*188]
        if p[0] != 0x47: continue
        pid = ((p[1] & 0x1F) << 8) | p[2]
        if pid in (0, 1, 16, 17, 18, 19, 20, 21, 8191): continue
        afc = (p[3] >> 4) & 0x3
        if afc == 2: continue
        off = 4
        if afc == 3:
            off = 5 + p[4]
        if off >= 188: continue
        pay = p[off:]
        if p[1] & 0x40:
            if len(pay) < 9: continue
            if pay[0:3] != b'\x00\x00\x01': continue
            sid = pay[3]
            if pid not in es:
                es[pid] = {"sid": sid, "data": bytearray()}
            pay = pay[9 + pay[8]:]
        if pid in es and pay:
            es[pid]["data"].extend(pay)
    out = {}
    for pid, info in es.items():
        sid = info["sid"]
        d = bytes(info["data"])
        if 0xE0 <= sid <= 0xEF:
            kind = "video"
        elif 0xC0 <= sid <= 0xDF:
            kind = "audio"
        elif sid == 0xBD:
            kind = "private"
        else:
            continue
        st = None
        if kind == "video":
            def _scan(_pat, _val):
                _n = 0; _idx = 0
                while True:
                    _j = d.find(_pat, _idx)
                    if _j < 0: break
                    if _val(_j + len(_pat)): _n += 1
                    _idx = _j + 1
                return _n
            def _v_mpeg2(_pos):
                if _pos + 4 > len(d): return False
                _w = (d[_pos] << 4) | (d[_pos+1] >> 4); _h = ((d[_pos+1] & 0x0F) << 8) | d[_pos+2]
                return 16 <= _w <= 4096 and 16 <= _h <= 4096 and (_w % 2 == 0) and (_h % 2 == 0)
            def _v_h264(_pos):
                if _pos + 3 > len(d): return False
                return d[_pos] in (66, 77, 88, 100, 110, 122, 244, 44, 83, 86, 118, 128, 138, 139, 134, 135, 106) and 10 <= d[_pos+2] <= 62
            def _v_h265(_pos):
                if _pos + 1 > len(d): return False
                return 1 <= (d[_pos] & 0x07) <= 7 and (d[_pos] & 0xF8) == 0
            _n265 = _scan(b'\x00\x00\x00\x01\x40', _v_h265) + _scan(b'\x00\x00\x01\x40', _v_h265)
            _n264 = _scan(b'\x00\x00\x00\x01\x67', _v_h264) + _scan(b'\x00\x00\x01\x67', _v_h264)
            _nmp2 = _scan(b'\x00\x00\x01\xb3', _v_mpeg2)
            if _n265 > 0: st = 0x24
            elif _n264 > 0: st = 0x1B
            elif _nmp2 > 0: st = 0x02
            else: st = 0x1B
        elif kind == "audio":
            head = d[:512]
            found = None
            for j in range(len(head) - 1):
                if head[j] == 0xFF and (head[j+1] & 0xF0) == 0xF0:
                    layer = (head[j+1] >> 1) & 0x3
                    found = 0x0F if layer == 0 else 0x03
                    break
            if found is not None:
                st = found
            elif b'\x0b\x77' in head:
                st = 0x81
            else:
                st = 0x03
        elif kind == "private":
            if b'\x0b\x77' in d[:512]:
                st = 0x81
            else:
                continue
        out[pid] = (kind, st)
    return out

PORT = int(os.environ.get("U_PANEL_WEB_PORT", "8080"))
BIND_FILE = "/etc/u-panel-web-bind.conf"

def get_bind():
    b = os.environ.get("U_PANEL_WEB_BIND", "")
    if b:
        return b.strip()
    try:
        with open(BIND_FILE) as f:
            v = f.read().strip()
            if v:
                return v
    except Exception:
        pass
    return "0.0.0.0"

