PIN_FILE = "/etc/u-panel-web-pin.conf"
LOG_FILE = "/tmp/u-panel-web-last.log"

def get_pin():
    p = os.environ.get("U_PANEL_WEB_PIN", "")
    if p:
        return p.strip()
    try:
        with open(PIN_FILE) as f:
            v = f.read().strip()
            if v:
                return v
    except Exception:
        pass
    return "1234"

def find_script():
    p = os.environ.get("U_PANEL_PATH", "")
    if p and os.path.isfile(p):
        return p
    cands = []
    # FIX V4.67: also match FIXED / V4.x filenames (U-Panel-V4.66-FIXED.sh) - MOD-only patterns returned "" so slot_names() silently failed
    for pat in ("/media/hdd/**/U-Panel*MOD*.sh", "/media/usb/**/U-Panel*MOD*.sh", "/tmp/U-Panel*MOD*.sh", "/media/hdd/U-Panel*.sh", "/media/hdd/**/U-Panel*.sh", "/media/usb/**/U-Panel*.sh", "/tmp/U-Panel*.sh", "/etc/enigma2/U-Panel*.sh", "/etc/enigma2/**/U-Panel*.sh", "/etc/enigma2/U-Script*.sh", "/etc/enigma2/**/U-Script*.sh"): 
        cands += glob.glob(pat, recursive=True)
    if cands:
        cands.sort(key=lambda x: os.path.getmtime(x), reverse=True)
        return cands[0]
    return ""

SCRIPT = find_script()

def resolve_script():
    # V5.91: SCRIPT was resolved ONCE at server start - if the server was started
    # by an old copy (or the script moved to /etc/enigma2), re-find it now.
    # V6.20 FIX (25 Nov): when the server was started from the obfuscated
    # wrapper, SCRIPT was the wrapper's temp file (/tmp/tmp.XXXX) - the wrapper
    # deleted it after the server daemonized (nohup), so jobs ran
    # "sh <deleted file>" -> "No such file or directory" + [EXIT 127].
    # Never return a stale path: return "" so run_job shows SCRIPT NOT FOUND
    # instead of EXIT 127.
    global SCRIPT
    if SCRIPT and os.path.isfile(SCRIPT):
        return SCRIPT
    _found = find_script()
    if _found:
        SCRIPT = _found
        return SCRIPT
    SCRIPT = ""
    return SCRIPT
