def _theme_groups_html(_cur):
    # Premium grouped theme picker: one card per group, grid of theme cards inside.
    # Each theme card shows its REAL background + its REAL button gradient, so what
    # you see is what the whole Panel will look like.
    _out = ""
    for _grp, _keys in WEB_THEME_GROUPS.items():
        _ic, _sub = WEB_THEME_GROUP_META.get(_grp, ("", ""))
        _out += "<div style='margin:16px 0;padding:14px;border-radius:18px;background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.08)'><div style='display:flex;align-items:center;gap:8px;margin-bottom:4px'><span style='font-size:22px'>%s</span><b style='font-size:17px'>%s</b><span style='font-size:12px;opacity:.7'>(%d)</span></div><div class='small' style='margin:0 0 10px'>%s</div><div style='display:grid;grid-template-columns:1fr 1fr;gap:10px'>" % (_ic, html.escape(_grp), len(_keys), html.escape(_sub))
        for _tk in _keys:
            _lbl, _c1, _c2, _bg, _fg, _tiles = WEB_THEMES[_tk]
            _is_cur = (_tk == _cur)
            _border = "2px solid %s" % _c2 if _is_cur else "1px solid rgba(255,255,255,.12)"
            _badge = "<span style='display:inline-block;padding:2px 8px;border-radius:99px;background:linear-gradient(135deg,%s,%s);color:#fff;font-size:11px;font-weight:700'>\u2713 Current</span>" % (_c1, _c2) if _is_cur else ""
            _new = "<span style='display:inline-block;padding:2px 8px;border-radius:99px;background:#F59E0B;color:#000;font-size:11px;font-weight:700'>NEW</span> " if _tk in ("black", "navy") else ""
            _out += "<a href='/setting/apply?theme=%s' style='display:block;padding:12px;border-radius:14px;background:%s;color:%s;border:%s;box-shadow:inset 0 1px 0 rgba(255,255,255,.25),0 6px 16px rgba(0,0,0,.35)'><div style='display:flex;justify-content:space-between;align-items:center;gap:6px'>%s%s</div><b style='display:block;margin:8px 0 2px;font-size:15px'>%s</b><span style='display:block;height:22px;border-radius:8px;background:linear-gradient(135deg,%s,%s);box-shadow:inset 0 1px 0 rgba(255,255,255,.4)'></span><span class='small' style='display:block;margin-top:6px;opacity:.75'>Buttons \u2192 Background</span></a>" % (html.escape(_tk), _bg, _fg, _border, _new, _badge, html.escape(_lbl), _c1, _c2)
        _out += "</div></div>"
    return _out
def _web_theme_current():
    try:
        with open("/etc/u-panel-web-theme.conf") as _f:
            for _ln in _f:
                if _ln.startswith("WEB_THEME="):
                    _tv = _ln.split("=", 1)[1].strip()
                    if _tv == "uscript": _tv = "upanel"
                    if _tv in WEB_THEMES: return _tv
    except Exception:
        pass
    return "upanel"
def _theme_vals():
    _tv = _web_theme_current()
    _lbl, _c1, _c2, _bg, _fg, _tiles = WEB_THEMES[_tv]
    def _hx(_h):
        _h = _h.lstrip("#")
        return tuple(int(_h[k:k+2], 16) for k in (0, 2, 4))
    def _mix(_a, _b, _t):
        _ra, _ga, _ba = _hx(_a); _rb, _gb, _bb = _hx(_b)
        return "#%02x%02x%02x" % (round(_ra + (_rb - _ra) * _t), round(_ga + (_gb - _ga) * _t), round(_ba + (_bb - _ba) * _t))
    _dark = sum(_hx(_bg)) < 380
    _card = _mix(_bg, "#ffffff", 0.08) if _dark else _mix(_bg, "#000000", 0.06)
    _lc2 = _mix(_c2, "#ffffff", 0.25)
    _dc1 = _mix(_c1, "#000000", 0.25)
    return _tv, _c1, _c2, _bg, _fg, _card, _lc2, _dc1, _dark, _hx(_c2)

def _web_theme_css():
    _tv = _web_theme_current()
    _lbl, _c1, _c2, _bg, _fg, _tiles = WEB_THEMES[_tv]
    def _hx(_h):
        _h = _h.lstrip("#")
        return tuple(int(_h[k:k+2], 16) for k in (0, 2, 4))
    def _mix(_a, _b, _t):
        _ra, _ga, _ba = _hx(_a); _rb, _gb, _bb = _hx(_b)
        return "#%02x%02x%02x" % (round(_ra + (_rb - _ra) * _t), round(_ga + (_gb - _ga) * _t), round(_ba + (_bb - _ba) * _t))
    _dark = sum(_hx(_bg)) < 380
    _card = _mix(_bg, "#ffffff", 0.08) if _dark else _mix(_bg, "#000000", 0.06)
    _small = _mix(_fg, _bg, 0.4)
    _lc2 = _mix(_c2, "#ffffff", 0.25)
    _dc1 = _mix(_c1, "#000000", 0.25)
    _tcol = "#ffffff" if _dark else _fg
    _css = "<style>body{background:%s;color:%s}h1{color:%s}.sec{color:%s}.small{color:%s}" % (_bg, _fg, _fg, _c2, _small)
    # BLACK GLOSSY for ALL buttons: the theme gradient used to repaint every
    # button/card purple here and beat PREMIUM_CSS (this CSS comes later) - that
    # is why the menus stayed purple while the dock / remote / Live TV buttons
    # (styled per-page, later) already went black glossy. Fill is now the same
    # black glossy as the dock, the theme colour survives as border + glow.
    _gloss = "background:linear-gradient(180deg,#3d3d3d,#1a1a1a 42%%,#000);color:#fff;border:1px solid %s66;box-shadow:inset 0 1px 0 rgba(255,255,255,.4),inset 0 -8px 12px rgba(0,0,0,.65),0 4px 12px %s55"
    _gloss_wide = "background:linear-gradient(180deg,#3d3d3d,#1a1a1a 42%%,#000);color:#fff;border:1px solid %s66;box-shadow:inset 0 1px 0 rgba(255,255,255,.4),inset 0 -8px 12px rgba(0,0,0,.65),0 0 24px %s,0 8px 24px rgba(0,0,0,.45)"
    _css += "a,button{" + _gloss % (_c2, _c2) + "}"
    _css += "a.primary,button.primary{" + _gloss % (_c2, _c2) + "}"
    _css += "a.gold,button.gold{" + _gloss % (_lc2, _lc2) + "}"
    _css += "a.danger,button.danger{" + _gloss % (_dc1, _c1) + "}"
    _css += "a.green,button.green{" + _gloss % (_lc2, _lc2) + "}"
    _css += "a.signal,button.signal{" + _gloss % (_c2, _c2) + "}"
    # Every <pre> (job output, Last Log, server configs) must wrap on a phone
    # screen - a bare <pre> lets long lines run off the right edge (the Done
    # job page had no wrapping at all, unlike the Running page).
    _css += "pre{white-space:pre-wrap;word-break:break-word;overflow-wrap:anywhere;max-width:100%;box-sizing:border-box}"
    _css += ".card{background:%s;border-color:%s}.pill{background:%s;color:%s}.pill.on{background:linear-gradient(135deg,%s,%s);color:#fff}.sigbar{background:%s}" % (_card, _c2, _card, _fg, _c1, _c2, _c1)
    _css += ".banner .t{color:%s;text-shadow:0 0 24px %s}.banner .line{background:linear-gradient(90deg,%s,%s)}.banner .sub{color:%s}" % (_tcol, _c2, _c1, _c2, _c2)
    _css += ".up-head{background:%s}.up-logo{color:%s;text-shadow:0 0 16px %s}.up-online{background:%s;border-color:%s;color:%s}.up-tabs{background:%s}.up-tabs a{color:%s}.up-tabs a.on{color:%s}" % (_bg, _tcol, _c2, _card, _c2, _fg, _bg, _small, _c2)
    _css += ".badge-new{background:linear-gradient(135deg,%s,%s);color:#fff}" % (_c1, _c2)
    _css += "select,input{background:%s;color:%s;border-color:%s}" % (_card, _fg, _c2)
    _css += ".grid2 a.wide{" + _gloss_wide % (_c2, _c2) + "}"
    # ONE colour for ALL buttons: every tile + hero uses the same black glossy
    # (theme colour as border + glow), so the whole screen stays harmonious when
    # the theme changes. Per-class rules are kept only so they beat PREMIUM_CSS
    # (same specificity, theme CSS comes later).
    _css += ".grid2 a{" + _gloss % (_c2, _c2) + "}"
    _css += ".grid2 a .ic{border-color:%s88;box-shadow:0 0 10px %s55}" % (_c2, _c2)
    for _cls in ["dv", "dr", "dg", "dp", "dc", "dt", "dl"]:
        _css += ".grid2 a.%s{" % _cls + _gloss % (_c2, _c2) + "}"
        _css += ".grid2 a.wide.%s{" % _cls + _gloss_wide % (_c2, _c2) + "}"
    _css += "</style>"
    return _css

