def _panel_lang_current():
    try:
        with open("/etc/u-panel-lang.conf") as _f:
            for _ln in _f:
                if _ln.startswith("PANEL_LANG="):
                    _sv = _ln.split("=", 1)[1].strip().lower()
                    if _sv in PANEL_LANGS: return _sv
    except Exception:
        pass
    return "en"
def _tr(_key):
    _lang = _panel_lang_current()
    _row = UI_TEXT.get(_key)
    if not _row: return _key
    _idx = {"en": 0, "ar": 1, "fr": 2}.get(_lang, 0)
    return _row[_idx] or _row[0]

