def _panel_font_current():
    try:
        with open("/etc/u-panel-web-font.conf") as _f:
            for _ln in _f:
                if _ln.startswith("PANEL_FONT="):
                    _fv = _ln.split("=", 1)[1].strip()
                    if _fv in PANEL_FONTS: return _fv
    except Exception:
        pass
    return "default"
def _panel_font_css():
    _fv = _panel_font_current()
    if _fv == "default": return ""
    _lbl, _stack = PANEL_FONTS[_fv]
    return "<style>body,button,input,select,a{font-family:%s}</style>" % _stack

