    st = SETUP_STATE
    steps = ["1) Packages", "2) Plugins", "3) Restore Files", "4) BootLogo Auto", "5) Channel List", "6) Finish"]
    head = "<h1>Setup your Enigma - Wizard</h1><p class='small'>" + " &gt; ".join(steps) + "</p>"
    summ = "<div class='card'><b>Your choices so far:</b><br><span class='small'>Plugins: %s<br>Restore: %s<br>Channel: %s</span></div>" % (html.escape(st.get("plugins", "-") or "-"), html.escape(st.get("restore", "-") or "-"), html.escape(st.get("channel", "-") or "-"))
    if step == 1:
        body = head + "<div class='card'><b>Step 1 - Packages + Safety Snapshot</b><br><span class='small'>Takes a safety snapshot (BeforeSetup) and installs system packages. No choice here - press Start.</span></div>" + summ + "<form method='post' action='/setup-run?step=1'><button>Start - Step 1: Packages</button></form><a href='/setup?step=1&reset=1'>Start over - Clear my choices</a><a href='/panel'>Back to Panel Menu</a>"
    elif step == 2:
        cats = ""
        for _cid, _title, _nums in CAT_WEB:
            cats += "<div class='card'><b>%s</b><br>" % html.escape(_title)
            for _n in _nums:
                _nm = PLUGINS_WEB[_n-1] if 1 <= _n <= len(PLUGINS_WEB) else ("#%d" % _n)
                _chk = " checked" if str(_n) in (" " + st.get("plugins", "") + " ").split() else ""
                cats += "<label><input type='checkbox' name='plugin' value='%d'%s> %s</label><br>" % (_n, _chk, html.escape(_nm))
            cats += "</div>"
        body = head + summ + "<form method='post' action='/setup-run?step=2'><div class='card'><b>Step 2 - Pick Plugins</b><br><span class='small'>Tick what you want - same plugin grouping as in the Terminal.</span></div>" + cats + "<button>Install Selected Plugins</button></form><a href='/setup?step=1'>Back to Step 1</a>"
    elif step == 3:
        opts = [("all", "Files - All (full files restore)"), ("channels", "Channels Only (bouquets+lamedb)"), ("skin", "Skin"), ("emu", "Emu (Oscam config + binaries)"), ("keys", "Keys (autosub/groqapi)"), ("network", "Network (hostname/resolv/interfaces)"), ("bootlogo", "BootLogo Auto")]
        boxes = ""
        _sel = st.get("restore", "").split()
        for _code, _desc in opts:
            _chk = " checked" if _code in _sel else ""
            boxes += "<label><input type='checkbox' name='restore' value='%s'%s> %s</label><br>" % (_code, _chk, html.escape(_desc))
        body = head + summ + "<form method='post' action='/setup-run?step=3'><div class='card'><b>Step 3 - Restore Files</b><br><span class='small'>From your backup. If there is no backup, this step is skipped automatically.</span><br>" + boxes + "</div><button>Restore Selected Files</button></form><a href='/setup?step=2'>Back to Step 2</a>"
    elif step == 4:
        body = head + summ + "<div class='card'><b>Step 4 - BootLogo Auto</b><br><span class='small'>Installs the right logo for your image automatically - no choice.</span></div><form method='post' action='/setup-run?step=4'><button>Install BootLogo Auto</button></form><a href='/setup?step=3'>Back to Step 3</a>"
    elif step == 5:
        chans = [("emil", "Emil Nabil"), ("mnasr", "Mnasr"), ("khaled", "Khaled"), ("hazem", "Hazem Wahba"), ("none", "No - keep current channel list")]
        radios = ""
        for _code, _desc in chans:
            _chk = " checked" if st.get("channel", "none") == _code else ""
            radios += "<label><input type='radio' name='channel' value='%s'%s> %s</label><br>" % (_code, _chk, html.escape(_desc))
        body = head + summ + "<form method='post' action='/setup-run?step=5'><div class='card'><b>Step 5 - Channel List</b><br><span class='small'>Enigma will stop and restart after installing the list.</span><br>" + radios + "</div><button>Install Channel List</button></form><a href='/setup?step=4'>Back to Step 4</a>"
    else:
        body = head + summ + "<form method='post' action='/setup-run?step=6'><div class='card'><b>Step 6 - Finish and Save</b><br><span class='small'>Saves your choices in Ur Favourite Setup.</span><br><label><input type='radio' name='fullbackup' value='y'> Make a Full Image Backup now</label><br><label><input type='radio' name='fullbackup' value='n' checked> No - skip the backup</label></div><button>Finish and Save the Favourite</button></form><a href='/setup?step=5'>Back to Step 5</a>"
    return body


