def _script_vars():
    _v = {}
    try:
        for _ln in open(SCRIPT or ""):
            _ln = _ln.strip()
            if "=" in _ln and not _ln.startswith("#"):
                _k, _val = _ln.split("=", 1)
                _v[_k.strip()] = _val.strip().strip('"')
    except Exception:
        pass
    return _v

def _us_roots():
    import glob as _g
    _r = [p for p in sorted(_g.glob("/media/hdd/U-Panel*") + _g.glob("/media/usb/U-Panel*") + _g.glob("/media/mmc/U-Panel*")) if os.path.isdir(p)]
    return _r or ["/media/hdd/U-Panel"]

def _backup_dirs(sub):
    import glob as _g
    out = []
    for _r in _us_roots():
        out += sorted(_g.glob(os.path.join(_r, sub)))
    return out

def _servers_entries():
    out = []
    try:
        for _ln in open("/etc/CCcam.cfg"):
            if _ln.startswith("C:"):
                _p = _ln.split()
                out.append(("cccam", "%s:%s %s ****" % (_p[1], _p[2], _p[3]) if len(_p) > 3 else _ln.strip()))
    except Exception: pass
    try:
        for _ln in open("/etc/tuxbox/config/newcamd.list"):
            if _ln.startswith("CWS"):
                _p = _ln.replace("=", " ").split()
                out.append(("mgcamd", "%s:%s %s ****" % (_p[2], _p[3], _p[4]) if len(_p) > 4 else _ln.strip()))
    except Exception: pass
    return out

def _iptv_entries():
    out = []
    _d = ""
    for _r in _us_roots():
        if os.path.isdir(os.path.join(_r, "MyIPTV")): _d = os.path.join(_r, "MyIPTV"); break
    if not _d: return out
    try:
        for _ln in open(os.path.join(_d, "servers.txt")):
            _ln = _ln.strip()
            if _ln: out.append(("server", _ln.split("|")[0]))
    except Exception: pass
    import glob as _g
    for _f in sorted(_g.glob(os.path.join(_d, "*.m3u"))):
        out.append(("m3u", os.path.basename(_f)))
    return out

def _mylinks_entries():
    out = []
    _f = ""
    for _r in _us_roots():
        _c = os.path.join(_r, "user_image_links.conf")
        if os.path.isfile(_c): _f = _c; break
    if not _f: return out
    try:
        for _ln in open(_f):
            _ln = _ln.strip()
            if _ln and not _ln.startswith("#"):
                _p = _ln.split("|")
                out.append("%s / %s - %s (%s)" % (_p[0], _p[1], _p[3], _p[2]) if len(_p) > 3 else _ln)
    except Exception: pass
    return out

def _multiboot_backups():
    import glob as _g
    out = []
    for _p in ("/media/hdd", "/media/usb", "/media/mmc"):
        out += _g.glob(os.path.join(_p, "U-Panel-Backup-*"))
    out = [p for p in out if os.path.isdir(p)]
    out.sort(key=lambda p: os.path.getmtime(p), reverse=True)
    return out

def shell_out(cmd):
    try:
        return subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=10).stdout.strip()
    except Exception as e:
        return "err: %s" % e


def _clean_image_version(_img):
    _kv = {}
    for _p in (_img or "").split():
        if "=" in _p:
            _k, _v = _p.split("=", 1)
            _kv[_k.strip().lower()] = _v.strip()
    if not _kv:
        return (_img or "").strip() or "-"
    _names = {"openatv": "OpenATV", "openpli": "OpenPLi", "openvix": "OpenViX", "openbh": "OpenBH", "egami": "Egami", "pure2": "PurE2", "openspa": "OpenSPA", "openhdf": "OpenHDF"}
    _d = _names.get(_kv.get("distro", "").lower(), _kv.get("distro", ""))
    _ver = _kv.get("imageversion", "").replace("~", " ").title()
    _out = " ".join(x for x in (_d, _ver, _kv.get("machine", "")) if x)
    return _out or (_img or "").strip() or "-"

def _clean_disk_line(_disk):
    _parts = (_disk or "").split()
    if len(_parts) >= 4:
        return "%s total - %s free" % (_parts[1], _parts[3])
    return (_disk or "").strip() or "-"

def _menu_label(_s):
    import re as _re
    _s = _re.sub(r"^[A-Za-z0-9]+\)\s*", "", _s)
    _s = _re.sub(r"\s*\(\d+\)$", "", _s)
    return _s

def status_info():
    box = shell_out("cat /proc/stb/info/model 2>/dev/null; cat /etc/hostname 2>/dev/null")
    img = shell_out("grep -E '^(distro|imageversion|machine)=' /etc/image-version 2>/dev/null | tr '\\n' ' '")
    disk = shell_out("df -h /media/hdd 2>/dev/null | tail -1")
    bk = shell_out("ls -dt /media/hdd/U-Panel*/ 2>/dev/null | head -3 | tr '\\n' ' '; ls /media/hdd/U-Panel/ 2>/dev/null | wc -l")
    return box, img, disk, bk

def _strip_ansi(s):
    import re as _re
    s = _re.sub(r"\x1b\[[0-9;?]*[A-Za-z]", "", s)
    s = _re.sub(r"\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)", "", s)
    s = _re.sub(r"\x1b[()#][0-9A-Z]", "", s)
    s = _re.sub(r"\x1b[=>]", "", s)
    return s.replace("\r\n", "\n").replace("\r", "\n")

def _run_live(job, cmd, shell=False, input_data="", timeout=3600, env=None):
    # Stream a long command: every line goes to job["output"] AS IT ARRIVES,
    # so the /job page shows live progress instead of a blank "Running..." page.
    import os as _os2, select as _sel2
    buf = ""
    try:
        p = subprocess.Popen(cmd, shell=shell, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=False, bufsize=0, env=env)
        try:
            if input_data:
                p.stdin.write(input_data.encode("utf-8", "ignore"))
            p.stdin.close()
        except Exception:
            pass
        _t0 = time.time()
        _chunk = ""
        while True:
            _r, _, _ = _sel2.select([p.stdout], [], [], 5)
            if not _r:
                if p.poll() is not None:
                    break
                if time.time() - _t0 > timeout:
                    try: p.kill()
                    except Exception: pass
                    buf += chr(10) + "[TIMEOUT after %ss]" % timeout + chr(10)
                    job["output"] = buf
                    break
                continue
            _data = _os2.read(p.stdout.fileno(), 65536)
            if not _data:
                break
            _chunk += _data.decode("utf-8", "ignore")
            while chr(10) in _chunk:
                _ln, _chunk = _chunk.split(chr(10), 1)
                buf += _strip_ansi(_ln + chr(10))
                if len(buf) > 60000:
                    buf = buf[-60000:]
                job["output"] = buf
        if _chunk:
            buf += _strip_ansi(_chunk)
            job["output"] = buf
        rc = p.wait()
        buf += chr(10) + "[EXIT %s]" % rc + chr(10)
        job["output"] = buf
        return buf
    except Exception as e:
        buf += chr(10) + "ERROR: %s" % e + chr(10)
        job["output"] = buf
        return buf


def run_job(job):
    job["status"] = "running"
    job["started"] = time.strftime("%H:%M:%S")
    job["started_ts"] = time.time()
    job["output"] = "Starting %s...\n" % job.get("action", "")
    out = ""
    # V5.91: never run "sh <missing file>" - fail with a clear message instead of EXIT 127
    if not resolve_script():
        job["output"] = ("SCRIPT NOT FOUND - the Panel server cannot find the U-Panel script file.\n"
                         "Run the script once from its real location, e.g.\n"
                         "  sh /etc/enigma2/U-Panel-V6.25.sh\n"
                         "then reload this page. No command was executed.\n")
        job["status"] = "done"
        return
    try:
        if job.get("kind") == "shell":
            out = _run_live(job, job["shell"], shell=True)
        elif job.get("kind") == "shell-argv":
            out = _run_live(job, ["sh", SCRIPT] + list(job.get("argv", [])), input_data=job.get("input", ""))
        elif job.get("kind") == "mac-lock":
            out = _run_live(job, ["sh", SCRIPT, "--web-mac-lock", job.get("mac_action", "")], input_data=job.get("input", ""))
        elif job.get("kind") == "web-pin":
            pr = subprocess.run(["sh", SCRIPT, "--web-webpin"], input=job.get("pw", "") + chr(10) + chr(10), capture_output=True, text=True, timeout=60)
            out = (pr.stdout or "") + (pr.stderr or "") + chr(10) + "[EXIT %s]" % pr.returncode + chr(10)
        elif job.get("kind") == "web-bind":
            pr = subprocess.run(["sh", SCRIPT, "--web-bind", job.get("bind_value", "")], input="", capture_output=True, text=True, timeout=60)
            out = (pr.stdout or "") + (pr.stderr or "") + chr(10) + "[EXIT %s]" % pr.returncode + chr(10)
        elif job.get("kind") == "change-password":
            _pw = job.get("pw", "")
            pr = subprocess.run(["passwd", "root"], input=_pw + chr(10) + _pw + chr(10), capture_output=True, text=True, timeout=60)
            out = (pr.stdout or "") + (pr.stderr or "") + chr(10) + "[EXIT %s]" % pr.returncode + chr(10)
            out += "Password changed - No Restart" + chr(10) if pr.returncode == 0 else "Password change FAILED" + chr(10)
        elif job.get("kind") == "download-image":
            import urllib.request as _u
            url = job["url"]
            dest = os.path.join(downloads_dir(), os.path.basename(url.split("?")[0]) or "downloaded-image.zip")
            os.makedirs(downloads_dir(), exist_ok=True)
            def _hook(_bn, _bs, _tot):
                _done = _bn * _bs
                job["output"] = "Downloading... %.1f MB / %.1f MB" % (_done/1048576.0, _tot/1048576.0) + chr(10) if _tot > 0 else "Downloading... %.1f MB" % (_done/1048576.0) + chr(10)
            _u.urlretrieve(url, dest, _hook)
            job["file"] = dest
            out = "Downloaded to: %s\nSize: %d bytes\n" % (dest, os.path.getsize(dest))
        elif job.get("kind") == "flash":
            _env = dict(os.environ)
            if job.get("flash_path"): _env["U_PANEL_FLASH_PATH"] = job["flash_path"]
            out = _run_live(job, ["sh", SCRIPT, "--web-flash"], input_data=job.get("input", ""), env=_env)
        elif job["action"] == "reboot":
            out = "Rebooting receiver...\n"; job["output"] = out
            subprocess.Popen(["/sbin/reboot"])
        elif job["action"] == "enigma-restart":
            out = "Restarting Enigma: init 4, wait, init 3...\n"; job["output"] = out
            subprocess.run("(/sbin/init 4 || /usr/sbin/init 4 || /bin/init 4 || true); sleep 3; (/sbin/init 3 || /usr/sbin/init 3 || /bin/init 3 || true)", shell=True, timeout=60)
            out += "Enigma restart command sent. Wait ~30 seconds for the picture to come back.\n"
        else:
            args = ACTIONS[job["action"]][2]
            cmd = ["sh", SCRIPT] + args
            out = _run_live(job, cmd, input_data=job.get("input", chr(10)*5))
    except Exception as e:
        out = "ERROR: %s\n" % e
    job["output"] = _strip_ansi(out)
    if job.get("action") in ("smart-restore", "flash-image", "download-image"):
        try: telegram_send_msg("U-Panel: %s finished\n%s" % (ACTIONS.get(job.get("action"), ("",))[0], out[-500:]))
        except Exception: pass
    job["status"] = "done"
    try:
        with open(LOG_FILE, "w") as f:
            f.write(out)
    except Exception:
        pass


def enigma_stop():
    subprocess.run("(/sbin/init 4 || /usr/sbin/init 4 || /bin/init 4 || true); sleep 3", shell=True, timeout=30)
def enigma_start():
    subprocess.run("(/sbin/init 3 || /usr/sbin/init 3 || /bin/init 3 || true); sleep 3", shell=True, timeout=30)

def bouquet_list():
    out = []
    try:
        with open(os.path.join(ENIGMA2_DIR, "bouquets.tv")) as f:
            blines = f.read().splitlines()
    except Exception:
        return out
    for i, ln in enumerate(blines):
        if 'FROM BOUQUET "' in ln:
            fn = ln.split('FROM BOUQUET "')[1].split('"')[0]
            nm = ""
            if i + 1 < len(blines) and blines[i + 1].startswith("#DESCRIPTION "):
                nm = blines[i + 1][len("#DESCRIPTION "):]
            if not nm:
                try:
                    with open(os.path.join(ENIGMA2_DIR, fn)) as bf:
                        for bline in bf.read().splitlines():
                            if bline.startswith("#NAME "):
                                nm = bline[len("#NAME "):]; break
                except Exception: pass
            out.append((fn, nm or fn))
    return out

def bouquet_channels(fn):
    chans = []
    try:
        with open(os.path.join(ENIGMA2_DIR, fn)) as f:
            clines = f.read().splitlines()
    except Exception:
        return chans
    i = 0
    while i < len(clines):
        if clines[i].startswith("#SERVICE "):
            nm = ""
            if i + 1 < len(clines) and clines[i + 1].startswith("#DESCRIPTION"):
                nm = clines[i + 1][len("#DESCRIPTION"):].lstrip(" :").strip()
            chans.append((i, clines[i], nm))
            i += 2 if nm else 1
        else:
            i += 1
    return chans

def channel_name_by_ref(ref):
    ref = ref.strip()
    for fn2, _bn in bouquet_list():
        for _ln, rf, nm in bouquet_channels(fn2):
            if rf[len("#SERVICE "):].strip() == ref:
                return display_name(rf, nm)
    return lamedb_lookup(ref) or "Unnamed channel"

def lamedb_names():
    out = {}
    for fname in ("lamedb5", "lamedb"):
        try:
            with open(os.path.join(ENIGMA2_DIR, fname)) as f: llines = f.read().splitlines()
        except Exception: continue
        if fname == "lamedb5":
            # one line per service: s:SID:NS:TSID:ONID:STYPE:0:0,"Name",p:Provider...
            for ln in llines:
                if not ln.startswith("s:"): continue
                fields = ln[2:].split(":")
                if len(fields) < 5: continue
                try: key = (int(fields[0], 16), int(fields[2], 16), int(fields[3], 16), int(fields[1], 16))
                except Exception: continue
                q1 = ln.find('"'); q2 = ln.find('"', q1 + 1) if q1 >= 0 else -1
                if q1 >= 0 and q2 > q1: out.setdefault(key, ln[q1 + 1:q2])
        else:
            # three lines per service: SID:NS:TSID:ONID:... / Name / p:Provider
            in_services = False
            for i, ln in enumerate(llines):
                if ln.strip() == "services": in_services = True; continue
                if ln.strip() == "end" and in_services: break
                if not in_services or i + 1 >= len(llines): continue
                fields = ln.split(":")
                if len(fields) < 4: continue
                try: key = (int(fields[0], 16), int(fields[2], 16), int(fields[3], 16), int(fields[1], 16))
                except Exception: continue
                name = llines[i + 1].strip()
                if name and not name.startswith("p:"): out.setdefault(key, name)
    return out

def lamedb_lookup(ref, names=None):
    if ref.startswith("#SERVICE "): ref = ref[len("#SERVICE "):]
    if names is None: names = lamedb_names()
    parts = ref.strip().split(":")
    if len(parts) < 7: return ""
    try: key = (int(parts[3], 16), int(parts[4], 16), int(parts[5], 16), int(parts[6], 16))
    except Exception: return ""
    return names.get(key, "")

def iptv_name_from_ref(ref):
    if ref.startswith("#SERVICE "): ref = ref[len("#SERVICE "):]
    import urllib.parse as _p
    parts = ref.strip().split(":", 10)
    if len(parts) < 11: return ""
    url = _p.unquote(parts[10]).strip()
    if not url: return ""
    url = url.split("?")[0].split("#")[0].rstrip("/")
    seg = _p.unquote(url.rsplit("/", 1)[-1])
    for ext in (".m3u8", ".ts", ".mp4", ".mkv", ".m3u"):
        if seg.lower().endswith(ext): seg = seg[:-len(ext)]; break
    seg = seg.replace("_", " ").replace("-", " ").replace(".", " ").replace("+", " ")
    return " ".join(seg.split())

def display_name(ref, bouquet_nm, names=None):
    return bouquet_nm or lamedb_lookup(ref, names) or iptv_name_from_ref(ref) or "Unnamed channel"

def backup_bouquet_file(fn):
    src = os.path.join(ENIGMA2_DIR, fn)
    dst = src + ".webbak-" + time.strftime("%Y%m%d-%H%M%S")
    try:
        shutil.copy2(src, dst)
    except Exception:
        pass
    return dst

def downloads_dir():
    if DOWNLOADS_DIR:
        return DOWNLOADS_DIR
    for cand in ("/media/hdd/U-Panel/Downloads", "/media/usb/U-Panel/Downloads", "/media/hdd/Downloads"):
        if os.path.isdir(cand):
            return cand
    return "/tmp"

def image_entries():
    out = []
    seen = set()
    for z in sorted(glob.glob(os.path.join(downloads_dir(), "*.zip"))):
        if z not in seen:
            seen.add(z); out.append(z)
    for root in BACKUP_ROOTS:
        for z in sorted(glob.glob(os.path.join(root, "*.zip")) + glob.glob(os.path.join(root, "*/*.zip"))):
            if z not in seen:
                seen.add(z); out.append(z)
    return out

def flash_image_list():
    out = []
    skip = {"timeshift", "movie", "movies", "lost+found", "picon"}
    for root in FLASH_SCAN_ROOTS:
        if not os.path.isdir(root):
            continue
        for d in sorted(glob.glob(os.path.join(root, "*/"))):
            bn = os.path.basename(d.rstrip("/"))
            if bn.startswith("U-Panel-Backup-") or bn in skip or bn.startswith("EPG"):
                continue
            out.append(("DIR", d))
    for root in FLASH_SCAN_ROOTS:
        for z in sorted(glob.glob(os.path.join(root, "*.zip"))):
            out.append(("ZIP", z))
    for z in sorted(glob.glob(os.path.join(downloads_dir(), "*.zip"))):
        if ("ZIP", z) not in out:
            out.append(("ZIP", z))
    for z in image_entries():
        if ("ZIP", z) not in out:
            out.append(("ZIP", z))
    return out

def multiboot_slots():
    # FIX V4.64: mirror shell upanel_slots(): slots = STARTUP_LINUX_N / STARTUP_N files, not len(STARTUP*) count
    # V6.20: ALSO scan blkid LABEL=linuxN - an Empty external slot has NO STARTUP
    # file (so Recovery hides it), but the Panel must still list it for flashing.
    try:
        import re as _re2
        slots = set()
        for f in os.listdir("/boot"):
            m = _re2.match(r"STARTUP(?:_LINUX)?_(\d+)$", f)
            if m: slots.add(int(m.group(1)))
        try:
            import subprocess as _sp2
            _out = _sp2.check_output(["blkid"], text=True, timeout=10)
            for m in _re2.finditer(r'LABEL="linux(\d+)"', _out):
                slots.add(int(m.group(1)))
        except Exception:
            pass
        if slots: return sorted(slots)
    except Exception:
        pass
    return list(range(1, 15))

def slot_names():
    # FIX V4.68: port of shell upanel_name() strategies 1+2, run DIRECTLY in Python.
    # The old version shelled out to --web-multiboot-show, which runs upanel_boot_mount +
    # upanel_ensure_debugfs (opkg update + install e2fsprogs when debugfs is missing).
    # That can take minutes -> the 60s subprocess timeout killed it -> all slots Empty.
    # Direct debugfs cat is instant and never installs anything on a page load.
    # upanel_root() logic, in order: (1) blkid LABEL=linuxN, (2) STARTUP_LINUX_N root=+rootsubdir=,
    # (3) shared root from /proc/cmdline + subdir linuxrootfsN.
    import subprocess as _sp, glob as _g, os as _os, re as _re
    def _iv_name(_txt):
        _d = _v = _c = ""
        for _ln in (_txt or "").splitlines():
            _k, _, _val = _ln.partition("=")
            _val = _val.strip().strip('"').strip()
            if _k.strip().lower() == "distro": _d = _val
            elif _k.strip().lower() == "version": _v = _val
            elif _k.strip().lower() == "creator": _c = _val
        return ((_d + " " + _v).strip() or ((_c + " " + _v).strip()))
    names = {}
    try:
        _cs = int(str(current_slot()))
    except Exception:
        _cs = 0
    # Current slot: running system IS /etc/image-version
    try:
        _nm = _iv_name(open("/etc/image-version", errors="ignore").read())
        if _cs and _nm: names[_cs] = _nm
    except Exception:
        pass
    # Shared root (eMMC layout) from /proc/cmdline, resolved like the shell does
    _shared = ""
    try:
        _cmd = open("/proc/cmdline", errors="ignore").read()
        m = _re.search(r"root=/dev/\S+", _cmd)
        if m: _shared = m.group(0).split("=", 1)[1]
        if not _shared:
            for _ln in open("/proc/mounts", errors="ignore").read().splitlines():
                _p = _ln.split()
                if len(_p) >= 2 and _p[1] == "/": _shared = _p[0]; break
        if _shared and not _os.path.exists(_shared):
            _r = _sp.run(["readlink", "-f", _shared], capture_output=True, text=True, timeout=5)
            if _r.stdout.strip(): _shared = _r.stdout.strip()
    except Exception:
        pass
    # blkid LABEL=linuxN map (SD layout)
    _blkid = ""
    try:
        _blkid = _sp.run(["blkid"], capture_output=True, text=True, timeout=10).stdout or ""
    except Exception:
        pass
    # /proc/mounts map: device -> mountpoint (strategy 1: already-mounted root)
    _mounts = {}
    try:
        for _ln in open("/proc/mounts", errors="ignore").read().splitlines():
            _p = _ln.split()
            if len(_p) >= 2: _mounts[_p[0]] = _p[1]
    except Exception:
        pass
    _has_debugfs = bool(__import__("shutil").which("debugfs"))
    try:
        for _n in multiboot_slots():
            if _n in names: continue
            _rp, _sub = "", ""
            m = _re.search(r"([^:\n]*):[^\n]*LABEL=\"linux%d\"" % _n, _blkid)
            if m:
                _rp, _sub = m.group(1), ""
            else:
                try:
                    _st = open("/boot/STARTUP_LINUX_%d" % _n, errors="ignore").read()
                    _rm = _re.search(r"root=/dev/\S+", _st)
                    _sm = _re.search(r"rootsubdir=\S+", _st)
                    if _rm: _rp = _rm.group(0).split("=", 1)[1]
                    if _sm: _sub = _sm.group(0).split("=", 1)[1]
                except Exception:
                    pass
                if not _rp and _shared:
                    _rp, _sub = _shared, "linuxrootfs%d" % _n
            _nm = ""
            # Strategy 1: root partition already mounted somewhere (not /)
            try:
                _em = _mounts.get(_rp, "")
                if _rp and _em and _em != "/":
                    _p2 = _em + ("/" + _sub if _sub else "") + "/etc/image-version"
                    if _os.path.isfile(_p2): _nm = _iv_name(open(_p2, errors="ignore").read())
                    if not _nm:
                        _p3 = _em + ("/" + _sub if _sub else "") + "/etc/issue"
                        if _os.path.isfile(_p3):
                            _il = open(_p3, errors="ignore").read().splitlines()
                            if _il: _nm = _il[0].split(chr(92))[0].strip()
            except Exception:
                pass
            # Strategy 2: debugfs cat, no mount, no install
            if not _nm and _rp and _has_debugfs:
                try:
                    _dp = ("/" + _sub if _sub else "") + "/etc/image-version"
                    _out = _sp.run(["debugfs", "-R", "cat " + _dp, _rp], capture_output=True, text=True, timeout=15).stdout or ""
                    _nm = _iv_name(_out)
                except Exception:
                    pass
            # Last: custom label file (same as shell upanel_name, after image-version fails)
            if not _nm:
                try:
                    _lf = "/boot/u-panel-slot-%d.label" % _n
                    if _os.path.isfile(_lf):
                        _ll = open(_lf, errors="ignore").read().splitlines()
                        if _ll: _nm = _ll[0].strip()
                except Exception:
                    pass
            if _nm: names[_n] = _nm
    except Exception:
        pass
    return names

def current_slot():
    cs = os.environ.get("U_PANEL_CURRENT_SLOT", "")
    if cs:
        return cs
    try:
        with open("/proc/cmdline") as f:
            cmd = f.read()
        import re as _re
        m = _re.search(r"rootsubdir=\w*(\d+)", cmd)
        if m:
            return m.group(1)
    except Exception:
        pass
    return "?"

def valid_image_path(path):
    ap = os.path.abspath(path)
    roots = list(BACKUP_ROOTS) + [downloads_dir()] + FLASH_SCAN_ROOTS
    for root in roots:
        ar = os.path.abspath(root)
        if ap == ar or ap.startswith(ar + os.sep):
            return ap
    return None

TELEGRAM_CONF = os.environ.get("U_PANEL_TELEGRAM_CONF", "/etc/u-panel-telegram.conf")
CRONTAB_FILE = os.environ.get("U_PANEL_CRONTAB_FILE", "")

def telegram_conf():
    tok, chat = "", ""
    try:
        for ln in open(TELEGRAM_CONF).read().splitlines():
            if ln.startswith("TOKEN="): tok = ln[6:].strip()
            if ln.startswith("CHAT="): chat = ln[5:].strip()
    except Exception: pass
    return tok, chat

def telegram_send_msg(text):
    tok, chat = telegram_conf()
    if not tok or not chat: return "Telegram not configured"
    try:
        import urllib.request as _u, json as _j
        data = _j.dumps({"chat_id": chat, "text": text}).encode()
        req = _u.Request("https://api.telegram.org/bot" + tok + "/sendMessage", data=data, headers={"Content-Type": "application/json"})
        with _u.urlopen(req, timeout=20) as r: return "Telegram sent (HTTP %s)" % r.status
    except Exception as e: return "Telegram failed: %s" % e

def openwebif_status():
    import urllib.request as _u
    installed = os.path.isdir("/usr/lib/enigma2/python/Plugins/Extensions/OpenWebif")
    reachable = False; detail = ""
    for url in ("http://127.0.0.1/web/about", "http://127.0.0.1/web/getcurrent"):
        try:
            with _u.urlopen(url, timeout=3) as r: reachable = True; detail = "OpenWebif answered on %s (HTTP %s)" % (url, r.status); break
        except Exception as e: detail = "%s -> %s" % (url, e)
    return installed, reachable, detail

ALERTS_FILE = os.environ.get("U_PANEL_ALERTS_FILE", "/etc/u-panel-epg-alerts.conf")

def epg_fetch(ref, start, end):
    import urllib.request as _u, urllib.parse as _p, xml.etree.ElementTree as _et
    url = "http://127.0.0.1/web/epgservice?sRef=" + _p.quote(ref, safe=":") + "&time=" + str(start) + "&endTime=" + str(end)
    try:
        with _u.urlopen(url, timeout=10) as r: raw = r.read()
        root = _et.fromstring(raw)
        out = []
        for ev in root.findall("e2event"):
            def txt(tag):
                el = ev.find(tag); return el.text if el is not None and el.text else ""
            try: st = int(txt("e2eventstart"))
            except Exception: continue
            try: dur = int(txt("e2eventduration"))
            except Exception: dur = 0
            out.append({"start": st, "dur": dur, "title": txt("e2eventtitle"), "desc": txt("e2eventdescription"), "ext": txt("e2eventdescriptionextended")})
        return out
    except Exception: return None

def alerts_list():
    out = []
    try:
        for ln in open(ALERTS_FILE).read().splitlines():
            parts = ln.split("|")
            if len(parts) == 5: out.append(parts)
    except Exception: pass
    return out

def alerts_save(rows):
    open(ALERTS_FILE, "w").write("\n".join("|".join(r) for r in rows) + ("\n" if rows else ""))

def alerts_cron_ensure():
    lines_ = crontab_lines()
    if any("U-Panel EPG alerts" in ln for ln in lines_): return True
    lines_.append("*/5 * * * * sh %s --web-check-alerts  # U-Panel EPG alerts" % SCRIPT)
    return crontab_write(lines_)

def sys_status():
    d = {}
    d["uptime"] = shell_out("uptime 2>/dev/null")
    d["temp"] = shell_out("cat /proc/stb/sensors/temp0/value 2>/dev/null; cat /sys/class/thermal/thermal_zone0/temp 2>/dev/null")
    d["mem"] = shell_out("free -m 2>/dev/null | head -2 | tail -1")
    d["disk"] = shell_out("df -h /media/hdd 2>/dev/null | tail -1")
    d["load"] = shell_out("cat /proc/loadavg 2>/dev/null")
    sig = ""
    for f in sorted(glob.glob("/proc/stb/frontend/*/snr")) + sorted(glob.glob("/proc/stb/frontend/*/agc")) + sorted(glob.glob("/proc/stb/frontend/*/lock")):
        try: sig += os.path.basename(os.path.dirname(f)) + " " + os.path.basename(f) + "=" + open(f).read().strip() + " "
        except Exception: pass
    d["signal"] = sig or "not available (frontend proc files missing)"
    d["timers"] = str(len(timers_list()))
    d["plugins"] = str(len(plugin_list()))
    d["backups"] = str(len(backup_entries()))
    return d

def timers_file():
    return os.path.join(ENIGMA2_DIR, "timers.xml")

def timers_list():
    import xml.etree.ElementTree as _et
    out = []
    try:
        tree = _et.parse(timers_file())
        for el in tree.getroot().findall("timer"):
            out.append(el)
    except Exception: pass
    return out

def timers_save(elems):
    import xml.etree.ElementTree as _et
    root = _et.Element("timers")
    for el in elems: root.append(el)
    _et.ElementTree(root).write(timers_file(), encoding="utf-8", xml_declaration=True)

def plugin_list():
    out = []
    base = "/usr/lib/enigma2/python/Plugins/Extensions"
    try:
        for d in sorted(os.listdir(base)):
            full = os.path.join(base, d)
            if os.path.isdir(full):
                try: sz = shell_out("du -sh '%s' 2>/dev/null | cut -f1" % full)
                except Exception: sz = "?"
                out.append((d, full, sz))
    except Exception: pass
    return out

def crontab_lines():
    if CRONTAB_FILE:
        try: return open(CRONTAB_FILE).read().splitlines()
        except Exception: return []
    try: return subprocess.run(["crontab", "-l"], capture_output=True, text=True, timeout=10).stdout.splitlines()
    except Exception: return []

def crontab_write(lines_):
    if CRONTAB_FILE:
        open(CRONTAB_FILE, "w").write("\n".join(lines_) + "\n"); return True
    try:
        pr = subprocess.run(["crontab", "-"], input="\n".join(lines_) + "\n", capture_output=True, text=True, timeout=10)
        return pr.returncode == 0
    except Exception: return False

def schedule_get():
    for ln in crontab_lines():
        if "U-Panel scheduled backup" in ln: return ln
    return ""

def cleanup_scan():
    out = []
    def sz(path):
        try: return int(shell_out("du -sb '%s' 2>/dev/null | cut -f1" % path) or 0)
        except Exception: return 0
    for root in BACKUP_ROOTS:
        ts = os.path.join(root, "timeshift")
        if os.path.isdir(ts): out.append(("timeshift", _tr("Timeshift files (%s)") % root, sz(ts), ts))
    logs = sorted(glob.glob("/media/hdd/*.log") + glob.glob("/media/hdd/*crash*") + glob.glob("/tmp/*crash*"))
    tot = sum(os.path.getsize(f) for f in logs if os.path.isfile(f))
    if logs: out.append(("crashlogs", _tr("Crash / log files (%d files)") % len(logs), tot, ";".join(logs)))
    parts = sorted(glob.glob(os.path.join(downloads_dir(), "*.part")) + glob.glob(os.path.join(downloads_dir(), "*.tmp")))
    tot2 = sum(os.path.getsize(f) for f in parts if os.path.isfile(f))
    if parts: out.append(("incomplete", _tr("Incomplete downloads (%d files)") % len(parts), tot2, ";".join(parts)))
    old = []
    for full, base, size, mtime in backup_entries():
        try:
            age = time.time() - os.stat(full).st_mtime
            if age > 30 * 86400: old.append(full)
        except Exception: pass
    if len(old) > 1:
        keep = old[:1]
        tot3 = sum(os.path.getsize(f) if os.path.isfile(f) else 0 for f in old[1:])
        out.append(("oldbackups", _tr("Old backups over 30 days (keeps the newest 1)"), tot3, ";".join(old[1:])))
    return out

def _nice_name(base):
    import re as _re
    _s = _re.sub(r"_x([0-9A-Fa-f]{4})_", lambda m: chr(int(m.group(1), 16)), base)
    _s = _re.sub(r"_x([0-9A-Fa-f]{2})_", lambda m: chr(int(m.group(1), 16)), _s)
    try:
        from urllib.parse import unquote as _uq
        _s = _uq(_s)
    except Exception: pass
    return _s

def backup_entries():
    out = []
    seen = set()
    for root in BACKUP_ROOTS:
        if not os.path.isdir(root):
            continue
        for base in sorted(os.listdir(root)):
            if not (base.startswith("U-Panel") or base.startswith("backup") or base.startswith("GOLD-BACKUP")):
                continue
            if base == "U-Panel":
                continue
            full = os.path.join(root, base)
            if not os.path.isdir(full) and not base.lower().endswith((".tar.gz", ".tgz", ".zip", ".tar")):
                continue
            if full in seen:
                continue
            seen.add(full)
            try:
                st = os.stat(full)
                if os.path.isdir(full):
                    size = shell_out("du -sh '%s' 2>/dev/null | cut -f1" % full)
                else:
                    size = "%d KB" % (st.st_size // 1024)
                out.append((full, base, size, time.strftime("%Y-%m-%d %H:%M", time.localtime(st.st_mtime))))
            except Exception:
                pass
    out.sort(key=lambda x: x[0])
    return out

def valid_backup_path(path):
    ap = os.path.abspath(path)
    for root in BACKUP_ROOTS:
        ar = os.path.abspath(root)
        if ap == ar or ap.startswith(ar + os.sep):
            return ap
    return None

