    _tabs = [("/", "M10 20v-6h4v6h5v-8h3L12 3 2 12h3v8z", "Home"), ("/panel", "M4 11h5V5H4v6zm0 7h5v-6H4v6zm6 0h5v-6h-5v6zm0-7h5V5h-5v6zm6-6v6h5V5h-5zm0 7h5v6h-5v-6z", "Panel"), ("/live", "M21 3H3c-1.1 0-2 .9-2 2v12c0 1.1.9 2 2 2h5v2h8v-2h5c1.1 0 1.99-.9 1.99-2L23 5c0-1.1-.9-2-2-2zm0 14H3V5h18v12z", "Live TV"), ("/setting", "M19.14 12.94c.04-.3.06-.61.06-.94 0-.32-.02-.64-.07-.94l2.03-1.58c.18-.14.23-.41.12-.61l-1.92-3.32c-.12-.22-.37-.29-.59-.22l-2.39.96c-.5-.38-1.03-.7-1.62-.94l-.36-2.54c-.04-.24-.24-.41-.48-.41h-3.84c-.24 0-.43.17-.47.41l-.36 2.54c-.59.24-1.13.57-1.62.94l-2.39-.96c-.22-.08-.47 0-.59.22L2.74 8.87c-.12.21-.08.47.12.61l2.03 1.58c-.05.3-.09.63-.09.94s.02.64.07.94l-2.03 1.58c-.18.14-.23.41-.12.61l1.92 3.32c.12.22.37.29.59.22l2.39-.96c.5.38 1.03.7 1.62.94l.36 2.54c.05.24.24.41.48.41h3.84c.24 0 .44-.17.47-.41l.36-2.54c.59-.24 1.13-.56 1.62-.94l2.39.96c.22.08.47 0 .59-.22l1.92-3.32c.12-.21.07-.47-.12-.61l-2.01-1.58zM12 15.6c-1.98 0-3.6-1.62-3.6-3.6s1.62-3.6 3.6-3.6 3.6 1.62 3.6 3.6-1.62 3.6-3.6 3.6z", "Settings")]
    _out = "<nav class='up-tabs'>"
    for _href, _d, _lbl in _tabs:
        _cls = " class='on'" if path == _href or (path.startswith(_href + "/") and _href != "/") else ""
        _out += "<a%s href='%s' aria-label='%s'><svg viewBox='0 0 24 24'><path d='%s'/></svg><span class='ut-lb'>%s</span></a>" % (_cls, _href, _tr(_lbl), _d, _tr(_lbl))
    _out += "</nav>"
    return _out

def _layout_mock(_lk):
    def _bx(_w, _h, _r):
        return "<span style='display:inline-block;width:%spx;height:%spx;border-radius:%spx;background:linear-gradient(135deg,#ec4899,#a855f7);margin:2px;vertical-align:middle'></span>" % (_w, _h, _r)
    if _lk == "list":
        return _bx(150, 14, 6) + "<br>" + _bx(150, 14, 6) + "<br>" + _bx(150, 14, 6)
    if _lk == "compact":
        return (_bx(30, 20, 5) * 3) + "<br>" + (_bx(30, 20, 5) * 3)
    if _lk == "tiles":
        return (_bx(30, 30, 5) * 3) + "<br>" + (_bx(30, 30, 5) * 3)
    if _lk == "sidebar":
        return "<span style='display:inline-block;width:14px;height:56px;border-radius:7px;background:rgba(255,255,255,.25);margin:2px;vertical-align:middle'></span>" + _bx(110, 14, 6) + "<br><span style='display:inline-block;width:14px;height:1px;margin:2px'></span>" + _bx(110, 14, 6)
    if _lk == "featured":
        return _bx(150, 30, 8) + "<br>" + _bx(70, 20, 6) + _bx(70, 20, 6)
    if _lk == "circles9":
        return _bx(30, 30, 15) + _bx(30, 30, 15) + _bx(30, 30, 15)
    if _lk == "pills":
        return _bx(150, 16, 8) + "<br>" + _bx(150, 16, 8) + "<br>" + _bx(150, 16, 8)
    if _lk == "cards":
        return _bx(150, 34, 8) + "<br>" + _bx(150, 34, 8)
    if _lk == "mini":
        return (_bx(22, 22, 5) * 4) + "<br>" + (_bx(22, 22, 5) * 4)
    if _lk == "split":
        return _bx(26, 26, 6) + _bx(110, 14, 6) + "<br>" + _bx(26, 26, 6) + _bx(110, 14, 6)
    if _lk == "cover":
        return _bx(150, 34, 8) + "<br>" + _bx(70, 20, 6) + _bx(70, 20, 6)
    return _bx(70, 22, 6) + _bx(70, 22, 6) + "<br>" + _bx(70, 22, 6) + _bx(70, 22, 6)


class H(BaseHTTPRequestHandler):
    def log_message(self, *a):
        pass
    def _dbg(self, msg):
        # V6.20 DIAG - checkpoint log with immediate flush+fsync, so it survives
        # even if the process is killed mid-request (buffered writes would be lost).
        try:
            with open("/tmp/prepare-debug.log", "a") as _f:
                _f.write(msg + "\n"); _f.flush()
                import os as _o2; _o2.fsync(_f.fileno())
        except Exception: pass
    def handle_error(self, request, client_address):
        # V6.20 DIAG - log the FULL traceback whenever a request drops the
        # connection (e.g. /multiboot/prepare "server dropped"). Without this,
        # BaseHTTPRequestHandler prints to stderr only and the cause is lost.
        import traceback
        try:
            with open("/tmp/u-panel-web-error.log", "a") as _ef:
                _ef.write("=== ERROR %s %s ===\n" % (client_address, request))
                _ef.write(traceback.format_exc() + "\n")
        except Exception: pass
    def authed(self):
        ck = self.headers.get("Cookie", "")
        return ("upanel_pin=" + get_pin()) in ck
    def send_html(self, body, code=200, cookie=None, refresh=None):
        _ref = ("<meta http-equiv='refresh' content='%d'>" % int(refresh)) if refresh else ""
        data = ("<!DOCTYPE html><html lang='%s' dir='%s'>" % (_panel_lang_current(), PANEL_LANGS[_panel_lang_current()][1]) + "<head><meta name='viewport' content='width=device-width,initial-scale=1'><meta charset='utf-8'><meta http-equiv='Cache-Control' content='no-cache, no-store, must-revalidate'><meta http-equiv='Pragma' content='no-cache'><meta http-equiv='Expires' content='0'>" + PWA_HEAD + _ref + "<title>U-Panel</title>" + PAGE_CSS + GOOGLE_FONTS_LINK + PREMIUM_CSS + _web_theme_css() + _panel_shape_css() + _panel_font_css() + _panel_layout_css() + _button_size_css() + "<script>try{if(location.href.indexOf(\'@\')>-1){history.replaceState(null,\'\',location.protocol+\'//\'+location.host+location.pathname+location.search+location.hash);}}catch(e){}(function(){var _f=window.fetch;window.fetch=function(u,o){if(typeof u===\'string\'&&u.charAt(0)===\'/\'){u=location.protocol+\'//\'+location.host+u;}return _f.call(this,u,o);};})();document.addEventListener(\'click\',function(e){var a=e.target.closest?e.target.closest(\'a\'):null;if(!a)return;var t=(a.textContent||\'\').trim();if(t.indexOf(\'Back\')===0||t.indexOf(\'\\u0631\\u062c\\u0648\\u0639\')===0||t.indexOf(\'Retour\')===0){if(window.history.length>1){e.preventDefault();history.back();}}});</script></head><body>" + _app_shell_top(self.path) + body + _app_shell_bottom(self.path) + "</body></html>").encode()
        self.send_response(code)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Cache-Control", "no-cache, no-store, must-revalidate")
        self.send_header("Pragma", "no-cache")
        self.send_header("Expires", "0")
        self.send_header("Content-Length", str(len(data)))
        if cookie:
            self.send_header("Set-Cookie", cookie + "; Path=/; HttpOnly")
        self.end_headers()
        self.wfile.write(data)
    def do_GET(self):
        u = urlparse(self.path)
        q = parse_qs(u.query)
        if u.path == "/login":
            self.send_html("<h1>U-Panel</h1><form method='post' action='/login'><input name='pin' type='password' placeholder='Enter PIN' autofocus><button>Login</button></form><p class='small'>LAN only. Default PIN is 1234 - change it from U-Panel Setting &gt; Panel Control.</p>")
            return
        if u.path == "/manifest.json":
            _m = PWA_MANIFEST.encode()
            self.send_response(200); self.send_header("Content-Type", "application/manifest+json"); self.send_header("Content-Length", str(len(_m))); self.end_headers(); self.wfile.write(_m); return
        if u.path == "/version":
            import json as _jjv
            _vb = _jjv.dumps({"version": os.environ.get("U_PANEL_VERSION", "V6.25"), "script": os.environ.get("U_PANEL_PATH", "")}).encode()
            self.send_response(200); self.send_header("Content-Type", "application/json"); self.send_header("Cache-Control", "no-cache"); self.send_header("Content-Length", str(len(_vb))); self.end_headers(); self.wfile.write(_vb); return; return
        if u.path == "/restart-server":
            _sp = resolve_script()
            if not _sp:
                self.send_html("<h1>Restart failed</h1><div class='card'>SCRIPT NOT FOUND - the Panel server cannot find the U-Panel script file.<br>Re-run the script from its real location, e.g.<br>sh /etc/enigma2/U-Panel-V6.25.sh<br>then reload this page.</div><a href='/'>Back</a>"); return
            def _do_restart():
                time.sleep(2)
                try: subprocess.Popen(["sh", _sp, "--restart-server"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                except Exception: pass
            threading.Thread(target=_do_restart, daemon=True).start()
            self.send_html("<h1>Restarting Panel Server</h1><p>Wait 6 seconds - the page will reload on the new server.</p><script>setTimeout(function(){location.href='/';},6000)</script><a href='/'>Back</a>"); return
        if u.path in ("/icon-192.png", "/icon-512.png", "/apple-touch-icon.png", "/icon.png"):
            _p = __import__("base64").b64decode(PWA_ICON_B64)
            self.send_response(200); self.send_header("Content-Type", "image/png"); self.send_header("Content-Length", str(len(_p))); self.end_headers(); self.wfile.write(_p); return
        # V6.19: theme/shape/font/layout are cosmetic (LAN only) - no login needed to change them.
        # The PIN still protects every destructive action. This kills the whole
        # "cookie lost -> tap theme -> sent to login -> nothing saved" failure class.
        if u.path not in ("/setting/theme-setting", "/setting/apply") and not self.authed():
            self.send_response(302); self.send_header("Location", "/login"); self.end_headers(); return
        # V5.96 REBUILD: Setup / Fav / Image-Essentials / Smart Restore / Custom Restore
        # Each page has its OWN handler (never lost in the shared dispatch block).
        # START buttons link straight to the job (confirm=1) - one tap, no more pages.
        if u.path == "/setup":
            _st = 1
            try: _st = int((q.get("step") or ["1"])[0] or 1)
            except Exception: _st = 1
            _st = max(1, min(6, _st))
            if (q.get("reset") or [""])[0] == "1":
                SETUP_STATE.clear()
                self.send_response(302); self.send_header("Location", "/setup?step=1"); self.end_headers(); return
            self.send_html(_setup_wizard_html(_st)); return
        if u.path == "/fav":
            self.send_html("<h1>Ur Favourite Setup</h1><div class='card'>Your saved favourite setup - runs in background as a job.<br><span class='small'>One tap starts it - no more pages.</span></div><a class='primary' href='/run?action=web-fav&confirm=1'>START - Ur Favourite Setup</a><a href='/panel'>Back to Panel Menu</a>"); return
        if u.path == "/image-essentials":
            self.send_html("<h1>Image with Essentials</h1><div class='card'>Full image build in one run: Packages -&gt; Essentials Plugins -&gt; BootLogo Auto -&gt; Channel list -&gt; <b>ONE reboot at the very end only</b>. Runs in background as a job.<br><span class='small'>One tap starts it - no more pages.</span></div><a class='primary' href='/run?action=web-image-essentials&confirm=1'>START - Image with Essentials</a><a href='/panel'>Back to Panel Menu</a>"); return
        if u.path == "/smart-restore":
            self.send_html("<h1>Smart Restore - LATEST BACKUP ONLY</h1><div class='card'>Mode auto-detected: SAME NAME + SAME PYTHON = FULL, else SAFE. BootLogo: in All only, for the CURRENT image.<br><span class='small'>One tap starts it - no more pages.</span></div><a class='primary' href='/run?action=smart-restore-packages&confirm=1'>START - Packages and Plugins</a><a class='primary' href='/run?action=smart-restore-files&confirm=1'>START - Files Only</a><a class='primary' href='/run?action=smart-restore&confirm=1'>START - All (Packages + Plugins + Files + BootLogo)</a><a href='/panel'>Back to Panel Menu</a>"); return
        if u.path == "/custom-restore":
            self.send_html("<h1>Custom Restore</h1><div class='card'>Items from Terminal Custom Restore. All = Plugins + Files + BootLogo Auto + Abertis.<br><span class='small'>One tap starts it - no more pages.</span></div><a class='primary' href='/run?action=custom-restore-plugins&confirm=1'>START - Restore Plugins</a><a class='primary' href='/run?action=custom-restore-files&confirm=1'>START - Restore Files</a><a class='primary' href='/run?action=custom-restore-all&confirm=1'>START - All</a><a href='/panel'>Back to Panel Menu</a>"); return
        if u.path == "/logout":
            self.send_html("<h1>Logged out</h1><a href='/login'>Login again</a>", cookie="upanel_pin=; Max-Age=0")
            return
        if u.path == "/run":
            action = (q.get("action") or [""])[0]
            if action not in ACTIONS:
                self.send_html("<h1>Unknown action</h1><a href='/'>Back</a>"); return
            if action.startswith("ui-style-") or action.startswith("ui-color-"):
                self.send_html("<h1>Terminal only</h1><div class='card'>Script style / colors are set from the Terminal only - hidden from the Web UI.<br><span class='small'>Run the script on the receiver and use U-Panel Setting in the Terminal.</span></div><a href='/setting'>Back to U-Panel Setting</a>"); return
            label, need_confirm, _ = ACTIONS[action]
            if need_confirm and q.get("confirm", [""])[0] != "1":
                self.send_html(("<h1>" + _tr("Confirm") + "</h1><div class='card'>%s<br><span class='small'>" + _tr("This cannot be undone. Make sure you really want it.") + "</span></div><a class='danger' href='/run?action=%s&confirm=1'>" + _tr("YES - ") + "%s</a><a href='/'>" + _tr("Cancel") + "</a>") % (html.escape(_tr(label)), html.escape(action), html.escape(_tr(label))))
                return
            jid = uuid.uuid4().hex[:8]
            JOBS[jid] = {"action": action, "status": "starting", "output": "", "started": ""}
            threading.Thread(target=run_job, args=(JOBS[jid],), daemon=True).start()
            self.send_response(302); self.send_header("Location", "/job?id=" + jid); self.end_headers(); return
        if u.path == "/job":
            jid = (q.get("id") or [""])[0]
            job = JOBS.get(jid)
            if not job:
                self.send_html("<h1>" + _tr("Job not found") + "</h1><a href='/'>" + _tr("Back") + "</a>"); return
