                     "var cmtAudio=null,cmtOn=false,cmtTimer=null;function cmtMsg(m){var e=document.getElementById('cmtstat');if(e)e.textContent=m;}function startCmt(){var v=document.getElementById('lv');var url=window.cmtSelUrl||document.getElementById('cmturl').value.trim();if(!url){cmtMsg('حط رابط صوت التعليق الأول.');return;}if(url.indexOf('http')==0){try{localStorage.setItem('upanel_cmt_url',url);}catch(e){}}if(!cmtAudio)cmtAudio=new Audio();cmtAudio.onerror=function(){if(!window.cmtTriedDirect){window.cmtTriedDirect=true;cmtMsg('الخادم مش قادر يحوّل الصوت - بجرّب الرابط المباشر...');cmtAudio.src=url;try{cmtAudio.play();}catch(e){}}else{cmtMsg('التعليق مشتغلش - جرّب محطة تانية.');document.getElementById('lv').muted=false;}};window.cmtTriedDirect=false;cmtAudio.src='/live/cmt?url='+encodeURIComponent(url);cmtAudio.volume=parseFloat(document.getElementById('cmtvol').value||'100')/100;var dly=parseFloat(document.getElementById('cmtdly').value||'0');document.getElementById('cmtdlyv').textContent=dly;if(cmtTimer)clearTimeout(cmtTimer);cmtMsg('بيشغّل التعليق'+(window.cmtSelName?' ('+window.cmtSelName+')':'')+' بعد '+dly+' ثانية...');v.muted=true;cmtTimer=setTimeout(function(){var pr=null;try{pr=cmtAudio.play();}catch(e){pr=null;}if(pr&&pr.then){pr.then(function(){if(window.cmtWatch)clearTimeout(window.cmtWatch);cmtMsg('التعليق شغال 🎙️'+(window.cmtSelName?' ('+window.cmtSelName+')':'')+' - صوت القناة الأصلي متكتم.');}).catch(function(e){if(!window.cmtTriedDirect){window.cmtTriedDirect=true;cmtMsg('بجرّب الرابط المباشر...');cmtAudio.src=url;try{cmtAudio.play();}catch(_e){}}else{cmtMsg('التعليق مشتغلش - جرّب محطة تانية.');document.getElementById('lv').muted=false;}});}else{cmtMsg('التعليق شغال 🎙️ - صوت القناة الأصلي متكتم.');}},dly*1000);cmtOn=true;var cb=document.getElementById('cmtbtn');cb.className='lvbtn stop';cb.textContent='🎙️ تغيير التعليق';if(window.cmtWatch)clearTimeout(window.cmtWatch);window.cmtWatch=setTimeout(function(){if(!cmtOn)return;if(cmtAudio&&cmtAudio.paused){if(!window.cmtTriedDirect){window.cmtTriedDirect=true;cmtMsg('المحطة دي مش بترد - بجرّب الرابط المباشر...');cmtAudio.src=url;try{cmtAudio.play();}catch(e){}window.cmtWatch=setTimeout(function(){if(cmtOn&&cmtAudio&&cmtAudio.paused){cmtMsg('التعليق مشتغلش - جرّب محطة تانية.');document.getElementById('lv').muted=false;}},8000);}else{cmtMsg('التعليق مشتغلش - جرّب محطة تانية.');document.getElementById('lv').muted=false;}}},dly*1000+8000);}function stopCmt(){if(cmtTimer)clearTimeout(cmtTimer);if(window.cmtWatch)clearTimeout(window.cmtWatch);if(cmtAudio)cmtAudio.pause();var v=document.getElementById('lv');v.muted=false;cmtOn=false;window.cmtSelUrl='';window.cmtSelName='';var _cl=document.getElementById('cmtlist');if(_cl)_cl.style.display='none';var cb=document.getElementById('cmtbtn');cb.className='lvbtn blk';cb.textContent='▶ تشغيل التعليق';cmtMsg('التعليق وقف - رجع صوت القناة الأصلي.');}function toggleCmt(){cmtListToggle();}"
