'Anis Al Kass 2',u:'http://radio.anisfm.vip/live/sha/K2?token=JLMYWO5XIT#'},{n:'Anis Max 1 Low',u:'http://radio.anisfm.vip/live/mx/1L?token=JLMYWO5XIT#'},{n:'Anis Max 2 Low',u:'http://radio.anisfm.vip/live/mx/2L?token=JLMYWO5XIT#'},{n:'Anis Max 3 Low',u:'http://radio.anisfm.vip/live/mx/3L?token=JLMYWO5XIT#'},{n:'Anis Max 4 Low',u:'http://radio.anisfm.vip/live/mx/4L?token=JLMYWO5XIT#'},{n:'Anis Max 5 Low',u:'http://radio.anisfm.vip/live/mx/5L?token=JLMYWO5XIT#'},{n:'Anis Max 6 Low',u:'http://radio.anisfm.vip/live/mx/6L?token=JLMYWO5XIT#'}];function cmtListToggle(){var l=document.getElementById('cmtlist');if(l.style.display=='block'){l.style.display='none';}else{cmtListRender();l.style.display='block';}}function cmtListRender(){var l=document.getElementById('cmtlist');l.innerHTML='';if(cmtOn){var s=document.createElement('div');s.style.padding='10px';s.style.borderBottom='1px solid #333';s.style.cursor='pointer';s.style.color='#ff8a8a';s.textContent='⏹ إيقاف التعليق';s.onclick=function(){stopCmt();};l.appendChild(s);}var inp=document.getElementById('cmturl').value.trim();if(inp.indexOf('http')==0){var m=document.createElement('div');m.style.padding='10px';m.style.borderBottom='1px solid #333';m.style.cursor='pointer';m.textContent='🔗 تشغيل الرابط اليدوي';m.onclick=function(){cmtPlay(inp,'رابط يدوي');};l.appendChild(m);}CMT_LIST.forEach(function(it){var row=document.createElement('div');row.style.padding='10px';row.style.borderBottom='1px solid #333';row.style.cursor='pointer';row.textContent='📻 '+it.n;row.onclick=function(){cmtPlay(it.u,it.n);};l.appendChild(row);});}function cmtPlay(url,name){window.cmtSelUrl=url;window.cmtSelName=name;document.getElementById('cmturl').value=name;var l=document.getElementById('cmtlist');if(l)l.style.display='none';try{if(!cmtAudio)cmtAudio=new Audio();cmtAudio.src='/live/cmt?url='+encodeURIComponent(url);cmtAudio.volume=0;var _p=cmtAudio.play();if(_p&&_p.then)_p.then(function(){try{cmtAudio.pause();}catch(e){}}).catch(function(){});}