        _devcard = "<div class='card' style='padding:4px 16px'>" + "<div style='display:flex;justify-content:space-between;gap:12px;align-items:center;padding:10px 0;border-bottom:1px solid rgba(128,128,128,.25)'><span style='opacity:.65'>Device</span><b>%s</b></div>" % html.escape((box or "").replace("\n", " \u2022 ")) + "<div style='display:flex;justify-content:space-between;gap:12px;align-items:center;padding:10px 0;border-bottom:1px solid rgba(128,128,128,.25)'><span style='opacity:.65'>Image</span><b>%s</b></div>" % html.escape(_clean_image_version(img)) + "<div style='display:flex;justify-content:space-between;gap:12px;align-items:center;padding:10px 0'><span style='opacity:.65'>HDD</span><b>%s</b></div></div>" % html.escape(_clean_disk_line(disk))
        body = _devcard
        body += "<p class='small'>Panel %s - Theme: %s</p>" % (os.environ.get("U_PANEL_VERSION", "V6.25"), html.escape(WEB_THEMES[_web_theme_current()][0]))
        body += "<div class='grid2'>"
        for _idx, it in enumerate(DASHBOARD):
            _extra = " wide center" if _idx in (0, 1) else ""
            _badge = "<span class='badge-new'>NEW</span>" if _idx == 0 else ""
            _ic = "<span class='ic'>%s</span>" % ICONS[it[4]]
            if it[0] == "link":
                body += "<a class='%s%s' href='%s'>%s%s%s</a>" % (it[3], _extra, it[2], _ic, html.escape(_tr(it[1])), _badge)
            else:
                body += "<a class='%s%s' href='/run?action=%s'>%s%s%s</a>" % (it[3], _extra, it[2], _ic, html.escape(_tr(it[1])), _badge)
        body += "</div>"
        body += "<p class='small'>Works only on your home WiFi (LAN). Never expose port 8080 to the internet.</p>"
        self.send_html(body)
    def do_POST(self):
        u = urlparse(self.path)
        if u.path == "/setup-run":
            if not self.authed():
                self.send_response(302); self.send_header("Location", "/login"); self.end_headers(); return
            ln = int(self.headers.get("Content-Length", "0"))
            body = self.rfile.read(ln).decode()
            _f = parse_qs(body)
            _step = 1
            try: _step = int((parse_qs(u.query).get("step") or ["1"])[0] or 1)
            except Exception: _step = 1
            _step = max(1, min(6, _step))
            _argv = ["--web-setup-step", str(_step)]
            _next = "/setup?step=%d" % min(_step + 1, 6)
            _nlabel = "Next step"
            if _step == 2:
                _plugs = " ".join(_f.get("plugin", []))
                if not _plugs.strip():
                    self.send_html("<h1>Pick at least one plugin</h1><a href='/setup?step=2'>Back</a>"); return
                SETUP_STATE["plugins"] = _plugs
                _argv.append(_plugs)
            elif _step == 3:
                _res = " ".join(_f.get("restore", []))
                SETUP_STATE["restore"] = _res
                _argv.append(_res)
            elif _step == 5:
                _ch = (_f.get("channel", ["none"])[0] or "none")
                SETUP_STATE["channel"] = _ch
                _argv.append(_ch)
            elif _step == 6:
                _fb = (_f.get("fullbackup", ["n"])[0] or "n")
                _argv += [SETUP_STATE.get("plugins", ""), SETUP_STATE.get("channel", "none"), SETUP_STATE.get("restore", ""), _fb]
                _next = "/"
                _nlabel = "Done - Back to Panel"
            jid = uuid.uuid4().hex[:8]
            JOBS[jid] = {"action": "web-setup", "kind": "shell-argv", "argv": _argv, "input": "", "status": "starting", "output": "", "started": "", "next": _next, "next_label": _nlabel}
            threading.Thread(target=run_job, args=(JOBS[jid],), daemon=True).start()
            self.send_response(302); self.send_header("Location", "/job?id=" + jid); self.end_headers(); return
        u = urlparse(self.path)
