# V4.28: Panel Control in U-Panel Setting - mobile browser page on http://RECEIVER-IP:8080 (LAN only, PIN), buttons: Backup Data / Backup Files / Smart Restore (confirm) / Reboot (confirm) + live job log. Headless flags --web-backup-data / --web-backup-files / --web-smart-restore. Embedded Python server, no extra files needed.
# V4.27: preview shown automatically after a Style/Color pick, then jump straight to Main Menu (no ENTER, no staying in the submenu)
ui_preview_auto() {
  show_banner; menu_top; menu_head "Preview - Style: $UI_STYLE / Color: $UI_COLOR"; menu_sep
  menu_section "INSTALLATION" "$C_TITLE_INSTALL"; menu_item "1) Setup your Enigma"; menu_item "2) Ur Favourite Setup"; menu_sep
  menu_section "BACKUP AND RESTORE" "$C_TITLE_BACKUP"; menu_item "7) Smart Restore"; menu_item "8) Custom Restore"; menu_bot
  printf "  Saved - returning to Main Menu...\n"; sleep 2
  UI_GOTO_MAIN=1
}
ui_style_menu() {
  while true; do show_banner; menu_top; menu_head "UI Style - shape of menus + banner"; menu_sep
    echo "  Current: Style=$UI_STYLE / Color=$UI_COLOR"
    menu_item "1) Premium - full banner box + arrow menus (current look)"
    menu_item "2) Classic - simple box banner + 1) menus"
    menu_item "3) Compact - one-line banner + tight menus (small screens / mobile)"
    menu_item "4) Minimal - no banner + plain menus"
    menu_item "P) Preview current Style"; menu_item "B) Back"; menu_bot
    printf "Your choice: "; read _us || return 0
    case "$_us" in
      1) UI_STYLE="premium"; ui_save; ui_preview_auto; return 0 ;;
      2) UI_STYLE="classic"; ui_save; ui_preview_auto; return 0 ;;
      3) UI_STYLE="compact"; ui_save; ui_preview_auto; return 0 ;;
      4) UI_STYLE="minimal"; ui_save; ui_preview_auto; return 0 ;;
      p|P) ui_preview ;;
      b|B) return 0 ;; *) wrong_choice ;; esac
  done
}
ui_color_menu() {
  while true; do show_banner; menu_top; menu_head "UI Color - palette on the current Style ($UI_STYLE)"; menu_sep
    echo "  Current: Style=$UI_STYLE / Color=$UI_COLOR"
    printf "  ${C_ACCENT}Gold${C_RESET} is the current palette accent - pick a color to see it change at once\n"
    menu_item "1) Gold - the original look"
    menu_item "2) Blue - all accents blue"
    menu_item "3) Green - all accents green"
    menu_item "4) Red - all accents red"
    menu_item "5) Purple - all accents purple"
    menu_item "6) Mono - white / grey only, no colors"
    menu_item "P) Preview current Color"; menu_item "B) Back"; menu_bot
    printf "Your choice: "; read _uc || return 0
    case "$_uc" in
      1) UI_COLOR="gold"; ui_save; ui_apply_color; ui_preview_auto; return 0 ;;
      2) UI_COLOR="blue"; ui_save; ui_apply_color; ui_preview_auto; return 0 ;;
      3) UI_COLOR="green"; ui_save; ui_apply_color; ui_preview_auto; return 0 ;;
      4) UI_COLOR="red"; ui_save; ui_apply_color; ui_preview_auto; return 0 ;;
      5) UI_COLOR="purple"; ui_save; ui_apply_color; ui_preview_auto; return 0 ;;
      6) UI_COLOR="mono"; ui_save; ui_apply_color; ui_preview_auto; return 0 ;;
      p|P) ui_preview ;;
      b|B) return 0 ;; *) wrong_choice ;; esac
  done
}
