setup_reboot_guard() {
  mkdir -p /tmp/no-reboot
  for _cmd in reboot shutdown halt poweroff init; do
    cat > /tmp/no-reboot/$_cmd <<'EOF'
#!/bin/sh
echo "[BLOCKED] Auto Reboot Blocked - $0 $* - No Reboot - Continue Install"
exit 0
EOF
    chmod +x /tmp/no-reboot/$_cmd
  done
  cat > /tmp/no-reboot/killall <<'EOF'
#!/bin/sh
for _a in "$@"; do
  case "$_a" in
    enigma2|enigma|init) echo "[BLOCKED] Auto Kill Enigma Blocked - killall $* - No Restart - Continue"; exit 0 ;;
  esac
done
exec /usr/bin/killall "$@" 2>/dev/null || exec /bin/killall "$@" 2>/dev/null || exit 0
EOF
  chmod +x /tmp/no-reboot/killall
  export PATH="/tmp/no-reboot:$PATH"
  reboot() { echo "[BLOCKED] Auto Reboot Blocked - reboot() - No Reboot - Continue"; return 0; }
  shutdown() { echo "[BLOCKED] Auto Shutdown Blocked - shutdown() - No Reboot - Continue"; return 0; }
  echo "[OK] Reboot Guard V4 ON - $1"
}
setup_reboot_guard "Global"
PYTHON_V=$(python3 --version 2>/dev/null | cut -d' ' -f2)
PY_MAJOR=$(echo "$PYTHON_V" | cut -d. -f1)
PY_MM=$(echo "$PYTHON_V" | cut -d. -f1-2)
if [ -z "$PYTHON_V" ] || [ "$PY_MAJOR" -lt 3 ]; then
  echo "[ERROR] Python 3 Required - Found: $PYTHON_V"
  echo "Press ENTER to Exit..."; read _x; exit 1
fi
echo "[OK] Python: $PYTHON_V - Folder Python: $PY_MM"
# ===== V16 - Universal: NO MAC lock - all Enigma2 devices - Box detect from 100+ sources =====
# _detect_box_slug: returns canonical machine slug (lowercase, no spaces) e.g. multiboxpro / vusolo4k / dm920 / sf8008 / h9 / zgemmah9 / octagonsf8008 / uclanustym4kpro / edisionosmini / formulerf1 / gigablueue4k / mutant51 / amikoviper / axhd61 / unknown
# Sources are checked in priority order: /proc/stb/* first (most reliable), then /etc/image-version, device-tree, cpuinfo, cmdline, sysfs, commands.
_detect_box_slug() {
  _RAW=""; _LOW=""
  # --- Group 1: /proc/stb (Enigma2 hardware info - highest priority) ---
  for _f in /proc/stb/info/model /proc/stb/info/boxtype /proc/stb/info/brand /proc/stb/info/chipset /proc/stb/info/board /proc/stb/info/hardware /proc/stb/info/machine /proc/stb/info/platform /proc/stb/info/version /proc/stb/info/vumodel /proc/stb/info/box /proc/stb/info/product /proc/stb/info/device /proc/stb/info/name /proc/stb/info/type /proc/stb/info/modelname /proc/stb/info/hwmodel /proc/stb/info/chip /proc/stb/info/soc /proc/stb/info/cpu /proc/stb/info/machinetype /proc/stb/info/boxtype2 /proc/stb/info/manufacturer /proc/stb/info/vendor /proc/stb/info/family /proc/stb/info/series /proc/stb/info/generation; do
    [ -f "$_f" ] || continue
    _RAW=$(cat "$_f" 2>/dev/null | head -1 | tr -d '\0' | tr -d '\n\r' | sed 's/^[ \t]*//;s/[ \t]*$//')
    [ -n "$_RAW" ] && _LOW=$(echo "$_RAW" | tr 'A-Z' 'a-z' | tr -d ' _-') && _LOW=$(_detect_normalize_slug "$_LOW") && [ "$_LOW" != "unknown" ] && [ -n "$_LOW" ] && echo "$_LOW" && return 0
  done
  # --- Group 2: /proc/stb subdirs (fp, video, audio, av, hdmi, tuner, frontend, demux, ca, dvr) ---
  for _f in /proc/stb/fp/version /proc/stb/fp/model /proc/stb/video/chipset /proc/stb/audio/chipset /proc/stb/av/chipset /proc/stb/hdmi/chipset /proc/stb/frontend/0/model /proc/stb/frontend/1/model /proc/stb/tuner/0/model /proc/stb/demux/0/model /proc/stb/ca/0/model /proc/stb/dvr/model /proc/stb/lcd/model /proc/stb/vfd/model /proc/stb/ir/model /proc/stb/power/model /proc/stb/usb/model /proc/stb/eth/model /proc/stb/wlan/model /proc/stb/sata/model /proc/stb/nand/model /proc/stb/emmc/model /proc/stb/mmc/model /proc/stb/flash/model /proc/stb/boxtype/model /proc/stb/info2/model /proc/stb/info2/boxtype; do
    [ -f "$_f" ] || continue
    _RAW=$(cat "$_f" 2>/dev/null | head -1 | tr -d '\0' | tr -d '\n\r' | sed 's/^[ \t]*//;s/[ \t]*$//')
    [ -n "$_RAW" ] && _LOW=$(echo "$_RAW" | tr 'A-Z' 'a-z' | tr -d ' _-') && _LOW=$(_detect_normalize_slug "$_LOW") && [ "$_LOW" != "unknown" ] && [ -n "$_LOW" ] && echo "$_LOW" && return 0
  done
  # --- Group 3: /etc image files (machine= is authoritative for flashing) ---
  _M2=$(grep "^machine=" /etc/image-version 2>/dev/null | cut -d= -f2 | tr -d ' \n\r' | tr 'A-Z' 'a-z' | tr -d ' _-')
  [ -n "$_M2" ] && _LOW=$(_detect_normalize_slug "$_M2") && [ "$_LOW" != "unknown" ] && echo "$_LOW" && return 0
  # (a) single-value files: whole file IS the box name - safe to read whole file
  for _f in /etc/hostname /etc/model /etc/box /etc/machine /etc/boxtype /etc/brand /etc/board /etc/hardware /etc/product /etc/device; do
    [ -f "$_f" ] || continue
    _RAW=$(cat "$_f" 2>/dev/null | head -1 | tr -d '\0' | tr -d '\n\r' | sed 's/^[ \t]*//;s/[ \t]*$//')
    [ -z "$_RAW" ] && continue
    _LOW=$(echo "$_RAW" | tr 'A-Z' 'a-z' | tr -d ' _-')
    _LOW=$(_detect_normalize_slug "$_LOW")
    [ "$_LOW" != "unknown" ] && [ -n "$_LOW" ] && echo "$_LOW" && return 0
  done
  # (b) key-value files: ONLY accept machine=/model=/boxtype= lines - never bare brand words (os-release contains "product", settings contains random words)
  for _f in /etc/image-version /etc/issue /etc/os-release /etc/enigma2/settings /etc/version /etc/release /etc/distro /etc/motd /etc/banner /etc/welcome /etc/sysinfo /etc/system /etc/info /etc/identity; do
    [ -f "$_f" ] || continue
    _RAW=$(grep -i -m1 -E "^(machine|model|boxtype|board|hardware|product|device|brand|box)[ =:]" "$_f" 2>/dev/null | head -1)
    [ -z "$_RAW" ] && continue
    _LOW=$(echo "$_RAW" | tr 'A-Z' 'a-z' | tr -d ' _-')
    _LOW=$(_detect_normalize_slug "$_LOW")
    [ "$_LOW" != "unknown" ] && [ -n "$_LOW" ] && echo "$_LOW" && return 0
  done
  # --- Group 4: device-tree ---
  for _f in /proc/device-tree/model /proc/device-tree/compatible /proc/device-tree/board /proc/device-tree/machine /proc/device-tree/name /proc/device-tree/hardware /proc/device-tree/vendor /proc/device-tree/product /proc/device-tree/serial-number /sys/firmware/devicetree/base/model /sys/firmware/devicetree/base/compatible /sys/firmware/devicetree/base/board /sys/firmware/devicetree/base/machine /sys/firmware/devicetree/base/name /sys/firmware/devicetree/base/hardware /sys/firmware/devicetree/base/vendor /sys/firmware/devicetree/base/product /sys/firmware/devicetree/base/serial-number /sys/firmware/fdt /proc/device-tree/soc/model /proc/device-tree/cpu/model /proc/device-tree/memory/model; do
    [ -f "$_f" ] || continue
    _RAW=$(cat "$_f" 2>/dev/null | tr -d '\0' | tr -d '\n\r' | head -c 200)
    [ -n "$_RAW" ] && _LOW=$(echo "$_RAW" | tr 'A-Z' 'a-z' | tr -d ' _-') && _LOW=$(_detect_normalize_slug "$_LOW") && [ "$_LOW" != "unknown" ] && [ -n "$_LOW" ] && echo "$_LOW" && return 0
  done
  # --- Group 5: /proc (only anchored keys - bare brand words are too noisy here: vmstat has "thp_zero_page_alloc", meminfo has "zero", etc.) ---
  for _f in /proc/cpuinfo /proc/cmdline /proc/mtd /proc/partitions /proc/mounts /proc/version /proc/sys/kernel/hostname /proc/sys/kernel/ostype /proc/sys/kernel/machine /proc/self/mounts /proc/self/cmdline /proc/self/status; do
    [ -f "$_f" ] || continue
    _RAW=$(grep -i -m1 -E "hardware[ :]|model[ :]|machine[ :]|board[ :]|rootsubdir=|machine=" "$_f" 2>/dev/null | head -1)
    [ -z "$_RAW" ] && continue
    _LOW=$(echo "$_RAW" | tr 'A-Z' 'a-z' | tr -d ' _-')
    _LOW=$(_detect_normalize_slug "$_LOW")
    [ "$_LOW" != "unknown" ] && [ -n "$_LOW" ] && echo "$_LOW" && return 0
  done
  for _f in /sys/class/dvb/dvb0.frontend0/name /sys/class/dvb/dvb0.demux0/name /sys/class/dvb/dvb0.dvr0/name /sys/class/dvb/dvb0.net0/name /sys/class/dvb/dvb0.ca0/name /sys/class/dvb/dvb0.audio0/name /sys/class/dvb/dvb0.video0/name /sys/class/dvb/dvb0.frontend1/name /sys/class/dvb/dvb0.frontend2/name /sys/class/dvb/dvb0.frontend3/name /sys/class/block/mmcblk0/device/name /sys/class/block/mmcblk0/device/model /sys/class/block/mmcblk0/device/manfid /sys/class/block/mmcblk0/device/oemid /sys/class/block/sda/device/model /sys/class/block/sda/device/vendor /sys/class/net/eth0/address /sys/class/net/eth0/device/modalias /sys/class/net/eth0/device/vendor /sys/class/net/eth0/device/device /sys/class/net/wlan0/address /sys/class/usb_device/usbdev1.1/product /sys/class/usb_device/usbdev1.1/manufacturer /sys/class/usb_device/usbdev1.1/serial /sys/class/leds/*/device_name /sys/class/firmware/timeout /sys/class/graphics/fb0/name /sys/class/graphics/fb0/modes /sys/class/input/input0/name /sys/class/input/input1/name /sys/class/input/input2/name /sys/class/input/input3/name /sys/class/input/input4/name /sys/class/input/input5/name /sys/class/input/input6/name /sys/class/input/input7/name /sys/class/input/input8/name /sys/class/input/input9/name /sys/class/input/input10/name /sys/class/input/input11/name /sys/class/input/input12/name /sys/class/input/input13/name /sys/class/input/input14/name /sys/class/input/input15/name /sys/class/input/input16/name /sys/class/input/input17/name /sys/class/input/input18/name /sys/class/input/input19/name /sys/class/input/input20/name; do
    [ -e "$_f" ] || continue
    _RAW=$(cat "$_f" 2>/dev/null | head -1 | tr -d '\0' | tr -d '\n\r')
    [ -n "$_RAW" ] && _LOW=$(echo "$_RAW" | tr 'A-Z' 'a-z' | tr -d ' _-') && _LOW=$(_detect_normalize_slug "$_LOW") && [ "$_LOW" != "unknown" ] && [ -n "$_LOW" ] && echo "$_LOW" && return 0
  done
  # --- Group 6: commands (uname, hostname, dmesg, lsusb, lspci, dmidecode, ip, ls) ---
  _RAW=$(hostname 2>/dev/null); [ -n "$_RAW" ] && _LOW=$(echo "$_RAW" | tr 'A-Z' 'a-z' | tr -d ' _-') && _LOW=$(_detect_normalize_slug "$_LOW") && [ "$_LOW" != "unknown" ] && echo "$_LOW" && return 0
  _RAW=$(uname -m 2>/dev/null); [ -n "$_RAW" ] && _LOW=$(echo "$_RAW" | tr 'A-Z' 'a-z' | tr -d ' _-') && _LOW=$(_detect_normalize_slug "$_LOW") && [ "$_LOW" != "unknown" ] && echo "$_LOW" && return 0
  _RAW=$(dmesg 2>/dev/null | grep -i -m1 -E "novaler|vuplus|dreambox|zgemma|octagon|uclan|edision|formuler|amiko|gigablue|xtrend|mutant|multibox|sf8008|ustym|machine|board|model"); [ -n "$_RAW" ] && _LOW=$(echo "$_RAW" | tr 'A-Z' 'a-z' | tr -d ' _-') && _LOW=$(_detect_normalize_slug "$_LOW") && [ "$_LOW" != "unknown" ] && echo "$_LOW" && return 0
  _RAW=$(lsusb 2>/dev/null | head -5 | tr '\n' ' '); [ -n "$_RAW" ] && _LOW=$(echo "$_RAW" | tr 'A-Z' 'a-z' | tr -d ' _-') && _LOW=$(_detect_normalize_slug "$_LOW") && [ "$_LOW" != "unknown" ] && echo "$_LOW" && return 0
  _RAW=$(lspci 2>/dev/null | head -5 | tr '\n' ' '); [ -n "$_RAW" ] && _LOW=$(echo "$_RAW" | tr 'A-Z' 'a-z' | tr -d ' _-') && _LOW=$(_detect_normalize_slug "$_LOW") && [ "$_LOW" != "unknown" ] && echo "$_LOW" && return 0
  _RAW=$(dmidecode -s system-product-name 2>/dev/null); [ -n "$_RAW" ] && _LOW=$(echo "$_RAW" | tr 'A-Z' 'a-z' | tr -d ' _-') && _LOW=$(_detect_normalize_slug "$_LOW") && [ "$_LOW" != "unknown" ] && echo "$_LOW" && return 0
  _RAW=$(cat /sys/class/dmi/id/product_name 2>/dev/null); [ -n "$_RAW" ] && _LOW=$(echo "$_RAW" | tr 'A-Z' 'a-z' | tr -d ' _-') && _LOW=$(_detect_normalize_slug "$_LOW") && [ "$_LOW" != "unknown" ] && echo "$_LOW" && return 0
  _RAW=$(cat /sys/class/dmi/id/board_name 2>/dev/null); [ -n "$_RAW" ] && _LOW=$(echo "$_RAW" | tr 'A-Z' 'a-z' | tr -d ' _-') && _LOW=$(_detect_normalize_slug "$_LOW") && [ "$_LOW" != "unknown" ] && echo "$_LOW" && return 0
  _RAW=$(cat /sys/class/dmi/id/sys_vendor 2>/dev/null); [ -n "$_RAW" ] && _LOW=$(echo "$_RAW" | tr 'A-Z' 'a-z' | tr -d ' _-') && _LOW=$(_detect_normalize_slug "$_LOW") && [ "$_LOW" != "unknown" ] && echo "$_LOW" && return 0
  _RAW=$(ls /proc/stb/info/ 2>/dev/null | tr '\n' ' '); [ -n "$_RAW" ] && _LOW=$(echo "$_RAW" | tr 'A-Z' 'a-z' | tr -d ' _-') && _LOW=$(_detect_normalize_slug "$_LOW") && [ "$_LOW" != "unknown" ] && echo "$_LOW" && return 0
  _RAW=$(ls /usr/share/enigma2/ 2>/dev/null | tr '\n' ' '); [ -n "$_RAW" ] && _LOW=$(echo "$_RAW" | tr 'A-Z' 'a-z' | tr -d ' _-') && _LOW=$(_detect_normalize_slug "$_LOW") && [ "$_LOW" != "unknown" ] && echo "$_LOW" && return 0
  echo "unknown"
}
