detect_image() {
  IMG=""
  for _f in /etc/image-version /etc/issue /etc/os-release /etc/enigma2/settings; do
    [ -f "$_f" ] && IMG="$IMG $(cat "$_f" 2>/dev/null | tr '\n' ' ')"
  done
  IMG_LOWER=$(echo "$IMG" | tr 'A-Z' 'a-z')
  case "$IMG_LOWER" in
    *openatv*|*atv*) echo "OpenATV (ATV)"; return 0 ;;
    *openpli*|*pli*) echo "OpenPLi (PLi)"; return 0 ;;
    *openvix*|*vix*) echo "OpenViX (VIX)"; return 0 ;;
    *blackhole*|*black*hole*) echo "BlackHole (BH)"; return 0 ;;
    *teamblue*|*team*blue*) echo "TeamBlue (TeamBlue)"; return 0 ;;
    *egami*) echo "Egami"; return 0 ;;
    *pur*|*pure2*) echo "PurE2 (PUR)"; return 0 ;;
    *spa*|*openspa*) echo "OpenSPA (SPA)"; return 0 ;;
    *openbh*) echo "OpenBH (BH)"; return 0 ;;
    *opendroid*) echo "OpenDroid"; return 0 ;;
    *openvision*) echo "OpenVision"; return 0 ;;
    *satdreamgr*) echo "SatDreamGr"; return 0 ;;
    *openhdf*) echo "OpenHDF"; return 0 ;;
    *openesi*) echo "OpenESI"; return 0 ;;
    *dreamos*|*dreambox*os*|*dream*os*) echo "DreamOS"; return 0 ;;
    *dreambox*) echo "DreamOS"; return 0 ;;
    *) echo "[WARN] Unknown image - please choose:" >&2; echo "1) OpenATV  2) OpenPLi  3) OpenViX  4) OpenBH  5) OpenSPA  6) PurE2  7) TeamBlue  8) Egami" >&2; printf "Your choice [1]: " >&2; read _ic < /dev/tty 2>/dev/null || read _ic; case "$_ic" in 2) echo "OpenPLi (PLi)" ;; 3) echo "OpenViX (VIX)" ;; 4) echo "OpenBH (BH)" ;; 5) echo "OpenSPA (SPA)" ;; 6) echo "PurE2 (PUR)" ;; 7) echo "TeamBlue (TeamBlue)" ;; 8) echo "Egami" ;; *) echo "OpenATV (ATV)" ;; esac ;;
  esac
}
# V22.7: DreamOS = apt/dpkg image (no opkg). Detect from IMAGE, /etc files, or apt present + opkg absent.
is_dreamos() {
  case "$IMAGE" in *DreamOS*|*Dreambox*) return 0 ;; esac
  [ -f /etc/dreambox-version ] && return 0
  grep -qi "dream" /etc/os-release 2>/dev/null && return 0
  grep -qi "dreamos" /etc/image-version 2>/dev/null && return 0
  if command -v apt-get >/dev/null 2>&1 && ! command -v opkg >/dev/null 2>&1 && command -v dpkg >/dev/null 2>&1; then return 0; fi
  return 1
}
get_aglare() {
  case "$IMAGE" in
    *PLi*|*VIX*|*BH*|*TeamBlue*|*BlackHole*|*OpenBH*) echo "Aglare PLI" ;;
    *) echo "Aglare-FHD" ;;
  esac
}
BOX=$(detect_box); IMAGE=$(detect_image); AGLARE=$(get_aglare)
get_backup_group() {
  case "$IMAGE" in
    *ATV*|*Egami*|*SPA*) echo "ATV-Egami-SPA" ;;
    *BH*|*BlackHole*|*OpenBH*|*VIX*|*ViX*|*PLi*) echo "BH-VIX-PLi" ;;
    *DreamOS*|*Dreambox*) echo "DreamOS" ;;
    *PUR*|*PurE2*) echo "PUR" ;;
    *TeamBlue*) echo "TeamBlue" ;;
    *Vision*) echo "Vision" ;;
    *HDF*) echo "HDF" ;;
    *ESI*) echo "ESI" ;;
    *Droid*) echo "Droid" ;;
    *SatDreamGr*) echo "SatDreamGr" ;;
    *) echo "ATV-Egami-SPA" ;;
  esac
}
BK=$(get_backup_group)
BKDIR="$UPANEL_ROOT-Backup-$BK"

# Plugins Backup/Restore - per IMAGE + Python (auto, no choice)
# V20.1: ONE unified folder: U-Panel-Backup-<IMAGE>/Python<MM>/{plugins,files} - old trees kept as fallback
get_plugins_backup_dir() {
  [ -z "$UPANEL_ROOT" ] && UPANEL_ROOT="$BACKUP_ROOT/U-Panel"
  _IMG_FOLDER=$(echo "$IMAGE" | tr ' ' '_' | tr -d '()' | tr -d '/')
  [ -z "$_IMG_FOLDER" ] && _IMG_FOLDER="Unknown"
  _NEW="$UPANEL_ROOT-Backup-$_IMG_FOLDER/Python$PY_MM/plugins"
  _OLD="$UPANEL_ROOT-Plugins-Backup-$_IMG_FOLDER/Python$PY_MM"
  if [ ! -d "$_NEW" ] && [ -d "$_OLD" ]; then echo "$_OLD"; else echo "$_NEW"; fi
}

# Files Backup/Restore - per IMAGE + Python (auto, no choice, no group)
get_files_backup_dir() {
  [ -z "$UPANEL_ROOT" ] && UPANEL_ROOT="$BACKUP_ROOT/U-Panel"
  _IMG_FOLDER=$(echo "$IMAGE" | tr ' ' '_' | tr -d '()' | tr -d '/')
  [ -z "$_IMG_FOLDER" ] && _IMG_FOLDER="Unknown"
  _NEW="$UPANEL_ROOT-Backup-$_IMG_FOLDER/Python$PY_MM/files"
  _OLD="$UPANEL_ROOT-Backup-$_IMG_FOLDER/Python$PY_MM"
  if [ ! -d "$_NEW" ] && { [ -f "$_OLD/files_manifest.csv" ] || [ -d "$_OLD/enigma2" ]; }; then echo "$_OLD"; else echo "$_NEW"; fi
}
BKDIR="$(get_files_backup_dir)"  # Files: per IMAGE + Python (auto)
FAV_FILE="$UPANEL_ROOT-Favourite-$BK.conf"
SELECTED_ALL=""
# ===== Novaler detection - UNIVERSAL for ALL Novaler boxes =====
# Novaler lineup (all share the same brand): Multibox / Multibox SE / Multibox Pro /
# Multibox 4K / Multibox Pro 4K / Multibox Twin / Multibox SE 4K / any future "multibox*" / "novaler*"
# We NEVER rely on one name only: we check BOX + FULL_MACHINE + MACHINE + image-version machine +
# every /proc/stb/info/* field + device-tree + opkg arch. A new Novaler model that reports
# brand=novaler or machine=multibox* is detected automatically, no code update needed.
NOVALER_MACHINES="multibox multiboxse multiboxpro multibox4k multiboxpro4k multiboxse4k multiboxtwin multibox4ktwin novaler"
is_novaler() {
  _NL=$(echo "$BOX $FULL_MACHINE $MACHINE" | tr 'A-Z' 'a-z' | tr -d ' _-')
  case "$_NL" in *novaler*|*multibox*) return 0 ;; esac
  for _m in $NOVALER_MACHINES; do case "$_NL" in *"$_m"*) return 0 ;; esac; done
  # image-version: machine=multiboxpro / multiboxse / novaler ...
  if [ -f /etc/image-version ]; then
    _IM=$(grep -i '^machine=' /etc/image-version 2>/dev/null | cut -d= -f2 | tr 'A-Z' 'a-z' | tr -d ' _-\r')
    case "$_IM" in *novaler*|*multibox*) return 0 ;; esac
    for _m in $NOVALER_MACHINES; do case "$_IM" in *"$_m"*) return 0 ;; esac; done
  fi
  # Hardware truth: ANY /proc/stb/info/* field (brand/manufacturer/model/boxtype/machine/chipset/...)
  for _f in /proc/stb/info/*; do
    [ -f "$_f" ] || continue
    _V=$(cat "$_f" 2>/dev/null | tr 'A-Z' 'a-z' | tr -d ' _-\r\n')
    case "$_V" in *novaler*|*multibox*) return 0 ;; esac
  done
  # Device-tree / compatible
  for _f in /proc/device-tree/model /proc/device-tree/compatible /sys/firmware/devicetree/base/model; do
    [ -f "$_f" ] || continue
    grep -qi -E 'novaler|multibox' "$_f" 2>/dev/null && return 0
  done
  # opkg arch: enigma2-plugin-...-multiboxpro etc / arch multibox*
  if command -v opkg >/dev/null 2>&1; then
    opkg print-architecture 2>/dev/null | grep -qi -E 'novaler|multibox' && return 0
  fi
  return 1
}
