show_banner() {
  case "$UI_STYLE" in
    classic) clear; printf "${C_GOLD}==============================================================${C_RESET}\n"; printf "${C_GOLD}|${C_RESET}  ${C_ACCENT}U-Panel${C_RESET}  ${C_DIM}-${C_RESET}  ${C_ITEM}Control Enigma${C_RESET}  ${C_DIM}(${C_RESET}${C_ITEM}$_SCRIPT_VERSION${C_RESET}${C_DIM})${C_RESET}%s${C_GOLD}|${C_RESET}\n" ""; printf "${C_GOLD}|${C_RESET}  ${C_DIM}Box:${C_RESET} ${C_ITEM}$BOX${C_RESET}  ${C_DIM}| Image:${C_RESET} ${C_ITEM}$IMAGE${C_RESET}  ${C_DIM}| Python:${C_RESET} ${C_ITEM}$PYTHON_V${C_RESET}  ${C_GOLD}|${C_RESET}\n"; printf "${C_GOLD}==============================================================${C_RESET}\n"; return 0 ;;
    compact) clear; printf "${C_ACCENT}U-Panel${C_RESET} ${C_DIM}|${C_RESET} ${C_ITEM}$BOX${C_RESET} ${C_DIM}|${C_RESET} ${C_ITEM}$IMAGE${C_RESET} ${C_DIM}|${C_RESET} ${C_ITEM}$PYTHON_V${C_RESET} ${C_DIM}|${C_RESET} ${C_ITEM}$_SCRIPT_VERSION${C_RESET}\n"; return 0 ;;
    minimal) clear; return 0 ;;
  esac
  clear
  # V4.1 Banner H adaptive: width follows terminal (44..70); rows split when values do not fit
  _W=${COLUMNS:-0}
  case "$_W" in *[!0-9]*|"") _W=0;; esac
  if [ "$_W" -lt 44 ]; then
    _SZ=$(stty size 2>/dev/null); _W=${_SZ##* }
    case "$_W" in *[!0-9]*|"") _W=0;; esac
  fi
  if [ "$_W" -lt 44 ]; then _W=$(tput cols 2>/dev/null || echo 0); case "$_W" in *[!0-9]*|"") _W=0;; esac; fi
  [ "$_W" -gt 70 ] && _W=70
  [ "$_W" -lt 44 ] && _W=44
  _EQ=""; _i=$((_W-2)); while [ "$_i" -gt 0 ]; do _EQ="$_EQ═"; _i=$((_i-1)); done
  _DS=""; _i=$((_W-6)); while [ "$_i" -gt 0 ]; do _DS="$_DS─"; _i=$((_i-1)); done
  printf "${C_GOLD}╔%s╗${C_RESET}\n" "$_EQ"
  printf "${C_GOLD}║ ${C_RESET}${C_ACCENT}┌%s┐${C_RESET}${C_GOLD} ║${C_RESET}\n" "$_DS"
  _TC=$((_W-8))
  _TPAD=$((_TC-28))
  printf "${C_GOLD}║ ${C_RESET}${C_ACCENT}│  ${C_RESET}${C_GOLD}◆ U-Panel${C_RESET}  ${C_DIM}—${C_RESET}  ${C_ACCENT}Control Enigma${C_RESET}%${_TPAD}s${C_ACCENT}│${C_RESET}${C_GOLD} ║${C_RESET}\n" ""
  if [ "$_TC" -ge $((38 + ${#_SCRIPT_VERSION})) ]; then
    _SUB="Universal Edition  •  $_SCRIPT_VERSION  •  All Enigma2"
    _SLEN=$((38 + ${#_SCRIPT_VERSION}))
  else
    _SUB="Universal Edition  •  $_SCRIPT_VERSION"
    _SLEN=$((22 + ${#_SCRIPT_VERSION}))
  fi
  _SPAD=$((_TC - _SLEN))
  [ "$_SPAD" -lt 0 ] && _SPAD=0
  printf "${C_GOLD}║ ${C_RESET}${C_ACCENT}│  ${C_RESET}${C_DIM}%s${C_RESET}%${_SPAD}s${C_ACCENT}│${C_RESET}${C_GOLD} ║${C_RESET}\n" "$_SUB" ""
  printf "${C_GOLD}║ ${C_RESET}${C_ACCENT}└%s┘${C_RESET}${C_GOLD} ║${C_RESET}\n" "$_DS"
  _CW=$((_W-6))
  if [ $((30 + ${#BOX} + ${#IMAGE} + ${#PYTHON_V})) -le "$_CW" ]; then
    _BNR_PAD=$((_CW - 30 - ${#BOX} - ${#IMAGE} - ${#PYTHON_V}))
    printf "${C_GOLD}║  ${C_RESET}${C_DIM}Box:${C_RESET} ${C_ITEM}%s${C_RESET}  ${C_DIM}│  Image:${C_RESET} ${C_ITEM}%s${C_RESET}  ${C_DIM}│  Python:${C_RESET} ${C_ITEM}%s${C_RESET}%${_BNR_PAD}s${C_GOLD}  ║${C_RESET}\n" "$BOX" "$IMAGE" "$PYTHON_V" ""
  else
    _B1=$((_CW-5)); _V1=$(printf "%.*s" "$_B1" "$BOX"); _P1=$((_CW-5-${#_V1}))
    printf "${C_GOLD}║  ${C_RESET}${C_DIM}Box:${C_RESET} ${C_ITEM}%s${C_RESET}%${_P1}s${C_GOLD}  ║${C_RESET}\n" "$_V1" ""
    _B2=$((_CW-7)); _V2=$(printf "%.*s" "$_B2" "$IMAGE"); _P2=$((_CW-7-${#_V2}))
    printf "${C_GOLD}║  ${C_RESET}${C_DIM}Image:${C_RESET} ${C_ITEM}%s${C_RESET}%${_P2}s${C_GOLD}  ║${C_RESET}\n" "$_V2" ""
    _B3=$((_CW-8)); _V3=$(printf "%.*s" "$_B3" "$PYTHON_V"); _P3=$((_CW-8-${#_V3}))
    printf "${C_GOLD}║  ${C_RESET}${C_DIM}Python:${C_RESET} ${C_ITEM}%s${C_RESET}%${_P3}s${C_GOLD}  ║${C_RESET}\n" "$_V3" ""
  fi
  if [ $((45 + ${#BKDIR})) -le "$_CW" ]; then
    _BNR_PAD2=$((_CW - 45 - ${#BKDIR}))
    printf "${C_GOLD}║  ${C_RESET}${C_DIM}Backup:${C_RESET} ${C_DIM}%s${C_RESET}  ${C_DIM}│  Copyright: Eng Ahmed Abdel-Moati${C_RESET}%${_BNR_PAD2}s${C_GOLD}  ║${C_RESET}\n" "$BKDIR" ""
  else
    _B4=$((_CW-8))
    if [ "${#BKDIR}" -gt "$_B4" ]; then
      _TAIL=$(printf '%s' "$BKDIR" | tail -c "$((_B4-3))")
      _V4="...$_TAIL"
    else
      _V4="$BKDIR"
    fi
    _P4=$((_CW-8-${#_V4}))
    [ "$_P4" -lt 0 ] && _P4=0
    printf "${C_GOLD}║  ${C_RESET}${C_DIM}Backup:${C_RESET} ${C_DIM}%s${C_RESET}%${_P4}s${C_GOLD}  ║${C_RESET}\n" "$_V4" ""
    _P5=$((_CW-32))
    [ "$_P5" -lt 0 ] && _P5=0
    printf "${C_GOLD}║  ${C_RESET}${C_DIM}Copyright: Eng Ahmed Abdel-Moati${C_RESET}%${_P5}s${C_GOLD}  ║${C_RESET}\n" ""
  fi
  printf "${C_GOLD}╚%s╝${C_RESET}\n" "$_EQ"
}
