# ===== V22.0 OFFLINE MODE =====
# OFFLINE_MODE=1 => ZERO network calls: no opkg update, no wget/curl, no secure_fetch/secure_run.
# Cache layout (inside the SAME plugins backup dir, so it travels with the backup):
#   <PLUGINS_BKDIR>/offline-cache/packages/*.ipk
#   <PLUGINS_BKDIR>/offline-cache/footonsat/installer.sh
#   <PLUGINS_BKDIR>/offline-cache/bootlogo/<BootLogoFile>.tar.gz
#   <PLUGINS_BKDIR>/offline-cache/manifest.txt  (what was cached, what was missing)
OFFLINE_MODE="${OFFLINE_MODE:-0}"
offline_is_on() { [ "${OFFLINE_MODE:-0}" = "1" ]; }
offline_cache_dir() { if [ -n "${PLUGINS_BKDIR:-}" ]; then echo "$PLUGINS_BKDIR/offline-cache"; else echo "$(get_plugins_backup_dir 2>/dev/null)/offline-cache"; fi; }
offline_bootlogo_file() {
  case "$(get_bootlogo_by_image 2>/dev/null)" in
    VIX) echo "BootLogoVIX-Novaler.tar.gz" ;;
    SPA) echo "BootLogoSPA-Novaler.tar.gz" ;;
    PUR) echo "BootLogoPUR-Novaler.tar.gz" ;;
    Egami) echo "BootLogoEgami-Novaler.tar.gz" ;;
    BH) echo "BootLogoBH-Novaler.tar.gz" ;;
    TeamBlue) echo "BootLogoTeamBlue-Novaler.tar.gz" ;;
    *) echo "BootLogoATV-Novaler.tar.gz" ;;
  esac
}
# Cache everything Offline Restore needs - call ONLY while ONLINE, at backup time.
# V22.6: rebuild a valid .ipk from an ALREADY-INSTALLED package.
# Why: opkg download refuses already-installed pkgs and feed-renamed pkgs -> CACHE-MISS.
# How: control block from opkg status + file list from opkg files -> data.tar.gz + control.tar.gz + debian-binary -> ar .ipk
rebuild_ipk_from_installed() {
  _P="$1"; _OUT="$2"; [ -z "$_P" ] || [ -z "$_OUT" ] && return 1
  command -v ar >/dev/null 2>&1 || command -v busybox >/dev/null 2>&1 && busybox ar --help >/dev/null 2>&1 || { echo "  [REBUILD-SKIP] $_P: no ar tool"; return 1; }
  _AR="ar"; command -v ar >/dev/null 2>&1 || _AR="busybox ar"
  _STATUS=""; for _sf in /usr/lib/opkg/status /var/lib/opkg/status /etc/opkg/status; do [ -f "$_sf" ] && _STATUS="$_sf" && break; done
  [ -z "$_STATUS" ] && { echo "  [REBUILD-SKIP] $_P: no opkg status"; return 1; }
  _TMPD="/tmp/rebuild_ipk_$$"; rm -rf "$_TMPD"; mkdir -p "$_TMPD/data" "$_TMPD/control"
  # control: Package/Version/Architecture/Depends/Description from status block
  awk -v pkg="$_P" 'BEGIN{inb=0} /^Package: /{inb=($2==pkg)} inb && /^Package:|^Version:|^Architecture:|^Depends:|^Description:|^Maintainer:|^Section:|^Priority:/{print} inb && /^$/{exit}' "$_STATUS" > "$_TMPD/control/control" 2>/dev/null
  grep -q "^Package: $_P" "$_TMPD/control/control" 2>/dev/null || { rm -rf "$_TMPD"; echo "  [REBUILD-SKIP] $_P: not in status (not installed)"; return 1; }
  # files: opkg files output, lines starting with space
  # V23.0: OpenATV opkg files prints files as '/path' with NO leading space (old code wanted '^ ' -> always empty -> REBUILD-SKIP)
  opkg files "$_P" 2>/dev/null | grep "^/" > "$_TMPD/filelist.txt" 2>/dev/null
  if [ ! -s "$_TMPD/filelist.txt" ]; then opkg files "$_P" 2>/dev/null | grep "^ " | sed 's/^ //' > "$_TMPD/filelist.txt" 2>/dev/null; fi
  [ -s "$_TMPD/filelist.txt" ] || { rm -rf "$_TMPD"; echo "  [REBUILD-SKIP] $_P: no file list"; return 1; }
  while IFS= read -r _f; do [ -f "$_f" ] || [ -L "$_f" ] || continue; _d="$_TMPD/data$(dirname "$_f")"; mkdir -p "$_d" 2>/dev/null; cp -a "$_f" "$_d/" 2>/dev/null; done < "$_TMPD/filelist.txt"
  (cd "$_TMPD/data" && tar -czf "$_TMPD/data.tar.gz" . 2>/dev/null) || { rm -rf "$_TMPD"; return 1; }
  (cd "$_TMPD/control" && tar -czf "$_TMPD/control.tar.gz" . 2>/dev/null) || { rm -rf "$_TMPD"; return 1; }
  echo "2.0" > "$_TMPD/debian-binary"
  (cd "$_TMPD" && $_AR r "$_OUT" debian-binary control.tar.gz data.tar.gz >/dev/null 2>&1) || { rm -rf "$_TMPD"; return 1; }
  [ -s "$_OUT" ] && { echo "  [REBUILD-OK] $_P -> $_OUT (from installed files)"; rm -rf "$_TMPD"; return 0; }
  rm -rf "$_TMPD"; return 1
}
# V23.0: BusyBox od does NOT support -An (seen on Novaler/OpenATV: 'od: invalid option -- A').
# Check gzip magic (1f 8b) with python3, fallback to gzip -t. No od anywhere.
is_gzip_file() {
  _F="$1"; [ -f "$_F" ] || return 1
  if command -v python3 >/dev/null 2>&1; then python3 -c "import sys; d=open(sys.argv[1],'rb').read(2); sys.exit(0 if d==b'\x1f\x8b' else 1)" "$_F" 2>/dev/null && return 0; return 1; fi
  gzip -t "$_F" 2>/dev/null && return 0; return 1
}
# V23.0 FIX: ls with MULTIPLE globs fails if ANY glob misses - even when one matches.
# So a rebuilt file was printed REBUILD-OK then counted CACHE-MISS. This helper = ANY match wins.
pkg_cached() {
  _D="$1"; _P="$2"
  for _G in "$_D/${_P}_"*.ipk "$_D/${_P}-"*.ipk "$_D/${_P}.ipk" "$_D/${_P}_"*.deb "$_D/${_P}-"*.deb; do [ -e "$_G" ] && return 0; done
  return 1
}
cache_offline_assets() {
  # V35: was writing cache with NO space check - HDD could fill mid-download -> partial/corrupt files.
  check_hdd_space "Offline Cache" || return 1
  line; info "Offline Cache - saving .ipk + FootOnSat + BootLogo (ONLINE, once)"
  _OC="$(offline_cache_dir)"; mkdir -p "$_OC/packages" "$_OC/footonsat" "$_OC/bootlogo"
  { echo "Date: $(date)"; echo "Image: $IMAGE"; echo "Python: $PYTHON_V"; echo "BootLogo: $(get_bootlogo_by_image 2>/dev/null) / $(offline_bootlogo_file)"; } > "$_OC/manifest.txt"
  _OK=0; _MISS=""
  # V22.1 FIX 1: opkg download NEEDS a fresh feed list first - without opkg update, EVERY package missed.
  # V6.20 FIX - screenshot 25 Nov 05:59: opkg update rc=255 (opkg lock held / feed down) then the
  # loop still ran Tier1+Tier2 opkg download/install for ALL 45 PACKAGESPY3 - every one of them
  # fails the same way, each with its own network/lock wait, so the WebUI sat "stuck" on
  # "Offline Cache" long AFTER the plugins backup itself had already finished (manifest +
  # plugins.tar.gz + skins_full.tar.gz were all done at 05:59). Cache is OPTIONAL - it must
  # never block publishing the backup. If the feed is down, skip the whole cache fast.
  _FEED_OK=1
  if command -v opkg >/dev/null 2>&1; then echo "  [CACHE] opkg update first (feed list)..."; timeout 60 opkg update > /tmp/upanel_cache_opkg_update.log 2>&1; _OURC=$?; echo "  [CACHE] opkg update rc=$_OURC"; if [ "$_OURC" != "0" ]; then echo "  [CACHE-SKIP] opkg update FAILED (rc=$_OURC - feed down or opkg lock held by another process) - skipping Offline Cache, backup itself is already complete"; tail -n 3 /tmp/upanel_cache_opkg_update.log 2>/dev/null; return 0; fi; fi
  for _P in $PACKAGESPY3; do
    if pkg_cached "$_OC/packages" "$_P"; then _OK=$((_OK+1)); continue; fi
    if command -v opkg >/dev/null 2>&1; then
      # Tier 1: plain download (works when pkg is in feed + not installed)
      (cd "$_OC/packages" && timeout 60 opkg download "$_P" >/dev/null 2>&1)
      # Tier 2: force download-only install (works when pkg IS already installed)
      if ! pkg_cached "$_OC/packages" "$_P"; then (cd "$_OC/packages" && timeout 60 opkg install --download-only --force-reinstall "$_P" >/dev/null 2>&1); fi
      if ! pkg_cached "$_OC/packages" "$_P"; then (cd "$_OC/packages" && timeout 60 opkg install --download-only --force-downgrade "$_P" >/dev/null 2>&1); fi
      # Tier 3 (V22.6): rebuild .ipk from the INSTALLED package on this box - cache from the
      # packages actually installed by this script / on this image, not from the feed only.
      if ! pkg_cached "$_OC/packages" "$_P"; then
        _VER=$(opkg list-installed "$_P" 2>/dev/null | awk '{print $3}' | head -1); [ -z "$_VER" ] && _VER="1.0"
        rebuild_ipk_from_installed "$_P" "$_OC/packages/${_P}_${_VER}_all.ipk" 2>/dev/null
      fi
      # Tier 4 (V22.7 DreamOS/apt): only if opkg tiers found nothing AND this is an apt image.
      if ! pkg_cached "$_OC/packages" "$_P" && is_dreamos; then
        echo "  [CACHE-APT] $_P: DreamOS detected - trying apt download / dpkg-repack..."
        (cd "$_OC/packages" && apt-get update >/dev/null 2>&1; apt-get download "$_P" >/dev/null 2>&1)
        if ! pkg_cached "$_OC/packages" "$_P" && command -v dpkg-repack >/dev/null 2>&1 && dpkg -l "$_P" 2>/dev/null | grep -q "^ii"; then
          (cd "$_OC/packages" && dpkg-repack "$_P" >/dev/null 2>&1) && echo "  [REBUILD-OK] $_P -> .deb (dpkg-repack from installed)"
        fi
      fi
      if pkg_cached "$_OC/packages" "$_P"; then _OK=$((_OK+1)); echo "  [CACHE-OK] $_P"; else _MISS="$_MISS $_P"; echo "  [CACHE-MISS] $_P (not in feed + not installed - nothing to cache from)"; fi
    fi
    # V22.7: apt-only image (no opkg at all) - the opkg block above never ran, so cache via apt here.
    if ! command -v opkg >/dev/null 2>&1 && is_dreamos; then
      if ! pkg_cached "$_OC/packages" "$_P"; then (cd "$_OC/packages" && apt-get update >/dev/null 2>&1; apt-get download "$_P" >/dev/null 2>&1); fi
      if ! pkg_cached "$_OC/packages" "$_P" && command -v dpkg-repack >/dev/null 2>&1 && dpkg -l "$_P" 2>/dev/null | grep -q "^ii"; then (cd "$_OC/packages" && dpkg-repack "$_P" >/dev/null 2>&1) && echo "  [REBUILD-OK] $_P -> .deb (dpkg-repack from installed)"; fi
      if pkg_cached "$_OC/packages" "$_P"; then _OK=$((_OK+1)); echo "  [CACHE-OK] $_P (.deb)"; else _MISS="$_MISS $_P"; echo "  [CACHE-MISS] $_P (apt: not in feed + not installed)"; fi
    fi
  done
  # V23.0: was single wget (one fail = CACHE-MISS). Now secure_fetch: 3 tries + curl fallback.
  if secure_fetch "https://dreambox4u.com/emilnabil237/plugins/FootOnsat/installer.sh" "$_OC/footonsat/installer.sh" "FootOnSat-installer" ""; then echo "  [CACHE-OK] FootOnSat installer.sh"; else _MISS="$_MISS FootOnSat-installer"; echo "  [CACHE-MISS] FootOnSat installer.sh (dreambox4u unreachable 3x - check net / server)"; rm -f "$_OC/footonsat/installer.sh"; fi
  # V22.1 FIX 2: BootLogo on GitHub is Git-LFS - raw.githubusercontent returns a TEXT POINTER, not gzip.
  # secure_fetch rightly rejects it. So: plain wget -> if pointer, try github.com/raw -> if still pointer, cache the LIVE bootlogo from this box.
  _BLF="$(offline_bootlogo_file)"; _BL_OK=0
  for _BL_URL in "https://raw.githubusercontent.com/ah40mee-blip/AllScript-Universal/main/$_BLF" "https://github.com/ah40mee-blip/AllScript-Universal/raw/main/$_BLF" "https://media.githubusercontent.com/media/ah40mee-blip/AllScript-Universal/main/$_BLF"; do
    wget --no-check-certificate --timeout=20 -O "$_OC/bootlogo/$_BLF" "$_BL_URL" 2>/dev/null
    if [ -s "$_OC/bootlogo/$_BLF" ] && ! grep -q "git-lfs" "$_OC/bootlogo/$_BLF" 2>/dev/null; then
      if is_gzip_file "$_OC/bootlogo/$_BLF"; then echo "  [CACHE-OK] BootLogo $_BLF from $_BL_URL"; _BL_OK=1; break; fi
    fi
    rm -f "$_OC/bootlogo/$_BLF"
  done
  if [ "$_BL_OK" != "1" ]; then
    echo "  [CACHE] BootLogo GitHub gave LFS pointer / not gzip - falling back to LIVE bootlogo from this box"
    # Live bootlogo files on Enigma2: /boot/bootlogo.mvi, /usr/share/bootlogo.mvi, /boot/*.mvi, /usr/share/enigma2/*.mvi
    (cd / && tar -czf "$_OC/bootlogo/$_BLF" boot/bootlogo.mvi boot/*.mvi usr/share/bootlogo.mvi usr/share/enigma2/bootlogo.mvi 2>/dev/null)
    if [ -s "$_OC/bootlogo/$_BLF" ]; then echo "LIVE-BOOTLOGO - captured from this box, not from GitHub" > "$_OC/bootlogo/LIVE-BOOTLOGO.txt"; echo "  [CACHE-OK] BootLogo $_BLF (LIVE from this box)"; _BL_OK=1; else _MISS="$_MISS BootLogo-$_BLF"; echo "  [CACHE-MISS] BootLogo $_BLF (no GitHub gzip + no live .mvi found)"; rm -f "$_OC/bootlogo/$_BLF"; fi
  fi
  echo "Cached packages: $_OK / Missing:$_MISS" | tee -a "$_OC/manifest.txt"
  echo "[OFFLINE-CACHE] Done - cache lives inside this backup: $_OC"
  echo "[OFFLINE-CACHE] MISSING .ipk = package not in feed (usually already in the fresh image) - Offline Restore will SKIP it, not fail."
}
# Offline install helper: install one package from cache only, never from feed.
offline_install_pkg() {
  _P="$1"
  _DEB=$(ls "$(offline_cache_dir)/packages/${_P}_"*.deb "$(offline_cache_dir)/packages/${_P}-"*.deb "$(offline_cache_dir)/packages/${_P}.deb" 2>/dev/null | head -1)
  if [ -n "$_DEB" ] && [ -f "$_DEB" ] && command -v dpkg >/dev/null 2>&1; then echo "  [OFFLINE] Installing from cache (.deb): $_DEB"; dpkg -i "$_DEB" 2>&1 | tail -n 2; return 0; fi
  _IPK=$(ls "$(offline_cache_dir)/packages/${_P}_"*.ipk "$(offline_cache_dir)/packages/${_P}-"*.ipk "$(offline_cache_dir)/packages/${_P}.ipk" 2>/dev/null | head -1)
  if [ -n "$_IPK" ] && [ -f "$_IPK" ]; then echo "  [OFFLINE] Installing from cache: $_IPK"; opkg install "$_IPK" 2>&1 | tail -n 2; return 0; fi
  echo "  [OFFLINE-SKIP] $_P - no cached .ipk/.deb (was installed at backup time or not in feed)"; return 1
}

install_packages() {
  setup_reboot_guard "Packages"
  line; info "Installing Packages..."
  echo "[Packages] Python: $PYTHON_V - Image: $IMAGE"
  if offline_is_on; then
    echo "[OFFLINE] Packages - NO opkg update, NO feed - installing ONLY from offline-cache/*.ipk"
    for PACKAGE in $PACKAGESPY3; do
      if is_installed "$PACKAGE"; then echo "Package $PACKAGE already installed, skipping..."; else offline_install_pkg "$PACKAGE" || true; fi
    done
    sync; ok "Packages (OFFLINE) Done - cached only, no net - No Reboot"; return 0
  fi
  # V23.0 CACHE-DIAG-FIX: (1) BusyBox od -A unsupported -> python3 magic check, (2) opkg files on OpenATV has NO leading space -> parse ^/ lines, (3) FootOnSat via secure_fetch 3 tries + curl fallback, (4) cache logs opkg update rc + one sample download error.
# V22.9 NO-BACKUP-SUBMENU: Backup submenu removed. Main menu: 5) Backup Ur Data (= old All), 6) Backup Ur Files (= files only). Renumbered 7-12.
# V22.8 RENAME: Full Restore -> Smart Restore, Custom Restore -> Custom Restore, no parenthetical text beside them.
# V22.7 DREAMOS-APT: DreamOS/apt Tier 4 - apt download + dpkg-repack rebuild .deb, offline_install_pkg handles .deb via dpkg.
# V22.6 CACHE-MISS-FIX: cache_offline_assets 3-tier (download -> download-only --force-reinstall -> rebuild .ipk from installed pkg). Fixes CACHE-MISS for already-installed / feed-missing packages.
# V22.5 SETUP-CACHE-PER-IMAGE: Setup-Cache + Hash-Pin per IMAGE + Python (like Backup-Cache), auto-migrate old Group cache.
# V22.4 SMART-ALL: Custom Restore + Setup-Cache (every secure_run installer cached at Setup time, Favourite replays from cache if net fails) + Files Oscam Smart.
# V22.3 SMART-RESTORE: renamed Smart Restore -> Smart Restore. Same unified logic.
# V22.2 SMART-RESTORE: try ONLINE first - if opkg update fails, fall back to cache, never stop.
  echo "[SMART] Packages - trying ONLINE first, cache fallback if net fails"
  _PKG_ONLINE=1
  if command -v opkg >/dev/null 2>&1; then opkg update >/dev/null 2>&1 || _PKG_ONLINE=0; elif command -v apt-get >/dev/null 2>&1; then apt-get update >/dev/null 2>&1 || _PKG_ONLINE=0; fi
  if [ "$_PKG_ONLINE" != "1" ]; then
    echo "[SMART-FALLBACK] Packages - opkg update FAILED (no net / feed down) - continuing from offline-cache/*.ipk"
    for PACKAGE in $PACKAGESPY3; do
      if is_installed "$PACKAGE"; then echo "Package $PACKAGE already installed, skipping..."; else offline_install_pkg "$PACKAGE" || true; fi
    done
    sync; ok "Packages (SMART-FALLBACK, cache) Done - No Reboot"; return 0
  fi
  echo "Python3 image - Using PACKAGESPY3 (V20: PY2 branch removed - PY2 exits at startup)"
  for PACKAGE in $PACKAGESPY3; do
    if is_installed "$PACKAGE"; then echo "Package $PACKAGE already installed, skipping..."; else echo "Installing package $PACKAGE..."; opkg_with_retry "$PACKAGE" || { echo "  [SMART-FALLBACK] $PACKAGE feed install failed - trying cache"; offline_install_pkg "$PACKAGE" || true; }; echo "Done: $PACKAGE"; fi
  done
  sync
  ok "Packages Installed - No Reboot"
}
