uninstall_plugin_by_num() {
  N=$1; NAME=$(plugin_name_by_num $N); [ -z "$NAME" ] && echo "[ERROR] No plugin $N" && return 1
  echo "Uninstall [$N] $NAME ? (y/n): "; read _u; case "$_u" in y|Y) ;; *) echo "Cancelled"; return 0 ;; esac
  rm -rf "/usr/lib/enigma2/python/Plugins/Extensions/$NAME" 2>/dev/null
  opkg remove "enigma2-plugin-extensions-$NAME" "enigma2-plugin-*$NAME" 2>/dev/null
  apt-get remove -y "*$NAME*" 2>/dev/null
  find /usr/lib/enigma2/python/Plugins/Extensions -name "*.pyc" -delete 2>/dev/null
  echo "[OK] Uninstalled $NAME - restart Enigma to apply (init 3)"; log_msg "Uninstalled plugin $NAME"
}
uninstall_plugin_menu() {
  echo "Installed plugins:"; ls /usr/lib/enigma2/python/Plugins/Extensions/ 2>/dev/null
  printf "Plugin number to uninstall (1-47) or 0 to go back: "; read _un
  [ "$_un" = "0" ] && return 0; uninstall_plugin_by_num "$_un"
}
# V36: Update = FORCE REINSTALL from the plugin's own telnet command, IGNORING dependencies.
#   Built-in: re-run install_plugin_by_num (its installer URL / opkg command) even if already installed.
#   Custom: re-run the saved telnet command from custom_file().
#   "Ignore dependencies" is real, not a label: every command runs with a temporary opkg shim first in PATH
#   that rewrites `opkg install X` -> `opkg install --force-depends --force-reinstall --force-overwrite X`.
#   Installer scripts that call bare `opkg` pick up the shim via PATH. Shim is removed right after, PATH restored.
#   Custom commands are DATA (blocked patterns still refused by custom_run_by_num) - they can never touch the script.
with_no_deps() {
  _ND_DIR="/tmp/upanel_no_deps_$$"; rm -rf "$_ND_DIR"; mkdir -p "$_ND_DIR"
  _ND_REAL="$(command -v opkg 2>/dev/null)"
  if [ -n "$_ND_REAL" ]; then
    printf '%s\n' '#!/bin/sh' 'if [ "$1" = "install" ]; then shift; exec "$OPKG_REAL" install --force-depends --force-reinstall --force-overwrite "$@" ; fi' 'exec "$OPKG_REAL" "$@"' > "$_ND_DIR/opkg"
    chmod +x "$_ND_DIR/opkg" 2>/dev/null
    _ND_OLD_PATH="$PATH"; PATH="$_ND_DIR:$PATH"; OPKG_REAL="$_ND_REAL"; export PATH OPKG_REAL
    echo "  [NO-DEPS] opkg shim ON - dependencies ignored for this install"
  else echo "  [NO-DEPS] no opkg on this image - installer runs as-is"; fi
  "$@"; _ND_RC=$?
  if [ -n "$_ND_REAL" ]; then PATH="$_ND_OLD_PATH"; unset OPKG_REAL; export PATH; echo "  [NO-DEPS] opkg shim OFF - PATH restored"; fi
  rm -rf "$_ND_DIR"; return $_ND_RC
}
force_reinstall_plugin_by_num() {
  _FR_N="$1"; _FR_NAME="$(plugin_name_by_num "$_FR_N")"; [ -z "$_FR_NAME" ] && { echo "[ERROR] No plugin $_FR_N"; return 1; }
  echo "------------------------------------------------------------"
  echo "[FORCE-REINSTALL] $_FR_NAME - from its telnet/installer command - dependencies IGNORED"
  echo "------------------------------------------------------------"
  setup_reboot_guard "Force Reinstall $_FR_NAME"
  with_no_deps install_plugin_by_num "$_FR_N"; _FR_RC=$?
  echo "[FORCE-REINSTALL] $_FR_NAME done (rc=$_FR_RC)"
  log_msg "Force reinstall (no-deps): $_FR_NAME rc=$_FR_RC"
  return $_FR_RC
}
force_reinstall_custom_by_num() {
  _FR_C="$1"; _FR_LINE="$(custom_get_by_num "$_FR_C")"; [ -z "$_FR_LINE" ] && { echo "No custom plugin C$_FR_C"; return 1; }
  _FR_NAME="$(echo "$_FR_LINE" | cut -f2)"
  echo "------------------------------------------------------------"
  echo "[FORCE-REINSTALL] $_FR_NAME (Custom C$_FR_C) - from its saved telnet command - dependencies IGNORED"
  echo "------------------------------------------------------------"
  with_no_deps custom_run_by_num "$_FR_C"; _FR_RC=$?
  echo "[FORCE-REINSTALL] $_FR_NAME done (rc=$_FR_RC)"
  log_msg "Force reinstall custom (no-deps): $_FR_NAME rc=$_FR_RC"
  return $_FR_RC
}
update_installed_plugins() {
  # Picker: only INSTALLED plugins are offered (built-in folder exists / custom folder exists).
  # Pick numbers / C-numbers / all - each is force-reinstalled from its own telnet command, deps ignored.
  while true; do
    show_banner; menu_head "Update Plugins - Force Reinstall (dependencies ignored)"
    menu_head "Re-runs each plugin's own telnet/installer command - even if already installed"
    menu_sep
    _UPD_LIST=""; _UPD_CUSTOM=""
    for _i in $(seq 1 47); do
      _pn=$(plugin_name_by_num $_i)
      if [ -d "/usr/lib/enigma2/python/Plugins/Extensions/$_pn" ]; then menu_item_o "[$_i] $_pn"; _UPD_LIST="$_UPD_LIST $_i"; fi
    done
    _CFU=$(custom_file)
    if [ -f "$_CFU" ]; then
      _ci=0
      while IFS=$(printf '\t') read -r _ccat _cname _ccmd; do
        [ -z "$_cname" ] && continue; _ci=$((_ci+1))
        if [ -d "/usr/lib/enigma2/python/Plugins/Extensions/$_cname" ]; then menu_item_o "[C$_ci] $_cname (Custom)"; _UPD_CUSTOM="$_UPD_CUSTOM C$_ci"; fi
      done < "$_CFU"
    fi
    [ -z "$(echo "$_UPD_LIST $_UPD_CUSTOM" | tr -d ' ')" ] && menu_footer "No installed plugins found"
    menu_bot
    menu_footer "Pick: numbers / C-numbers - Example: 3 12 C2  |  all = force-reinstall everything  |  0 = back"
    printf "Your choice: "; read _up || return 0
    case "$_up" in
      0) return 0 ;;
      all) for _u in $_UPD_LIST; do force_reinstall_plugin_by_num "$_u"; done; for _u in $_UPD_CUSTOM; do force_reinstall_custom_by_num "$(echo "$_u" | tr -d 'C')"; done; echo "[OK] Force-reinstalled all installed plugins"; printf "Press ENTER... "; read _b ;;
      "") continue ;;
      *) for _u in $_up; do case "$_u" in C*|c*) force_reinstall_custom_by_num "$(echo "$_u" | tr -d 'Cc ')";; ''|*[!0-9]*) wrong_choice;; *) case " $_UPD_LIST " in *" $_u "*) force_reinstall_plugin_by_num "$_u";; *) echo "Plugin $_u is not installed - skipping";; esac;; esac; done; printf "Press ENTER... "; read _b ;;
    esac
  done
}
install_all_plugins() { i=1; for p in $PLUGINS; do install_plugin_by_num $i; i=$((i+1)); done; }
install_selected_basket() { if [ -z "$SELECTED_ALL" ]; then echo "No Plugins Selected"; return 0; fi; for n in $SELECTED_ALL; do install_plugin_by_num $n; done; }
show_category_menu() {
  CAT_LIST="$1"; CAT_TITLE="$2"
  while true; do
    show_banner
    menu_top
    menu_head "$CAT_TITLE"
    menu_sep
    _VISIBLE=0
    for n in $CAT_LIST; do
      NM=$(plugin_name_by_num $n)
      plugin_allowed_by_device $n || continue
      _VISIBLE=$((_VISIBLE+1))
      if is_selected $n; then menu_item_x "[$n] $NM"; else menu_item_o "[$n] $NM"; fi
    done
    _CATID=$(custom_cat_id_by_title "$CAT_TITLE")
    _CF2=$(custom_file)
    if [ -f "$_CF2" ]; then
      _ci=0
      while IFS=$(printf '\t') read -r _ccat _cname _ccmd; do
        [ -z "$_cname" ] && continue; _ci=$((_ci+1))
        if [ "$_ccat" = "$_CATID" ]; then menu_item_o "[C$_ci] $_cname (Custom)"; _VISIBLE=$((_VISIBLE+1)); fi
      done < "$_CF2"
    fi
    [ "$_VISIBLE" = "0" ] && menu_footer "No plugins for your device ($BOX) in this category"
    menu_bot
    show_basket
    menu_footer "To select press numbers - Example: 1 3"
    menu_footer "To go back press (b)  |  To go to Main press (0)"
    printf "Your choice: "; read _sel || return 0
    case "$_sel" in
      b|B) return 0 ;;
      0) return 0 ;;
      all) for n in $CAT_LIST; do plugin_allowed_by_device $n || continue; toggle_plugin $n; done; sleep 1 ;;
      "") continue ;;
      C*|c*)
        _cn=$(echo "$_sel" | tr -d 'Cc ' | tr -d 'Cc')
        case "$_cn" in ''|*[!0-9]*) wrong_choice ;; *) printf "Run custom plugin C$_cn? (y/n): "; read _cry; case "$_cry" in y|Y) custom_run_by_num "$_cn" ;; *) echo "Cancelled" ;; esac; sleep 1 ;; esac ;;
      *) for n in $_sel; do case "$n" in ''|*[!0-9]*) wrong_choice ;; *) toggle_plugin $n ;; esac; done; sleep 1 ;;
    esac
  done
}
show_plugins_menu() {
  setup_reboot_guard "Plugins Menu"
  while true; do
    show_banner
    menu_top
    menu_head "Plugins"
    menu_sep
    # V36/V37: categories are ONLY 01-10. Actions live OUTSIDE the category list, under their own header,
    # so nobody mistakes them for a category. V37: Actions are LETTERS (U/P/A), not numbers.
    # Counts add custom plugins per category: base count + customs in that category.
    _CCF=$(custom_file); _C1=0; _C2=0; _C3=0; _C4=0; _C5=0; _C6=0; _C7=0; _C8=0; _C9=0; _C10=0
    if [ -f "$_CCF" ]; then while IFS=$(printf '\t') read -r _ccat _cname _ccmd; do [ -z "$_cname" ] && continue; case "$_ccat" in 1) _C1=$((_C1+1));; 2) _C2=$((_C2+1));; 3) _C3=$((_C3+1));; 4) _C4=$((_C4+1));; 5) _C5=$((_C5+1));; 6) _C6=$((_C6+1));; 7) _C7=$((_C7+1));; 8) _C8=$((_C8+1));; 9) _C9=$((_C9+1));; 10) _C10=$((_C10+1));; esac; done < "$_CCF"; fi
    menu_item "01) Streaming / IPTV ($((6+_C1)))"
    menu_item "02) Sport ($((4+_C2)))"
    menu_item "03) Sat and TV ($((9+_C3)))"
    menu_item "04) Subtitles ($((3+_C4)))"
    menu_item "05) Skins & UI ($((3+_C5)))"
    menu_item "06) Emu & Keys & Biss ($((2+_C6)))"
    menu_item "07) System & Tools ($((11+_C7)))"
    menu_item "08) Stores ($((5+_C8)))"
    menu_item "09) Islamic ($((2+_C9)))"
    menu_item "10) Multiboot ($((3+_C10)))"
    menu_sep
    # V40: "Actions - NOT categories" header REMOVED - the gold letters already separate them from the numbered categories.
    # V37/V40: Actions are LETTERS (U/P/A), not numbers - gold via menu_item, NO parenthetical text beside them.
    menu_item "U) Uninstall Plugins"
    menu_item "P) Update Plugins"
    menu_item "A) Add Plugin"
    menu_bot
    show_basket
    footer_all
    footer_cs
    footer_back
    printf "Your choice: "; read _c || return 0
    case "$_c" in
      1) show_category_menu "$CAT_STREAMING" "Streaming / IPTV" ;;
      2) show_category_menu "$CAT_SPORT" "Sport" ;;
      3) show_category_menu "$CAT_SATTV" "Sat and TV" ;;
      4) show_category_menu "$CAT_SUBS" "Subtitles" ;;
      5) show_category_menu "$CAT_SKIN" "Skins & UI" ;;
      6) show_category_menu "$CAT_EMU" "Emu & Keys & Biss" ;;
      7) show_category_menu "$CAT_SYSTEM" "System & Tools" ;;
      8) show_category_menu "$CAT_STORES" "Stores" ;;
      9) show_category_menu "$CAT_ISLAMIC" "Islamic" ;;
      10) show_category_menu "$CAT_MULTIBOOT" "Multiboot" ;;
      U|u) uninstall_plugin_menu ;;
      P|p) update_installed_plugins ;;
      A|a) custom_menu ;;
      all) SELECTED_ALL=""; for i in $(seq 1 47); do plugin_allowed_by_device $i || continue; SELECTED_ALL="$SELECTED_ALL $i"; done; SELECTED_ALL=$(echo $SELECTED_ALL); echo "All Selected - $(echo $SELECTED_ALL | wc -w) Plugins"; sleep 1 ;;
      c|C) SELECTED_ALL=""; echo "Basket Cleared"; sleep 1 ;;
      s|S) if [ -z "$SELECTED_ALL" ]; then echo "Basket is empty - Select first"; sleep 1; continue; fi; printf "Sure? Install Basket? (y/n): "; read _sure; case "$_sure" in y|Y) install_selected_basket; ok "Plugins Installed - No Reboot"; echo "Press 0 to return to main menu"; printf "Your choice (0): "; read _back || return 0; [ "$_back" = "0" ] && return 0 ;; n|N) continue ;; *) wrong_choice ;; esac ;;
      0) return 0 ;;
      *) wrong_choice ;;
    esac
  done
}
get_bootlogo_by_image() {
  case "$IMAGE" in
    *VIX*|*ViX*) echo "VIX" ;;
    *SPA*) echo "SPA" ;;
    *DreamOS*|*Dreambox*) echo "DreamOS" ;;
    *PUR*|*PurE2*) echo "PUR" ;;
    *PLi*) echo "PLi" ;;
    *Egami*) echo "Egami" ;;
    *BH*|*BlackHole*|*OpenBH*) echo "BH" ;;
    *TeamBlue*) echo "TeamBlue" ;;
    *Vision*) echo "Vision" ;;
    *HDF*) echo "HDF" ;;
    *ATV*) echo "ATV" ;;
    *) echo "ATV" ;;
  esac
}
install_bootlogo() {
  setup_reboot_guard "BootLogo $1"
  LG="$1"
  # V23.0 CACHE-DIAG-FIX: (1) BusyBox od -A unsupported -> python3 magic check, (2) opkg files on OpenATV has NO leading space -> parse ^/ lines, (3) FootOnSat via secure_fetch 3 tries + curl fallback, (4) cache logs opkg update rc + one sample download error.
# V22.9 NO-BACKUP-SUBMENU: Backup submenu removed. Main menu: 5) Backup Ur Data (= old All), 6) Backup Ur Files (= files only). Renumbered 7-12.
# V22.8 RENAME: Full Restore -> Smart Restore, Custom Restore -> Custom Restore, no parenthetical text beside them.
# V22.7 DREAMOS-APT: DreamOS/apt Tier 4 - apt download + dpkg-repack rebuild .deb, offline_install_pkg handles .deb via dpkg.
# V22.6 CACHE-MISS-FIX: cache_offline_assets 3-tier (download -> download-only --force-reinstall -> rebuild .ipk from installed pkg). Fixes CACHE-MISS for already-installed / feed-missing packages.
# V22.5 SETUP-CACHE-PER-IMAGE: Setup-Cache + Hash-Pin per IMAGE + Python (like Backup-Cache), auto-migrate old Group cache.
# V22.4 SMART-ALL: Custom Restore + Setup-Cache (every secure_run installer cached at Setup time, Favourite replays from cache if net fails) + Files Oscam Smart.
# V22.3 SMART-RESTORE: renamed Smart Restore -> Smart Restore. Same unified logic.
# V22.2 SMART-RESTORE: cache-first in ALL modes - cached BootLogo is the exact file online would download,
  # so using it first guarantees BootLogo never blocks on net. Online download only if no cache.
  if [ -z "$LG" ] || [ "$LG" = "none" ]; then echo "BootLogo = none - Skipped"; return 0; fi
  [ "$LG" = "Auto" ] && LG=$(get_bootlogo_by_image)
  _BLF_SMART=""; case "$LG" in VIX) _BLF_SMART="BootLogoVIX-Novaler.tar.gz";; SPA) _BLF_SMART="BootLogoSPA-Novaler.tar.gz";; PUR) _BLF_SMART="BootLogoPUR-Novaler.tar.gz";; Egami) _BLF_SMART="BootLogoEgami-Novaler.tar.gz";; BH) _BLF_SMART="BootLogoBH-Novaler.tar.gz";; TeamBlue) _BLF_SMART="BootLogoTeamBlue-Novaler.tar.gz";; *) _BLF_SMART="BootLogoATV-Novaler.tar.gz";; esac
  _CACHED_SMART="$(offline_cache_dir)/bootlogo/$_BLF_SMART"
  if [ -f "$_CACHED_SMART" ]; then echo "[SMART] BootLogo $LG from cache (same file online would download): $_CACHED_SMART"; tar -xzf "$_CACHED_SMART" -C / 2>/dev/null; ok "BootLogo $LG Installed (SMART, from cache) - No Reboot"; return 0; fi
  echo "[SMART] BootLogo $LG - no cache, trying ONLINE download..."
  if offline_is_on; then
    [ -z "$LG" ] || [ "$LG" = "none" ] && echo "BootLogo = none - Skipped" && return 0
    [ "$LG" = "Auto" ] && LG=$(get_bootlogo_by_image)
    _BLF=""; case "$LG" in VIX) _BLF="BootLogoVIX-Novaler.tar.gz";; SPA) _BLF="BootLogoSPA-Novaler.tar.gz";; PUR) _BLF="BootLogoPUR-Novaler.tar.gz";; Egami) _BLF="BootLogoEgami-Novaler.tar.gz";; BH) _BLF="BootLogoBH-Novaler.tar.gz";; TeamBlue) _BLF="BootLogoTeamBlue-Novaler.tar.gz";; *) _BLF="BootLogoATV-Novaler.tar.gz";; esac
    _CACHED="$(offline_cache_dir)/bootlogo/$_BLF"
    if [ -f "$_CACHED" ]; then echo "[OFFLINE] BootLogo $LG from cache: $_CACHED"; tar -xzf "$_CACHED" -C / 2>/dev/null; ok "BootLogo $LG Installed (OFFLINE, from cache) - No Reboot"; return 0; fi
    echo "[OFFLINE-SKIP] BootLogo $LG - no cached $_BLF in offline-cache/bootlogo/ - continuing without BootLogo"; return 0
  fi
  [ -z "$LG" ] || [ "$LG" = "none" ] && echo "BootLogo = none - Skipped" && return 0
  [ "$LG" = "Auto" ] && LG=$(get_bootlogo_by_image)
  echo "------------------------------------------------------------"
  echo "Installing BootLogo - $LG - For Image: $IMAGE - Reboot Guard V4 ON"
  echo "------------------------------------------------------------"
  case "$LG" in
    VIX) cd / && secure_fetch_file "https://raw.githubusercontent.com/ah40mee-blip/AllScript-Universal/main/BootLogoVIX-Novaler.tar.gz" "/BootLogoVIX-Novaler.tar.gz" "BootLogoVIX-Novaler.tar.gz" && tar -xzf /BootLogoVIX-Novaler.tar.gz /BootLogoVIX-Novaler.tar.gz -C / && rm -f /BootLogoVIX-Novaler.tar.gz && echo "VIX Novaler Done" ;;
    SPA) cd / && secure_fetch_file "https://raw.githubusercontent.com/ah40mee-blip/AllScript-Universal/main/BootLogoSPA-Novaler.tar.gz" "/BootLogoSPA-Novaler.tar.gz" "BootLogoSPA-Novaler.tar.gz" && tar -xzf /BootLogoSPA-Novaler.tar.gz /BootLogoSPA-Novaler.tar.gz -C / && rm -f /BootLogoSPA-Novaler.tar.gz && echo "SPA Novaler Done" ;;
    PUR) cd / && secure_fetch_file "https://raw.githubusercontent.com/ah40mee-blip/AllScript-Universal/main/BootLogoPUR-Novaler.tar.gz" "/BootLogoPUR-Novaler.tar.gz" "BootLogoPUR-Novaler.tar.gz" && tar -xzf /BootLogoPUR-Novaler.tar.gz /BootLogoPUR-Novaler.tar.gz -C / && rm -f /BootLogoPUR-Novaler.tar.gz && echo "PUR Novaler Done" ;;
    PLi) cd / && secure_fetch_file "https://raw.githubusercontent.com/ah40mee-blip/AllScript-Universal/main/BootLogoATV-Novaler.tar.gz" "/BootLogoATV-Novaler.tar.gz" "BootLogoATV-Novaler.tar.gz" && tar -xzf /BootLogoATV-Novaler.tar.gz /BootLogoATV-Novaler.tar.gz -C / && rm -f /BootLogoATV-Novaler.tar.gz && echo "PLi -> ATV Novaler Done (Fallback - No PLi Novaler file)" ;;
    Egami) cd / && secure_fetch_file "https://raw.githubusercontent.com/ah40mee-blip/AllScript-Universal/main/BootLogoEgami-Novaler.tar.gz" "/BootLogoEgami-Novaler.tar.gz" "BootLogoEgami-Novaler.tar.gz" && tar -xzf /BootLogoEgami-Novaler.tar.gz /BootLogoEgami-Novaler.tar.gz -C / && rm -f /BootLogoEgami-Novaler.tar.gz && echo "Egami Novaler Done" ;;
    BH) cd / && secure_fetch_file "https://raw.githubusercontent.com/ah40mee-blip/AllScript-Universal/main/BootLogoBH-Novaler.tar.gz" "/BootLogoBH-Novaler.tar.gz" "BootLogoBH-Novaler.tar.gz" && tar -xzf /BootLogoBH-Novaler.tar.gz /BootLogoBH-Novaler.tar.gz -C / && rm -f /BootLogoBH-Novaler.tar.gz && echo "BH Novaler Done" ;;
    ATV) cd / && secure_fetch_file "https://raw.githubusercontent.com/ah40mee-blip/AllScript-Universal/main/BootLogoATV-Novaler.tar.gz" "/BootLogoATV-Novaler.tar.gz" "BootLogoATV-Novaler.tar.gz" && tar -xzf /BootLogoATV-Novaler.tar.gz /BootLogoATV-Novaler.tar.gz -C / && rm -f /BootLogoATV-Novaler.tar.gz && echo "ATV Novaler Done" ;;
    TeamBlue) cd / && secure_fetch_file "https://raw.githubusercontent.com/ah40mee-blip/AllScript-Universal/main/BootLogoTeamBlue-Novaler.tar.gz" "/BootLogoTeamBlue-Novaler.tar.gz" "BootLogoTeamBlue-Novaler.tar.gz" && tar -xzf /BootLogoTeamBlue-Novaler.tar.gz /BootLogoTeamBlue-Novaler.tar.gz -C / && rm -f /BootLogoTeamBlue-Novaler.tar.gz && echo "TeamBlue Novaler Done" ;;
    Vision|HDF|*) cd / && secure_fetch_file "https://raw.githubusercontent.com/ah40mee-blip/AllScript-Universal/main/BootLogoATV-Novaler.tar.gz" "/BootLogoATV-Novaler.tar.gz" "BootLogoATV-Novaler.tar.gz" && tar -xzf /BootLogoATV-Novaler.tar.gz /BootLogoATV-Novaler.tar.gz -C / && rm -f /BootLogoATV-Novaler.tar.gz && echo "ATV Novaler Done" ;;
  esac
  ok "BootLogo $LG Installed - For Image: $IMAGE - No Reboot - Will Show After Reboot"
}
install_bootlogo_auto() { LG_AUTO=$(get_bootlogo_by_image); echo "BootLogo Auto - Detected Image: $IMAGE -> BootLogo: $LG_AUTO"; install_bootlogo "$LG_AUTO"; }
# V4.6: IPTV + Personal backup helpers - every copied file gets a manifest line "rel|orig"
# so restore + MD5 verify know the ORIGINAL path (sources live in many different roots).
backup_personal_file() {
  _SRC="$1"; _DEST="$2"; _MAN="$3"; _SUB="${4:-}"
  [ -f "$_SRC" ] || return 0
  _SZ=$(stat -c%s "$_SRC" 2>/dev/null || echo 0)
  [ "$_SZ" -gt 52428800 ] && { echo "  [SKIP] >50MB: $_SRC"; return 0; }
  [ -n "$_SUB" ] && [ "$_SUB" != "." ] && _DEST="$_DEST/$_SUB"
  mkdir -p "$_DEST" 2>/dev/null
  _BASE=$(basename "$_SRC"); _DST="$_DEST/$_BASE"
  if [ -f "$_DST" ]; then _PRE=$(basename "$(dirname "$_SRC")" | tr -d ' '); [ -n "$_PRE" ] && [ "$_PRE" != "." ] && _DST="$_DEST/${_PRE}-$_BASE"; fi
  cp -a "$_SRC" "$_DST" 2>/dev/null || return 0
  _REL=${_DST#$BKDIR/}
  echo "$_REL|$_SRC" >> "$_MAN"
  echo "  + $_SRC"
}
backup_personal_dir() {
  # NOTE: uses _PD_* names ONLY - backup_personal_file clobbers _SRC/_DEST/_REL,
  # so this loop must not use those names or the 2nd file in a dir gets a wrong path.
  _PD_SRC="$1"; _PD_DEST="$2"; _PD_MAN="$3"
  [ -d "$_PD_SRC" ] || return 0
  _PD_BASE=$(basename "$_PD_SRC")
  find "$_PD_SRC" -type f ! -iname "*.ts" ! -iname "*.mp4" ! -iname "*.mkv" ! -iname "*.avi" ! -iname "*.mov" ! -iname "*.mp3" ! -iname "*.flac" -size -50M 2>/dev/null | while read -r _PD_F; do
    _PD_REL=${_PD_F#$_PD_SRC/}; _PD_D=$(dirname "$_PD_REL"); [ "$_PD_D" = "." ] && _PD_D=""
    backup_personal_file "$_PD_F" "$_PD_DEST/$_PD_BASE" "$_PD_MAN" "$_PD_D"
  done
  echo "  + dir $_PD_SRC"
}
restore_personal_manifest() {
  _MAN="$1"
  [ -f "$_MAN" ] || return 0
  while IFS='|' read -r _rel _orig; do
    [ -z "$_rel" ] && continue; [ -z "$_orig" ] && continue
    case "$_orig" in /*) ;; *) echo "  [SKIP] not absolute: $_orig"; continue;; esac
    case "$_orig" in "$BACKUP_ROOT"/U-Panel*|"$BACKUP_ROOT"/U-Panel-Backup*|/proc/*|/sys/*|/dev/*|/etc/passwd|/etc/shadow|/etc/shadow-) echo "  [SKIP] unsafe restore target: $_orig"; continue;; esac
    case "$_orig" in /etc/enigma2/*|/etc/*.m3u*|/root/*|/home/*|/media/*) ;; *) echo "  [SKIP] outside allowed roots: $_orig"; continue;; esac
    [ -f "$BKDIR/$_rel" ] || { echo "  [MISSING] in backup: $_rel"; continue; }
    mkdir -p "$(dirname "$_orig")" 2>/dev/null
    cp -a "$BKDIR/$_rel" "$_orig" 2>/dev/null && echo "  [OK] $_orig"
  done < "$_MAN"
}

backup_files() {
  setup_reboot_guard "Backup"
  BKDIR="$(get_files_backup_dir)"
  case "$BKDIR" in /*) ;; *) echo "[BACKUP-FAIL] BKDIR is not absolute (UPANEL_ROOT broken): $BKDIR - aborting, nothing touched"; return 1;; esac
  check_hdd_space "Backup Files" || return 1
  echo "> Stopping Enigma - /sbin/init 4 (files frozen so verify vs live is exact)"
  selective_stop_enigma
  _BK_REAL="$BKDIR"; BKDIR="$BKDIR.tmp.$$"
  for _oldtmp in "$BACKUP_ROOT"/U-Panel-Backup-*/Python*/*.tmp.* "$BACKUP_ROOT"/U-Panel-Backup-*/Python*.tmp.*; do [ -d "$_oldtmp" ] && [ "$_oldtmp" != "$BKDIR" ] && echo "[CLEANUP] Removing stale tmp: $_oldtmp" && rm -rf "$_oldtmp"; done
  rm -rf "$BKDIR"; mkdir -p "$BKDIR"
  line; info "Backup V7 - Auto: Same IMAGE + Python - Image: $IMAGE - Python: $PYTHON_V - Folder: $BKDIR - Box: $BOX"
  rm -rf "$BKDIR"; mkdir -p "$BKDIR"
  mkdir -p "$BKDIR/enigma2" "$BKDIR/tuxbox" "$BKDIR/keys" "$BKDIR/emu" "$BKDIR/skin" "$BKDIR/image"
  echo "> [1/7] Enigma2 Settings - Full Copy"
  cp -a /etc/enigma2/settings "$BKDIR/enigma2/settings" 2>/dev/null
  cp -a /etc/enigma2/*.xml "$BKDIR/enigma2/" 2>/dev/null
  cp -a /etc/enigma2/*.bouquet /etc/enigma2/*.tv /etc/enigma2/*.radio /etc/enigma2/*.del "$BKDIR/enigma2/" 2>/dev/null
  cp -a /etc/enigma2/userbouquet.* /etc/enigma2/bouquets.tv /etc/enigma2/bouquets.radio "$BKDIR/enigma2/" 2>/dev/null
  cp -a /etc/enigma2/lamedb /etc/enigma2/lamedb5 /etc/enigma2/satellites.xml "$BKDIR/enigma2/" 2>/dev/null
  for _d in jediplaylists xstreamity EPGImport AutoSub AJPanel subsupport; do [ -d "/etc/enigma2/$_d" ] && cp -a "/etc/enigma2/$_d" "$BKDIR/enigma2/" 2>/dev/null && echo "  + enigma2/$_d"; done
  for _f in /etc/enigma2/*.json /etc/enigma2/*.conf /etc/enigma2/*.key /etc/enigma2/*.txt; do [ -f "$_f" ] && cp -a "$_f" "$BKDIR/enigma2/" 2>/dev/null; done
  [ -f /etc/enigma2/ipaudio.json ] && cp -a /etc/enigma2/ipaudio.json "$BKDIR/enigma2/"
  [ -f /etc/enigma2/iptosat.conf ] && cp -a /etc/enigma2/iptosat.conf "$BKDIR/enigma2/"
  [ -f /etc/enigma2/iptosat.json ] && cp -a /etc/enigma2/iptosat.json "$BKDIR/enigma2/"
  echo "> [2/7] Oscam / Ncam / CCcam - Full tuxbox"
  cp -a /etc/tuxbox "$BKDIR/tuxbox_full" 2>/dev/null
  [ -d /etc/tuxbox/config ] && cp -a /etc/tuxbox/config "$BKDIR/tuxbox/config" 2>/dev/null
  [ -f /etc/CCcam.cfg ] && cp -a /etc/CCcam.cfg "$BKDIR/tuxbox/CCcam.cfg"
  [ -f /etc/tuxbox/config/oscam.server ] && echo "  + oscam.server FOUND"
  [ -f /etc/tuxbox/config/oscam.conf ] && echo "  + oscam.conf FOUND"
  [ -f /etc/tuxbox/config/oscam.user ] && echo "  + oscam.user FOUND"
  [ -f /etc/tuxbox/config/ncam.server ] && echo "  + ncam.server FOUND"
  for _ic in /etc/tuxbox/config-icam /etc/tuxbox/config_oscam-icam /etc/tuxbox/config-oscam-icam /etc/tuxbox/oscam-icam; do [ -d "$_ic" ] && cp -a "$_ic" "$BKDIR/tuxbox/$(basename $_ic)" 2>/dev/null && echo "  + ICAM config FOUND: $_ic"; done
  echo "> [3/7] Keys - Fix V5"
  rm -rf "$BKDIR/keys"; mkdir -p "$BKDIR/keys"
  > "$BKDIR/keys/autosub_locations.txt"
  if [ -f "/etc/enigma2/autosub key" ]; then cp -a "/etc/enigma2/autosub key" "$BKDIR/keys/autosub key"; echo "/etc/enigma2/autosub key" >> "$BKDIR/keys/autosub_locations.txt"; echo "  [OK] Found: /etc/enigma2/autosub key - WITH SPACE"; fi
  if [ -f /etc/enigma2/autosub.key ]; then cp -a /etc/enigma2/autosub.key "$BKDIR/keys/autosub.key"; echo "/etc/enigma2/autosub.key" >> "$BKDIR/keys/autosub_locations.txt"; echo "  [OK] Found: /etc/enigma2/autosub.key - WITH DOT"; fi
  if [ -f "/media/hdd/Novaler/MyImageFiles/autosub key" ]; then cp -a "/media/hdd/Novaler/MyImageFiles/autosub key" "$BKDIR/keys/autosub key.myimage"; echo "  [OK] Found: /media/hdd/Novaler/MyImageFiles/autosub key"; fi
  if [ -f /media/hdd/Novaler/MyImageFiles/autosub.txt ]; then cp -a /media/hdd/Novaler/MyImageFiles/autosub.txt "$BKDIR/keys/autosub.txt"; echo "  [OK] Found: /media/hdd/Novaler/MyImageFiles/autosub.txt"; fi
  grep -i -E "autosub|groq" /etc/enigma2/settings > "$BKDIR/keys/settings_keys.txt" 2>/dev/null
  [ -s "$BKDIR/keys/settings_keys.txt" ] && echo "  Settings keys:" && cat "$BKDIR/keys/settings_keys.txt"
  for _g in /etc/enigma2/groqapi.key /etc/groqapi.key "/media/hdd/Novaler/MyImageFiles/groqapi.key"; do [ -f "$_g" ] && echo "  [OK] Found groqapi.key at: $_g" && cp -a "$_g" "$BKDIR/keys/groqapi.key" 2>/dev/null; done
  [ -d /usr/keys ] && cp -a /usr/keys "$BKDIR/keys/usr_keys" 2>/dev/null && echo "  + /usr/keys backed up"
  ls -lh "$BKDIR/keys/" 2>/dev/null
  echo "> [4/7] Emu - Active Emu"
  ACTIVE_EMU=""; [ -L /etc/init.d/softcam ] && ACTIVE_EMU=$(readlink /etc/init.d/softcam | xargs basename 2>/dev/null)
  [ -z "$ACTIVE_EMU" ] && ACTIVE_EMU=$(ls /etc/*.emu 2>/dev/null | head -1 | xargs basename 2>/dev/null)
  [ -z "$ACTIVE_EMU" ] && ACTIVE_EMU=$(grep "^config.softcam" /etc/enigma2/settings 2>/dev/null | cut -d= -f2)
  echo "$ACTIVE_EMU" > "$BKDIR/emu/active_emu.txt"; echo "  Active Emu: $ACTIVE_EMU"
  cp -a /etc/*.emu "$BKDIR/emu/" 2>/dev/null
  for _sc in /etc/init.d/softcam.*; do [ -f "$_sc" ] && [ ! -L "$_sc" ] && cp -a "$_sc" "$BKDIR/emu/" 2>/dev/null && echo "  + $(basename $_sc) backed up - real file only"; done
  ls /usr/bin/cam/ > "$BKDIR/emu/cam_list.txt" 2>/dev/null
  ls /usr/bin/OSCam* /usr/bin/oscam* > "$BKDIR/emu/bin_list.txt" 2>/dev/null
  ls /usr/lib/enigma2/python/Plugins/Extensions/ > "$BKDIR/enigma2/installed_plugins_list.txt" 2>/dev/null
  opkg list-installed | grep enigma2-plugin > "$BKDIR/enigma2/installed_plugins_opkg.txt" 2>/dev/null
  echo "> [4b/7] Emu Binary - Fix V4 - Real Name OSCam_11.726-r798"
  mkdir -p "$BKDIR/emu/bin"
  CAMNAME=""
  if [ -L /etc/init.d/softcam ]; then CAMFILE=$(readlink /etc/init.d/softcam); else CAMFILE="softcam.OSCam_11.726-r798"; fi
  [ -f "/etc/init.d/$CAMFILE" ] && CAMNAME=$(grep 'CAMNAME=' "/etc/init.d/$CAMFILE" 2>/dev/null | cut -d'"' -f2)
  [ -z "$CAMNAME" ] && CAMNAME="OSCam_11.726-r798"
  echo "  CAMNAME from softcam: $CAMNAME"
  echo "$CAMNAME" > "$BKDIR/emu/camname.txt"
  for _b in /usr/bin/OSCam* /usr/bin/oscam* /usr/bin/*icam*; do [ -f "$_b" ] && cp -a "$_b" "$BKDIR/emu/bin/" && echo "  + $(basename $_b) backed up - Size: $(ls -lh $_b | awk '{print $5}')"; done
  ls -lh "$BKDIR/emu/bin/" 2>/dev/null
  [ -f "$BKDIR/emu/bin/$CAMNAME" ] && echo "  [OK] Main binary $CAMNAME backed up" || echo "  [WARN] Main binary $CAMNAME NOT found"
  echo "> [4c/7] ICAM Detection V6"
  > "$BKDIR/emu/icam_locations.txt"
  find /usr/bin /usr/bin/cam /etc/init.d /etc/tuxbox -maxdepth 3 -iname "*icam*" 2>/dev/null | tee -a "$BKDIR/emu/icam_locations.txt"
  find / -maxdepth 4 -iname "*icam*" 2>/dev/null | grep -v -E "^/proc|^/sys" | tee -a "$BKDIR/emu/icam_locations.txt"
  sort -u "$BKDIR/emu/icam_locations.txt" -o "$BKDIR/emu/icam_locations.txt"
  cat "$BKDIR/emu/icam_locations.txt"
  for _icam in /usr/bin/oscam-icam /usr/bin/oscam.icam /usr/bin/oscamicam /usr/bin/oscamicamall /usr/bin/OSCam-icam /usr/bin/OSCam.icam /usr/bin/cam/oscam-icam /usr/bin/cam/oscam.icam; do [ -f "$_icam" ] && cp -a "$_icam" "$BKDIR/emu/bin/" && chmod +x "$BKDIR/emu/bin/$(basename $_icam)" && echo "  [OK] ICAM Binary FOUND: $_icam"; done
  for _s in /etc/init.d/softcam*icam* /etc/init.d/softcam.*icam* /etc/init.d/*icam*; do [ -f "$_s" ] && cp -a "$_s" "$BKDIR/emu/" && echo "  [OK] ICAM Softcam Script FOUND: $_s"; done
  opkg list-installed | grep -i -E "icam|oscam" > "$BKDIR/emu/opkg_oscam_icam.txt" 2>/dev/null
  cat "$BKDIR/emu/opkg_oscam_icam.txt"
  ls -lh "$BKDIR/emu/bin/" 2>/dev/null
  echo "> [5/7] Skin"
  SKIN=$(grep "^config.skin.primary_skin" /etc/enigma2/settings 2>/dev/null | cut -d= -f2 | cut -d/ -f1)
  [ -z "$SKIN" ] && SKIN="default"
  echo "$SKIN" > "$BKDIR/skin/active_skin.txt"; echo "  Active Skin: $SKIN"
  [ -d "/usr/share/enigma2/$SKIN" ] && cp -a "/usr/share/enigma2/$SKIN" "$BKDIR/skin/" 2>/dev/null
  echo "> [5b/7] IPTV - m3u / playlists / portals (V4.6)"
  mkdir -p "$BKDIR/iptv" "$BKDIR/personal"
  : > "$BKDIR/iptv/locations.txt"; : > "$BKDIR/personal/locations.txt"
  for _f in /etc/enigma2/*.m3u /etc/enigma2/*.m3u8; do backup_personal_file "$_f" "$BKDIR/iptv/enigma2" "$BKDIR/iptv/locations.txt"; done
  for _d in /etc/enigma2/*iptv* /etc/enigma2/*IPTV* /etc/enigma2/*xtream* /etc/enigma2/*Xtream*; do [ -d "$_d" ] && backup_personal_dir "$_d" "$BKDIR/iptv/enigma2-dirs" "$BKDIR/iptv/locations.txt"; done
  for _f in /etc/*.m3u /etc/*.m3u8; do backup_personal_file "$_f" "$BKDIR/iptv/etc" "$BKDIR/iptv/locations.txt"; done
  for _f in "$BACKUP_ROOT"/*.m3u "$BACKUP_ROOT"/*.m3u8; do backup_personal_file "$_f" "$BKDIR/iptv/hdd" "$BKDIR/iptv/locations.txt"; done
  if [ -d /media/usb ]; then for _f in /media/usb/*.m3u /media/usb/*.m3u8; do backup_personal_file "$_f" "$BKDIR/iptv/usb" "$BKDIR/iptv/locations.txt"; done; fi
  for _d in "$BACKUP_ROOT"/IPTV "$BACKUP_ROOT"/iptv /media/usb/IPTV /media/usb/iptv; do [ -d "$_d" ] && backup_personal_dir "$_d" "$BKDIR/iptv/dirs" "$BKDIR/iptv/locations.txt"; done
  echo "> [5c/7] Personal files - MyImageFiles / root / HDD top-level (V4.6)"
  if [ -d /media/hdd/Novaler/MyImageFiles ]; then backup_personal_dir /media/hdd/Novaler/MyImageFiles "$BKDIR/personal" "$BKDIR/personal/locations.txt"; fi
  for _f in /root/*.txt /root/*.key /root/*.json /root/*.cfg /root/*.conf /root/*.xml /root/*.m3u*; do backup_personal_file "$_f" "$BKDIR/personal/root" "$BKDIR/personal/locations.txt"; done
  for _f in "$BACKUP_ROOT"/*.txt "$BACKUP_ROOT"/*.key "$BACKUP_ROOT"/*.json "$BACKUP_ROOT"/*.cfg "$BACKUP_ROOT"/*.conf "$BACKUP_ROOT"/*.xml; do backup_personal_file "$_f" "$BKDIR/personal/hdd" "$BKDIR/personal/locations.txt"; done
  if [ -d /media/usb ]; then for _f in /media/usb/*.txt /media/usb/*.key /media/usb/*.json /media/usb/*.cfg; do backup_personal_file "$_f" "$BKDIR/personal/usb" "$BKDIR/personal/locations.txt"; done; fi
  echo "  IPTV files: $(grep -c . "$BKDIR/iptv/locations.txt" 2>/dev/null) - Personal files: $(grep -c . "$BKDIR/personal/locations.txt" 2>/dev/null)"
  echo "> [7b/8] Timers / EPG / Samba (V20)"
  [ -f /etc/enigma2/timers.xml ] && cp -a /etc/enigma2/timers.xml "$BKDIR/enigma2/" 2>/dev/null
  [ -f /etc/enigma2/autotimer.xml ] && cp -a /etc/enigma2/autotimer.xml "$BKDIR/enigma2/" 2>/dev/null
  [ -f /etc/enigma2/epg.dat ] && cp -a /etc/enigma2/epg.dat "$BKDIR/enigma2/" 2>/dev/null
  [ -f /etc/samba/smb.conf ] && mkdir -p "$BKDIR/image/samba" && cp -a /etc/samba/smb.conf "$BKDIR/image/samba/" 2>/dev/null
  echo "> [7/7] Image - Network / Hostname"
  cp -a /etc/hostname /etc/resolv.conf "$BKDIR/image/" 2>/dev/null
  [ -f /etc/network/interfaces ] && cp -a /etc/network/interfaces "$BKDIR/image/" 2>/dev/null
  {
    echo "Image: $IMAGE"; echo "Box: $BOX"; echo "Skin: $SKIN"; echo "Active Emu: $ACTIVE_EMU"
    echo "Backup: $IMAGE - Python$PY_MM"; echo "CAMNAME: $CAMNAME"
    echo "Date: $(date)"; echo "Backup Folder: $BKDIR"
    echo "settings: $([ -f $BKDIR/enigma2/settings ] && echo YES || echo NO)"
    echo "oscam.server: $([ -f $BKDIR/tuxbox/config/oscam.server ] && echo YES || echo NO)"
    echo "oscam.conf: $([ -f $BKDIR/tuxbox/config/oscam.conf ] && echo YES || echo NO)"
    echo "ncam.server: $([ -f $BKDIR/tuxbox/config/ncam.server ] && echo YES || echo NO)"
    echo "lamedb: $([ -f $BKDIR/enigma2/lamedb ] && echo YES || echo NO)"
    echo "autosub key (SPACE): $([ -f "$BKDIR/keys/autosub key" ] && echo YES || echo NO)"
    echo "autosub.key (DOT): $([ -f $BKDIR/keys/autosub.key ] && echo YES || echo NO)"
    echo "groqapi.key: $([ -f $BKDIR/keys/groqapi.key ] && echo YES || echo NO)"
    echo "oscam.binary: $([ -f $BKDIR/emu/bin/$CAMNAME ] && echo YES - $CAMNAME || echo NO)"
    echo "icam.binaries: $(ls $BKDIR/emu/bin/*icam* 2>/dev/null | wc -l) files"
    echo "icam.locations: $(cat $BKDIR/emu/icam_locations.txt 2>/dev/null | wc -l) paths"
    echo "iptv files: $(grep -c . $BKDIR/iptv/locations.txt 2>/dev/null) files"
    echo "personal files: $(grep -c . $BKDIR/personal/locations.txt 2>/dev/null) files"
  } > "$BKDIR/backup_info.txt"
  cat "$BKDIR/backup_info.txt"
  sed -i "s|$BKDIR|$_BK_REAL|g" "$BKDIR/backup_info.txt" 2>/dev/null
  generate_files_manifest "$BKDIR"
  echo "> Verify Backup MD5 - before publish (backup vs live source)"
  verify_files_backup "$BKDIR" || { ask_retrieve_enigma; BKDIR="$_BK_REAL"; echo "[BACKUP-FAIL] Files backup verify FAILED - NOT published, old backup kept"; return 1; }
  swap_backup_dir "$_BK_REAL" "$BKDIR" || { ask_retrieve_enigma; BKDIR="$_BK_REAL"; echo "[BACKUP-FAIL] Swap failed - backup NOT published"; return 1; }
  BKDIR="$_BK_REAL"
  ok "Backup V7 Done: $BKDIR - Group: $BK"
  ask_retrieve_enigma
  [ "$U_PANEL_SCHEDULED" = "1" ] && telegram_send "U-Panel scheduled backup finished: $BKDIR"
  if [ "$BACKUP_BATCH" != "1" ]; then printf "Press ENTER to return... "; read _back; fi
}
backup_full_image() {
  setup_reboot_guard "Full Backup V2.5"
  show_banner
  _MLOW=$(echo "$FULL_MACHINE" | tr 'A-Z' 'a-z')
  case "$_MLOW" in *dm900*|*dm920*|*dm7080*|*dreambox*|*dream*) echo "[ERROR] Dreambox NOT Supported - DM900 / DM920 / DM7080"; echo "[ERROR] Dreambox uses NFI - Not ZIP - Use dBackup Plugin"; echo "[ERROR] FULL Backup Stopped - To Protect Your Box"; printf "Press ENTER... "; read _back; return 0 ;; esac
  line; info "FULL BACKUP V2.5 - Dream Excluded - Machine: $FULL_MACHINE - Image: $IMAGE - Box: $BOX"
  check_full_image_space || { printf "Press ENTER... "; read _back; return 1; }
  _ROOTDEV=$(mount | grep " on / " | awk '{print $1}')
  _CMDLINE=$(cat /proc/cmdline 2>/dev/null)
  echo "Root: $_ROOTDEV"; echo "Cmdline: $_CMDLINE"; echo "Machine: $FULL_MACHINE"; ls -lh /boot/ 2>/dev/null
  if [ "$_ROOTDEV" = "/dev/mmcblk0p1" ] || [ ! -f /usr/bin/enigma2 ]; then echo "[ERROR] You are in Recovery - Backup not allowed - Boot working image first"; printf "Press ENTER... "; read _back; return 0; fi
  echo "[OK] Working image - Root: $_ROOTDEV"
  KERNEL_SRC="none"; KERNEL_PART=""; KERNEL_FILE=""
  KERNEL_PART=$(echo "$_CMDLINE" | grep -o "kernel=/dev/mmcblk0p[0-9]*" | cut -d= -f2)
  [ -n "$KERNEL_PART" ] && KERNEL_SRC="cmdline" && echo "Kernel from cmdline: $KERNEL_PART"
  if [ -z "$KERNEL_PART" ] && [ -f /boot/uImage ]; then KERNEL_FILE="/boot/uImage"; KERNEL_SRC="boot-uImage"; echo "Kernel from /boot/uImage - File"; fi
  if [ -z "$KERNEL_PART" ] && [ -z "$KERNEL_FILE" ] && [ -f /boot/kernel.bin ]; then KERNEL_FILE="/boot/kernel.bin"; KERNEL_SRC="boot-kernel.bin"; echo "Kernel from /boot/kernel.bin - File"; fi
  if [ -z "$KERNEL_PART" ] && [ -z "$KERNEL_FILE" ]; then for _s in /boot/STARTUP*; do [ -f "$_s" ] || continue; _KP=$(grep -o "kernel=/dev/mmcblk0p[0-9]*" "$_s" | cut -d= -f2 | head -1); [ -n "$_KP" ] && KERNEL_PART="$_KP" && KERNEL_SRC="STARTUP-$_s" && echo "Kernel from STARTUP $_s: $KERNEL_PART" && break; done; fi
  if [ -z "$KERNEL_PART" ] && [ -z "$KERNEL_FILE" ]; then case "$FULL_MACHINE" in multiboxpro|multiboxse|multibox) _SUB=$(echo "$_CMDLINE" | grep -o "rootsubdir=[a-z0-9]*" | cut -d= -f2); echo "Novaler Root subdir: $_SUB"; case "$_SUB" in linuxrootfs1) KERNEL_PART="/dev/mmcblk0p19" ;; linuxrootfs2) KERNEL_PART="/dev/mmcblk0p20" ;; linuxrootfs3) KERNEL_PART="/dev/mmcblk0p21" ;; linuxrootfs4) KERNEL_PART="/dev/mmcblk0p22" ;; *) ;; esac; [ -n "$KERNEL_PART" ] && KERNEL_SRC="novaler-mapping-$_SUB"; echo "Kernel from Novaler Mapping $_SUB: $KERNEL_PART" ;; esac; fi
  if [ -z "$KERNEL_PART" ] && [ -z "$KERNEL_FILE" ]; then echo "Fallback Scan - All mmcblk0p* For Magic 27051956"; _ROOT_NUM=$(echo "$_ROOTDEV" | sed 's/.*p//'); _BEST_DIFF=9999; for _p in /dev/mmcblk0p*; do [ "$_p" = "$_ROOTDEV" ] && continue; _M=$(hexdump -n 4 -e '4/1 "%02x"' "$_p" 2>/dev/null); [ "$_M" != "27051956" ] && continue; _PN=$(echo "$_p" | sed 's/.*p//'); _DIFF=$((_PN - _ROOT_NUM)); [ "$_DIFF" -lt 0 ] && _DIFF=$((-_DIFF)); [ "$_DIFF" -lt "$_BEST_DIFF" ] && _BEST_DIFF=$_DIFF && KERNEL_PART="$_p"; done; [ -n "$KERNEL_PART" ] && KERNEL_SRC="scan" && echo "Kernel from Scan: $KERNEL_PART"; fi
  echo "Final Kernel Source: $KERNEL_SRC - Part: $KERNEL_PART - File: $KERNEL_FILE"
  if [ -z "$KERNEL_PART" ] && [ -z "$KERNEL_FILE" ]; then echo "[ERROR] No kernel found - STOP - Do NOT make broken backup"; printf "Press ENTER... "; read _back; return 0; fi
  printf "Do you want to start FULL Backup V2.5? (y/n): "; read _fb
  case "$_fb" in y|Y) ;; *) echo "Cancelled"; printf "Press ENTER... "; read _back; return 0 ;; esac
  command -v zip >/dev/null 2>&1 || opkg_with_retry zip
  FULL_DATE=$(date +%Y%m%d-%H%M); FULL_WORK="$UPANEL_ROOT/Full-Image/backup-$FULL_DATE"; FULL_ZIP="$UPANEL_ROOT/Full-Image/my-backup-$FULL_MACHINE-$FULL_DATE-multi.zip"; GOLD_DIR="$UPANEL_ROOT/Full-Image/GOLD-BACKUP-$FULL_MACHINE-$FULL_DATE"
  rm -rf "$FULL_WORK" "$GOLD_DIR"; mkdir -p "$FULL_WORK/$FULL_MACHINE" "$GOLD_DIR"
  if [ -n "$KERNEL_FILE" ]; then echo "> Kernel From File $KERNEL_FILE - Copy"; cp -a "$KERNEL_FILE" "$FULL_WORK/$FULL_MACHINE/kernel.bin"; cp -a "$KERNEL_FILE" "$FULL_WORK/$FULL_MACHINE/uImage"; _M=$(hexdump -n 4 -e '4/1 "%02x"' "$FULL_WORK/$FULL_MACHINE/kernel.bin" 2>/dev/null); echo "Kernel magic: $_M"; [ "$_M" != "27051956" ] && echo "[WARN] File magic is $_M - Not uImage - Check manually" || echo "[OK] File magic OK"; else echo "> Kernel From Partition $KERNEL_PART - Dump + Trim 64 + Size"; _MAGIC=$(hexdump -n 4 -e '4/1 "%02x"' "$KERNEL_PART" 2>/dev/null); echo "Kernel magic: $_MAGIC - Must be 27051956"; if [ "$_MAGIC" != "27051956" ]; then echo "[ERROR] $KERNEL_PART magic is $_MAGIC - Not a kernel - STOP"; printf "Press ENTER... "; read _back; return 0; fi; dd if=$KERNEL_PART of="$FULL_WORK/kernel-full.bin" bs=1M status=none 2>/dev/null; _SIZE_HEX=$(hexdump -s 12 -n 4 -e '4/1 "%02x"' "$FULL_WORK/kernel-full.bin" 2>/dev/null); _SIZE_DEC=$((16#$_SIZE_HEX)); _TOTAL=$((_SIZE_DEC + 64)); echo "Kernel data: $_SIZE_DEC Total: $_TOTAL"; if [ "$_SIZE_DEC" -lt 1000000 ] || [ "$_SIZE_DEC" -gt 20000000 ]; then echo "[ERROR] Kernel size invalid - $_SIZE_DEC - STOP"; printf "Press ENTER... "; read _back; return 0; fi; dd if="$FULL_WORK/kernel-full.bin" of="$FULL_WORK/$FULL_MACHINE/kernel.bin" bs=1 count=$_TOTAL status=none 2>/dev/null; cp -a "$FULL_WORK/$FULL_MACHINE/kernel.bin" "$FULL_WORK/$FULL_MACHINE/uImage"; rm -f "$FULL_WORK/kernel-full.bin"; fi
  ls -lh "$FULL_WORK/$FULL_MACHINE/kernel.bin" "$FULL_WORK/$FULL_MACHINE/uImage"
  _KSIZE=$(stat -c%s "$FULL_WORK/$FULL_MACHINE/kernel.bin" 2>/dev/null); echo "Kernel size: $_KSIZE - Source: $KERNEL_SRC"
  [ -z "$_KSIZE" ] || [ "$_KSIZE" -lt 1000000 ] && echo "[ERROR] Kernel too small - STOP" && printf "Press ENTER... "; read _back; return 0
  echo "> imageversion"
  if [ -f /etc/image-version ]; then grep -E "^(distro|version|machine|date|creator|url)=" /etc/image-version > "$FULL_WORK/$FULL_MACHINE/imageversion" 2>/dev/null; [ ! -s "$FULL_WORK/$FULL_MACHINE/imageversion" ] && cp -a /etc/image-version "$FULL_WORK/$FULL_MACHINE/imageversion"; else echo "distro=$BK" > "$FULL_WORK/$FULL_MACHINE/imageversion"; echo "machine=$FULL_MACHINE" >> "$FULL_WORK/$FULL_MACHINE/imageversion"; fi
  cat "$FULL_WORK/$FULL_MACHINE/imageversion"
  touch "$FULL_WORK/force.$FULL_MACHINE"; echo "force.$FULL_MACHINE" > "$FULL_WORK/force.$FULL_MACHINE"
  echo "[INFO] No STARTUP in ZIP - Recovery creates STARTUP"
  echo "> rootfs - init 4 - tar -C / . - init 3"
  if [ "$RESTORE_BATCH" != "1" ]; then /sbin/init 4 2>/dev/null || /usr/sbin/init 4 2>/dev/null || /bin/init 4 2>/dev/null; sleep 3; /usr/bin/killall -9 enigma2 2>/dev/null || /bin/killall -9 enigma2 2>/dev/null; sleep 2; else echo "  [Batch] Enigma already stopped by Full Restore - skipping init 4"; fi; sync
  tar --exclude=./media/hdd --exclude=./media/usb --exclude=./proc --exclude=./sys --exclude=./tmp --exclude=./dev --exclude=./run --exclude=./boot --exclude=./media/sda1 --exclude=.$UPANEL_ROOT/Full-Image/backup-$FULL_DATE -cjf "$FULL_WORK/$FULL_MACHINE/rootfs.tar.bz2" -C / .
  _TAR_RC=$?; if [ "$_TAR_RC" != "0" ]; then echo "[ERROR] tar rootfs failed rc=$_TAR_RC - STOP, backup NOT published"; /sbin/init 3 2>/dev/null; printf "Press ENTER... "; read _back; return 0; fi
  ls -lh "$FULL_WORK/$FULL_MACHINE/"
  if ! tar -tjf "$FULL_WORK/$FULL_MACHINE/rootfs.tar.bz2" | grep -q "usr/bin/enigma2"; then echo "[ERROR] rootfs has no enigma2"; /sbin/init 3 2>/dev/null; printf "Press ENTER... "; read _back; return 0; fi
  /sbin/init 3 2>/dev/null || /usr/sbin/init 3 2>/dev/null || /bin/init 3 2>/dev/null; sleep 3
  if ! ps | grep -v grep | grep -q enigma2; then enigma2 & sleep 2; fi
  echo "> ZIP + USB Folder - Machine: $FULL_MACHINE"
  cd "$FULL_WORK" && zip -r "$FULL_ZIP" "$FULL_MACHINE" "force.$FULL_MACHINE"; cd /
  cp -a "$FULL_WORK/$FULL_MACHINE" "$GOLD_DIR/"; cp -a "$FULL_WORK/force.$FULL_MACHINE" "$GOLD_DIR/"; rm -rf "$FULL_WORK"
  ls -lh "$FULL_ZIP"; ls -lhR "$GOLD_DIR"
  echo "> Verify ZIP + MD5 - Full Image safety"
  if unzip -l "$FULL_ZIP" >/dev/null 2>&1; then echo "  [OK] ZIP listing OK: $FULL_ZIP"; else echo "  [FAIL] ZIP is corrupt - do NOT flash it"; printf "Press ENTER... "; read _back; return 1; fi
  md5sum "$FULL_ZIP" > "$FULL_ZIP.md5" 2>/dev/null; { echo "ZIP: $FULL_ZIP"; echo "Machine: $FULL_MACHINE"; echo "Image: $IMAGE"; echo "Date: $(date)"; echo "Size: $(stat -c%s "$FULL_ZIP" 2>/dev/null)"; echo "MD5: $(cut -d" " -f1 "$FULL_ZIP.md5" 2>/dev/null)"; } > "$FULL_ZIP.info"; cat "$FULL_ZIP.md5"; cat "$FULL_ZIP.info"
  echo "Kernel Source: $KERNEL_SRC - Part: $KERNEL_PART - File: $KERNEL_FILE"
  echo "Machine: $FULL_MACHINE - ZIP Folder Must Match Machine - Do NOT flash Pro ZIP on VU+"
  echo "Flash to EMPTY Slot - Do NOT flash on running Slot"
  ok "FULL BACKUP V2.5 Done: $FULL_ZIP + $GOLD_DIR"
  printf "Press ENTER... "; read _back
}
restore_files_setup() {
  setup_reboot_guard "Restore"
  ensure_files_backup_extracted
  check_hdd_space "Restore Files" || return 1
  if [ ! -d "$BKDIR" ]; then echo "[ERROR] No Backup Found For This Group - $BKDIR"; echo "Group: $BK - Image: $IMAGE"; echo "Do Backup first - Option 5"; return 0; fi
  line; info "Restore V3 + Oscam V4 + Keys V5 + ICAM V6 - Image: $IMAGE - Python: $PY_MM - Guard V4 Still ON"
  [ -f "$BKDIR/backup_info.txt" ] && cat "$BKDIR/backup_info.txt"
  echo "------------------------------------------------------------"
  CAMNAME="OSCam_11.726-r798"
  [ -f "$BKDIR/emu/camname.txt" ] && CAMNAME=$(cat "$BKDIR/emu/camname.txt")
  echo "BEFORE Restore:"; echo "  Backup Group: $BK"; echo "  Current Image: $IMAGE"; echo "  CAMNAME: $CAMNAME"
  _RB_SNAP="$BKDIR/BeforeRestore-Files-$(date +%Y%m%d_%H%M%S)"; mkdir -p "$_RB_SNAP/tuxbox_config"; cp -a /etc/enigma2/settings "$_RB_SNAP/settings" 2>/dev/null; cp -a /etc/enigma2/lamedb "$_RB_SNAP/lamedb" 2>/dev/null; cp -a /etc/tuxbox/config/. "$_RB_SNAP/tuxbox_config/" 2>/dev/null; echo "  [ROLLBACK-SNAP] Current files saved to $_RB_SNAP"
  echo "> [0/7] Stopping Enigma2 - /sbin/init 4 - Bypass Guard"
  /sbin/init 4 2>/dev/null || /usr/sbin/init 4 2>/dev/null || /bin/init 4 2>/dev/null; sleep 3
  /usr/bin/killall -9 enigma2 2>/dev/null || /bin/killall -9 enigma2 2>/dev/null; sleep 2
  echo "> [1/7] Restore Enigma2 Settings - Enigma is OFF - Safe"
  cp -a /etc/enigma2/settings /tmp/settings.before_restore 2>/dev/null
  [ -f "$BKDIR/enigma2/settings" ] && cp -a "$BKDIR/enigma2/settings" /etc/enigma2/settings && echo "  [OK] settings restored" || echo "  [MISSING] settings not in backup"
  rm -f /etc/enigma2/*.bouquet /etc/enigma2/*.tv /etc/enigma2/*.radio /etc/enigma2/*.del /etc/enigma2/userbouquet.* /etc/enigma2/bouquets.tv /etc/enigma2/bouquets.radio 2>/dev/null
  cp -a "$BKDIR/enigma2/"*.bouquet "$BKDIR/enigma2/"*.tv "$BKDIR/enigma2/"*.radio /etc/enigma2/ 2>/dev/null
  cp -a "$BKDIR/enigma2/userbouquet."* "$BKDIR/enigma2/bouquets.tv" "$BKDIR/enigma2/bouquets.radio" /etc/enigma2/ 2>/dev/null
  [ -f "$BKDIR/enigma2/lamedb" ] && cp -a "$BKDIR/enigma2/lamedb" /etc/enigma2/lamedb && echo "  [OK] lamedb restored" || echo "  [MISSING] lamedb"
  [ -f "$BKDIR/enigma2/lamedb5" ] && cp -a "$BKDIR/enigma2/lamedb5" /etc/enigma2/lamedb5
  [ -f "$BKDIR/enigma2/satellites.xml" ] && cp -a "$BKDIR/enigma2/satellites.xml" /etc/enigma2/satellites.xml
  for _d in jediplaylists xstreamity EPGImport AutoSub AJPanel subsupport; do [ -d "$BKDIR/enigma2/$_d" ] && rm -rf "/etc/enigma2/$_d" && cp -a "$BKDIR/enigma2/$_d" /etc/enigma2/ && echo "  [OK] enigma2/$_d restored"; done
  cp -a "$BKDIR/enigma2/"*.json "$BKDIR/enigma2/"*.conf /etc/enigma2/ 2>/dev/null
  echo "> [2/7] Restore Oscam - Full Replace"
  if [ -d "$BKDIR/tuxbox/config" ]; then rm -rf /etc/tuxbox/config; cp -a "$BKDIR/tuxbox/config" /etc/tuxbox/config; chmod 755 /etc/tuxbox/config 2>/dev/null; chmod 644 /etc/tuxbox/config/* 2>/dev/null; echo "  [OK] /etc/tuxbox/config restored - $(ls /etc/tuxbox/config | wc -l) files"; else echo "  [ERROR] tuxbox/config not in backup"; fi
  for _ic in "$BKDIR/tuxbox/config-icam" "$BKDIR/tuxbox/config_oscam-icam" "$BKDIR/tuxbox/config-oscam-icam"; do [ -d "$_ic" ] && cp -a "$_ic" "/etc/tuxbox/$(basename $_ic)" && echo "  [OK] ICAM config restored: $_ic"; done
  [ -f "$BKDIR/tuxbox/CCcam.cfg" ] && cp -a "$BKDIR/tuxbox/CCcam.cfg" /etc/CCcam.cfg && echo "  [OK] CCcam.cfg restored"
  echo "> [2b/7] Oscam Fix V4 + ICAM V6 - Restore Binary With Real Name - /usr/bin/"
  echo "  CAMNAME from Backup: $CAMNAME"
  for _b in "$BKDIR/emu/bin/"*; do [ -f "$_b" ] && cp -a "$_b" /usr/bin/ && chmod +x /usr/bin/$(basename $_b) && echo "  [OK] $(basename $_b) restored to /usr/bin/"; done
  for _s in "$BKDIR/emu/"softcam.*; do [ -f "$_s" ] && [ ! -L "$_s" ] && cp -a "$_s" /etc/init.d/ && chmod +x /etc/init.d/$(basename $_s) && echo "  [OK] $(basename $_s) restored"; done
  if [ ! -f "/usr/bin/$CAMNAME" ]; then echo "  [WARN] No binary in Backup - Oscam missing - trying SMART: cache .ipk first, then feed";
    if ! offline_install_pkg "enigma2-plugin-softcams-oscam" 2>/dev/null; then
      if check_net 2>/dev/null; then opkg update 2>/dev/null; opkg install enigma2-plugin-softcams-oscam 2>/dev/null || echo "  [SMART] Oscam feed install failed - continuing without it"; else echo "  [SMART-SKIP] Oscam - no net + no cached .ipk - continuing, Oscam binary stays missing"; fi
    fi
  fi
  chmod +x /usr/bin/OSCam* /usr/bin/oscam* /usr/bin/*icam* 2>/dev/null
  ls -l /usr/bin/*icam* 2>/dev/null && echo "  [OK] ICAM binaries restored" || echo "  [INFO] No ICAM binary in backup"
  echo "> [3/7] Restore Keys - Fix V5 - Restore BOTH Names - SPACE + DOT"
  if [ -f "$BKDIR/keys/autosub key" ]; then cp -a "$BKDIR/keys/autosub key" "/etc/enigma2/autosub key"; echo "  [OK] autosub key restored - WITH SPACE"; cp -a "$BKDIR/keys/autosub key" /etc/enigma2/autosub.key; echo "  [OK] autosub.key restored - WITH DOT"; fi
  if [ -f "$BKDIR/keys/autosub.key" ]; then cp -a "$BKDIR/keys/autosub.key" /etc/enigma2/autosub.key; cp -a "$BKDIR/keys/autosub.key" "/etc/enigma2/autosub key"; echo "  [OK] autosub.key restored - BOTH Names"; fi
  if [ -f "$BKDIR/keys/groqapi.key" ]; then cp -a "$BKDIR/keys/groqapi.key" /etc/enigma2/groqapi.key; cp -a "$BKDIR/keys/groqapi.key" /etc/groqapi.key; echo "  [OK] groqapi.key restored"; fi
  [ -d "$BKDIR/keys/usr_keys" ] && cp -a "$BKDIR/keys/usr_keys/." /usr/keys/ 2>/dev/null && echo "  [OK] /usr/keys restored"
  echo "  Verify Keys:"; ls -l "/etc/enigma2/autosub key" /etc/enigma2/autosub.key /etc/enigma2/groqapi.key 2>/dev/null
  echo "> [4/7] Restore Emu - WITHOUT Overwriting softcam Link"
  [ -f "$BKDIR/emu/active_emu.txt" ] && ACTIVE_EMU=$(cat "$BKDIR/emu/active_emu.txt") && echo "  Active Emu in Backup: $ACTIVE_EMU"
  cp -a "$BKDIR/emu/"*.emu /etc/ 2>/dev/null
  echo "> [4b/7] Oscam Fix V4 FINAL - Fix Link AFTER All Restores"
  rm -f /etc/init.d/softcam
  if [ -f "/etc/init.d/softcam.$CAMNAME" ]; then ln -sf "softcam.$CAMNAME" /etc/init.d/softcam; echo "  [OK] softcam linked to softcam.$CAMNAME"; else _first=$(ls /etc/init.d/softcam.* 2>/dev/null | grep -v None | head -1 | xargs basename); ln -sf "$_first" /etc/init.d/softcam; echo "  [OK] softcam linked to $_first"; fi
  echo "  Binary: $(ls -l /usr/bin/$CAMNAME 2>/dev/null)"; echo "  Softcam Link: $(ls -l /etc/init.d/softcam 2>/dev/null)"; echo "  Softcam Target: $(readlink /etc/init.d/softcam)"
  echo "> [5/7] Restore Skin"
  if [ -f "$BKDIR/skin/active_skin.txt" ]; then SKIN=$(cat "$BKDIR/skin/active_skin.txt"); echo "  Skin in Backup: $SKIN"; [ -d "$BKDIR/skin/$SKIN" ] && cp -a "$BKDIR/skin/$SKIN" /usr/share/enigma2/ && echo "  [OK] Skin $SKIN restored"; sed -i "/^config.skin.primary_skin=/d" /etc/enigma2/settings; echo "config.skin.primary_skin=$SKIN/skin.xml" >> /etc/enigma2/settings; echo "  [OK] primary_skin set to $SKIN"; else echo "  [MISSING] active_skin.txt"; fi
  echo "> [5b/7] Restore IPTV + Personal (V4.6)"
  if [ -f "$BKDIR/iptv/locations.txt" ]; then restore_personal_manifest "$BKDIR/iptv/locations.txt"; elif [ -d "$BKDIR/iptv/enigma2" ]; then cp -a "$BKDIR/iptv/enigma2/"* /etc/enigma2/ 2>/dev/null && echo "  [OK] iptv/enigma2 restored (legacy, no manifest)"; fi
  if [ -f "$BKDIR/personal/locations.txt" ]; then restore_personal_manifest "$BKDIR/personal/locations.txt"; fi
  echo "> [7b/7] Restore Timers / EPG / Samba (V20)"
  [ -f "$BKDIR/enigma2/timers.xml" ] && cp -a "$BKDIR/enigma2/timers.xml" /etc/enigma2/timers.xml && echo "  [OK] timers.xml restored"
  [ -f "$BKDIR/enigma2/autotimer.xml" ] && cp -a "$BKDIR/enigma2/autotimer.xml" /etc/enigma2/autotimer.xml && echo "  [OK] autotimer.xml restored"
  [ -f "$BKDIR/enigma2/epg.dat" ] && cp -a "$BKDIR/enigma2/epg.dat" /etc/enigma2/epg.dat && echo "  [OK] epg.dat restored"
  [ -f "$BKDIR/image/samba/smb.conf" ] && cp -a "$BKDIR/image/samba/smb.conf" /etc/samba/smb.conf && echo "  [OK] smb.conf restored"
  echo "> [7/7] Retrieve Enigma? (optional - no auto start, no reboot)"
  if [ "$RESTORE_BATCH" != "1" ]; then ask_retrieve_enigma; else echo "  [Batch] Enigma start is asked once by Full Restore - skipping here"; fi
  if ps | grep -v grep | grep -q enigma2; then echo "  [OK] Enigma Running"; else echo "  [INFO] Enigma stays STOPPED by your choice - continue in the menu"; fi
  echo "> Restart Oscam Only - Via softcam Script"
  /usr/bin/killall -9 "$CAMNAME" oscam-icam oscam.icam oscamicamall OSCam ncam 2>/dev/null || /bin/killall -9 "$CAMNAME" oscam-icam oscamicamall 2>/dev/null; sleep 2
  rm -f /tmp/cam.pid /tmp/oscam.log 2>/dev/null
  if [ -x /etc/init.d/softcam ]; then /etc/init.d/softcam restart 2>/dev/null && echo "  [OK] softcam restarted via /etc/init.d/softcam"; fi
  sleep 3
  if ps | grep -v grep | grep -q "$CAMNAME"; then echo "  [OK] Oscam Running - $CAMNAME"; ps | grep -v grep | grep "$CAMNAME"; else echo "  [WARN] Oscam still NOT running - Trying direct start..."; /usr/bin/$CAMNAME --daemon --pidfile /tmp/cam.pid --restart 2 --utf8; sleep 2; ps | grep -v grep | grep "$CAMNAME" && echo "  [OK] Oscam Running - Direct Start" || echo "  [WARN] Oscam Not Running - Check config"; fi
  if ps | grep -v grep | grep -q -i icam; then echo "  [OK] ICAM Running"; ps | grep -v grep | grep -i icam; fi
  ok "Restore V3 + Oscam V4 + Keys V5 + ICAM V6 Done - Group: $BK - Enigma Restarted - No Box Reboot Needed"
}
plugin_keywords() {
  _name="$1"
  _low=$(echo "$_name" | tr 'A-Z' 'a-z')
  echo "$_name $_low"
  case "$_low" in
    *ajpanel*) echo "ajpanel AJPanel" ;;
    *subssupport*|*subs*) echo "subssupport SubsSupport subs" ;;
    *mystreamer*) echo "mystreamer MyStreamer" ;;
    *jedi*|*bouquetmaker*) echo "jedi jedimakerxtream bouquetmaker" ;;
    *xstreamity*) echo "xstreamity" ;;
    *ipaudio*) echo "ipaudio ipaudioplus" ;;
    *epgimport*|*epg-grabber*) echo "epgimport epg-grabber EPGImport" ;;
    *autosub*) echo "autosub AutoSub" ;;
    *fury*) echo "fury" ;;
    *luka*) echo "luka" ;;
    *chromium*) echo "chromium" ;;
    *novaler*) echo "novaler" ;;
    *emu*) echo "emu" ;;
    *quran*) echo "quran" ;;
    *hisn*) echo "hisn hisnmuslim" ;;
  esac
}
# V21.1 - Folder filter: keep real files only in a list file (dirs/stale opkg entries polluted missing_files.txt)
filter_files_only() {
  _FF="$1"; [ -f "$_FF" ] || return 1
  while IFS= read -r _ff; do [ -f "$_ff" ] && echo "$_ff"; done < "$_FF" > "$_FF.filtered"
  mv "$_FF.filtered" "$_FF"
}

backup_plugins_only() {
  setup_reboot_guard "Plugins Backup Only"
  check_hdd_space "Backup Plugins" || return 1
  show_banner  # Per IMAGE + Python - auto
  PLUGINS_BKDIR="$(get_plugins_backup_dir)"
  PLUGINS_BASE="$(dirname "$PLUGINS_BKDIR")"
  for _oldtmp in "$PLUGINS_BASE"/*.tmp.* "$BACKUP_ROOT"/U-Panel-Plugins-Backup-*/Python*.tmp.*; do [ -d "$_oldtmp" ] && echo "[CLEANUP] Removing stale tmp: $_oldtmp" && rm -rf "$_oldtmp"; done
  _PLUG_REAL="$PLUGINS_BKDIR"; PLUGINS_BKDIR="$PLUGINS_BKDIR.tmp.$$"
  line
  info "Plugins Backup - Auto: Per IMAGE + Python - Image: $IMAGE - Python: $PYTHON_V - Folder: Python$PY_MM"
  echo "  Folder: $PLUGINS_BKDIR"
  rm -rf "$PLUGINS_BKDIR"
  echo "> Stopping Enigma - /sbin/init 4 (plugins backup - stays stopped after, screen stays black)"
  selective_stop_enigma
  mkdir -p "$PLUGINS_BKDIR/files"
  {
    echo "Date: $(date)"
    echo "Box: $BOX"
    echo "Image: $IMAGE"
    echo "Python: $PYTHON_V"
    echo "Python Folder: Python$PY_MM"
    echo "Group: $BK"
    echo "Folder: $PLUGINS_BKDIR"
    echo "Version: V20.1 - ONE Scan Internal Flash - Python Major.Minor Only"
  } > "$PLUGINS_BKDIR/plugins_info.txt"
  cat "$PLUGINS_BKDIR/plugins_info.txt"
  echo "Available Backups:"
  ls -d $UPANEL_ROOT-Backup-*/Python*/plugins $UPANEL_ROOT-Plugins-Backup-*/Python* 2>/dev/null | grep -v '\.tmp\.'
  echo "> [1/5] List Plugins"
  opkg list-installed | grep enigma2-plugin > "$PLUGINS_BKDIR/plugins_opkg.txt" 2>/dev/null
  ls /usr/lib/enigma2/python/Plugins/Extensions/ > "$PLUGINS_BKDIR/plugins_extensions.txt" 2>/dev/null
  cat "$PLUGINS_BKDIR/plugins_extensions.txt"
  echo "Count: $(wc -l < $PLUGINS_BKDIR/plugins_extensions.txt)"
  # V20.1: opkg failure must not silently produce an empty backup
  if [ ! -s "$PLUGINS_BKDIR/plugins_opkg.txt" ] && [ ! -s "$PLUGINS_BKDIR/plugins_extensions.txt" ]; then
    echo "[ERROR] opkg list-installed is EMPTY and no plugins in Extensions - backup would be empty - aborting"
    rm -rf "$PLUGINS_BKDIR"; return 1
  fi
  if [ ! -s "$PLUGINS_BKDIR/plugins_opkg.txt" ]; then
    echo "[WARN] opkg list-installed is EMPTY (feed/lock problem?) - continuing with Extensions scan only - reinstall.sh will be incomplete"
  fi
  echo "> [2/5] Phase 1 - opkg files"
  > "$PLUGINS_BKDIR/all_files.txt"
  for _pkg in $(cat "$PLUGINS_BKDIR/plugins_opkg.txt" | awk '{print $1}'); do opkg files "$_pkg" 2>/dev/null | grep "^ /" >> "$PLUGINS_BKDIR/all_files.txt"; done
  # V20.1: ONE full-filesystem listing, filtered by ALL keywords (was: one find per plugin x per keyword = ~180 full scans = hang)
  echo "> [3/5] Phase 2+3 - ONE scan for all plugins (was: find per keyword per plugin)"
  > "$PLUGINS_BKDIR/_keywords.txt"
  while read -r _plug; do [ -z "$_plug" ] && continue; plugin_keywords "$_plug" >> "$PLUGINS_BKDIR/_keywords.txt"; done < "$PLUGINS_BKDIR/plugins_extensions.txt"
  grep -v '^$' "$PLUGINS_BKDIR/_keywords.txt" | sort -u > "$PLUGINS_BKDIR/_keywords.tmp" && mv "$PLUGINS_BKDIR/_keywords.tmp" "$PLUGINS_BKDIR/_keywords.txt"
  _SCAN_LIST="/tmp/upanel_plugins_scan_$$.txt"
  : > "$PLUGINS_BKDIR/scan_files.txt"
  if [ -s "$PLUGINS_BKDIR/_keywords.txt" ]; then
    find / -xdev \( -path /media -o -path /proc -o -path /sys -o -path /dev -o -path /tmp -o -path /run \) -prune -o -print 2>/dev/null > "$_SCAN_LIST"
    grep -i -F -f "$PLUGINS_BKDIR/_keywords.txt" -- "$_SCAN_LIST" > "$PLUGINS_BKDIR/scan_match.txt" 2>/dev/null || : > "$PLUGINS_BKDIR/scan_match.txt"
    while read -r _p; do
      [ -z "$_p" ] && continue
      if [ -d "$_p" ]; then echo "    Dir Found: $_p" >> "$PLUGINS_BKDIR/scan_report.txt"; find "$_p" -type f 2>/dev/null >> "$PLUGINS_BKDIR/scan_files.txt"
      elif [ -f "$_p" ]; then echo "$_p" >> "$PLUGINS_BKDIR/scan_files.txt"; fi
    done < "$PLUGINS_BKDIR/scan_match.txt"
    # skins: keyword matches that are skin files (from the SAME single listing)
    grep -i -E 'skin|skin\.xml|\.png$' "$PLUGINS_BKDIR/scan_match.txt" >> "$PLUGINS_BKDIR/scan_files.txt" 2>/dev/null
    rm -f "$_SCAN_LIST" "$PLUGINS_BKDIR/scan_match.txt"
  fi
  # Extensions-local skin/xml/png per plugin (fast - Extensions dir only, not full fs)
  for _plug in $(cat "$PLUGINS_BKDIR/plugins_extensions.txt"); do
    [ -d "/usr/lib/enigma2/python/Plugins/Extensions/$_plug" ] || continue
    find "/usr/lib/enigma2/python/Plugins/Extensions/$_plug" -type f \( -iname "*skin*" -o -iname "*.xml" -o -iname "*.png" \) 2>/dev/null >> "$PLUGINS_BKDIR/scan_files.txt"
  done
  echo "> [4/5] Phase 4 - plugin configs ONLY (V20.1: generic /etc/enigma2 *.json/*.conf REMOVED - owned by Files backup)"
  for _plug in $(cat "$PLUGINS_BKDIR/plugins_extensions.txt"); do
    case "$_plug" in
      *jedi*|*Jedi*) find /etc/enigma2 -iname "*jedi*" -type f 2>/dev/null >> "$PLUGINS_BKDIR/scan_files.txt" ;;
      *xstream*|*Xstream*) find /etc/enigma2 -iname "*xstream*" -type f 2>/dev/null >> "$PLUGINS_BKDIR/scan_files.txt" ;;
      *ipaudio*|*IPAudio*) find /etc/enigma2 -iname "*ipaudio*" -type f 2>/dev/null >> "$PLUGINS_BKDIR/scan_files.txt" ;;
      *iptosat*|*IPTosat*) find /etc/enigma2 -iname "*iptosat*" -type f 2>/dev/null >> "$PLUGINS_BKDIR/scan_files.txt" ;;
    esac
  done
  find /etc/enigma2 -iname "*playlist*" -type f 2>/dev/null >> "$PLUGINS_BKDIR/scan_files.txt"
  # dedup + files only + drop .pyc (tmp file - never cat > same file)
  cat "$PLUGINS_BKDIR/all_files.txt" "$PLUGINS_BKDIR/scan_files.txt" 2>/dev/null | sort -u > "$PLUGINS_BKDIR/all_files.tmp" && mv "$PLUGINS_BKDIR/all_files.tmp" "$PLUGINS_BKDIR/all_files.txt"
  filter_files_only "$PLUGINS_BKDIR/all_files.txt"
  grep -v '\.pyc$' "$PLUGINS_BKDIR/all_files.txt" > "$PLUGINS_BKDIR/all_files.tmp" && mv "$PLUGINS_BKDIR/all_files.tmp" "$PLUGINS_BKDIR/all_files.txt"
  echo "> [5/5] Copy files + manifest"
  echo "file,orig_path,size,md5" > "$PLUGINS_BKDIR/manifest.csv"
  while read -r _f; do
    [ -z "$_f" ] && continue
    [ -f "$_f" ] || continue
    _dest="$PLUGINS_BKDIR/files$_f"
    mkdir -p "$(dirname "$_dest")" 2>/dev/null
    cp -a "$_f" "$_dest" 2>/dev/null || continue
    _sz=$(stat -c %s "$_f" 2>/dev/null || echo 0)
    _md5=$(md5sum "$_f" 2>/dev/null | cut -d' ' -f1)
    printf '"%s","%s","%s","%s"\n' "$_f" "$_f" "$_sz" "$_md5" >> "$PLUGINS_BKDIR/manifest.csv"
  done < "$PLUGINS_BKDIR/all_files.txt"
  # verify BEFORE swap (manifest files must exist + md5 match)
  verify_plugins_backup "$PLUGINS_BKDIR" || { echo "[WARN] Plugins backup verify FAILED - keeping backup anyway (MD5 warn-not-stop)"; }
  # fallback tarballs (restore uses them ONLY if manifest.csv is missing) - test them, delete if corrupt
  (cd /usr/lib/enigma2/python/Plugins/Extensions && tar -czf "$PLUGINS_BKDIR/plugins.tar.gz" . 2>/dev/null)
  (cd /usr/share/enigma2 && tar -czf "$PLUGINS_BKDIR/skins_full.tar.gz" . 2>/dev/null)
  for _tb in plugins.tar.gz skins_full.tar.gz; do
    if [ -f "$PLUGINS_BKDIR/$_tb" ]; then
      tar -tzf "$PLUGINS_BKDIR/$_tb" >/dev/null 2>&1 && echo "  [OK] $_tb tested" || { echo "  [WARN] $_tb CORRUPT - deleting (manifest restore still works)"; rm -f "$PLUGINS_BKDIR/$_tb"; }
    fi
  done
  # reinstall.sh (from opkg list - may be incomplete if opkg failed)
  { echo "opkg update"; while read -r _p; do [ -n "$_p" ] && echo "opkg install $_p"; done < "$PLUGINS_BKDIR/plugins_opkg.txt"; } > "$PLUGINS_BKDIR/reinstall.sh"
  ls -lh "$PLUGINS_BKDIR" 2>/dev/null; du -sh "$PLUGINS_BKDIR" 2>/dev/null
  # V22.0: cache Offline assets NOW (we are online at backup time) - inside this same backup dir
  swap_backup_dir "$_PLUG_REAL" "$PLUGINS_BKDIR" || { echo "[ERROR] swap failed"; return 1; }
  PLUGINS_BKDIR="$_PLUG_REAL"
  # V6.20 FIX: cache AFTER publish (was: before swap) - even if the cache hangs/fails, the
  # plugins backup is already published and usable, and Enigma can be restarted.
  if check_net 2>/dev/null; then cache_offline_assets; else echo "[OFFLINE-CACHE] No net at backup time - cache skipped, Offline Restore will still work from tarball/manifest"; fi
  ok "Plugins Backup Done - $PLUGINS_BKDIR"
  if [ "$BACKUP_BATCH" = "1" ]; then echo "[Batch] Continuing to Files backup - Enigma stays stopped"; return 0; fi
  ask_retrieve_enigma
  printf "Press ENTER to return... "; read _b
}
restore_plugins_only() {
  PLUGINS_VERIFY_RC=0
  setup_reboot_guard "Plugins Restore Only"
  check_hdd_space "Restore Plugins" || return 1
  show_banner  # Per IMAGE + Python - auto from detected IMAGE + PY_MM (no choice, no group)
  # V24 CROSS: if Cross-Image set an override, source = other image backup (same logic, different folder)
  if [ -n "${CROSS_PLUGINS_OVERRIDE:-}" ]; then PLUGINS_BKDIR="$CROSS_PLUGINS_OVERRIDE"; else PLUGINS_BKDIR="$(get_plugins_backup_dir)"; fi
  PLUGINS_BASE="$(dirname "$PLUGINS_BKDIR")"
  RESTORE_LOG="$PLUGINS_BKDIR/restore_report_$(date +%Y%m%d_%H%M%S).txt"
  line
  info "Plugins Restore V5 - 100% Mode - Auto: Same IMAGE + Python - Image: $IMAGE - Python: $PYTHON_V - Folder: Python$PY_MM"
  echo "  Folder: $PLUGINS_BKDIR"
  echo "  Current Image: $IMAGE"
  if [ ! -d "$PLUGINS_BKDIR" ]; then
    echo "[ERROR] No Plugins Backup For This Group + Python"
    echo "Wanted: $PLUGINS_BKDIR"
    echo "Group: $BK - Image: $IMAGE - Python: $PYTHON_V - Folder: Python$PY_MM"
    echo ""
    echo "Available Plugins Backups:"
    ls -d $UPANEL_ROOT-Backup-*/Python*/plugins $UPANEL_ROOT-Plugins-Backup-*/Python* 2>/dev/null | grep -v '\.tmp\.'
    printf "Press ENTER to return... "; read _back
    return 1
  fi
  [ -f "$PLUGINS_BKDIR/plugins_info.txt" ] && cat "$PLUGINS_BKDIR/plugins_info.txt"
  echo ""
  echo "Current: Image: $IMAGE - Python: $PYTHON_V - Folder: Python$PY_MM"
  echo "Backup Files: $(wc -l < $PLUGINS_BKDIR/all_files.txt 2>/dev/null) files"
  echo "[OK] Python Match - Folder is Python$PY_MM"
  # --- V4-1: Block image-specific system plugins - they MUST NOT cross ATV <-> SPA ---
  # These are restored by opkg from the NEW image feed, never copied as files.
  _SYS_BLACKLIST="enigma2-plugin-systemplugins-softwaremanager enigma2-plugin-systemplugins-videomode enigma2-plugin-systemplugins-networkbrowser enigma2-plugin-systemplugins-positionersetup enigma2-plugin-systemplugins-satfinder enigma2-plugin-systemplugins-wirelesslan enigma2-plugin-systemplugins-hdmicec enigma2-plugin-systemplugins-frontprocessorupgrade enigma2-plugin-systemplugins-audiosync enigma2-plugin-systemplugins-osdpositionsetup enigma2-plugin-systemplugins-osd3dsetup enigma2-plugin-systemplugins-commoninterfaceassignment enigma2-plugin-systemplugins-cablescan enigma2-plugin-systemplugins-fastscan enigma2-plugin-systemplugins-terrestrialscan"
  if [ "${FULL_AUTO:-0}" = "1" ]; then echo "[AUTO] Plugins restore auto-confirmed (Full/Selective Auto - no prompt)"; else printf "Do you want to Restore Plugins Only V4? (y/n): "; read _rp; case "$_rp" in y|Y) ;; *) echo "Cancelled - Plugins Restore cancelled by user"; printf "Press ENTER... "; read _back; return 2 ;; esac; fi
  {
  echo "Restore Report - $(date) - From: $(cat $PLUGINS_BKDIR/plugins_info.txt 2>/dev/null | tr '\n' ' ') - To: $IMAGE - Python: $PYTHON_V"
  echo "> [0/6] Safety Backup of CURRENT plugins (before overwrite)"
    mkdir -p "$PLUGINS_BASE/BeforeRestore-$(date +%Y%m%d_%H%M%S)"
    cp -a /usr/lib/enigma2/python/Plugins/Extensions "$PLUGINS_BASE/BeforeRestore-$(date +%Y%m%d_%H%M%S)/" 2>/dev/null
  echo "> [1/6] Stopping Enigma - /sbin/init 4"
  } | tee -a "$RESTORE_LOG"
  if [ "$RESTORE_BATCH" != "1" ]; then /sbin/init 4 2>/dev/null || /usr/sbin/init 4 2>/dev/null || /bin/init 4 2>/dev/null; sleep 3; /usr/bin/killall -9 enigma2 2>/dev/null || /bin/killall -9 enigma2 2>/dev/null; sleep 2; else echo "  [Batch] Enigma already stopped by Full Restore - skipping init 4" | tee -a "$RESTORE_LOG"; fi
  echo "> [2/6] Restoring - كل ملف في مكانه الاصلي - من Manifest (ماعدا بلاجنات السيستم)" | tee -a "$RESTORE_LOG"
  if [ -f "$PLUGINS_BKDIR/manifest.csv" ]; then
    tail -n +2 "$PLUGINS_BKDIR/manifest.csv" | while IFS= read -r _line; do _line=${_line#'"'}; _line=${_line%'"'}; _qfile=${_line%%'",'*}; _csvrest=${_line#*'",'}; _qorig=${_csvrest%%'",'*}; _csvrest=${_csvrest#*'",'}; _qsize=${_csvrest%%'",'*}; _qmd5=${_csvrest#*'",'};
      _orig=$(echo "$_qorig" | tr -d '"')
      [ -z "$_orig" ] && continue
      # V4: skip files that belong to blacklisted system plugins - opkg will handle them
      case "$_orig" in */SystemPlugins/*) echo "  [SKIP-SYS] $_orig" >> "$RESTORE_LOG"; continue ;; esac
      _src="$PLUGINS_BKDIR/files$_orig"
      if [ -f "$_src" ]; then
        mkdir -p "$(dirname "$_orig")"
        cp -a "$_src" "$_orig" 2>/dev/null
      else
        echo "  [MISSING] $_orig" >> "$RESTORE_LOG"
      fi
    done
  else
    cp -a "$PLUGINS_BKDIR/files/." / 2>/dev/null
  fi
  # V20.1: tarballs are FALLBACK ONLY - used when manifest.csv is missing (was: always extracted over manifest files)
  if [ ! -f "$PLUGINS_BKDIR/manifest.csv" ]; then
    echo "  [FALLBACK] No manifest.csv - restoring from tarballs (not MD5-verified)" | tee -a "$RESTORE_LOG"
    if [ -f "$PLUGINS_BKDIR/plugins.tar.gz" ]; then
      # V4: extract excluding SystemPlugins - they differ ATV <-> SPA
      tar -xzf "$PLUGINS_BKDIR/plugins.tar.gz" -C /usr/lib/enigma2/python/Plugins/Extensions/ --exclude='*/SystemPlugins/*' 2>/dev/null
      echo "  [OK] Extensions Restored from tarball (SystemPlugins excluded)" | tee -a "$RESTORE_LOG"
    fi
    if [ -f "$PLUGINS_BKDIR/skins_full.tar.gz" ]; then
      tar -xzf "$PLUGINS_BKDIR/skins_full.tar.gz" -C /usr/share/enigma2/ 2>/dev/null
      echo "  [OK] Skins Restored from tarball" | tee -a "$RESTORE_LOG"
    fi
  else
    echo "  [SKIP] Tarballs skipped - manifest restore already done (MD5-verified)" | tee -a "$RESTORE_LOG"
  fi
  if ! is_novaler; then
    rm -rf /usr/lib/enigma2/python/Plugins/Extensions/novalerStore /usr/lib/enigma2/python/Plugins/Extensions/novalerdownloader /usr/lib/enigma2/python/Plugins/Extensions/ipaudiplus 2>/dev/null
  fi
  echo "> [3/6] Clean - مسح .pyc و .so القديمة + فحص الـ .so" | tee -a "$RESTORE_LOG"
  find /usr/lib/enigma2/python/Plugins/Extensions -name "*.pyc" -delete 2>/dev/null
  find /usr/lib/enigma2/python/Plugins/Extensions -name "__pycache__" -type d -exec rm -rf {} + 2>/dev/null
  # Any .so that fails to load will be caught in verify step and its plugin reinstalled
  find /usr/lib/enigma2/python/Plugins/Extensions -name "*.so" 2>/dev/null >> "$RESTORE_LOG"
  echo "> [4/6] Dependencies - من فيد الصورة الجديدة (مش من الباكب)" | tee -a "$RESTORE_LOG"
  _OPKG_RC=0
  if offline_is_on; then
    echo "  [OFFLINE] Dependencies - NO opkg update, NO feed - installing missing plugins ONLY from offline-cache/packages/*.ipk" | tee -a "$RESTORE_LOG"
    if [ -f "$PLUGINS_BKDIR/plugins_opkg.txt" ]; then
      while read -r _line; do _pkg=$(echo "$_line" | cut -d' ' -f1); [ -z "$_pkg" ] && continue
        case " $_SYS_BLACKLIST " in *" $_pkg "*) echo "  [SYS-OFFLINE] $_pkg - skipped (system plugin, needs feed - will stay missing offline)" | tee -a "$RESTORE_LOG"; continue ;; esac
        if is_installed "$_pkg"; then echo "  Already installed: $_pkg - Skipped" >> "$RESTORE_LOG"; else offline_install_pkg "$_pkg" | tee -a "$RESTORE_LOG" || true; fi
      done < "$PLUGINS_BKDIR/plugins_opkg.txt"
    fi
    _OPKG_RC=99
  else
  opkg update > /tmp/upanel_opkg_update.log 2>&1 || _OPKG_RC=$?
  # V23.0 CACHE-DIAG-FIX: (1) BusyBox od -A unsupported -> python3 magic check, (2) opkg files on OpenATV has NO leading space -> parse ^/ lines, (3) FootOnSat via secure_fetch 3 tries + curl fallback, (4) cache logs opkg update rc + one sample download error.
# V22.9 NO-BACKUP-SUBMENU: Backup submenu removed. Main menu: 5) Backup Ur Data (= old All), 6) Backup Ur Files (= files only). Renumbered 7-12.
# V22.8 RENAME: Full Restore -> Smart Restore, Custom Restore -> Custom Restore, no parenthetical text beside them.
# V22.7 DREAMOS-APT: DreamOS/apt Tier 4 - apt download + dpkg-repack rebuild .deb, offline_install_pkg handles .deb via dpkg.
# V22.6 CACHE-MISS-FIX: cache_offline_assets 3-tier (download -> download-only --force-reinstall -> rebuild .ipk from installed pkg). Fixes CACHE-MISS for already-installed / feed-missing packages.
# V22.5 SETUP-CACHE-PER-IMAGE: Setup-Cache + Hash-Pin per IMAGE + Python (like Backup-Cache), auto-migrate old Group cache.
# V22.4 SMART-ALL: Custom Restore + Setup-Cache (every secure_run installer cached at Setup time, Favourite replays from cache if net fails) + Files Oscam Smart.
# V22.3 SMART-RESTORE: renamed Smart Restore -> Smart Restore. Same unified logic.
# V22.2 SMART-RESTORE: opkg update failed mid-restore -> do NOT skip dependencies, fall back to cache now.
  if [ "$_OPKG_RC" != "0" ]; then
    echo "  [SMART-FALLBACK] opkg update FAILED - installing missing plugins from offline-cache/packages/*.ipk" | tee -a "$RESTORE_LOG"
    if [ -f "$PLUGINS_BKDIR/plugins_opkg.txt" ]; then
      while read -r _line; do _pkg=$(echo "$_line" | cut -d' ' -f1); [ -z "$_pkg" ] && continue
        case " $_SYS_BLACKLIST " in *" $_pkg "*) echo "  [SYS-SMART] $_pkg - skipped (system plugin, needs feed)" | tee -a "$RESTORE_LOG"; continue ;; esac
        if is_installed "$_pkg"; then echo "  Already installed: $_pkg - Skipped" >> "$RESTORE_LOG"; else offline_install_pkg "$_pkg" | tee -a "$RESTORE_LOG" || true; fi
      done < "$PLUGINS_BKDIR/plugins_opkg.txt"
    fi
    _OPKG_RC=99
  fi
  fi
  if [ -f /tmp/upanel_opkg_update.log ]; then tail -n 3 /tmp/upanel_opkg_update.log | tee -a "$RESTORE_LOG"; rm -f /tmp/upanel_opkg_update.log; fi
  if [ "$_OPKG_RC" = "99" ]; then
    echo "  [OFFLINE] Dependencies done from cache - manifest files already restored" | tee -a "$RESTORE_LOG"
  elif [ "$_OPKG_RC" != "0" ]; then
    echo "  [WARN] opkg update FAILED (no net / feed down) - skipping install loop - manifest files already restored" | tee -a "$RESTORE_LOG"
  elif [ -f "$PLUGINS_BKDIR/plugins_opkg.txt" ]; then
    while read -r _line; do
      _pkg=$(echo "$_line" | cut -d' ' -f1)
      [ -z "$_pkg" ] && continue
      # V4: skip blacklisted system plugins here too - install them fresh by name, not as backup
      case " $_SYS_BLACKLIST " in *" $_pkg "*) echo "  [SYS] Installing fresh from new feed: $_pkg" | tee -a "$RESTORE_LOG";; esac
      if is_installed "$_pkg"; then
        echo "  Already installed: $_pkg - Skipped" >> "$RESTORE_LOG"
      else
        echo "  Installing: $_pkg" | tee -a "$RESTORE_LOG"
        opkg install "$_pkg" 2>&1 | tail -n 2 | tee -a "$RESTORE_LOG"
      fi
    done < "$PLUGINS_BKDIR/plugins_opkg.txt"
  fi
  echo "> [5/6] Verify - فحص كل بلاجن لوحده + إعادة تثبيت اللي فشل" | tee -a "$RESTORE_LOG"
  _FAILED=""
  for _d in /usr/lib/enigma2/python/Plugins/Extensions/*/; do
    _plug=$(basename "$_d")
    [ -z "$_plug" ] && continue
    # py_compile every .py - catches syntax / Python-version breakage
    # V20.1: compile ONLY if .py files exist (a .so-only / data-only plugin is NOT a failure)
    if ls "$_d"*.py >/dev/null 2>&1; then
      if ! python3 -m py_compile "$_d"*.py 2>/dev/null; then
        echo "  [FAIL-COMPILE] $_plug" | tee -a "$RESTORE_LOG"
        _FAILED="$_FAILED $_plug"
        continue
      fi
    fi
    # Try import plugin.py - catches missing dependency / bad .so
    if ! python3 -c "import sys; sys.path.insert(0,'$_d'); import plugin" 2>/dev/null; then
      _err=$(python3 -c "import sys; sys.path.insert(0,'$_d'); import plugin" 2>&1 | head -n 1)
      case "$_err" in
        *enigma*|*Enigma*) echo "  [OK] $_plug (needs Enigma2 runtime - not a real failure)" >> "$RESTORE_LOG" ;;
        *cannot\ open\ shared*|*undefined\ symbol*) echo "  [FAIL-SO] $_plug - bad .so - $_err" | tee -a "$RESTORE_LOG"; _FAILED="$_FAILED $_plug" ;;
        *No\ module*|*ModuleNotFoundError*|*ImportError*) echo "  [FAIL-IMPORT] $_plug - missing lib - $_err" | tee -a "$RESTORE_LOG"; _FAILED="$_FAILED $_plug" ;;
        *) echo "  [OK] $_plug (needs Enigma2 runtime)" >> "$RESTORE_LOG" ;;
      esac
    else
      echo "  [OK] $_plug" >> "$RESTORE_LOG"
    fi
  done
  # V4: Auto-reinstall failed plugins from their original installers (same PLUGINS list)
  if [ -n "$_FAILED" ] && ! offline_is_on && ! check_net 2>/dev/null; then
    echo "  [SMART-SKIP] Failed plugins: $_FAILED - no net, reinstall would fail - tarball files stay as-is" | tee -a "$RESTORE_LOG"; _FAILED=""
  fi
  if offline_is_on && [ -n "$_FAILED" ]; then
    echo "  [OFFLINE] Failed plugins: $_FAILED - SKIPPING reinstall from installers (needs net) - tarball files stay as-is" | tee -a "$RESTORE_LOG"
  elif [ -n "$_FAILED" ]; then
    echo "  Failed plugins: $_FAILED - Reinstalling from installers..." | tee -a "$RESTORE_LOG"
    _i=1
    for _p in $PLUGINS; do
      for _f in $_FAILED; do
        if [ "$(echo "$_p" | tr 'A-Z' 'a-z')" = "$(echo "$_f" | tr 'A-Z' 'a-z')" ]; then
          echo "  Reinstalling: $_p (num $_i)" | tee -a "$RESTORE_LOG"
          install_plugin_by_num "$_i" 2>&1 | tail -n 3 | tee -a "$RESTORE_LOG"
        fi
      done
      _i=$((_i+1))
    done
    echo "  If a plugin still fails after reinstall, it is binary-incompatible with this image - no file-copy restore can fix it." | tee -a "$RESTORE_LOG"
  else
    echo "  All plugins passed verify." | tee -a "$RESTORE_LOG"
  fi
  echo "> [6/6] Verify MD5 (real - live files vs manifest) + Starting Enigma" | tee -a "$RESTORE_LOG"
  verify_plugins_md5 "$PLUGINS_BKDIR" 2>&1 | tee -a "$RESTORE_LOG"
  PLUGINS_VERIFY_RC=$?
  if [ "$PLUGINS_VERIFY_RC" != "0" ]; then echo "  [WARN] Plugins MD5 verify FAILED - some plugins may be incomplete (see DIFF/MISSING above)" | tee -a "$RESTORE_LOG"; else echo "  [OK] Plugins MD5 verify passed" | tee -a "$RESTORE_LOG"; fi
  if [ "$RESTORE_BATCH" != "1" ]; then echo "> Retrieve Enigma? (optional - no auto start, no reboot)" | tee -a "$RESTORE_LOG"; ask_retrieve_enigma; else echo "> [Batch] Enigma start is asked once by Full Restore - skipping here" | tee -a "$RESTORE_LOG"; fi
  ok "Plugins Restore V4 Done - Report: $RESTORE_LOG"
  echo "Failed (auto-reinstalled): $_FAILED"
  echo "اتأكد: Menu > Plugins - لازم تلاقي بلوجناتك - والسكين شغال صح"
  if [ "${FULL_AUTO:-0}" != "1" ]; then printf "Press ENTER to return... "; read _back; fi
}

# ORDER RULE: Plugins BEFORE Files - always. Plugins restore installs code, Files restore then restores configs that depend on that code.



# ORDER RULE: Plugins BEFORE Files - always.


# ===== CANONICAL ORDER - SINGLE SOURCE OF TRUTH =====
# Plugins FIRST, then Files. No other function may call restore_plugins_only or restore_files_setup directly except these wrappers and the manual menus.
backup_plugins_then_files() {
  echo "=== Backup All: Plugins then Files (auto - no mid prompts) ==="
  BACKUP_BATCH=1
  backup_plugins_only
  _BRC=$?
  backup_files
  _FRC=$?
  BACKUP_BATCH=0
  echo "=== Backup All Done: Plugins rc=$_BRC Files rc=$_FRC ==="
  ask_retrieve_enigma
  return 0
}
verify_files_restore() {
  _MISS=""
  for _f in /etc/enigma2/settings /etc/enigma2/lamedb /etc/enigma2/bouquets.tv; do [ -f "$_f" ] || _MISS="$_MISS $_f"; done
  if [ -f "$BKDIR/tuxbox/config/oscam.server" ] && [ ! -f /etc/tuxbox/config/oscam.server ]; then _MISS="$_MISS /etc/tuxbox/config/oscam.server"; fi
  if [ -f "$BKDIR/tuxbox/config/ncam.server" ] && [ ! -f /etc/tuxbox/config/ncam.server ]; then _MISS="$_MISS /etc/tuxbox/config/ncam.server"; fi
  if [ -n "$_MISS" ]; then echo "  [WARN] Files missing after restore:$_MISS"; else echo "  [OK] Files verify passed - settings/lamedb/bouquets present"; fi
  verify_files_md5 "$BKDIR"
  _MD5_RC=$?
  if [ "$_MD5_RC" != "0" ]; then echo "  [WARN] Files MD5 verify FAILED (see DIFF/MISSING above) - files may be incomplete"; else echo "  [OK] Files MD5 verify passed"; fi
  return $_MD5_RC
}
# ===== FORCE PLUGINS TARBALL - end of Plugins restore, BEFORE Files restore =====
# Guarantees ALL plugins return, even if manifest restore missed some files.
# Runs while Enigma is STILL stopped (RESTORE_BATCH=1), so NO init 4 / init 3 here:
# init 3 before Files restore would restart Enigma and break Files restore.
force_restore_plugins_tarball() {
  line; info "Force Plugins Tarball - end of Plugins restore, before Files restore"
  _TARBALL=""
  # 1) Same backup dir used by restore_plugins_only (exact, no glob ambiguity)
  if [ -n "${PLUGINS_BKDIR:-}" ] && [ -f "$PLUGINS_BKDIR/plugins.tar.gz" ]; then _TARBALL="$PLUGINS_BKDIR/plugins.tar.gz"; fi
  # 2) Fallback: newest matching tarball for this Python version (same pattern as your command)
  if [ -z "$_TARBALL" ]; then _TARBALL=$(ls -t "$BACKUP_ROOT"/U-Panel-Plugins-Backup-*/Python$PY_MM/plugins.tar.gz "$BACKUP_ROOT"/U-Panel-Backup-*/Python$PY_MM/plugins/plugins.tar.gz 2>/dev/null | head -1); fi
  if [ -z "$_TARBALL" ] || [ ! -f "$_TARBALL" ]; then echo "[FORCE-PLUGINS] No plugins.tar.gz found - skipping force restore"; return 0; fi
  echo "[FORCE-PLUGINS] Tarball: $_TARBALL"
  echo "[FORCE-PLUGINS] Enigma already stopped - extracting WITHOUT init 4 / init 3"
  tar -xzf "$_TARBALL" -C /usr/lib/enigma2/python/Plugins/Extensions/ --exclude='*/SystemPlugins/*' 2>/dev/null
  echo "[FORCE-PLUGINS] Extensions count after force restore: $(ls /usr/lib/enigma2/python/Plugins/Extensions/ 2>/dev/null | wc -l)"
  find /usr/lib/enigma2/python/Plugins/Extensions -name "*.pyc" -delete 2>/dev/null
  find /usr/lib/enigma2/python/Plugins/Extensions -name "__pycache__" -type d -exec rm -rf {} + 2>/dev/null
  # V20.4 FIX 1: Skins were NOT restored by Force Tarball (only plugins.tar.gz) - now restore skins_full.tar.gz too
  _SKINS=""
  if [ -n "${PLUGINS_BKDIR:-}" ] && [ -f "$PLUGINS_BKDIR/skins_full.tar.gz" ]; then _SKINS="$PLUGINS_BKDIR/skins_full.tar.gz"; fi
  if [ -z "$_SKINS" ]; then _SKINS=$(ls -t "$BACKUP_ROOT"/U-Panel-Plugins-Backup-*/Python$PY_MM/skins_full.tar.gz "$BACKUP_ROOT"/U-Panel-Backup-*/Python$PY_MM/plugins/skins_full.tar.gz 2>/dev/null | head -1); fi
  if [ -n "$_SKINS" ] && [ -f "$_SKINS" ]; then
    echo "[FORCE-PLUGINS] Skins tarball: $_SKINS"
    tar -xzf "$_SKINS" -C /usr/share/enigma2/ 2>/dev/null
    echo "[FORCE-PLUGINS] Skins restored from tarball"
  else
    echo "[FORCE-PLUGINS] No skins_full.tar.gz found - skipping skins force restore"
  fi
  echo "[FORCE-PLUGINS] Done - SystemPlugins excluded (from feed), Enigma still stopped for Files restore"
}
# ===== FORCE REINSTALL FootOnSat - after Force Tarball, BEFORE Files restore =====
# Runs while Enigma is STILL stopped, so NO init 4 / init 3 here (same reason as tarball step).
# Reboot Guard is already ON, so if installer.sh tries reboot/kill enigma, it gets blocked.
force_reinstall_footonsat() {
  line; info "Force Reinstall FootOnSat - after Force Tarball, before Files restore"
  echo "[FOOTONSAT] Enigma already stopped - reinstalling WITHOUT init 4 / init 3"
  rm -rf /usr/lib/enigma2/python/Plugins/Extensions/FootOnSat /usr/lib/enigma2/python/Plugins/Extensions/FootOnsat 2>/dev/null
  rm -f /usr/lib/enigma2/python/Plugins/Extensions/FootOnSat*.pyc 2>/dev/null
  echo "[FOOTONSAT] Old FootOnSat removed - installer source: cache first, then download"
  _FOOT_CACHED="$(offline_cache_dir)/footonsat/installer.sh"
  if [ -f "$_FOOT_CACHED" ]; then
    echo "[FOOTONSAT] Using CACHED installer (offline-safe): $_FOOT_CACHED"; cp "$_FOOT_CACHED" /tmp/foot.sh; sh /tmp/foot.sh; echo "[FOOTONSAT] Cached installer finished (rc=$?)"
  elif offline_is_on; then
    echo "[FOOTONSAT] [OFFLINE-SKIP] No cached installer.sh - FootOnSat stays as restored from tarball, continuing to Files restore"
  elif wget --no-check-certificate https://dreambox4u.com/emilnabil237/plugins/FootOnsat/installer.sh -O /tmp/foot.sh 2>/dev/null; then
    sh /tmp/foot.sh
    echo "[FOOTONSAT] Installer finished (rc=$?)"
  else
    echo "[FOOTONSAT] [WARN] Download failed - skipping FootOnSat reinstall, continuing to Files restore"
  fi
  rm -f /tmp/foot.sh 2>/dev/null
  echo "[FOOTONSAT] Check:"
  ls /usr/lib/enigma2/python/Plugins/Extensions/ 2>/dev/null | grep -i foot || echo "[FOOTONSAT] [WARN] No Foot* folder found after reinstall"
  echo "[FOOTONSAT] Done - Enigma still stopped for Files restore"
}
# ===== VERIFY AFTER FORCE - V20.4 FIX 2 =====
# restore_plugins_only verifies BEFORE the Force Tarball, so plugins/skins
# restored ONLY by the Force Tarball were never verified. Re-verify here:
# MD5 (live vs manifest) + py_compile for every Extensions plugin.
# Failed plugins are reinstalled from their original installers (same PLUGINS list).
verify_after_force_plugins() {
  line; info "Verify After Force Tarball - MD5 + py_compile - before Files restore"
  _AF_FAILED=""
  echo "[VERIFY-AFTER-FORCE] MD5 (live vs manifest):"
  verify_plugins_md5 "$PLUGINS_BKDIR" 2>&1 | tee -a "$RESTORE_LOG"
  _AF_MD5=$?
  if [ "$_AF_MD5" != "0" ]; then echo "  [WARN] MD5 after force restore FAILED - see DIFF/MISSING above" | tee -a "$RESTORE_LOG"; else echo "  [OK] MD5 after force restore passed" | tee -a "$RESTORE_LOG"; fi
  PLUGINS_VERIFY_RC=$_AF_MD5
  echo "[VERIFY-AFTER-FORCE] py_compile every Extensions plugin:"
  for _d in /usr/lib/enigma2/python/Plugins/Extensions/*/; do
    _plug=$(basename "$_d"); [ -z "$_plug" ] && continue
    if ls "$_d"*.py >/dev/null 2>&1; then
      if ! python3 -m py_compile "$_d"*.py 2>/dev/null; then
        echo "  [FAIL-COMPILE-AFTER-FORCE] $_plug" | tee -a "$RESTORE_LOG"; _AF_FAILED="$_AF_FAILED $_plug"
      fi
    fi
  done
  if [ -n "$_AF_FAILED" ] && ! offline_is_on && ! check_net 2>/dev/null; then
    echo "  [SMART-SKIP] Failed after force restore: $_AF_FAILED - no net, reinstall would fail - tarball files stay as-is" | tee -a "$RESTORE_LOG"; _AF_FAILED=""
  fi
  if offline_is_on && [ -n "$_AF_FAILED" ]; then
    echo "  [OFFLINE] Failed after force restore: $_AF_FAILED - SKIPPING reinstall from installers (needs net) - tarball files stay as-is" | tee -a "$RESTORE_LOG"
  elif [ -n "$_AF_FAILED" ]; then
    echo "  Failed after force restore: $_AF_FAILED - Reinstalling from installers..." | tee -a "$RESTORE_LOG"
    _i=1
    for _p in $PLUGINS; do
      for _f in $_AF_FAILED; do
        if [ "$(echo "$_p" | tr 'A-Z' 'a-z')" = "$(echo "$_f" | tr 'A-Z' 'a-z')" ]; then
          echo "  Reinstalling: $_p (num $_i)" | tee -a "$RESTORE_LOG"
          install_plugin_by_num "$_i" 2>&1 | tail -n 3 | tee -a "$RESTORE_LOG"
        fi
      done
      _i=$((_i+1))
    done
  else
    echo "  [OK] All Extensions plugins passed py_compile after force restore" | tee -a "$RESTORE_LOG"
  fi
  echo "[VERIFY-AFTER-FORCE] Done - continuing to FootOnSat / Files restore"
}
# ===== PLUGINS + 2 EXTRAS (no Files) - shared by Full / Selective Plugins / Selective All =====
# Plugins restore -> Force Tarball (+Skins) -> Verify After Force -> FootOnSat
restore_plugins_with_extras() {
  line; info "Restore Plugins + Extras (auto)"
  RESTORE_BATCH=1
  restore_plugins_only
  _PLUG_RC=$?
  if [ "$_PLUG_RC" = "2" ]; then echo "Plugins Restore cancelled - stopped"; RESTORE_BATCH=0; return 2; fi
  if [ "$_PLUG_RC" != "0" ]; then echo "Plugins Restore failed (rc=$_PLUG_RC) - stopped"; RESTORE_BATCH=0; return 1; fi
  force_restore_plugins_tarball
  verify_after_force_plugins
  force_reinstall_footonsat
  RESTORE_BATCH=0
  return 0
}
restore_plugins_then_files() {
  line; info "Restore Order: 1) Plugins (V5 verify + reinstall failed, SystemPlugins from feed)  1.5) Force Plugins Tarball (+Skins)  1.6) Verify After Force (MD5+py_compile)  1.7) Force Reinstall FootOnSat  2) Files (verify)"
  RESTORE_BATCH=1
  restore_plugins_with_extras
  _PLUG_RC=$?
  if [ "$_PLUG_RC" != "0" ]; then echo "Plugins Restore failed/cancelled (rc=$_PLUG_RC) - Files Restore stopped"; RESTORE_BATCH=0; return $_PLUG_RC; fi
  RESTORE_BATCH=1
  restore_files_setup
  _FILES_RC=$?
  RESTORE_BATCH=0
  verify_files_restore
  _VRF_RC=$?
  if [ "${PLUGINS_VERIFY_RC:-0}" != "0" ] || [ "$_VRF_RC" != "0" ]; then echo "[VERIFY-WARN] Full Restore MD5 differs (plugins rc=${PLUGINS_VERIFY_RC:-0}, files rc=$_VRF_RC) - continuing, see report (V20: warn, not stop)"; log_msg "Full Restore MD5 warn: plugins=${PLUGINS_VERIFY_RC:-0} files=$_VRF_RC"; fi
  return $_FILES_RC
}
# ===== V7 - Safety + Manager + Selective + Report (Items 1-8) =====
# (1) Pre-check: HDD mounted + space + net - returns 0 OK, 1 FAIL
check_hdd_space() {
  _NEED="${1:-Backup}"; _FAIL=""
  if ! mount | grep -q " /media/hdd " && ! mount | grep -q " $BACKUP_ROOT "; then [ ! -d "$BACKUP_ROOT" ] && _FAIL="$_FAIL HDD-missing"; fi
  _FREE_KB=$(df "$BACKUP_ROOT" 2>/dev/null | tail -n 1 | awk '{print $4}')
  [ -z "$_FREE_KB" ] && _FREE_KB=0
  if [ "$_FREE_KB" -lt 500000 ]; then _FAIL="$_FAIL LowSpace(${_FREE_KB}KB)"; fi
  if [ -n "$_FAIL" ]; then echo "[CHECK-FAIL] $_NEED blocked:$_FAIL"; echo "  Fix HDD / space and retry."; return 1; fi
  echo "[CHECK-OK] $_NEED - HDD OK, Free: ${_FREE_KB}KB"; return 0
}
check_net() {
  if ! ping -c 1 -W 3 8.8.8.8 >/dev/null 2>&1; then
    if ! wget -q --timeout=5 -O /dev/null https://raw.githubusercontent.com 2>/dev/null; then echo "[CHECK-FAIL] NoNet"; return 1; fi
  fi
  echo "[CHECK-OK] Net OK"; return 0
}
# V20: backup/restore are LOCAL - they use check_hdd_space only. Net is checked only before downloads.
check_hdd_space_net() {
  _NEED="${1:-Backup}"
  _FAIL=""
  if ! mount | grep -q " /media/hdd "; then [ ! -d /media/hdd ] && _FAIL="$_FAIL HDD-missing"; fi
  _FREE_KB=$(df /media/hdd 2>/dev/null | tail -n 1 | awk '{print $4}')
  [ -z "$_FREE_KB" ] && _FREE_KB=0
  if [ "$_FREE_KB" -lt 500000 ]; then _FAIL="$_FAIL LowSpace(${_FREE_KB}KB)"; fi
  if ! ping -c 1 -W 3 8.8.8.8 >/dev/null 2>&1; then
    if ! wget -q --timeout=5 -O /dev/null https://raw.githubusercontent.com 2>/dev/null; then _FAIL="$_FAIL NoNet"; fi
  fi
  if [ -n "$_FAIL" ]; then echo "[CHECK-FAIL] $_NEED blocked:$_FAIL"; echo "  Fix HDD / space / net and retry."; return 1; fi
  echo "[CHECK-OK] $_NEED - HDD OK, Free: ${_FREE_KB}KB, Net OK"; return 0
}
# Full Image safety: HDD + 2GB free + zip available - Full Image is ONE big ZIP, not per-file backup
check_full_image_space() {
  _FAIL=""
  if ! mount | grep -q " /media/hdd "; then [ ! -d /media/hdd ] && _FAIL="$_FAIL HDD-missing"; fi
  _FREE_KB=$(df /media/hdd 2>/dev/null | tail -n 1 | awk '{print $4}'); [ -z "$_FREE_KB" ] && _FREE_KB=0
  _ROOT_KB=$(du -sk / --exclude=/media --exclude=/proc --exclude=/sys --exclude=/tmp --exclude=/dev --exclude=/run --exclude=/boot 2>/dev/null | cut -f1); [ -z "$_ROOT_KB" ] && _ROOT_KB=1500000
  _NEED_KB=$((_ROOT_KB + 500000))
  [ "$_FREE_KB" -lt 2000000 ] && _FAIL="$_FAIL LowSpace(${_FREE_KB}KB < 2GB)"
  if [ -n "$_FAIL" ]; then echo "[CHECK-FAIL] Full Image blocked:$_FAIL"; echo "  Need: ~$((_NEED_KB/1024))MB free on /media/hdd - Free now: $((_FREE_KB/1024))MB - Root size: $((_ROOT_KB/1024))MB"; return 1; fi
  echo "[CHECK-OK] Full Image - HDD OK, Free: $((_FREE_KB/1024))MB, Need ~$((_NEED_KB/1024))MB (root $((_ROOT_KB/1024))MB + 500MB margin)"
  return 0
}
# ===== Download protection: retry + verify before running - never pipe wget straight to sh =====
# secure_fetch URL DEST LABEL [EXPECTED_SHA256-or-empty]: 3 tries, timeout, rejects HTML/404/empty/too-small
is_zip_file() {
  _F="$1"; [ -f "$_F" ] || return 1
  if command -v python3 >/dev/null 2>&1; then python3 -c "import sys; d=open(sys.argv[1],'rb').read(2); sys.exit(0 if d==b'PK' else 1)" "$_F" 2>/dev/null && return 0; return 1; fi
  return 1
}
secure_fetch() {
  _U="$1"; _D="$2"; _L="$3"; _EXP="$4"; _TRY=0
  while [ "$_TRY" -lt 3 ]; do _TRY=$((_TRY+1)); rm -f "$_D"
    # RESUME (V 3.4): keep a partial .tmp and continue it. Only the FIRST
    # try resumes; later tries start fresh (a broken partial must not loop).
    if [ "$_TRY" -gt 1 ]; then rm -f "$_D.tmp"; fi
    if [ -s "$_D.tmp" ]; then echo "  [RESUME] Continuing partial download: $(stat -c%s "$_D.tmp" 2>/dev/null)B already have."; fi
    _DL_OK=1
    if command -v wget >/dev/null 2>&1; then wget -c --no-check-certificate --timeout=20 --tries=1 -O "$_D.tmp" "$_U" 2>/dev/null || _DL_OK=0
    elif command -v curl >/dev/null 2>&1; then curl -k -L -C - --max-time 20 -o "$_D.tmp" "$_U" 2>/dev/null || _DL_OK=0
    else echo "  [FETCH-FAIL] $_L: no wget/curl"; _DL_OK=0; fi
    if [ "$_DL_OK" = "1" ]; then
      _SZ=$(stat -c%s "$_D.tmp" 2>/dev/null); [ -z "$_SZ" ] && _SZ=0
      _HEAD=$(head -c 300 "$_D.tmp" 2>/dev/null | tr '[:upper:]' '[:lower:]')
      case "$_HEAD" in *"<html"*|*"404 not found"*|*"not found"*|*"repository not found"*) echo "  [FETCH-FAIL] $_L: got HTML/404 (try $_TRY/3)"; sleep 2; continue ;; esac
      if [ "$_SZ" -lt 20 ]; then echo "  [FETCH-FAIL] $_L: too small (${_SZ}B, try $_TRY/3)"; sleep 2; continue; fi
      case "$_D" in *.sh|*.installer) if ! grep -q -E 'echo|wget|opkg|mkdir|cp |install|#!/bin/sh|#!/bin/bash' "$_D.tmp" 2>/dev/null; then echo "  [FETCH-FAIL] $_L: not a shell installer (try $_TRY/3)"; sleep 2; continue; fi ;; *.tar.gz|*.tgz) if ! is_gzip_file "$_D.tmp"; then echo "  [FETCH-FAIL] $_L: not gzip (try $_TRY/3)"; sleep 2; continue; fi ;; *.zip) if ! is_zip_file "$_D.tmp"; then echo "  [FETCH-FAIL] $_L: not zip (try $_TRY/3)"; sleep 2; continue; fi ;; *.ipk) _MG=$(head -c 7 "$_D.tmp" 2>/dev/null); case "$_MG" in *'!<arch>'*) ;; *) echo "  [FETCH-FAIL] $_L: not ipk/ar (try $_TRY/3)"; sleep 2; continue ;; esac ;; esac
      if [ -n "$_EXP" ]; then _GOT=$(md5sum "$_D.tmp" 2>/dev/null | cut -d' ' -f1); [ "$_GOT" != "$_EXP" ] && echo "  [FETCH-FAIL] $_L: checksum mismatch (try $_TRY/3)" && sleep 2 && continue; fi
      mv "$_D.tmp" "$_D"; echo "  [FETCH-OK] $_L: ${_SZ}B from $_U"; return 0
    else echo "  [FETCH-FAIL] $_L: wget failed (try $_TRY/3)"; sleep 2; fi
  done
  rm -f "$_D.tmp"; echo "  [FETCH-FAIL] $_L: gave up after 3 tries - SKIPPED, install NOT run"; return 1
}
# V22.5: Setup-Cache per IMAGE + Python - EXACTLY like Backup-Cache. Old Group cache is
# auto-migrated (copied) once into the new per-image dir, so nothing already cached is lost.
setup_cache_dir() {
  _IMG_FOLDER=$(echo "$IMAGE" | tr ' ' '_' | tr -d '()' | tr -d '/'); [ -z "$_IMG_FOLDER" ] && _IMG_FOLDER="Unknown"
  echo "$UPANEL_ROOT-Setup-Cache-$_IMG_FOLDER/Python$PY_MM"
}
setup_hash_file() { echo "$(setup_cache_dir)/U-Panel-Installer-Hashes.txt"; }
migrate_setup_cache() {
  _NEW="$(setup_cache_dir)/installers"; _OLD="$UPANEL_ROOT-Setup-Cache-$BK/installers"
  [ -d "$_OLD" ] || return 0; mkdir -p "$_NEW" 2>/dev/null
  if [ -z "$(ls "$_NEW" 2>/dev/null)" ] && [ -n "$(ls "$_OLD" 2>/dev/null)" ]; then
    cp -a "$_OLD/." "$_NEW/" 2>/dev/null; echo "  [SETUP-CACHE-MIGRATE] Old Group cache ($BK) copied to per-image cache: $_NEW"
  fi
  # Hash pins: copy old global pins once, so already-pinned installers keep working
  _OLD_HASH="$UPANEL_ROOT-Installer-Hashes.txt"; _NEW_HASH="$(setup_hash_file)"
  if [ -f "$_OLD_HASH" ] && [ ! -f "$_NEW_HASH" ]; then cp "$_OLD_HASH" "$_NEW_HASH" 2>/dev/null; echo "  [HASH-MIGRATE] Old hash pins copied to per-image hash file"; fi
}
secure_run() {
  _U="$1"; _L="${2:-installer}"; _F="/tmp/secure_$$_${_L}.sh"; _F=$(echo "$_F" | tr -cd 'a-zA-Z0-9_/.=-')
  migrate_setup_cache
  _SCACHE="$(setup_cache_dir)/installers"; mkdir -p "$_SCACHE" 2>/dev/null
  _CACHED="$_SCACHE/$(echo "$_L" | tr -cd 'a-zA-Z0-9_.-').sh"
  if ! secure_fetch "$_U" "$_F" "$_L" ""; then
    # V22.4 SMART: download failed - fall back to the installer cached during Setup your Enigma
    if [ -f "$_CACHED" ]; then echo "  [SMART-FALLBACK] $_L: download failed - using Setup-Cache installer: $_CACHED"; cp "$_CACHED" "$_F"; else echo "  [SMART] $_L: no cached installer - giving up"; return 1; fi
  else
    # V22.4 SETUP-CACHE: every installer executed (plugins + channels) is saved as it runs,
    # so Ur Favourite Setup can replay it later with NO net.
    cp "$_F" "$_CACHED" 2>/dev/null && echo "  [SETUP-CACHE] $_L saved: $_CACHED"
  fi
  # V20: installer hash pinning (TOFU) - first download is recorded, later downloads must match
  _HASH_FILE="$(setup_hash_file)"
  _H=$(sha256sum "$_F" 2>/dev/null | cut -d' ' -f1)
  if [ -n "$_H" ]; then
    _PIN=$(grep -F "$_L|" "$_HASH_FILE" 2>/dev/null | cut -d'|' -f2 | tail -1)
    if [ -n "$_PIN" ] && [ "$_PIN" != "$_H" ]; then echo "  [HASH-FAIL] $_L changed since first download - REFUSING to run (possible tampering)"; rm -f "$_F"; return 1; fi
    if [ -z "$_PIN" ]; then echo "$_L|$_H" >> "$_HASH_FILE" 2>/dev/null; echo "  [HASH-PIN] $_L pinned: ${_H}"; else echo "  [HASH-OK] $_L matches pinned hash"; fi
  fi
  echo "  [RUN] $_L: executing verified installer (${_F})"
  /bin/sh "$_F"; _RC=$?; rm -f "$_F"; [ "$_RC" != "0" ] && echo "  [RUN-FAIL] $_L: installer exited rc=$_RC" || echo "  [RUN-OK] $_L done"
  return $_RC
}
secure_fetch_file() {
  secure_fetch "$1" "$2" "${3:-file}" ""
}
opkg_with_retry() {
  if ! command -v opkg >/dev/null 2>&1 && command -v apt-get >/dev/null 2>&1; then echo "  [APT] apt-get install: $*"; apt-get update 2>/dev/null; apt-get install -y "$@" 2>/dev/null && return 0; echo "  [APT-FAIL] $*"; return 1; fi
  _TRY=0; while [ "$_TRY" -lt 2 ]; do _TRY=$((_TRY+1)); opkg update 2>/dev/null && break; sleep 3; done
  _TRY=0; while [ "$_TRY" -lt 3 ]; do _TRY=$((_TRY+1)); opkg install "$@" 2>/dev/null && return 0; echo "  [OPKG] install try $_TRY/3 failed: $*"; sleep 3; done; echo "  [OPKG-FAIL] gave up: $*"; return 1
}
# (2) Safe swap: tmp -> real, keep old as .prev
swap_backup_dir() {
  _REAL="$1"; _TMP="$2"
  case "$_REAL" in /*) ;; *) echo "[SWAP-FAIL] _REAL not absolute: $_REAL"; return 1;; esac
  case "$_TMP" in /*) ;; *) echo "[SWAP-FAIL] _TMP not absolute: $_TMP"; return 1;; esac
  [ ! -d "$_TMP" ] && echo "[SWAP-FAIL] tmp missing: $_TMP" && return 1
  if [ -d "$_REAL" ]; then rm -rf "$_REAL.prev"; mv "$_REAL" "$_REAL.prev" || return 1; fi
  mv "$_TMP" "$_REAL" || { echo "[SWAP-FAIL] mv failed - old kept in $_REAL.prev"; return 1; }
  echo "[SWAP-OK] Backup published: $_REAL (old kept in $_REAL.prev)"; return 0
}
# (8) Files manifest: md5 for every file in BKDIR
generate_files_manifest() {
  _B="$1"; [ -z "$_B" ] && _B="$BKDIR"
  _M="$_B/files_manifest.csv"; echo "file,orig_path,size,md5" > "$_M"
  (cd -- "$_B" && _MT=$(find . -type f ! -name "files_manifest.csv" ! -name "backup_info.txt" 2>/dev/null | wc -l) && _MN=0 && find . -type f ! -name "files_manifest.csv" ! -name "backup_info.txt" 2>/dev/null | while read -r _f; do _sz=$(stat -c%s "$_B/$_f" 2>/dev/null); _md=$(md5sum "$_B/$_f" 2>/dev/null | cut -d' ' -f1); echo "\"$_f\",\"$_f\",\"$_sz\",\"$_md\"" >> "$_M"; _MN=$((_MN+1)); [ $(( _MN % 500 )) = 0 ] && echo "  Manifest... $_MN / $_MT files"; done)
  echo "[MANIFEST] Files manifest: $_M - $(wc -l < "$_M") entries"
}
verify_files_md5() {
  _B="$1"; [ -z "$_B" ] && _B="$BKDIR"
  _M="$_B/files_manifest.csv"; [ ! -f "$_M" ] && echo "[MD5] No files manifest - skipped (old backup?)" && return 0
  _BAD=0; _OKN=0; _MISS=0
  _TMPV="/tmp/verify_md5_$$.txt"; : > "$_TMPV"
  tail -n +2 "$_M" | while IFS= read -r _line; do _line=${_line#'"'}; _line=${_line%'"'}; _qfile=${_line%%'",'*}; _csvrest=${_line#*'",'}; _qorig=${_csvrest%%'",'*}; _csvrest=${_csvrest#*'",'}; _qsize=${_csvrest%%'",'*}; _qmd5=${_csvrest#*'",'}; _f=$(echo "$_qorig" | tr -d '"'); _exp=$(echo "$_qmd5" | tr -d '"'); [ -z "$_f" ] && continue; _dest="$_f"; case "$_dest" in ./*) _dest="${_dest#./}";; esac
    case "$_dest" in
      enigma2/*) _live="/etc/enigma2/${_dest#enigma2/}" ;;
      tuxbox/*) _live="/etc/${_dest}" ;;
      keys/*) case "$(basename "$_dest")" in "autosub key") _live="/etc/enigma2/autosub key" ;; "autosub.key") _live="/etc/enigma2/autosub.key" ;; "groqapi.key") _live="/etc/enigma2/groqapi.key" ;; *) _live="/etc/enigma2/$(basename "$_dest")" ;; esac ;;
      emu/bin/*) _live="/usr/bin/$(basename "$_dest")" ;;
      emu/*) _live="" ;;
      skin/*) _live="/usr/share/enigma2/${_dest#skin/}" ;;
      picon/*) _live="" ;;
      image/*) _live="/etc/$(basename "$_dest")" ;;
      iptv/*|personal/*) _MAN="$_B/${_dest%%/*}/locations.txt"; _live=$(grep -F "$_dest|" "$_MAN" 2>/dev/null | cut -d'|' -f2 | head -1) ;;
      *) _live="" ;;
    esac
    [ -z "$_live" ] && echo "SKIP $_dest" >> "$_TMPV" && continue
    [ ! -f "$_live" ] && echo "MISSING $_live" >> "$_TMPV" && continue
    _got=$(md5sum "$_live" 2>/dev/null | cut -d' ' -f1)
    if [ "$_got" = "$_exp" ]; then echo "OK $_live" >> "$_TMPV"; else echo "DIFF $_live" >> "$_TMPV"; fi
  done
  _OKN=$(grep -c '^OK ' "$_TMPV" 2>/dev/null); _BAD=$(grep -c '^DIFF ' "$_TMPV" 2>/dev/null); _MISS=$(grep -c '^MISSING ' "$_TMPV" 2>/dev/null)
  grep '^MISSING \|^DIFF ' "$_TMPV" 2>/dev/null | head -n 20
  rm -f "$_TMPV"
  echo "[MD5] Files verify: OK=$_OKN DIFF=$_BAD MISSING=$_MISS"
  [ "$_BAD" = "0" ] && [ "$_MISS" = "0" ] && return 0 || return 1
}
