    _got=$(md5sum "$_bk" 2>/dev/null | cut -d' ' -f1); _want=$(md5sum "$_live" 2>/dev/null | cut -d' ' -f1)
    if [ "$_got" = "$_want" ]; then echo "OK $_rel" >> "$_TMPV"; else echo "DIFF $_rel (backup != live)" >> "$_TMPV"; fi
    _VN=$((_VN+1)); [ $(( _VN % 500 )) = 0 ] && echo "  Verifying files... $_VN / $_VT files"
  done
  _OKN=$(grep -c '^OK ' "$_TMPV" 2>/dev/null); _BAD=$(grep -c '^DIFF ' "$_TMPV" 2>/dev/null); _MISS=$(grep -c '^MISSING ' "$_TMPV" 2>/dev/null)
  grep '^MISSING \|^DIFF ' "$_TMPV" 2>/dev/null | head -n 20; rm -f "$_TMPV"
  echo "[MD5-FILES-BK] Backup verify: OK=$_OKN DIFF=$_BAD MISSING=$_MISS"
  [ "$_BAD" = "0" ] && [ "$_MISS" = "0" ] && return 0 || return 1
}
selective_snapshot() {
  _SNAP="$BKDIR/BeforeRestore-Files-$(date +%Y%m%d_%H%M%S)"; mkdir -p "$_SNAP"
  cp -a /etc/enigma2/settings "$_SNAP/settings" 2>/dev/null; cp -a /etc/enigma2/lamedb "$_SNAP/lamedb" 2>/dev/null
  cp -a /etc/enigma2/*.bouquet "$_SNAP/" 2>/dev/null; cp -a /etc/enigma2/bouquets.tv /etc/enigma2/bouquets.radio "$_SNAP/" 2>/dev/null
  mkdir -p "$_SNAP/tuxbox_config"; cp -a /etc/tuxbox/config/. "$_SNAP/tuxbox_config/" 2>/dev/null
  for _k in "/etc/enigma2/autosub key" /etc/enigma2/autosub.key /etc/enigma2/groqapi.key; do [ -f "$_k" ] && cp -a "$_k" "$_SNAP/" 2>/dev/null; done
  echo "$_SNAP"
}
selective_stop_enigma() { /sbin/init 4 2>/dev/null || /usr/sbin/init 4 2>/dev/null || /bin/init 4 2>/dev/null; sleep 3; /usr/bin/killall -9 enigma2 2>/dev/null || /bin/killall -9 enigma2 2>/dev/null; sleep 2; }
selective_start_enigma() { /sbin/init 3 2>/dev/null || /usr/sbin/init 3 2>/dev/null || /bin/init 3 2>/dev/null; sleep 3; if ! ps | grep -v grep | grep -q enigma2; then enigma2 & sleep 2; fi; }
ask_retrieve_enigma() { if [ "$RESTORE_BATCH" = "1" ] || [ "$BACKUP_BATCH" = "1" ] || [ "$SETUP_BATCH" = "1" ]; then return 0; fi; if ps | grep -v grep | grep -q enigma2; then return 0; fi; printf "Retrieve Enigma? (y/n): "; read _re; case "$_re" in y|Y) selective_start_enigma; echo "[ENIGMA] Enigma started - No Reboot" ;; *) echo "[ENIGMA-STOPPED] Enigma stays STOPPED - screen stays black - continue in the script menu" ;; esac; }
selective_restore_channels() {
  ensure_files_backup_extracted; [ -d "$BKDIR" ] || { echo "[ERROR] No Files backup: $BKDIR"; return 1; }
  _SNAP=$(selective_snapshot); echo "  [SNAP] $_SNAP"; selective_stop_enigma
  cp -a "$BKDIR/enigma2/"*.bouquet "$BKDIR/enigma2/"*.tv "$BKDIR/enigma2/"*.radio /etc/enigma2/ 2>/dev/null
  cp -a "$BKDIR/enigma2/userbouquet."* "$BKDIR/enigma2/bouquets.tv" "$BKDIR/enigma2/bouquets.radio" /etc/enigma2/ 2>/dev/null
  [ -f "$BKDIR/enigma2/lamedb" ] && cp -a "$BKDIR/enigma2/lamedb" /etc/enigma2/lamedb
  if [ -f /etc/enigma2/lamedb ] && ls /etc/enigma2/*.bouquet >/dev/null 2>&1; then echo "  [OK] Channels restored + verified"; else echo "  [WARN] Channels verify FAILED"; fi
  ask_retrieve_enigma
}
selective_restore_skin() {
  ensure_files_backup_extracted; [ -d "$BKDIR" ] || { echo "[ERROR] No Files backup: $BKDIR"; return 1; }
  _SK=$(cat "$BKDIR/skin/active_skin.txt" 2>/dev/null); [ -z "$_SK" ] && echo "Skin not in backup" && return 1
  [ -d "$BKDIR/skin/$_SK" ] || { echo "Skin $_SK not in backup"; return 1; }
  _SNAP=$(selective_snapshot); echo "  [SNAP] $_SNAP"; selective_stop_enigma
  cp -a "$BKDIR/skin/$_SK" /usr/share/enigma2/ && echo "  [OK] Skin $_SK copied"
  sed -i "/^config.skin.primary_skin=/d" /etc/enigma2/settings; echo "config.skin.primary_skin=$_SK/skin.xml" >> /etc/enigma2/settings; echo "  [OK] primary_skin set to $_SK"
  if [ -d "/usr/share/enigma2/$_SK" ] && grep -q "config.skin.primary_skin=$_SK/skin.xml" /etc/enigma2/settings; then echo "  [OK] Skin restored + verified"; else echo "  [WARN] Skin verify FAILED"; fi
  ask_retrieve_enigma
}
selective_restore_emu() {
  ensure_files_backup_extracted; [ -d "$BKDIR" ] || { echo "[ERROR] No Files backup: $BKDIR"; return 1; }
  _SNAP=$(selective_snapshot); echo "  [SNAP] $_SNAP"; selective_stop_enigma
  [ -d "$BKDIR/tuxbox/config" ] && rm -rf /etc/tuxbox/config && cp -a "$BKDIR/tuxbox/config" /etc/tuxbox/config && echo "  [OK] Oscam config restored"
  for _b in "$BKDIR/emu/bin/"*; do [ -f "$_b" ] && cp -a "$_b" /usr/bin/ && chmod +x "/usr/bin/$(basename "$_b")"; done; echo "  [OK] Emu binaries restored"
  if [ -f /etc/tuxbox/config/oscam.server ]; then echo "  [OK] Emu+Oscam verified: oscam.server present"; else echo "  [WARN] Emu verify FAILED: oscam.server missing"; fi
  ask_retrieve_enigma
  if [ -x /etc/init.d/softcam ]; then /etc/init.d/softcam restart 2>/dev/null && echo "  [OK] softcam restarted"; fi
}
selective_restore_keys() {
  ensure_files_backup_extracted; [ -d "$BKDIR" ] || { echo "[ERROR] No Files backup: $BKDIR"; return 1; }
  _SNAP=$(selective_snapshot); echo "  [SNAP] $_SNAP"
  [ -f "$BKDIR/keys/autosub key" ] && cp -a "$BKDIR/keys/autosub key" "/etc/enigma2/autosub key" && cp -a "$BKDIR/keys/autosub key" /etc/enigma2/autosub.key
  [ -f "$BKDIR/keys/autosub.key" ] && cp -a "$BKDIR/keys/autosub.key" /etc/enigma2/autosub.key && cp -a "$BKDIR/keys/autosub.key" "/etc/enigma2/autosub key"
  [ -f "$BKDIR/keys/groqapi.key" ] && cp -a "$BKDIR/keys/groqapi.key" /etc/enigma2/groqapi.key && cp -a "$BKDIR/keys/groqapi.key" /etc/groqapi.key
  _MISS=""; [ ! -f "/etc/enigma2/autosub key" ] && [ ! -f /etc/enigma2/autosub.key ] && _MISS="$_MISS autosub"; [ ! -f /etc/enigma2/groqapi.key ] && _MISS="$_MISS groqapi"
  if [ -z "$_MISS" ]; then echo "  [OK] Keys restored + verified"; else echo "  [WARN] Keys verify: missing$_MISS"; fi
}
selective_restore_network() {
  ensure_files_backup_extracted; [ -d "$BKDIR" ] || { echo "[ERROR] No Files backup: $BKDIR"; return 1; }
  _SNAP=$(selective_snapshot); echo "  [SNAP] $_SNAP"
  [ -f "$BKDIR/image/hostname" ] && cp -a "$BKDIR/image/hostname" /etc/hostname && echo "  [OK] hostname restored"
  [ -f "$BKDIR/image/resolv.conf" ] && cp -a "$BKDIR/image/resolv.conf" /etc/resolv.conf && echo "  [OK] resolv.conf restored"
  [ -f "$BKDIR/image/interfaces" ] && cp -a "$BKDIR/image/interfaces" /etc/network/interfaces && echo "  [OK] interfaces restored"
}
selective_restore_bootlogo() { echo "BootLogo Auto - Image: $IMAGE"; install_bootlogo_auto; }
ensure_files_backup_extracted() {
  if [ ! -d "$BKDIR" ] && [ -f "$BKDIR.tar.gz" ]; then echo "[EXTRACT] Old backup is compressed - extracting $BKDIR.tar.gz ..."; mkdir -p "$BKDIR"; tar -xzf "$BKDIR.tar.gz" -C "$(dirname "$BKDIR")" 2>/dev/null && echo "  [OK] Extracted"; fi
  # V20.1: unified folder - old compressed backup may be the whole Python<MM> dir (plugins+files)
  if [ ! -d "$BKDIR" ] && [ -f "$(dirname "$BKDIR").tar.gz" ]; then echo "[EXTRACT] Old unified backup compressed - extracting $(dirname "$BKDIR").tar.gz ..."; mkdir -p "$(dirname "$BKDIR")"; tar -xzf "$(dirname "$BKDIR").tar.gz" -C "$(dirname "$(dirname "$BKDIR")")" 2>/dev/null && echo "  [OK] Extracted unified backup"; fi
}
# (3) Files rollback: restore from latest BeforeRestore-Files-*
rollback_files() {
  ensure_files_backup_extracted
  _LATEST=$(ls -dt "$BKDIR"/BeforeRestore-Files-* 2>/dev/null | head -n 1)
  [ -z "$_LATEST" ] && echo "[ROLLBACK] No BeforeRestore-Files found in $BKDIR" && return 1
  echo "Rollback from: $_LATEST"; printf "Restore files rollback? (y/n): "; read _rb; case "$_rb" in y|Y) ;; *) echo "Cancelled"; return 2 ;; esac
  [ -f "$_LATEST/settings" ] && cp -a "$_LATEST/settings" /etc/enigma2/settings && echo "  [OK] settings rolled back"
  [ -d "$_LATEST/tuxbox_config" ] && rm -rf /etc/tuxbox/config && cp -a "$_LATEST/tuxbox_config" /etc/tuxbox/config && echo "  [OK] tuxbox/config rolled back"
  [ -f "$_LATEST/lamedb" ] && cp -a "$_LATEST/lamedb" /etc/enigma2/lamedb && echo "  [OK] lamedb rolled back"
  echo "[ROLLBACK] Done - Reboot or init 3 to apply"; return 0
}
# (5) Backup manager: list / cleanup / delete
list_all_backups() {
  echo "--- Unified Backups (plugins + files in ONE folder) ---"; ls -dt $UPANEL_ROOT-Backup-*/Python* 2>/dev/null | grep -v '\.tmp\.'
  echo "--- Plugins (old tree, backward-compat) ---"; ls -dt $UPANEL_ROOT-Plugins-Backup-*/Python* 2>/dev/null | grep -v '\.tmp\.'
  echo "--- .prev (previous) ---"; ls -dt $UPANEL_ROOT-Backup-*.prev $UPANEL_ROOT-Plugins-Backup-*.prev 2>/dev/null
  echo "--- Compressed (.tar.gz) ---"; ls -dt $UPANEL_ROOT-Backup-*/*.tar.gz $UPANEL_ROOT-Backup-*/*/*.tar.gz $UPANEL_ROOT-Plugins-Backup-*/*.tar.gz 2>/dev/null
}
cleanup_old_backups() {
  # Keep last 3 Files + last 3 Plugins per image group (by date) - .prev older than 30d removed
  for _base in $UPANEL_ROOT-Backup-* $UPANEL_ROOT-Plugins-Backup-*; do case "$_base" in *.prev) continue ;; esac; [ -d "$_base" ] || continue; ls -dt "$_base"/Python* 2>/dev/null | grep -v '\.tmp\.' | tail -n +4 | while read -r _old; do
    # V20: compress old backups instead of deleting - keep .tar.gz, remove raw
    if [ -d "$_old" ] && [ ! -f "$_old.tar.gz" ]; then echo "[COMPRESS] $_old -> $_old.tar.gz"; tar -czf "$_old.tar.gz" -C "$_base" "$(basename "$_old")" 2>/dev/null && rm -rf "$_old" && echo "  [OK] Compressed"; fi
  done; done
  # V20: .prev older than 30 days - remove (latest .prev kept)
  find $UPANEL_ROOT -maxdepth 1 -name "*.prev" -type d -mtime +30 2>/dev/null | while read -r _pv; do echo "[CLEANUP] Removing old .prev: $_pv"; rm -rf "$_pv"; done
  # V20: BeforeRestore-* older than 30 days - keep latest per group (V20.1: also inside files/ subdir)
  for _grp in $UPANEL_ROOT-Backup-*/Python* $UPANEL_ROOT-Backup-*/Python*/files $UPANEL_ROOT-Plugins-Backup-*/Python*; do [ -d "$_grp" ] || continue; ls -dt "$_grp"/BeforeRestore-* 2>/dev/null | tail -n +2 | while read -r _br; do find "$_br" -maxdepth 0 -mtime +30 -exec rm -rf {} + 2>/dev/null; done; done
  echo "[CLEANUP] Kept last 3 per group + compressed older + removed old .prev/BeforeRestore"
}
show_backup_manager() {
  while true; do show_banner; menu_top; menu_head "Backup Manager - List / Cleanup / Rollback"; menu_sep; menu_item "1) List All Backups"; menu_item "2) Cleanup - Keep Last 3 Per Group"; menu_item "3) Rollback Files (Latest BeforeRestore)"; menu_item "4) Rollback Plugins (Latest BeforeRestore)"; menu_item "5) Change Backup Location - HDD / USB"; menu_item "M) Main Menu"; menu_bot; printf "Your choice: "; read _bm || return 0
    case "$_bm" in 1) list_all_backups; printf "Press ENTER... "; read _b ;; 2) cleanup_old_backups; printf "Press ENTER... "; read _b ;; 3) rollback_files; printf "Press ENTER... "; read _b ;; 4) _PL=$(ls -dt "$(get_plugins_backup_dir)"/BeforeRestore-* 2>/dev/null | head -n 1); [ -n "$_PL" ] && echo "Plugins rollback: cp -a $_PL/Extensions/. /usr/lib/enigma2/python/Plugins/Extensions/ - then init 3" || echo "No plugins BeforeRestore found"; printf "Press ENTER... "; read _b ;; 5) ask_backup_root; printf "Press ENTER... "; read _b ;; m|M) return 0 ;; *) wrong_choice ;; esac
  done
}
# (6) Selective restore
selective_restore_menu() {
  while true; do show_banner; menu_top; menu_head "Custom Restore"; menu_sep; menu_item "1) Restore Plugins"; menu_item "2) Restore Files"; menu_item "3) All"; menu_item "M) Main Menu"; menu_bot; printf "Your choice: "; read _sr || return 0
    case "$_sr" in
      1) FULL_AUTO=1; RESTORE_BATCH=1; restore_plugins_with_extras; _RC=$?; FULL_AUTO=0; RESTORE_BATCH=0; echo "Custom Plugins done (rc=$_RC)"; ask_retrieve_enigma; printf "Press ENTER... "; read _b ;;
      2) FULL_AUTO=1; restore_files_setup; _RC=$?; verify_files_restore; FULL_AUTO=0; echo "Custom Files done (rc=$_RC)"; printf "Press ENTER... "; read _b ;;
      3) FULL_AUTO=1; RESTORE_BATCH=1; restore_plugins_then_files; _RC=$?; if [ "$_RC" = "0" ]; then line; info "Custom All - BootLogo Auto (end, like Smart Restore)"; install_bootlogo_auto; if check_net 2>/dev/null; then tools_abertis_astra auto; else echo "[SMART-SKIP] Abertis skipped (no net)"; fi; write_unified_report; show_summary; fi; FULL_AUTO=0; RESTORE_BATCH=0; echo "Custom All done (rc=$_RC)"; ask_retrieve_enigma; printf "Press ENTER... "; read _b ;;
      m|M) return 0 ;; *) wrong_choice ;;
    esac
  done
}
# (7) Unified report
write_unified_report() {
  _R="$UPANEL_ROOT-Restore-Report-$(date +%Y%m%d_%H%M%S).txt"
  { echo "U-Panel Unified Restore Report - $(date)"; echo "Box: $BOX | Image: $IMAGE | Python: $PYTHON_V"; echo "Plugins Backup: $(get_plugins_backup_dir)"; echo "Files Backup: $BKDIR"; echo "--- Plugins ---"; echo "Failed (auto-reinstalled): ${UNIFIED_FAILED:-$ _FAILED}"; echo "--- Files ---"; ls -l /etc/enigma2/settings /etc/enigma2/lamedb 2>/dev/null; echo "--- End ---"; } > "$_R"
  echo "[REPORT] Unified report: $_R"; cat "$_R"
}


# (4) Self-test (no real device needed) - checks logic, not hardware
self_test() {
  echo "=== Self-Test V20 (real checks, no device changes) ==="
  _TFAIL=""
  # 1) Gating on fake devices
  _OLD_FM="$FULL_MACHINE"; _OLD_BOX="$BOX"
  for _t in "vuplus_uno4k:45" "multiboxpro:40" "h9:40" "dm920:40" "sf8008:40"; do
    _fm="${_t%%:*}"; _exp="${_t##*:}"; FULL_MACHINE="$_fm"
    if [ "$_exp" = "45" ]; then plugin_allowed_by_device 45 || _TFAIL="$_TFAIL gating-vuplus"; plugin_allowed_by_device 40 && _TFAIL="$_TFAIL gating-vuplus-multiboot"; else plugin_allowed_by_device 40 || _TFAIL="$_TFAIL gating-$_fm"; plugin_allowed_by_device 45 && _TFAIL="$_TFAIL gating-$_fm-neoboot"; fi
  done
  FULL_MACHINE="$_OLD_FM"; BOX="$_OLD_BOX"
  [ -z "$_TFAIL" ] && echo "  [OK] Gating: Vu+->NeoBoot, others->Multiboot" || echo "  [FAIL] Gating:$_TFAIL"
  # 2) Swap on /tmp
  rm -rf /tmp/selftest_real /tmp/selftest_tmp; mkdir -p /tmp/selftest_tmp; echo test > /tmp/selftest_tmp/f.txt
  swap_backup_dir /tmp/selftest_real /tmp/selftest_tmp >/dev/null 2>&1 && [ -f /tmp/selftest_real/f.txt ] && echo "  [OK] swap_backup_dir" || echo "  [FAIL] swap_backup_dir"
  rm -rf /tmp/selftest_real /tmp/selftest_tmp
  # 3) Manifest + verify on /tmp
  rm -rf /tmp/selftest_m; mkdir -p /tmp/selftest_m/enigma2; echo x > /tmp/selftest_m/enigma2/settings
  generate_files_manifest /tmp/selftest_m >/dev/null 2>&1; [ -f /tmp/selftest_m/files_manifest.csv ] && echo "  [OK] generate_files_manifest" || echo "  [FAIL] manifest"
  rm -rf /tmp/selftest_m
  # 3b) CSV: filename with comma (picon "DB, MUX 4.png") must parse quote-aware
  rm -rf /tmp/selftest_comma; mkdir -p "/tmp/selftest_comma/files/usr/share/enigma2/piconProv"
  echo picon > "/tmp/selftest_comma/files/usr/share/enigma2/piconProv/DB, MUX 4.png"
  _c5=$(md5sum "/tmp/selftest_comma/files/usr/share/enigma2/piconProv/DB, MUX 4.png" | cut -d' ' -f1)
  printf 'file,orig_path,size,md5\n"/usr/share/enigma2/piconProv/DB, MUX 4.png","/usr/share/enigma2/piconProv/DB, MUX 4.png","6","%s"\n' "$_c5" > /tmp/selftest_comma/manifest.csv
  verify_plugins_backup /tmp/selftest_comma >/dev/null 2>&1 && echo "  [OK] CSV comma filename parses (DB, MUX 4.png)" || echo "  [FAIL] CSV comma filename"
  rm -rf /tmp/selftest_comma
  # 3c) Folder filter: list with file + dir + dangling symlink + stale path -> file only
  rm -rf /tmp/selftest_filter; mkdir -p /tmp/selftest_filter/sub
  echo real > /tmp/selftest_filter/real.txt
  ln -s /nonexistent-target /tmp/selftest_filter/dangling.txt
  printf '%s\n' /tmp/selftest_filter/real.txt /tmp/selftest_filter/sub /tmp/selftest_filter/dangling.txt /tmp/selftest_filter/nope.txt > /tmp/selftest_filter/list.txt
  filter_files_only /tmp/selftest_filter/list.txt
  if [ "$(wc -l < /tmp/selftest_filter/list.txt)" = "1" ] && [ "$(cat /tmp/selftest_filter/list.txt)" = "/tmp/selftest_filter/real.txt" ]; then echo "  [OK] Folder filter keeps files only"; else echo "  [FAIL] Folder filter"; fi
  rm -rf /tmp/selftest_filter
  # 4) Favourite validation
  printf 'FAV_PLUGINS="1 2"\nEVIL=$(reboot)\n' > /tmp/selftest_fav
  if grep -qv -E '^(FAV_[A-Z_]+=|#|$)' /tmp/selftest_fav; then echo "  [OK] Favourite validation rejects bad lines"; else echo "  [FAIL] Favourite validation"; fi
  rm -f /tmp/selftest_fav
  # 5) Functions exist
  for _fn in check_hdd_space check_net swap_backup_dir generate_files_manifest verify_files_md5 rollback_files list_all_backups cleanup_old_backups show_backup_manager selective_restore_menu write_unified_report restore_plugins_then_files plugin_allowed_by_device uninstall_plugin_by_num update_installed_plugins setup_snapshot install_channel_list choose_channel_list setup_restore_picker run_recorded_restore run_recorded_channel setup_your_enigma favourite_setup full_restore ensure_files_backup_extracted tools_confirm_snapshot; do type "$_fn" >/dev/null 2>&1 || echo "  [MISSING] $_fn"; done
  echo "  [OK] All V20 helpers defined"
  # 5b) V20.1: every function called from menus is defined + external commands exist
  for _fn in personal_setup favourite_setup plugins_manual backup_plugins_then_files personal_full_restore cache_offline_assets offline_install_pkg selective_restore_menu backup_full_image show_tools_menu show_backup_manager self_test; do command -v "$_fn" >/dev/null 2>&1 || echo "  [MISSING] menu function: $_fn"; done
  echo "  [OK] All menu functions defined"
  for _cmd in opkg tar md5sum python3 find grep sed awk cp mkdir rm ls; do command -v "$_cmd" >/dev/null 2>&1 || echo "  [MISSING] command: $_cmd"; done
  echo "  [OK] External commands present"
  echo "  [CHECK] HDD: $(df $BACKUP_ROOT 2>/dev/null | tail -n 1)"
  echo "  [CHECK] Plugins dir: $(get_plugins_backup_dir)"
  echo "  [CHECK] Files dir: $BKDIR"
  echo "  [CHECK] BackupRoot: $BACKUP_ROOT"
  echo "=== Self-Test Done ==="
  printf "Press ENTER... "; read _b
}
# ===== V8 - New Main Menu structure: Installation / Backup and Restore / Tools & Management =====
plugins_manual() {
  setup_reboot_guard "Plugins Manual"
  show_banner; line; info "Plugins Manual - Add plugins manually any time - after Setup - Reboot Guard V4 ON"
  echo "Pick plugins from categories - same basket logic as Setup - no Restore, no BootLogo change here"
  printf "Press ENTER to open Plugins categories - or 0 to go back: "; read _go; [ "$_go" = "0" ] && return 0
  SELECTED_ALL=""
  show_plugins_menu
  if [ -z "$SELECTED_ALL" ]; then echo "No Plugins Selected - Returning"; return 0; fi; log_msg "Plugins manual started"
  echo "Selected: $SELECTED_ALL - Installing..."; install_selected_basket
  ok "Plugins Manual Done - No Reboot"
  printf "Press ENTER to return... "; read _back; return 0
}
tools_confirm_snapshot() {
  echo "=== Confirm: $1 ==="
  _TSNAP="$UPANEL_ROOT-Tools-Snapshot-$(date +%Y%m%d_%H%M%S)"
  mkdir -p "$_TSNAP" 2>/dev/null; cp -a /etc/enigma2/settings "$_TSNAP/settings" 2>/dev/null; cp -a /etc/tuxbox/config/. "$_TSNAP/" 2>/dev/null
  echo "Snapshot saved: $_TSNAP (restore manually if needed)"
  printf "Are you SURE? This deletes data. (y/n): "; read _tc; case "$_tc" in y|Y) return 0 ;; *) echo "Cancelled"; return 1 ;; esac
}
# Restore Plugins and Files: Plugins V5 first, then ask Files: All or Pick
tools_change_password() { line; info "Change Password (V20: you choose, not root)"; printf "New password: "; stty -echo; read _np; stty echo; echo ""; printf "Repeat: "; stty -echo; read _np2; stty echo; echo ""; [ "$_np" != "$_np2" ] && echo "[ERROR] Passwords do not match" && printf "Press ENTER... " && read _back && return 0; [ -z "$_np" ] && echo "[ERROR] Empty password" && printf "Press ENTER... " && read _back && return 0; printf "%s\n%s\n" "$_np" "$_np" | passwd root >/dev/null 2>&1 && ok "Password changed - No Restart" || echo "[ERROR] passwd failed"; printf "Press ENTER to return... "; read _back; }
tools_delete_password() { line; info "Delete Old Password"; passwd -d root; ok "Password deleted - No Restart"; printf "Press ENTER to return... "; read _back; }
tools_delete_crashlog() { line; info "Delete Crash Log"; rm -rf /media/hdd/logs/Enigma2_crash* /media/hdd/enigma2_crash* /media/usb/logs/Enigma2_crash* /home/root/logs/Enigma2_crash* 2>/dev/null; rm -rf /media/hdd/logs/Enigma2_debug* /media/usb/logs/Enigma2_debug* /home/root/logs/Enigma2_debug* 2>/dev/null; ok "Crash Log deleted"; printf "Press ENTER to return... "; read _back; }
tools_delete_all_emu() { tools_confirm_snapshot "Delete All Emu" || return 0; line; info "Delete All Emu - LOCAL (V20: no external script)"; for _e in OSCam Ncam ncam oscam powercam ultracam gosatplus; do /usr/bin/killall -9 "$_e" 2>/dev/null; done; opkg remove enigma2-plugin-softcams-* 2>/dev/null; apt-get remove -y "*softcam*" 2>/dev/null; rm -rf /usr/bin/cam/* /etc/init.d/softcam* /etc/tuxbox/config 2>/dev/null; ok "All Emu deleted (local)"; printf "Press ENTER to return... "; read _back; }
tools_delete_ncam() { line; info "Delete Ncam Emu"; opkg remove enigma2-plugin-softcams-ncam* 2>/dev/null; ok "Ncam deleted"; printf "Press ENTER to return... "; read _back; }
