tools_remove_emu_config() { tools_confirm_snapshot "Remove Emu and Config files" || return 0; line; info "Remove Emu and Config files"; for file in OSCam Ncam powercam ncam oscam; do /usr/bin/killall -9 $file 2>/dev/null; /usr/bin/killall -9 /usr/bin/cam/$file 2>/dev/null; done; sleep 1; for file in OSCam oscam ncam Ncam powercam oscamicam CCcam; do rm -rf /usr/camd/${file}* /usr/emu/${file}* /usr/scr/${file}* /usr/scr/cam/${file}* /usr/softcams/${file}* /var/emu/${file}* /var/scr/${file}* /usr/bin/${file}* /usr/bin/cam/${file}* 2>/dev/null; done; rm -rf /etc/ncam* /usr/camscript/Ncam* /usr/script/*cam.sh /usr/script/*em.sh /usr/camscript/*cam.sh /usr/emu_scripts/EGcam* /etc/init.d/softcam* /usr/emu/start/*emu /usr/emupanel/*em.sh /usr/LTCAM/*ncam.sh /usr/script/cam/*cam.sh /usr/script/*emu /etc/*emu.emu /etc/cam.d/*cam.sh 2>/dev/null; for pkg in enigma2-plugin-softcams-gosatplusv2-oscam enigma2-plugin-softcams-oscam enigma2-plugin-softcams-oscamicam enigma2-plugin-softcams-powercam-oscam enigma2-plugin-softcams-supcam-oscam enigma2-plugin-softcams-ncam enigma2-plugin-softcams-revcamv2-ncam enigma2-plugin-softcams-supcam-ncam enigma2-plugin-softcams-powercam-ncam enigma2-plugin-softcams-gosatplusv2-ncam enigma2-plugin-softcams-gosatplus2 enigma2-plugin-softcams-powercam enigma2-plugin-softcams-revcamv2 enigma2-softcams-cccam-images enigma2-softcams-cccam enigma2-plugin-softcams-oscamicamnew enigma2-plugin-softcams-oscam-emu-levi45 enigma2-softcams-oscam-all-images; do opkg remove --force-depends $pkg 2>/dev/null; done; rm -rf /etc/tuxbox/config /etc/tuxbox/gosatplus /etc/tuxbox/powercam /etc/tuxbox/ultracam /etc/CCcam.cfg /usr/keys/* 2>/dev/null; echo "> done"; printf "Press ENTER to return... "; read _back; }
