# V4.11: EPG download - XMLTV files for Egyptian/Arabic channels -> $UPANEL_ROOT/EPG (one-folder rule)
# Sources: EPGShare01 (AE Arabic, beIN, Al Jazeera, Qatar - updated daily) + iptv-org Egypt (elcinema)
# EPGShare01 Egypt (EG1) DELIBERATELY NOT included - last updated Jan 2024 (stale, 2 years old)
# E-Moati EPG: tar.gz release, VERIFIED (exists + >10KB + tar lists .xml + extracted .xml contains <tv) before keeping
# Every .xml.gz VERIFIED (exists + >10KB + valid gzip + decompressed file contains <tv) before keeping
epg_try_gz_url() {
  _EG_URL="$1"; _EG_OUT="$2"
  echo ">> Trying: $_EG_URL"
  rm -f "$_EG_TMP/dl.xml.gz"
  wget --tries=2 --timeout=60 -O "$_EG_TMP/dl.xml.gz" "$_EG_URL" 2>/dev/null
  [ -s "$_EG_TMP/dl.xml.gz" ] || { echo "   FAIL: no file"; return 1; }
  _EG_SZ=$(stat -c%s "$_EG_TMP/dl.xml.gz" 2>/dev/null || echo 0)
  [ "$_EG_SZ" -gt 10000 ] || { echo "   FAIL: too small ($_EG_SZ)"; return 1; }
  gzip -t "$_EG_TMP/dl.xml.gz" 2>/dev/null || { echo "   FAIL: not a gzip file"; rm -f "$_EG_TMP/dl.xml.gz"; return 1; }
  gunzip -c "$_EG_TMP/dl.xml.gz" > "$_EG_TMP/out.xml" 2>/dev/null || { echo "   FAIL: decompress failed"; rm -f "$_EG_TMP/out.xml"; return 1; }
  grep -q "<tv" "$_EG_TMP/out.xml" 2>/dev/null || { echo "   FAIL: no XMLTV data in file"; rm -f "$_EG_TMP/out.xml"; return 1; }
  mv "$_EG_TMP/out.xml" "$_EG_TGT/$_EG_OUT" 2>/dev/null || { echo "   FAIL: could not install file"; rm -f "$_EG_TMP/out.xml"; return 1; }
  echo "   OK: $_EG_OUT ($(( $(stat -c%s "$_EG_TGT/$_EG_OUT" 2>/dev/null || echo 0) / 1024 )) KB)"
  return 0
}
epg_try_tar_url() {
  _EG_URL="$1"
  echo ">> Trying: $_EG_URL"
  rm -f "$_EG_TMP/dl.tar.gz"
  wget --tries=2 --timeout=60 -O "$_EG_TMP/dl.tar.gz" "$_EG_URL" 2>/dev/null
  [ -s "$_EG_TMP/dl.tar.gz" ] || { echo "   FAIL: no file"; return 1; }
  _EG_SZ=$(stat -c%s "$_EG_TMP/dl.tar.gz" 2>/dev/null || echo 0)
  [ "$_EG_SZ" -gt 10000 ] || { echo "   FAIL: too small ($_EG_SZ)"; return 1; }
  tar -tzf "$_EG_TMP/dl.tar.gz" 2>/dev/null | grep -q "\.xml" || { echo "   FAIL: no .xml in archive"; rm -f "$_EG_TMP/dl.tar.gz"; return 1; }
  rm -rf "$_EG_TMP/extract"; mkdir -p "$_EG_TMP/extract"
  tar -xzf "$_EG_TMP/dl.tar.gz" -C "$_EG_TMP/extract" 2>/dev/null || { echo "   FAIL: extract failed"; return 1; }
  _EG_N=0
  for _EG_F in $(find "$_EG_TMP/extract" -name "*.xml" 2>/dev/null); do [ -f "$_EG_F" ] || continue; grep -q "<tv" "$_EG_F" 2>/dev/null || continue; cp "$_EG_F" "$_EG_TGT/$(basename "$_EG_F")" 2>/dev/null && _EG_N=$((_EG_N + 1)); done
  [ "$_EG_N" -gt 0 ] || { echo "   FAIL: no XMLTV data in extracted files"; return 1; }
  echo "   OK: $_EG_N XMLTV file(s) extracted"
  return 0
}
download_epg_menu() {
  line; info "Download EPG - XMLTV for Egyptian/Arabic channels"
  _EG_TGT="${UPANEL_ROOT:-/media/hdd/U-Panel}/EPG"
  echo "EPG server - choose source:"
  echo "  1) Arabic Gulf"
  echo "  2) Egypt Epg"
  echo "  3) U-Panel EPG"
  printf "Server (1-3): "; read _EG_SRV
  case "$_EG_SRV" in 2|3) ;; *) _EG_SRV=1;; esac
  check_net || { echo "[ERROR] No net - EPG download stopped"; printf "Press ENTER to return... "; read _back; return 1; }
  mkdir -p "$_EG_TGT" || { echo "[ERROR] Cannot create $_EG_TGT"; printf "Press ENTER... "; read _back; return 1; }
  _EG_FREE=$(df "$_EG_TGT" 2>/dev/null | tail -n 1 | awk '{print $4}'); [ -z "$_EG_FREE" ] && _EG_FREE=0
  if [ "$_EG_FREE" -lt 100000 ]; then echo "[WARN] Free space: $((_EG_FREE / 1024)) MB - need ~100MB"; printf "Continue anyway? (y/n): "; read _EG_GO; case "$_EG_GO" in y|Y) ;; *) return 0;; esac; fi
  printf "Start download? (y/n): "; read _EG_GO2; case "$_EG_GO2" in y|Y) ;; *) return 0;; esac
  _EG_TMP="/tmp/epg-tmp"; rm -rf "$_EG_TMP"; mkdir -p "$_EG_TMP"
  _EG_OK=0; _EG_FAIL=0
  case "$_EG_SRV" in
    1) epg_try_gz_url "https://epgshare01.online/epgshare01/epg_ripper_AE1.xml.gz" "epg_ripper_AE1.xml" && _EG_OK=$((_EG_OK + 1)) || _EG_FAIL=$((_EG_FAIL + 1))
       epg_try_gz_url "https://epgshare01.online/epgshare01/epg_ripper_BEIN1.xml.gz" "epg_ripper_BEIN1.xml" && _EG_OK=$((_EG_OK + 1)) || _EG_FAIL=$((_EG_FAIL + 1))
       epg_try_gz_url "https://epgshare01.online/epgshare01/epg_ripper_ALJAZEERA1.xml.gz" "epg_ripper_ALJAZEERA1.xml" && _EG_OK=$((_EG_OK + 1)) || _EG_FAIL=$((_EG_FAIL + 1))
       epg_try_gz_url "https://epgshare01.online/epgshare01/epg_ripper_QA1.xml.gz" "epg_ripper_QA1.xml" && _EG_OK=$((_EG_OK + 1)) || _EG_FAIL=$((_EG_FAIL + 1)) ;;
    2) epg_try_gz_url "https://iptv-org.github.io/epg/guides/eg-ar/elcinema.com.epg.xml.gz" "elcinema.com.epg.xml" && _EG_OK=1 || _EG_FAIL=1 ;;
    3) epg_try_tar_url "https://github.com/KhaledAli65/novaler/raw/main/epg.tar.gz" && _EG_OK=1 || _EG_FAIL=1 ;;
  esac
  rm -rf "$_EG_TMP"
  if [ "$_EG_OK" = "0" ]; then echo "[ERROR] ALL SOURCES FAILED - nothing installed"; printf "Press ENTER to return... "; read _back; return 1; fi
  [ "$_EG_FAIL" -gt 0 ] && echo "[WARN] $_EG_FAIL source(s) failed - the rest installed OK"
  ok "EPG installed: $_EG_OK file(s) in $_EG_TGT"
  ls -lh "$_EG_TGT"/*.xml 2>/dev/null | awk '{print "  " $9 " - " $5}'
  echo "Load the .xml files in EPGImport (add as custom sources) or Jedi EPG Xtream"
  printf "Press ENTER to return... "; read _back
}

# V4.14: EPG auto-refresh - cron every 3 days (05:00) re-downloads ALL 3 choices headless.
# Old-file protection: every download lands in /tmp first, is verified (<tv present),
# THEN moved over the old file. A failed download NEVER touches the old file.
# EPGImport registration: writes /etc/epgimport/upanel.sources.xml (file:// URLs) so
# EPGImport picks the files up on its own daily schedule - no manual source setup.
epg_register_sources() {
  _EG_IMPDIR="${EPGIMPORT_DIR:-/etc/epgimport}"
  [ -d "$_EG_IMPDIR" ] || { echo "   SKIP: $_EG_IMPDIR not found - EPGImport not installed, files still usable manually"; return 0; }
  _EG_TGT="${UPANEL_ROOT:-/media/hdd/U-Panel}/EPG"
  {
    echo '<?xml version="1.0" encoding="utf-8"?>'
    echo '<sources>'
    for _EG_F in epg_ripper_AE1.xml epg_ripper_BEIN1.xml epg_ripper_ALJAZEERA1.xml epg_ripper_QA1.xml elcinema.com.epg.xml epg.xml; do
      [ -f "$_EG_TGT/$_EG_F" ] || continue
      echo "  <source type=\"gen_xmltv\">"
      echo "    <description>U-Panel - $_EG_F</description>"
      echo "    <url>file://$_EG_TGT/$_EG_F</url>"
      echo "  </source>"
    done
    echo '</sources>'
  } > "$_EG_IMPDIR/upanel.sources.xml" 2>/dev/null && echo "   OK: EPGImport sources registered: $_EG_IMPDIR/upanel.sources.xml" || echo "   WARN: could not write $_EG_IMPDIR/upanel.sources.xml"
  return 0
}
epg_auto_refresh_all() {
  _EG_TGT="${UPANEL_ROOT:-/media/hdd/U-Panel}/EPG"
  echo "=== U-Panel EPG auto-refresh: $(date '+%Y-%m-%d %H:%M:%S') ==="
  check_net || { echo "[ERROR] No net - auto-refresh stopped, old files kept"; return 1; }
  mkdir -p "$_EG_TGT" || { echo "[ERROR] Cannot create $_EG_TGT"; return 1; }
  _EG_TMP="/tmp/epg-tmp"; rm -rf "$_EG_TMP"; mkdir -p "$_EG_TMP"
  _EG_OK=0; _EG_FAIL=0
  epg_try_gz_url "https://epgshare01.online/epgshare01/epg_ripper_AE1.xml.gz" "epg_ripper_AE1.xml" && _EG_OK=$((_EG_OK + 1)) || _EG_FAIL=$((_EG_FAIL + 1))
  epg_try_gz_url "https://epgshare01.online/epgshare01/epg_ripper_BEIN1.xml.gz" "epg_ripper_BEIN1.xml" && _EG_OK=$((_EG_OK + 1)) || _EG_FAIL=$((_EG_FAIL + 1))
  epg_try_gz_url "https://epgshare01.online/epgshare01/epg_ripper_ALJAZEERA1.xml.gz" "epg_ripper_ALJAZEERA1.xml" && _EG_OK=$((_EG_OK + 1)) || _EG_FAIL=$((_EG_FAIL + 1))
  epg_try_gz_url "https://epgshare01.online/epgshare01/epg_ripper_QA1.xml.gz" "epg_ripper_QA1.xml" && _EG_OK=$((_EG_OK + 1)) || _EG_FAIL=$((_EG_FAIL + 1))
  epg_try_gz_url "https://iptv-org.github.io/epg/guides/eg-ar/elcinema.com.epg.xml.gz" "elcinema.com.epg.xml" && _EG_OK=$((_EG_OK + 1)) || _EG_FAIL=$((_EG_FAIL + 1))
  epg_try_tar_url "https://github.com/KhaledAli65/novaler/raw/main/epg.tar.gz" && _EG_OK=$((_EG_OK + 1)) || _EG_FAIL=$((_EG_FAIL + 1))
  rm -rf "$_EG_TMP"
  epg_register_sources
  echo "=== Auto-refresh done: $_EG_OK OK / $_EG_FAIL failed (old files kept for every failure) ==="
  [ "$_EG_OK" -gt 0 ]
}
# V4.15: autorefresh is AUTOMATIC on the receiver - no menu step needed.
# On every script start: if the user never disabled it AND no cron job exists,
# the cron job is installed silently. First run with no EPG files also downloads
# them once, so the guide is full from day one. Disabling from the menu writes a
# marker file, so a later restart will NOT re-enable it behind the user's back.
epg_cron_autoinstall() {
  _EG_MARKER="${UPANEL_ROOT:-/media/hdd/U-Panel}/EPG/.autorefresh-disabled"
  [ -f "$_EG_MARKER" ] && return 0
  command -v crontab >/dev/null 2>&1 || return 0
  # V5.91 SELF-HEAL: cron line exists but points at an OLD path (script moved) -> fall through and reinstall with THIS path
  _EG_SELF_NOW=$(readlink -f "$0" 2>/dev/null || echo "$0")
  if crontab -l 2>/dev/null | grep -q "U-Panel-EPG-AutoRefresh"; then
    crontab -l 2>/dev/null | grep "U-Panel-EPG-AutoRefresh" | grep -qs -- "$_EG_SELF_NOW" && return 0
  fi
  _EG_TMPCT="/tmp/upanel-cron.txt"
  crontab -l 2>/dev/null | grep -v "U-Panel-EPG-AutoRefresh" > "$_EG_TMPCT"
  epg_cron_line >> "$_EG_TMPCT"
  crontab "$_EG_TMPCT" 2>/dev/null || { rm -f "$_EG_TMPCT"; return 0; }
  rm -f "$_EG_TMPCT"
  _EG_TGT="${UPANEL_ROOT:-/media/hdd/U-Panel}/EPG"
  if [ -z "$(ls "$_EG_TGT"/*.xml 2>/dev/null)" ]; then mkdir -p "$_EG_TGT"; epg_auto_refresh_all >> "$_EG_TGT/auto-refresh.log" 2>&1; fi
  return 0
}
epg_cron_line() {
  _EG_SELF=$(readlink -f "$0" 2>/dev/null || echo "$0")
  echo "0 5 */3 * * $_EG_SELF --epg-auto >> ${UPANEL_ROOT:-/media/hdd/U-Panel}/EPG/auto-refresh.log 2>&1 # U-Panel-EPG-AutoRefresh"
}
epg_cron_status() {
  command -v crontab >/dev/null 2>&1 || { echo "OFF (no crontab on this image)"; return 1; }
  crontab -l 2>/dev/null | grep -q "U-Panel-EPG-AutoRefresh" && { echo "ON - every 3 days at 05:00"; return 0; } || { echo "OFF"; return 1; }
}
epg_cron_install() {
  rm -f "${UPANEL_ROOT:-/media/hdd/U-Panel}/EPG/.autorefresh-disabled"
  command -v crontab >/dev/null 2>&1 || { echo "[ERROR] crontab not found on this image - auto-refresh not available"; return 1; }
  _EG_TMPCT="/tmp/upanel-cron.txt"
  crontab -l 2>/dev/null | grep -v "U-Panel-EPG-AutoRefresh" > "$_EG_TMPCT"
  epg_cron_line >> "$_EG_TMPCT"
  crontab "$_EG_TMPCT" 2>/dev/null && { rm -f "$_EG_TMPCT"; echo "OK: auto-refresh ON - every 3 days at 05:00"; return 0; } || { rm -f "$_EG_TMPCT"; echo "[ERROR] could not install cron job"; return 1; }
}
epg_cron_remove() {
  command -v crontab >/dev/null 2>&1 || { echo "[ERROR] crontab not found"; return 1; }
  _EG_TMPCT="/tmp/upanel-cron.txt"
  crontab -l 2>/dev/null | grep -v "U-Panel-EPG-AutoRefresh" > "$_EG_TMPCT"
  crontab "$_EG_TMPCT" 2>/dev/null && { rm -f "$_EG_TMPCT"; mkdir -p "${UPANEL_ROOT:-/media/hdd/U-Panel}/EPG"; touch "${UPANEL_ROOT:-/media/hdd/U-Panel}/EPG/.autorefresh-disabled"; echo "OK: auto-refresh OFF"; return 0; } || { rm -f "$_EG_TMPCT"; echo "[ERROR] could not remove cron job"; return 1; }
}
epg_auto_menu() {
  while true; do
    line; info "EPG Auto-refresh"
    printf "Status: "; epg_cron_status
    echo "  1) Enable auto-refresh (every 3 days at 05:00 + refresh now)"
    echo "  2) Disable auto-refresh"
    echo "  3) Refresh now (all 3 choices)"
    echo "  0) Back"
    printf "Your choice: "; read _EG_AM || return 0
    case "$_EG_AM" in
      1) epg_cron_install && epg_auto_refresh_all; printf "Press ENTER to return... "; read _back ;;
      2) epg_cron_remove; printf "Press ENTER to return... "; read _back ;;
      3) epg_auto_refresh_all; printf "Press ENTER to return... "; read _back ;;
      0) return 0 ;;
      *) wrong_choice ;;
    esac
  done
}

# V4.9: Picons download - choose server: 1) Ocram SNP 2) Ocram SRP 3) Image feed (opkg) 4) E-Moati Picons (GitHub release zip) - SNP/SRP 220x132 light/dark -> /media/hdd/picon (or /usr/share/enigma2/picon if HDD not mounted)
# Ocram fallback chain, each source VERIFIED (file exists + >1MB + tar lists .png) before extract:
# 1) GitHub API (picons/picons releases/latest, hardlink then symlink)  2) picons.xyz listing  3) picons.eu listing  4) image feed (opkg)
# E-Moati: single release zip, VERIFIED (exists + >100KB + zip lists .png) before extract, NO opkg fallback (opkg would install Ocram, not E-Moati)
picons_try_url() {
  _PU_URL="$1"
  echo ">> Trying: $_PU_URL"
  rm -f "$_PU_TMP/picons.tar.xz"
  wget --tries=2 --timeout=30 -O "$_PU_TMP/picons.tar.xz" "$_PU_URL" 2>/dev/null
  [ -s "$_PU_TMP/picons.tar.xz" ] || { echo "   FAIL: no file"; return 1; }
  _PU_SZ=$(stat -c%s "$_PU_TMP/picons.tar.xz" 2>/dev/null || echo 0)
  [ "$_PU_SZ" -gt 1000000 ] || { echo "   FAIL: too small ($_PU_SZ)"; return 1; }
  tar -tJf "$_PU_TMP/picons.tar.xz" 2>/dev/null | grep -q "\.png" || { echo "   FAIL: not a picons archive"; rm -f "$_PU_TMP/picons.tar.xz"; return 1; }
  echo "   OK: $((_PU_SZ / 1024 / 1024)) MB"
  return 0
}
picons_listing_url() {
  _PL_BASE="$1"; _PL_LIST="$2"
  _PL_L=$(wget -qO- --timeout=30 "$_PL_LIST" 2>/dev/null | grep -o 'href="[^"]*'"$_PU_PAT"'[^"]*\.tar\.xz"' | head -1 | cut -d'"' -f2)
  [ -z "$_PL_L" ] && return 1
  case "$_PL_L" in http*) echo "$_PL_L";; /*) echo "$_PL_BASE$_PL_L";; *) echo "$_PL_BASE/downloads/$_PL_L";; esac
}
picons_try_zip_url() {
  _PU_URL="$1"
  echo ">> Trying: $_PU_URL"
  rm -f "$_PU_TMP/picons.zip"
  wget --tries=2 --timeout=60 -O "$_PU_TMP/picons.zip" "$_PU_URL" 2>/dev/null
  [ -s "$_PU_TMP/picons.zip" ] || { echo "   FAIL: no file"; return 1; }
  _PU_SZ=$(stat -c%s "$_PU_TMP/picons.zip" 2>/dev/null || echo 0)
  [ "$_PU_SZ" -gt 100000 ] || { echo "   FAIL: too small ($_PU_SZ)"; return 1; }
  if command -v unzip >/dev/null 2>&1; then unzip -l "$_PU_TMP/picons.zip" 2>/dev/null | grep -q "\.png" || { echo "   FAIL: no png files in zip"; rm -f "$_PU_TMP/picons.zip"; return 1; }
  elif command -v python3 >/dev/null 2>&1; then python3 -m zipfile -l "$_PU_TMP/picons.zip" 2>/dev/null | grep -q "\.png" || { echo "   FAIL: no png files in zip"; rm -f "$_PU_TMP/picons.zip"; return 1; }
  else echo "   FAIL: no unzip and no python3 to check zip"; rm -f "$_PU_TMP/picons.zip"; return 1; fi
  echo "   OK: $((_PU_SZ / 1024)) KB"
  return 0
}
picons_unzip() {
  if command -v unzip >/dev/null 2>&1; then unzip -o -q "$1" -d "$2" 2>/dev/null; return $?
  elif command -v python3 >/dev/null 2>&1; then python3 -m zipfile -e "$1" "$2" 2>/dev/null; return $?
  fi
  return 1
}
download_picons_menu() {
  line; info "Download Picons - SNP/SRP 220x132 - to /media/hdd/picon"
  _PU_TGT="/media/hdd/picon"
  if ! mount | grep -q " /media/hdd "; then echo "[WARN] /media/hdd NOT mounted - using /usr/share/enigma2/picon instead"; _PU_TGT="/usr/share/enigma2/picon"; fi
  echo "Server - choose picons source:"
  echo "  1) Ocram SNP  - by channel NAME (default, recommended)"
  echo "  2) Ocram SRP  - by service REFERENCE (best if same name on 2 satellites)"
  echo "  3) Image feed - picons package from your image feed (opkg)"
  echo "  4) U-Panel Picons - GitHub release zip"
  printf "Server (1/2/3/4): "; read _PU_SRV
  case "$_PU_SRV" in 2|3|4) ;; *) _PU_SRV=1;; esac
  if [ "$_PU_SRV" = "4" ]; then
    _PU_PAT="E-Moati picon.zip"
  else
    printf "Style - 1) Light on transparent (default)  2) Dark on transparent : "; read _PU_STYLE
    _PU_KIND="snp-full"; _PU_LISTDIR="binaries-snp-full"
    [ "$_PU_SRV" = "2" ] && { _PU_KIND="srp-full"; _PU_LISTDIR="binaries-srp-full"; }
    _PU_PAT="$_PU_KIND.220x132-190x102.light.on.transparent"
    case "$_PU_STYLE" in 2) _PU_PAT="$_PU_KIND.220x132-190x102.dark.on.transparent";; esac
  fi
  echo "Picons: server $_PU_SRV - $_PU_PAT -> $_PU_TGT"
  check_net || { echo "[ERROR] No net - Picons download stopped"; printf "Press ENTER to return... "; read _back; return 1; }
  _PU_FREE=$(df "$_PU_TGT" 2>/dev/null | tail -n 1 | awk '{print $4}'); [ -z "$_PU_FREE" ] && _PU_FREE=0
  if [ "$_PU_FREE" -lt 500000 ]; then echo "[WARN] Free space: $((_PU_FREE / 1024)) MB - need ~500MB"; printf "Continue anyway? (y/n): "; read _PU_GO; case "$_PU_GO" in y|Y) ;; *) return 0;; esac; fi
  printf "Start download? (y/n): "; read _PU_GO2; case "$_PU_GO2" in y|Y) ;; *) return 0;; esac
  _PU_TMP="/tmp/picons-tmp"; rm -rf "$_PU_TMP"; mkdir -p "$_PU_TGT" "$_PU_TMP/extract"
  _PU_OK=0
  if [ "$_PU_SRV" = "4" ]; then
    picons_try_zip_url "https://github.com/KhaledAli65/books/releases/download/Picon/picon.zip" && _PU_OK=1
  else
    if [ "$_PU_SRV" != "3" ]; then
      if wget -qO- --timeout=30 https://api.github.com/repos/picons/picons/releases/latest > "$_PU_TMP/api.json" 2>/dev/null; then
        _PU_U=$(grep -o '"browser_download_url": *"[^"]*'"$_PU_PAT"'[^"]*hardlink.tar.xz"' "$_PU_TMP/api.json" | head -1 | cut -d'"' -f4)
        [ -z "$_PU_U" ] && _PU_U=$(grep -o '"browser_download_url": *"[^"]*'"$_PU_PAT"'[^"]*symlink.tar.xz"' "$_PU_TMP/api.json" | head -1 | cut -d'"' -f4)
        [ -n "$_PU_U" ] && picons_try_url "$_PU_U" && _PU_OK=1
      else echo "   GitHub API unreachable - trying next source"; fi
      if [ "$_PU_OK" = "0" ]; then _PU_U=$(picons_listing_url "https://picons.xyz" "https://picons.xyz/downloads/?dir=$_PU_LISTDIR"); [ -n "$_PU_U" ] && picons_try_url "$_PU_U" && _PU_OK=1; fi
      if [ "$_PU_OK" = "0" ]; then _PU_U=$(picons_listing_url "https://picons.eu" "https://picons.eu/downloads/?dir=$_PU_LISTDIR"); [ -n "$_PU_U" ] && picons_try_url "$_PU_U" && _PU_OK=1; fi
    fi
    if [ "$_PU_OK" = "0" ]; then
      echo ">> Image feed (opkg)"
      opkg update 2>/dev/null && opkg install "enigma2-plugin-picons-$_PU_PAT" 2>/dev/null
      [ -d /usr/share/enigma2/picon ] && cp -a /usr/share/enigma2/picon/*.png "$_PU_TGT/" 2>/dev/null && _PU_OK=1
    fi
  fi
  if [ "$_PU_OK" = "0" ]; then echo "[ERROR] ALL SOURCES FAILED - nothing installed"; rm -rf "$_PU_TMP"; printf "Press ENTER to return... "; read _back; return 1; fi
  if [ -s "$_PU_TMP/picons.zip" ]; then
    picons_unzip "$_PU_TMP/picons.zip" "$_PU_TMP/extract" || { echo "[ERROR] Extract failed"; rm -rf "$_PU_TMP"; printf "Press ENTER... "; read _back; return 1; }
    cd "$_PU_TMP/extract" 2>/dev/null
    _PU_D=$(ls -d */ 2>/dev/null | head -1)
    [ -n "$_PU_D" ] && cd "$_PU_D" 2>/dev/null
    cp -a *.png "$_PU_TGT/" 2>/dev/null
    cd / 2>/dev/null
  elif [ -s "$_PU_TMP/picons.tar.xz" ]; then
    tar -xJf "$_PU_TMP/picons.tar.xz" -C "$_PU_TMP/extract" 2>/dev/null || { echo "[ERROR] Extract failed"; rm -rf "$_PU_TMP"; printf "Press ENTER... "; read _back; return 1; }
    cd "$_PU_TMP/extract" 2>/dev/null
    _PU_D=$(ls -d */ 2>/dev/null | head -1)
    [ -n "$_PU_D" ] && cd "$_PU_D" 2>/dev/null
    cp -a *.png "$_PU_TGT/" 2>/dev/null
    cd / 2>/dev/null
  fi
  _PU_N=$(ls "$_PU_TGT/"*.png 2>/dev/null | wc -l)
  rm -rf "$_PU_TMP"
  if [ "$_PU_N" -gt 100 ]; then ok "Picons installed: $_PU_N files in $_PU_TGT"; else echo "[WARN] Only $_PU_N picons in $_PU_TGT - check the download"; fi
  printf "Restart GUI now to show picons? (y/n): "; read _PU_R
  case "$_PU_R" in y|Y) /sbin/init 4 2>/dev/null || /usr/sbin/init 4 2>/dev/null || /bin/init 4 2>/dev/null; sleep 3; /usr/bin/killall -9 enigma2 2>/dev/null || /bin/killall -9 enigma2 2>/dev/null; sleep 2; /sbin/init 3 2>/dev/null || /usr/sbin/init 3 2>/dev/null || /bin/init 3 2>/dev/null; sleep 3; echo "  GUI restarted";; esac
  printf "Press ENTER to return... "; read _back
}

# V4.18: Enigma UI / E-Moati EPG / E-Moati Channel List - new main-menu sections.
# Picons + EPG moved OUT of Tools (Tools back to 1-15).
# Channel List Renew: backup current settings -> download latest Vhannibal Motor
# (direct link, always newest) -> init 4 -> install -> restore favourites -> init 3.
# Favourites (userbouquet.favourites.tv) are saved before replace and restored after,
# so the user's own ordering is never lost. Auto-renew is OPT-IN from the menu only -
# it is NOT auto-installed at startup (unlike EPG), because replacing channel lists
# without the user asking is riskier than refreshing EPG files.
channellist_dir() { echo "${UPANEL_ROOT:-/media/hdd/U-Panel}/ChannelList"; }
channellist_backup_current() {
  _CL_BK="$(channellist_dir)/Backup-$(date +%Y%m%d_%H%M%S)"
  mkdir -p "$_CL_BK" || return 1
  cp -a /etc/enigma2/lamedb "$_CL_BK/lamedb" 2>/dev/null
  cp -a /etc/enigma2/bouquets.tv "$_CL_BK/bouquets.tv" 2>/dev/null
  cp -a /etc/enigma2/bouquets.radio "$_CL_BK/bouquets.radio" 2>/dev/null
  cp -a /etc/enigma2/*.bouquet "$_CL_BK/" 2>/dev/null
  echo "$_CL_BK"
}
channellist_renew_now() {
  _CL_MODE="${1:-menu}"
  if [ "$_CL_MODE" != "auto" ]; then
    printf "Renew Channel List now? (downloads latest Vhannibal Motor + keeps your favourites) (y/n): "; read _CL_GO
    case "$_CL_GO" in y|Y) ;; *) echo "Cancelled"; return 0;; esac
  fi
  check_net || { echo "[ERROR] No net - Channel List renew stopped, current list kept"; return 1; }
  _CL_DIR="$(channellist_dir)"; mkdir -p "$_CL_DIR" || { echo "[ERROR] Cannot create $_CL_DIR"; return 1; }
  _CL_TMP="/tmp/channellist-tmp"; rm -rf "$_CL_TMP"; mkdir -p "$_CL_TMP"
  echo ">> Downloading latest Vhannibal Motor settings..."
  secure_fetch_file "https://www.vhannibal.net/download_setting.php?id=11&action=download" "$_CL_TMP/motor.zip" "Vhannibal Motor" || { echo "[ERROR] Download failed - current list kept"; rm -rf "$_CL_TMP"; return 1; }
  _CL_SZ=$(stat -c%s "$_CL_TMP/motor.zip" 2>/dev/null || echo 0)
  [ "$_CL_SZ" -gt 100000 ] || { echo "[ERROR] Downloaded file too small ($_CL_SZ) - current list kept"; rm -rf "$_CL_TMP"; return 1; }
  _CL_HAS=0
  if command -v unzip >/dev/null 2>&1; then unzip -l "$_CL_TMP/motor.zip" 2>/dev/null | grep -q "lamedb" && _CL_HAS=1
  elif command -v python3 >/dev/null 2>&1; then python3 -m zipfile -l "$_CL_TMP/motor.zip" 2>/dev/null | grep -q "lamedb" && _CL_HAS=1; fi
  [ "$_CL_HAS" = "1" ] || { echo "[ERROR] Downloaded file has no lamedb - not a settings zip - current list kept"; rm -rf "$_CL_TMP"; return 1; }
  _CL_BK=$(channellist_backup_current) || { echo "[ERROR] Backup failed - refusing to replace list"; rm -rf "$_CL_TMP"; return 1; }
  echo "   Backup: $_CL_BK"
  [ -f /etc/enigma2/userbouquet.favourites.tv ] && cp -a /etc/enigma2/userbouquet.favourites.tv "$_CL_TMP/favourites.tv"
  echo "> Stopping Enigma2 (init 4)..."
  /sbin/init 4 2>/dev/null || /usr/sbin/init 4 2>/dev/null || /bin/init 4 2>/dev/null; sleep 3
  /usr/bin/killall -9 enigma2 2>/dev/null || /bin/killall -9 enigma2 2>/dev/null; sleep 2
  rm -rf "$_CL_TMP/extract"; mkdir -p "$_CL_TMP/extract"
  if command -v unzip >/dev/null 2>&1; then unzip -o -q "$_CL_TMP/motor.zip" -d "$_CL_TMP/extract" 2>/dev/null
  elif command -v python3 >/dev/null 2>&1; then python3 -m zipfile -e "$_CL_TMP/motor.zip" "$_CL_TMP/extract" 2>/dev/null
  else echo "[ERROR] no unzip/python3 to extract"; /sbin/init 3 2>/dev/null; rm -rf "$_CL_TMP"; return 1; fi
  _CL_SRC="$_CL_TMP/extract"
  _CL_F=$(find "$_CL_TMP/extract" -name lamedb -print 2>/dev/null | head -1)
  [ -n "$_CL_F" ] && _CL_SRC=$(dirname "$_CL_F")
  [ -n "$_CL_SRC" ] && [ -f "$_CL_SRC/lamedb" ] || { echo "[ERROR] lamedb not found after extract - current list kept"; /sbin/init 3 2>/dev/null; rm -rf "$_CL_TMP"; return 1; }
  cp -a "$_CL_SRC"/lamedb "$_CL_SRC"/bouquets.tv "$_CL_SRC"/bouquets.radio "$_CL_SRC"/*.bouquet /etc/enigma2/ 2>/dev/null
  [ -f "$_CL_TMP/favourites.tv" ] && cp -a "$_CL_TMP/favourites.tv" /etc/enigma2/userbouquet.favourites.tv
  rm -rf "$_CL_TMP"
  echo "> Restarting Enigma2 (init 3)..."
  /sbin/init 3 2>/dev/null || /usr/sbin/init 3 2>/dev/null || /bin/init 3 2>/dev/null; sleep 3
  ok "Channel List renewed: Vhannibal Motor (latest) - favourites kept - backup: $_CL_BK"
  return 0
}
channellist_auto_refresh_all() {
  _CL_DIR="$(channellist_dir)"
  echo "=== U-Panel Channel List auto-renew: $(date '+%Y-%m-%d %H:%M:%S') ==="
  mkdir -p "$_CL_DIR"
  channellist_renew_now auto >> "$_CL_DIR/auto-renew.log" 2>&1
  _CL_RC=$?
  echo "=== Auto-renew done: rc=$_CL_RC ==="
  return $_CL_RC
}
channellist_cron_line() {
  _CL_SELF=$(readlink -f "$0" 2>/dev/null || echo "$0")
  echo "0 5 * * 5 $_CL_SELF --channellist-auto >> ${UPANEL_ROOT:-/media/hdd/U-Panel}/ChannelList/auto-renew.log 2>&1 # U-Panel-ChannelList-AutoRenew"
}
channellist_cron_status() {
  command -v crontab >/dev/null 2>&1 || { echo "OFF (no crontab on this image)"; return 1; }
  crontab -l 2>/dev/null | grep -q "U-Panel-ChannelList-AutoRenew" && { echo "ON - every Friday at 05:00"; return 0; } || { echo "OFF"; return 1; }
}
channellist_cron_install() {
  rm -f "$(channellist_dir)/.autorenew-disabled"
  command -v crontab >/dev/null 2>&1 || { echo "[ERROR] crontab not found on this image - auto-renew not available"; return 1; }
  _CL_TMPCT="/tmp/upanel-cron.txt"
  crontab -l 2>/dev/null | grep -v "U-Panel-ChannelList-AutoRenew" > "$_CL_TMPCT"
  channellist_cron_line >> "$_CL_TMPCT"
  crontab "$_CL_TMPCT" 2>/dev/null && { rm -f "$_CL_TMPCT"; echo "OK: auto-renew ON - every Friday at 05:00"; return 0; } || { rm -f "$_CL_TMPCT"; echo "[ERROR] could not install cron job"; return 1; }
}
channellist_cron_remove() {
  command -v crontab >/dev/null 2>&1 || { echo "[ERROR] crontab not found"; return 1; }
  _CL_TMPCT="/tmp/upanel-cron.txt"
  crontab -l 2>/dev/null | grep -v "U-Panel-ChannelList-AutoRenew" > "$_CL_TMPCT"
  crontab "$_CL_TMPCT" 2>/dev/null && { rm -f "$_CL_TMPCT"; mkdir -p "$(channellist_dir)"; touch "$(channellist_dir)/.autorenew-disabled"; echo "OK: auto-renew OFF"; return 0; } || { rm -f "$_CL_TMPCT"; echo "[ERROR] could not remove cron job"; return 1; }
}
emoati_epg_menu() {
  while true; do
    show_banner
    line; info "U-Panel EPG - guide data for Egyptian/Arabic channels"
    menu_top; menu_head "U-Panel EPG"; menu_sep
    menu_item "1) Download EPG"; menu_item "2) EPG Auto-refresh"
    menu_bot; footer_back
    printf "Your choice: "; read _EE || return 0
    case "$_EE" in 1) download_epg_menu ;; 2) epg_auto_menu ;; 0) return 0 ;; *) wrong_choice ;; esac
  done
}
channel_editor_menu() {
  while true; do
    show_banner
    menu_top; menu_head "U-Panel Channel Editor"; menu_sep
    menu_item "1) Renew Channel List"; menu_item "2) Bouquet Editor"; menu_item "3) Transponder Update"; menu_item "0) Back"; menu_bot
    printf "Your choice: "; read _CE || return 0
    case "$_CE" in 1) emoati_channellist_menu ;; 2) bouquet_editor_menu ;; 3) transponder_update_menu ;; 0) return 0 ;; *) wrong_choice ;; esac
  done
}
streaming_menu() {
  while true; do
    show_banner
    menu_top; menu_head "U-Panel Streaming"; menu_sep
    menu_item "1) Sharing Servers"; menu_item "2) IPTV Servers"; menu_item "0) Back"; menu_bot
    printf "Your choice: "; read _ST || return 0
    case "$_ST" in 1) my_servers_menu ;; 2) my_iptv_menu ;; 0) return 0 ;; *) wrong_choice ;; esac
  done
}
emoati_channellist_menu() {
  while true; do
    show_banner
    line; info "Renew Channel List - Vhannibal Motor (latest) - favourites kept - backup before replace"
    printf "Auto-renew status: "; channellist_cron_status
    menu_top; menu_head "Renew Channel List"; menu_sep
    menu_item "1) Renew Channel List Now"; menu_item "2) Auto-renew ON (every Friday 05:00 + renew now)"; menu_item "3) Auto-renew OFF"; menu_item "4) Install Auto-ChannelList Plugin"
    menu_bot; footer_back
    printf "Your choice: "; read _EC || return 0
    case "$_EC" in
      1) channellist_renew_now; printf "Press ENTER to return... "; read _back ;;
      2) channellist_cron_install && channellist_renew_now auto; printf "Press ENTER to return... "; read _back ;;
      3) channellist_cron_remove; printf "Press ENTER to return... "; read _back ;;
      4) _CL_PN=0; for _i in $(seq 1 100); do [ "$(plugin_name_by_num $_i)" = "Auto-ChannelList" ] && _CL_PN=$_i && break; done; if [ "$_CL_PN" != "0" ]; then install_plugin_by_num $_CL_PN; else echo "[ERROR] Auto-ChannelList plugin not found in plugin list"; fi; printf "Press ENTER to return... "; read _back ;;
      0) return 0 ;;
      *) wrong_choice ;;
    esac
  done
}
# V4.20: ENIGMA UI gains 6 new choices: 19) Image Update (opkg upgrade, no flash) /
# 20) Transponder Update (latest satellites.xml from OE-Alliance, backup first) /
# 21) Bouquet Editor (create/rename/delete/hide-show/move channel/backup/restore) /
# 22) Skin Changer (switch installed skin + backup skin setting + install from Plugins) /
# 23) My Servers (enter YOUR OWN CCcam C-line / Mgcamd CWS line + list/delete/backup/restore) /
# 24) My IPTV (enter YOUR OWN Xtream / M3U + free legal iptv-org Egypt + backup/restore).
# My Servers / My IPTV store YOUR OWN subscription only - nothing is fetched from free-server sites.
# Enigma Tools gains 16) Factory Reset (backup first, Full or Settings-only).
enigma_stop() {
  /sbin/init 4 2>/dev/null || /usr/sbin/init 4 2>/dev/null || /bin/init 4 2>/dev/null; sleep 3
  /usr/bin/killall -9 enigma2 2>/dev/null || /bin/killall -9 enigma2 2>/dev/null; sleep 2
}
enigma_start() {
  /sbin/init 3 2>/dev/null || /usr/sbin/init 3 2>/dev/null || /bin/init 3 2>/dev/null; sleep 3
}
image_update_menu() {
  while true; do
    show_banner
    line; info "Image Update - updates the RUNNING image (opkg/apt) - NO flash, nothing is erased"
    menu_top; menu_head "Image Update"; menu_sep
    menu_item "1) Check available updates"; menu_item "2) Update now (update feeds + upgrade)"; menu_item "3) Update feeds only"
    menu_bot; footer_back
    printf "Your choice: "; read _IU || return 0
    case "$_IU" in
      1) check_net || { echo "[ERROR] No net"; printf "Press ENTER... "; read _back; continue; }
         if command -v opkg >/dev/null 2>&1; then opkg update 2>/dev/null; echo "--- Available updates:"; opkg list-upgradable 2>/dev/null || echo "  (none / list-upgradable not supported)"
         elif command -v apt-get >/dev/null 2>&1; then apt-get update 2>/dev/null; apt-get list --upgradable 2>/dev/null
         else echo "[ERROR] no opkg/apt-get on this image"; fi
         printf "Press ENTER to return... "; read _back ;;
      2) printf "Update image now? This can take a while - do NOT reboot during update (y/n): "; read _IU_GO
         case "$_IU_GO" in y|Y) ;; *) continue;; esac
         check_net || { echo "[ERROR] No net"; printf "Press ENTER... "; read _back; continue; }
         if command -v opkg >/dev/null 2>&1; then opkg update 2>/dev/null; opkg upgrade 2>/dev/null; ok "Image update done - reboot recommended"
         elif command -v apt-get >/dev/null 2>&1; then apt-get update 2>/dev/null; apt-get upgrade -y 2>/dev/null; ok "Image update done - reboot recommended"
         else echo "[ERROR] no opkg/apt-get on this image"; fi
         printf "Press ENTER to return... "; read _back ;;
      3) check_net || { echo "[ERROR] No net"; printf "Press ENTER... "; read _back; continue; }
         if command -v opkg >/dev/null 2>&1; then opkg update 2>/dev/null; ok "Feeds updated"
         elif command -v apt-get >/dev/null 2>&1; then apt-get update 2>/dev/null; ok "Feeds updated"
         else echo "[ERROR] no opkg/apt-get on this image"; fi
         printf "Press ENTER to return... "; read _back ;;
      0) return 0 ;;
      *) wrong_choice ;;
    esac
  done
}
transponder_dir() { echo "${UPANEL_ROOT:-/media/hdd/U-Panel}/Transponder"; }
transponder_backup_current() {
  _TP_BK="$(transponder_dir)/Backup-$(date +%Y%m%d_%H%M%S)"
  mkdir -p "$_TP_BK" || return 1
  cp -a /etc/tuxbox/satellites.xml "$_TP_BK/satellites.xml" 2>/dev/null
  cp -a /etc/enigma2/satellites.xml "$_TP_BK/satellites-enigma2.xml" 2>/dev/null
  echo "$_TP_BK"
}
transponder_update_menu() {
  while true; do
    show_banner
    line; info "Transponder Update - latest satellites.xml (OE-Alliance) - backup first"
    menu_top; menu_head "Transponder Update"; menu_sep
    menu_item "1) Update satellites.xml now"; menu_item "2) Backup current satellites.xml"
    menu_bot; footer_back
    printf "Your choice: "; read _TP || return 0
    case "$_TP" in
      1) printf "Update satellites.xml now? (backup first, rescan needed after) (y/n): "; read _TP_GO
         case "$_TP_GO" in y|Y) ;; *) continue;; esac
         check_net || { echo "[ERROR] No net - update stopped"; printf "Press ENTER... "; read _back; continue; }
         _TP_TMP="/tmp/satellites.xml"
         secure_fetch_file "https://raw.githubusercontent.com/oe-alliance/oe-alliance-tuxbox-common/master/src/satellites.xml" "$_TP_TMP" "satellites.xml" || { echo "[ERROR] Download failed - old file kept"; printf "Press ENTER... "; read _back; continue; }
         grep -q "<satellites>" "$_TP_TMP" 2>/dev/null || { echo "[ERROR] Downloaded file has no <satellites> - old file kept"; rm -f "$_TP_TMP"; printf "Press ENTER... "; read _back; continue; }
         _TP_BK=$(transponder_backup_current) || { echo "[ERROR] Backup failed - refusing to replace"; rm -f "$_TP_TMP"; printf "Press ENTER... "; read _back; continue; }
         echo "   Backup: $_TP_BK"
         cp -a "$_TP_TMP" /etc/tuxbox/satellites.xml 2>/dev/null || { echo "[ERROR] Cannot write /etc/tuxbox/satellites.xml"; rm -f "$_TP_TMP"; printf "Press ENTER... "; read _back; continue; }
         [ -f /etc/enigma2/satellites.xml ] && cp -a "$_TP_TMP" /etc/enigma2/satellites.xml 2>/dev/null
         rm -f "$_TP_TMP"
         ok "satellites.xml updated - run a channel scan to use the new transponders"
         printf "Press ENTER to return... "; read _back ;;
      2) _TP_BK=$(transponder_backup_current) && echo "Backup: $_TP_BK"; printf "Press ENTER to return... "; read _back ;;
      0) return 0 ;;
      *) wrong_choice ;;
    esac
  done
}
# --- Bouquet Editor ---
bq_build_list() {
  _BQ_LIST="/tmp/bq-list.txt"; : > "$_BQ_LIST"
  _BQ_I=0; _BQ_F=""
  [ -f /etc/enigma2/bouquets.tv ] || { echo "0"; return 0; }
  while IFS= read -r _l; do
    case "$_l" in
      \#SERVICE*FROM\ BOUQUET*)
        if [ -n "$_BQ_F" ]; then _BQ_I=$((_BQ_I+1)); echo "$_BQ_I|$_BQ_F|$_BQ_F" >> "$_BQ_LIST"; fi
        _BQ_F=$(echo "$_l" | sed 's/.*FROM BOUQUET "\(.*\)" ORDER.*/\1/') ;;
      \#DESCRIPTION*)
        if [ -n "$_BQ_F" ]; then _BQ_I=$((_BQ_I+1)); echo "$_BQ_I|$_BQ_F|${_l#\#DESCRIPTION }" >> "$_BQ_LIST"; _BQ_F=""; fi ;;
    esac
  done < /etc/enigma2/bouquets.tv
  if [ -n "$_BQ_F" ]; then _BQ_I=$((_BQ_I+1)); echo "$_BQ_I|$_BQ_F|$_BQ_F" >> "$_BQ_LIST"; fi
  echo "$_BQ_I"
}
bq_show_list() {
  _BQ_N=$(bq_build_list)
  [ "$_BQ_N" = "0" ] && { echo "  (no bouquets)"; return 1; }
  while IFS='|' read -r _n _f _nm; do
    _BQ_C=$(grep -c "^#SERVICE" "/etc/enigma2/$_f" 2>/dev/null || echo 0)
    echo "  $_n) $_nm  [$_f - $_BQ_C ch]"
  done < "$_BQ_LIST"
  return 0
}
bq_file_by_num() { sed -n "${1}p" "$_BQ_LIST" 2>/dev/null | cut -d'|' -f2; }
bq_remove_from_bouquets_tv() {
  _BQ_RF="$1"
  _BQ_LN=$(grep -n "FROM BOUQUET \"$_BQ_RF\"" /etc/enigma2/bouquets.tv 2>/dev/null | head -1 | cut -d: -f1)
  [ -z "$_BQ_LN" ] && return 0
  _BQ_NEXT=$(sed -n "$((_BQ_LN+1))p" /etc/enigma2/bouquets.tv 2>/dev/null)
  case "$_BQ_NEXT" in \#DESCRIPTION*) sed -i "${_BQ_LN},$((_BQ_LN+1))d" /etc/enigma2/bouquets.tv ;; *) sed -i "${_BQ_LN}d" /etc/enigma2/bouquets.tv ;; esac
}
bq_build_services() {
  _BQ_SVC="/tmp/bq-svc.txt"; : > "$_BQ_SVC"
  _BQ_I=0; _BQ_LN=0; _BQ_REF=""; _BQ_RLN=0
  while IFS= read -r _l; do _BQ_LN=$((_BQ_LN+1))
    case "$_l" in
      \#SERVICE*)
        if [ -n "$_BQ_REF" ]; then _BQ_I=$((_BQ_I+1)); echo "$_BQ_I|$_BQ_RLN|$_BQ_REF" >> "$_BQ_SVC"; fi
        _BQ_REF="$_l"; _BQ_RLN=$_BQ_LN ;;
      \#DESCRIPTION*)
        if [ -n "$_BQ_REF" ]; then _BQ_I=$((_BQ_I+1)); echo "$_BQ_I|$_BQ_RLN|${_l#\#DESCRIPTION }" >> "$_BQ_SVC"; _BQ_REF=""; fi ;;
    esac
  done < "/etc/enigma2/$1"
  if [ -n "$_BQ_REF" ]; then _BQ_I=$((_BQ_I+1)); echo "$_BQ_I|$_BQ_RLN|$_BQ_REF" >> "$_BQ_SVC"; fi
  echo "$_BQ_I"
}
bouquet_editor_menu() {
  while true; do
    show_banner
    line; info "Bouquet Editor - create/rename/delete/hide-show/move channel/backup"
    menu_top; menu_head "Bouquet Editor"; menu_sep
    menu_item "1) List bouquets"; menu_item "2) Create bouquet"; menu_item "3) Rename bouquet"; menu_item "4) Delete bouquet"; menu_item "5) Hide / Show bouquet"; menu_item "6) Move channel between bouquets"; menu_item "7) Backup bouquets"; menu_item "8) Restore bouquets"
    menu_bot; footer_back
    printf "Your choice: "; read _BQ || return 0
    case "$_BQ" in
      1) bq_show_list; printf "Press ENTER to return... "; read _back ;;
      2) printf "New bouquet name: "; read _BQ_NAME
         [ -z "$_BQ_NAME" ] && { echo "Cancelled"; continue; }
         _BQ_SLUG=$(echo "$_BQ_NAME" | tr '[:upper:]' '[:lower:]' | tr ' ' '_' | tr -cd 'a-z0-9_-')
         [ -z "$_BQ_SLUG" ] && { echo "[ERROR] Name must contain letters/numbers"; continue; }
         _BQ_FILE="userbouquet.$_BQ_SLUG.tv"
         [ -f "/etc/enigma2/$_BQ_FILE" ] && { echo "[ERROR] Bouquet already exists: $_BQ_FILE"; continue; }
         enigma_stop
         printf '#NAME %s\n' "$_BQ_NAME" > "/etc/enigma2/$_BQ_FILE"
         printf '#SERVICE 1:7:1:0:0:0:0:0:0:0:FROM BOUQUET "%s" ORDER BY bouquet\n#DESCRIPTION %s\n' "$_BQ_FILE" "$_BQ_NAME" >> /etc/enigma2/bouquets.tv
         enigma_start
         ok "Bouquet created: $_BQ_NAME"; printf "Press ENTER... "; read _back ;;
      3) bq_show_list || { printf "Press ENTER... "; read _back; continue; }
         printf "Bouquet to rename (number): "; read _BQ_P
         case "$_BQ_P" in ''|*[!0-9]*) wrong_choice; continue;; esac
         _BQ_FILE=$(bq_file_by_num "$_BQ_P"); [ -z "$_BQ_FILE" ] && { wrong_choice; continue; }
         printf "New name: "; read _BQ_NEW; [ -z "$_BQ_NEW" ] && { echo "Cancelled"; continue; }
         enigma_stop
         sed -i "s|^#NAME .*|#NAME $_BQ_NEW|" "/etc/enigma2/$_BQ_FILE" 2>/dev/null
         _BQ_LN=$(grep -n "FROM BOUQUET \"$_BQ_FILE\"" /etc/enigma2/bouquets.tv 2>/dev/null | head -1 | cut -d: -f1)
         [ -n "$_BQ_LN" ] && sed -i "$((_BQ_LN+1))s|^#DESCRIPTION .*|#DESCRIPTION $_BQ_NEW|" /etc/enigma2/bouquets.tv 2>/dev/null
         enigma_start
         ok "Bouquet renamed to: $_BQ_NEW"; printf "Press ENTER... "; read _back ;;
      4) bq_show_list || { printf "Press ENTER... "; read _back; continue; }
         printf "Bouquet to delete (number): "; read _BQ_P
         case "$_BQ_P" in ''|*[!0-9]*) wrong_choice; continue;; esac
         _BQ_FILE=$(bq_file_by_num "$_BQ_P"); [ -z "$_BQ_FILE" ] && { wrong_choice; continue; }
         [ "$_BQ_FILE" = "userbouquet.favourites.tv" ] && { echo "[ERROR] Favourites cannot be deleted here - use Hide instead"; printf "Press ENTER... "; read _back; continue; }
         printf "Delete bouquet $_BQ_FILE? (y/n): "; read _BQ_DEL
         case "$_BQ_DEL" in y|Y) ;; *) continue;; esac
         enigma_stop
         bq_remove_from_bouquets_tv "$_BQ_FILE"
         rm -f "/etc/enigma2/$_BQ_FILE"
         enigma_start
         ok "Bouquet deleted: $_BQ_FILE"; printf "Press ENTER... "; read _back ;;
      5) printf "1) Hide a bouquet (file kept, hidden from list)\n  2) Show a hidden bouquet\nYour choice: "; read _BQ_HS
         case "$_BQ_HS" in
           1) bq_show_list || { printf "Press ENTER... "; read _back; continue; }
              printf "Bouquet to hide (number): "; read _BQ_P
              case "$_BQ_P" in ''|*[!0-9]*) wrong_choice; continue;; esac
              _BQ_FILE=$(bq_file_by_num "$_BQ_P"); [ -z "$_BQ_FILE" ] && { wrong_choice; continue; }
              enigma_stop; bq_remove_from_bouquets_tv "$_BQ_FILE"; enigma_start
              ok "Bouquet hidden (file kept): $_BQ_FILE"; printf "Press ENTER... "; read _back ;;
           2) _BQ_HID=""; _BQ_HI=0
              for _f in /etc/enigma2/userbouquet.*.tv; do
                [ -f "$_f" ] || continue
                _b=$(basename "$_f")
                grep -q "FROM BOUQUET \"$_b\"" /etc/enigma2/bouquets.tv 2>/dev/null && continue
                _BQ_HI=$((_BQ_HI+1)); echo "  $_BQ_HI) $_b"; _BQ_HID="$_BQ_HID $_b"
              done
              [ "$_BQ_HI" = "0" ] && { echo "  (no hidden bouquets)"; printf "Press ENTER... "; read _back; continue; }
              printf "Bouquet to show (number): "; read _BQ_P
              case "$_BQ_P" in ''|*[!0-9]*) wrong_choice; continue;; esac
              _BQ_FILE=$(echo "$_BQ_HID" | cut -d' ' -f$((_BQ_P+1))); [ -z "$_BQ_FILE" ] && { wrong_choice; continue; }
              _BQ_NM=$(grep "^#NAME " "/etc/enigma2/$_BQ_FILE" 2>/dev/null | head -1 | sed 's/^#NAME //'); [ -z "$_BQ_NM" ] && _BQ_NM="$_BQ_FILE"
              enigma_stop
              printf '#SERVICE 1:7:1:0:0:0:0:0:0:0:FROM BOUQUET "%s" ORDER BY bouquet\n#DESCRIPTION %s\n' "$_BQ_FILE" "$_BQ_NM" >> /etc/enigma2/bouquets.tv
              enigma_start
              ok "Bouquet shown: $_BQ_NM"; printf "Press ENTER... "; read _back ;;
           *) wrong_choice ;;
         esac ;;
      6) bq_show_list || { printf "Press ENTER... "; read _back; continue; }
         printf "Source bouquet (number): "; read _BQ_SRC_N
         case "$_BQ_SRC_N" in ''|*[!0-9]*) wrong_choice; continue;; esac
         _BQ_SRC=$(bq_file_by_num "$_BQ_SRC_N"); [ -z "$_BQ_SRC" ] && { wrong_choice; continue; }
         _BQ_SN=$(bq_build_services "$_BQ_SRC")
         [ "$_BQ_SN" = "0" ] && { echo "  (no channels in this bouquet)"; printf "Press ENTER... "; read _back; continue; }
         while IFS='|' read -r _n _ln _nm; do echo "  $_n) $_nm"; done < "$_BQ_SVC"
         printf "Channel to move (number): "; read _BQ_CH
         case "$_BQ_CH" in ''|*[!0-9]*) wrong_choice; continue;; esac
         _BQ_SEL=$(sed -n "${_BQ_CH}p" "$_BQ_SVC" 2>/dev/null); [ -z "$_BQ_SEL" ] && { wrong_choice; continue; }
         _BQ_SLN=$(echo "$_BQ_SEL" | cut -d'|' -f2)
         echo "Target bouquet:"
         _BQ_TL=""; _BQ_TI=0
         _BQ_N=$(bq_build_list)
         while IFS='|' read -r _n _f _nm; do
           [ "$_f" = "$_BQ_SRC" ] && continue
           _BQ_TI=$((_BQ_TI+1)); echo "  $_BQ_TI) $_nm"; _BQ_TL="$_BQ_TL $_f"
         done < "$_BQ_LIST"
         [ "$_BQ_TI" = "0" ] && { echo "  (no other bouquet - create one first)"; printf "Press ENTER... "; read _back; continue; }
         printf "Target bouquet (number): "; read _BQ_TN
         case "$_BQ_TN" in ''|*[!0-9]*) wrong_choice; continue;; esac
         _BQ_TGT=$(echo "$_BQ_TL" | cut -d' ' -f$((_BQ_TN+1))); [ -z "$_BQ_TGT" ] && { wrong_choice; continue; }
         _BQ_SLINE=$(sed -n "${_BQ_SLN}p" "/etc/enigma2/$_BQ_SRC" 2>/dev/null)
         _BQ_NEXT=$(sed -n "$((_BQ_SLN+1))p" "/etc/enigma2/$_BQ_SRC" 2>/dev/null)
         enigma_stop
         case "$_BQ_NEXT" in
           \#DESCRIPTION*) sed -i "${_BQ_SLN},$((_BQ_SLN+1))d" "/etc/enigma2/$_BQ_SRC"; { echo "$_BQ_SLINE"; echo "$_BQ_NEXT"; } >> "/etc/enigma2/$_BQ_TGT" ;;
           *) sed -i "${_BQ_SLN}d" "/etc/enigma2/$_BQ_SRC"; echo "$_BQ_SLINE" >> "/etc/enigma2/$_BQ_TGT" ;;
         esac
         enigma_start
         ok "Channel moved: $_BQ_SRC -> $_BQ_TGT"; printf "Press ENTER... "; read _back ;;
      7) _BQ_BK="${UPANEL_ROOT:-/media/hdd/U-Panel}/ChannelList/Backup-Bouquets-$(date +%Y%m%d_%H%M%S)"
         mkdir -p "$_BQ_BK" || { echo "[ERROR] Cannot create backup dir"; printf "Press ENTER... "; read _back; continue; }
         cp -a /etc/enigma2/bouquets.tv /etc/enigma2/bouquets.radio /etc/enigma2/*.bouquet /etc/enigma2/userbouquet.* "$_BQ_BK/" 2>/dev/null
         ok "Bouquets backed up: $_BQ_BK"; printf "Press ENTER... "; read _back ;;
      8) _BQ_RS=""; _BQ_RI=0
         for _d in "${UPANEL_ROOT:-/media/hdd/U-Panel}"/ChannelList/Backup-Bouquets-*; do
           [ -d "$_d" ] || continue
           _BQ_RI=$((_BQ_RI+1)); echo "  $_BQ_RI) $(basename "$_d")"; _BQ_RS="$_BQ_RS $_d"
         done
         [ "$_BQ_RI" = "0" ] && { echo "  (no bouquet backups)"; printf "Press ENTER... "; read _back; continue; }
         printf "Backup to restore (number): "; read _BQ_RN
         case "$_BQ_RN" in ''|*[!0-9]*) wrong_choice; continue;; esac
         _BQ_RD=$(echo "$_BQ_RS" | cut -d' ' -f$((_BQ_RN+1))); [ -z "$_BQ_RD" ] && { wrong_choice; continue; }
         printf "Restore bouquets from $(basename "$_BQ_RD")? (y/n): "; read _BQ_RY
         case "$_BQ_RY" in y|Y) ;; *) continue;; esac
         enigma_stop
         cp -a "$_BQ_RD"/. /etc/enigma2/ 2>/dev/null
         enigma_start
         ok "Bouquets restored from: $(basename "$_BQ_RD")"; printf "Press ENTER... "; read _back ;;
      0) return 0 ;;
      *) wrong_choice ;;
    esac
  done
}
# --- Skin Changer ---
skin_changer_menu() {
  while true; do
    show_banner
    line; info "Skin Changer - switch Enigma2 skin"
    printf "Current skin: "; grep "^config.skin.primary_skin=" /etc/enigma2/settings 2>/dev/null | cut -d= -f2; echo ""
    menu_top; menu_head "Skin Changer"; menu_sep
    menu_item "1) Choose skin (installed)"; menu_item "2) Backup current skin setting"; menu_item "3) Install skin from Plugins menu (Skins & UI)"
    menu_bot; footer_back
    printf "Your choice: "; read _SC || return 0
    case "$_SC" in
      1) _SC_LIST=""; _SC_I=0
         for _d in /usr/share/enigma2/*/; do
           [ -f "$_d/skin.xml" ] || continue
           _n=$(basename "$_d"); [ "$_n" = "skin_default" ] && continue
           _SC_I=$((_SC_I+1)); echo "  $_SC_I) $_n"; _SC_LIST="$_SC_LIST $_n"
         done
         [ "$_SC_I" = "0" ] && { echo "  (no skins found)"; printf "Press ENTER... "; read _back; continue; }
         printf "Skin (1-$_SC_I): "; read _SC_P
         case "$_SC_P" in ''|*[!0-9]*) wrong_choice; continue;; esac
         _SC_NAME=$(echo "$_SC_LIST" | cut -d' ' -f$((_SC_P+1))); [ -z "$_SC_NAME" ] && { wrong_choice; continue; }
         printf "Change skin to $_SC_NAME? GUI will restart (y/n): "; read _SC_Y
         case "$_SC_Y" in y|Y) ;; *) continue;; esac
         enigma_stop
         if grep -q "^config.skin.primary_skin=" /etc/enigma2/settings 2>/dev/null; then sed -i "s|^config.skin.primary_skin=.*|config.skin.primary_skin=$_SC_NAME/skin.xml|" /etc/enigma2/settings
         else echo "config.skin.primary_skin=$_SC_NAME/skin.xml" >> /etc/enigma2/settings; fi
         enigma_start
         ok "Skin changed to: $_SC_NAME"; printf "Press ENTER... "; read _back ;;
      2) _SC_BK="${UPANEL_ROOT:-/media/hdd/U-Panel}/Skins/Backup-$(date +%Y%m%d_%H%M%S)"
         mkdir -p "$_SC_BK" || { echo "[ERROR] Cannot create backup dir"; printf "Press ENTER... "; read _back; continue; }
         cp -a /etc/enigma2/settings "$_SC_BK/settings" 2>/dev/null
         ok "Skin setting backed up: $_SC_BK"; printf "Press ENTER... "; read _back ;;
      3) show_category_menu "$CAT_SKIN" "Skins & UI" ;;
      0) return 0 ;;
      *) wrong_choice ;;
    esac
  done
}
# --- My Servers (YOUR OWN subscription) ---
my_servers_dir() { echo "${UPANEL_ROOT:-/media/hdd/U-Panel}/MyServers"; }
my_servers_backup() {
  _MS_BK="$(my_servers_dir)/Backup-$(date +%Y%m%d_%H%M%S)"
  mkdir -p "$_MS_BK" || return 1
  cp -a /etc/CCcam.cfg "$_MS_BK/CCcam.cfg" 2>/dev/null
  cp -a /etc/tuxbox/config/newcamd.list "$_MS_BK/newcamd.list" 2>/dev/null
  echo "$_MS_BK"
}
my_servers_list() {
  echo "--- CCcam (/etc/CCcam.cfg):"
  if [ -f /etc/CCcam.cfg ]; then grep "^C:" /etc/CCcam.cfg 2>/dev/null | awk '{print "  C: " $2 " " $3 " " $4 " ****"}'; else echo "  (no CCcam.cfg)"; fi
  echo "--- Mgcamd (/etc/tuxbox/config/newcamd.list):"
  if [ -f /etc/tuxbox/config/newcamd.list ]; then grep "^CWS" /etc/tuxbox/config/newcamd.list 2>/dev/null | awk '{print "  CWS: " $3 " " $4 " " $5 " ****"}'; else echo "  (no newcamd.list)"; fi
}
my_servers_menu() {
  while true; do
    show_banner
    line; info "Sharing Servers - YOUR OWN CCcam / Mgcamd subscription - enter it, back it up, restore it"
    menu_top; menu_head "Sharing Servers"; menu_sep
    menu_item "1) Add CCcam server (C-line)"; menu_item "2) Add Mgcamd server (CWS line)"; menu_item "3) List my servers"; menu_item "4) Delete a server"; menu_item "5) Backup my servers"; menu_item "6) Restore my servers"
    menu_bot; footer_back
    printf "Your choice: "; read _MS || return 0
    case "$_MS" in
      1) printf "CCcam host: "; read _MS_H; printf "Port: "; read _MS_P; printf "Username: "; read _MS_U; printf "Password: "; read _MS_W
         [ -z "$_MS_H" ] || [ -z "$_MS_P" ] || [ -z "$_MS_U" ] || [ -z "$_MS_W" ] && { echo "[ERROR] All 4 fields are required"; printf "Press ENTER... "; read _back; continue; }
         case "$_MS_P" in ''|*[!0-9]*) echo "[ERROR] Port must be a number"; printf "Press ENTER... "; read _back; continue;; esac
         _MS_BK=$(my_servers_backup) && echo "   Backup: $_MS_BK"
         echo "C: $_MS_H $_MS_P $_MS_U $_MS_W" >> /etc/CCcam.cfg
         ok "CCcam server added: $_MS_H:$_MS_P - restart your softcam from the image menu to apply"
         printf "Press ENTER... "; read _back ;;
      2) printf "Mgcamd host: "; read _MS_H; printf "Port: "; read _MS_P; printf "Username: "; read _MS_U; printf "Password: "; read _MS_W; printf "DES key (ENTER = default 01 02 03 ... 14): "; read _MS_D
         [ -z "$_MS_H" ] || [ -z "$_MS_P" ] || [ -z "$_MS_U" ] || [ -z "$_MS_W" ] && { echo "[ERROR] Host/Port/Username/Password are required"; printf "Press ENTER... "; read _back; continue; }
         case "$_MS_P" in ''|*[!0-9]*) echo "[ERROR] Port must be a number"; printf "Press ENTER... "; read _back; continue;; esac
         [ -z "$_MS_D" ] && _MS_D="01 02 03 04 05 06 07 08 09 10 11 12 13 14"
         _MS_BK=$(my_servers_backup) && echo "   Backup: $_MS_BK"
         mkdir -p /etc/tuxbox/config 2>/dev/null
         echo "CWS = $_MS_H $_MS_P $_MS_U $_MS_W $_MS_D" >> /etc/tuxbox/config/newcamd.list
         ok "Mgcamd server added: $_MS_H:$_MS_P - restart your softcam from the image menu to apply"
         printf "Press ENTER... "; read _back ;;
      3) my_servers_list; printf "Press ENTER... "; read _back ;;
      4) _MS_L="/tmp/ms-list.txt"; : > "$_MS_L"; _MS_I=0
         if [ -f /etc/CCcam.cfg ]; then
           grep -n "^C:" /etc/CCcam.cfg 2>/dev/null | while IFS=: read -r _ln _line; do echo "cccam|$_ln|$_line" >> "$_MS_L"; done
         fi
         if [ -f /etc/tuxbox/config/newcamd.list ]; then
           grep -n "^CWS" /etc/tuxbox/config/newcamd.list 2>/dev/null | while IFS=: read -r _ln _line; do echo "mgcamd|$_ln|$_line" >> "$_MS_L"; done
         fi
         _MS_I=$(wc -l < "$_MS_L" 2>/dev/null)
         [ "$_MS_I" = "0" ] && { echo "  (no servers saved)"; printf "Press ENTER... "; read _back; continue; }
         _MS_N=0
         while IFS='|' read -r _t _ln _line; do
           _MS_N=$((_MS_N+1))
           case "$_t" in
             cccam) echo "$_line" | awk -v n="$_MS_N" '{print "  " n ") CCcam: " $2 " " $3 " " $4 " ****"}' ;;
             *) echo "$_line" | awk -v n="$_MS_N" '{print "  " n ") Mgcamd: " $3 " " $4 " " $5 " ****"}' ;;
           esac
         done < "$_MS_L"
         printf "Server to delete (number): "; read _MS_DN
         case "$_MS_DN" in ''|*[!0-9]*) wrong_choice; continue;; esac
         _MS_SEL=$(sed -n "${_MS_DN}p" "$_MS_L" 2>/dev/null); [ -z "$_MS_SEL" ] && { wrong_choice; continue; }
         _MS_DT=$(echo "$_MS_SEL" | cut -d'|' -f1); _MS_DL=$(echo "$_MS_SEL" | cut -d'|' -f2)
         printf "Delete this server? (y/n): "; read _MS_DY
         case "$_MS_DY" in y|Y) ;; *) continue;; esac
         _MS_BK=$(my_servers_backup) && echo "   Backup: $_MS_BK"
         case "$_MS_DT" in cccam) sed -i "${_MS_DL}d" /etc/CCcam.cfg ;; *) sed -i "${_MS_DL}d" /etc/tuxbox/config/newcamd.list ;; esac
         ok "Server deleted"; printf "Press ENTER... "; read _back ;;
      5) _MS_BK=$(my_servers_backup) && ok "Servers backed up: $_MS_BK"; printf "Press ENTER... "; read _back ;;
      6) _MS_RS=""; _MS_RI=0
         for _d in "$(my_servers_dir)"/Backup-*; do
           [ -d "$_d" ] || continue
           _MS_RI=$((_MS_RI+1)); echo "  $_MS_RI) $(basename "$_d")"; _MS_RS="$_MS_RS $_d"
         done
         [ "$_MS_RI" = "0" ] && { echo "  (no server backups)"; printf "Press ENTER... "; read _back; continue; }
         printf "Backup to restore (number): "; read _MS_RN
         case "$_MS_RN" in ''|*[!0-9]*) wrong_choice; continue;; esac
         _MS_RD=$(echo "$_MS_RS" | cut -d' ' -f$((_MS_RN+1))); [ -z "$_MS_RD" ] && { wrong_choice; continue; }
         printf "Restore servers from $(basename "$_MS_RD")? (overwrites current) (y/n): "; read _MS_RY
         case "$_MS_RY" in y|Y) ;; *) continue;; esac
         _MS_BK=$(my_servers_backup) && echo "   Current backed up: $_MS_BK"
         [ -f "$_MS_RD/CCcam.cfg" ] && cp -a "$_MS_RD/CCcam.cfg" /etc/CCcam.cfg
         [ -f "$_MS_RD/newcamd.list" ] && { mkdir -p /etc/tuxbox/config 2>/dev/null; cp -a "$_MS_RD/newcamd.list" /etc/tuxbox/config/newcamd.list; }
         ok "Servers restored from: $(basename "$_MS_RD")"; printf "Press ENTER... "; read _back ;;
      0) return 0 ;;
      *) wrong_choice ;;
    esac
  done
}
# --- My IPTV (YOUR OWN subscription) ---
my_iptv_dir() { echo "${UPANEL_ROOT:-/media/hdd/U-Panel}/MyIPTV"; }
my_iptv_backup() {
  _MI_BK="${UPANEL_ROOT:-/media/hdd/U-Panel}/MyIPTV-Backup-$(date +%Y%m%d_%H%M%S)"
  mkdir -p "$_MI_BK" || return 1
  cp -a "$(my_iptv_dir)/." "$_MI_BK/" 2>/dev/null
  echo "$_MI_BK"
}
my_iptv_menu() {
  while true; do
    show_banner
    line; info "IPTV Servers - YOUR OWN Xtream / M3U subscription + free legal iptv-org"
    menu_top; menu_head "IPTV Servers"; menu_sep
    menu_item "1) Add Xtream server"; menu_item "2) Add M3U playlist (URL)"; menu_item "3) Download free legal IPTV (iptv-org Egypt)"; menu_item "4) List my IPTV"; menu_item "5) Delete an entry"; menu_item "6) Backup my IPTV"; menu_item "7) Restore my IPTV"
    menu_bot; footer_back
    printf "Your choice: "; read _MI || return 0
    case "$_MI" in
      1) mkdir -p "$(my_iptv_dir)" 2>/dev/null
         printf "Name (e.g. MyServer): "; read _MI_N; printf "Host (no http://): "; read _MI_H; printf "Port: "; read _MI_P; printf "Username: "; read _MI_U; printf "Password: "; read _MI_W
         [ -z "$_MI_N" ] || [ -z "$_MI_H" ] || [ -z "$_MI_P" ] || [ -z "$_MI_U" ] || [ -z "$_MI_W" ] && { echo "[ERROR] All fields are required"; printf "Press ENTER... "; read _back; continue; }
         case "$_MI_P" in ''|*[!0-9]*) echo "[ERROR] Port must be a number"; printf "Press ENTER... "; read _back; continue;; esac
         _MI_SLUG=$(echo "$_MI_N" | tr '[:upper:]' '[:lower:]' | tr ' ' '_' | tr -cd 'a-z0-9_-'); [ -z "$_MI_SLUG" ] && _MI_SLUG="server"
         grep -v "^$_MI_N|" "$(my_iptv_dir)/servers.txt" 2>/dev/null > /tmp/mi-srv.txt; mv /tmp/mi-srv.txt "$(my_iptv_dir)/servers.txt" 2>/dev/null
         echo "$_MI_N|$_MI_H|$_MI_P|$_MI_U|$_MI_W" >> "$(my_iptv_dir)/servers.txt"
         _MI_URL="http://$_MI_H:$_MI_P/get.php?username=$_MI_U&password=$_MI_W&type=m3u_plus&output=ts"
         check_net || { echo "[WARN] No net - server saved, playlist NOT downloaded"; echo "$_MI_URL" > "$(my_iptv_dir)/$_MI_SLUG.url.txt"; printf "Press ENTER... "; read _back; continue; }
         if secure_fetch_file "$_MI_URL" "$(my_iptv_dir)/$_MI_SLUG.m3u" "IPTV $_MI_N" && grep -q "#EXTM3U" "$(my_iptv_dir)/$_MI_SLUG.m3u" 2>/dev/null; then
           ok "Xtream server added + playlist downloaded: $_MI_SLUG.m3u"
         else
           rm -f "$(my_iptv_dir)/$_MI_SLUG.m3u"
           echo "$_MI_URL" > "$(my_iptv_dir)/$_MI_SLUG.url.txt"
           echo "Server saved - playlist could not be downloaded, URL saved in $_MI_SLUG.url.txt (open it in VLC / JediMaker)"
         fi
         printf "Press ENTER... "; read _back ;;
      2) mkdir -p "$(my_iptv_dir)" 2>/dev/null
         printf "Name (e.g. EgyptList): "; read _MI_N; printf "M3U URL: "; read _MI_U
         [ -z "$_MI_N" ] || [ -z "$_MI_U" ] && { echo "[ERROR] Name and URL are required"; printf "Press ENTER... "; read _back; continue; }
         _MI_SLUG=$(echo "$_MI_N" | tr '[:upper:]' '[:lower:]' | tr ' ' '_' | tr -cd 'a-z0-9_-'); [ -z "$_MI_SLUG" ] && _MI_SLUG="playlist"
         check_net || { echo "[ERROR] No net"; printf "Press ENTER... "; read _back; continue; }
         if secure_fetch_file "$_MI_U" "$(my_iptv_dir)/$_MI_SLUG.m3u" "M3U $_MI_N" && grep -q "#EXTM3U" "$(my_iptv_dir)/$_MI_SLUG.m3u" 2>/dev/null; then
           ok "M3U playlist added: $_MI_SLUG.m3u"
         else
           rm -f "$(my_iptv_dir)/$_MI_SLUG.m3u"; echo "[ERROR] Download failed or not an M3U playlist (no #EXTM3U)"
         fi
         printf "Press ENTER... "; read _back ;;
      3) mkdir -p "$(my_iptv_dir)" 2>/dev/null
         check_net || { echo "[ERROR] No net"; printf "Press ENTER... "; read _back; continue; }
         if secure_fetch_file "https://iptv-org.github.io/iptv/countries/eg.m3u" "$(my_iptv_dir)/iptv-org-egypt.m3u" "iptv-org Egypt" && grep -q "#EXTM3U" "$(my_iptv_dir)/iptv-org-egypt.m3u" 2>/dev/null; then
           ok "Free legal IPTV downloaded: iptv-org-egypt.m3u (open channels only)"
         else
           rm -f "$(my_iptv_dir)/iptv-org-egypt.m3u"; echo "[ERROR] Download failed"
         fi
         printf "Press ENTER... "; read _back ;;
      4) echo "--- Xtream servers:"
         if [ -f "$(my_iptv_dir)/servers.txt" ]; then awk -F'|' '{print "  " $1 " - " $2 ":" $3 " - " $4 " ****"}' "$(my_iptv_dir)/servers.txt" 2>/dev/null; else echo "  (none)"; fi
         echo "--- M3U playlists:"
         _MI_ANY=0
         for _f in "$(my_iptv_dir)"/*.m3u; do [ -f "$_f" ] || continue; _MI_ANY=1; echo "  $(basename "$_f") - $(stat -c%s "$_f" 2>/dev/null) bytes"; done
         [ "$_MI_ANY" = "0" ] && echo "  (none)"
         printf "Press ENTER... "; read _back ;;
      5) _MI_L="/tmp/mi-list.txt"; : > "$_MI_L"; _MI_I=0
         if [ -f "$(my_iptv_dir)/servers.txt" ]; then
           while IFS='|' read -r _n _h _p _u _w; do [ -z "$_n" ] && continue; _MI_I=$((_MI_I+1)); echo "$_MI_I|server|$_n" >> "$_MI_L"; done < "$(my_iptv_dir)/servers.txt"
         fi
         for _f in "$(my_iptv_dir)"/*.m3u; do [ -f "$_f" ] || continue; _MI_I=$((_MI_I+1)); echo "$_MI_I|m3u|$(basename "$_f")" >> "$_MI_L"; done
         [ "$_MI_I" = "0" ] && { echo "  (nothing to delete)"; printf "Press ENTER... "; read _back; continue; }
         while IFS='|' read -r _n _t _nm; do echo "  $_n) [$_t] $_nm"; done < "$_MI_L"
         printf "Entry to delete (number): "; read _MI_DN
         case "$_MI_DN" in ''|*[!0-9]*) wrong_choice; continue;; esac
         _MI_SEL=$(sed -n "${_MI_DN}p" "$_MI_L" 2>/dev/null); [ -z "$_MI_SEL" ] && { wrong_choice; continue; }
         _MI_DT=$(echo "$_MI_SEL" | cut -d'|' -f2); _MI_DNM=$(echo "$_MI_SEL" | cut -d'|' -f3)
         printf "Delete [$_MI_DT] $_MI_DNM? (y/n): "; read _MI_DY
         case "$_MI_DY" in y|Y) ;; *) continue;; esac
         if [ "$_MI_DT" = "server" ]; then
           _MI_SLUG=$(echo "$_MI_DNM" | tr '[:upper:]' '[:lower:]' | tr ' ' '_' | tr -cd 'a-z0-9_-')
           grep -v "^$_MI_DNM|" "$(my_iptv_dir)/servers.txt" 2>/dev/null > /tmp/mi-srv.txt; mv /tmp/mi-srv.txt "$(my_iptv_dir)/servers.txt" 2>/dev/null
           rm -f "$(my_iptv_dir)/$_MI_SLUG.m3u" "$(my_iptv_dir)/$_MI_SLUG.url.txt"
         else
           rm -f "$(my_iptv_dir)/$_MI_DNM"
         fi
         ok "Deleted: $_MI_DNM"; printf "Press ENTER... "; read _back ;;
      6) _MI_BK=$(my_iptv_backup) && ok "IPTV backed up: $_MI_BK"; printf "Press ENTER... "; read _back ;;
      7) _MI_RS=""; _MI_RI=0
         for _d in "${UPANEL_ROOT:-/media/hdd/U-Panel}"/MyIPTV-Backup-*; do
           [ -d "$_d" ] || continue
           _MI_RI=$((_MI_RI+1)); echo "  $_MI_RI) $(basename "$_d")"; _MI_RS="$_MI_RS $_d"
         done
         [ "$_MI_RI" = "0" ] && { echo "  (no IPTV backups)"; printf "Press ENTER... "; read _back; continue; }
         printf "Backup to restore (number): "; read _MI_RN
         case "$_MI_RN" in ''|*[!0-9]*) wrong_choice; continue;; esac
         _MI_RD=$(echo "$_MI_RS" | cut -d' ' -f$((_MI_RN+1))); [ -z "$_MI_RD" ] && { wrong_choice; continue; }
         printf "Restore IPTV from $(basename "$_MI_RD")? (overwrites current) (y/n): "; read _MI_RY
         case "$_MI_RY" in y|Y) ;; *) continue;; esac
         _MI_BK=$(my_iptv_backup) && echo "   Current backed up: $_MI_BK"
         rm -rf "$(my_iptv_dir)"; mkdir -p "$(my_iptv_dir)" 2>/dev/null; cp -a "$_MI_RD"/. "$(my_iptv_dir)/" 2>/dev/null
         ok "IPTV restored from: $(basename "$_MI_RD")"; printf "Press ENTER... "; read _back ;;
      0) return 0 ;;
      *) wrong_choice ;;
    esac
  done
}
# --- Factory Reset (Enigma Tools) ---
factory_reset_menu() {
  while true; do
    show_banner
    line; info "Factory Reset - back to clean Enigma2 - backup taken FIRST, nothing is lost without a backup"
    menu_top; menu_head "Factory Reset"; menu_sep
    menu_item "1) Full Factory Reset (settings + channels + emu config)"; menu_item "2) Settings only (keep channels)"
    menu_bot; footer_back
    printf "Your choice: "; read _FR || return 0
    case "$_FR" in
      1|2) printf "Type YES / y to confirm Factory Reset: "; read _FR_Y
           is_yes "$_FR_Y" || { echo "Cancelled"; continue; }
           _FR_BK="${UPANEL_ROOT:-/media/hdd/U-Panel}/FactoryReset-Backup-$(date +%Y%m%d_%H%M%S)"
           mkdir -p "$_FR_BK" || { echo "[ERROR] Cannot create backup dir"; continue; }
           cp -a /etc/enigma2/. "$_FR_BK/" 2>/dev/null
           mkdir -p "$_FR_BK/tuxbox_config" 2>/dev/null; cp -a /etc/tuxbox/config/. "$_FR_BK/tuxbox_config/" 2>/dev/null
           echo "   Backup: $_FR_BK"
           enigma_stop
           rm -f /etc/enigma2/settings
           if [ "$_FR" = "1" ]; then
             rm -f /etc/enigma2/lamedb /etc/enigma2/bouquets.tv /etc/enigma2/bouquets.radio /etc/enigma2/*.bouquet /etc/enigma2/userbouquet.* /etc/enigma2/timers.xml /etc/enigma2/autotimer.xml /etc/enigma2/epg.dat
             rm -rf /etc/tuxbox/config/*
           fi
           enigma_start
           ok "Factory Reset done - backup: $_FR_BK - re-run Setup to configure again"
           printf "Press ENTER to return... "; read _back ;;
      0) return 0 ;;
      *) wrong_choice ;;
    esac
  done
}
show_tools_menu() {
  while true; do
    show_banner
    menu_top; menu_head "Tools"; menu_sep
    menu_item "1) Change Password to root"; menu_item "2) Delete Old Password"; menu_item "3) Delete Crash Log"; menu_item "4) Delete All Emu"; menu_item "5) Delete Ncam Emu"; menu_item "6) Delete Oscam Emu"; menu_item "7) Remove All Config Files"; menu_item "8) Remove Emu and Config"; menu_item "9) Delete All Servers"; menu_item "10) Delete All Channels"; menu_item "11) Remove BootLogo"; menu_item "12) Abertis Astra"; menu_item "13) Remove Tuner Setting"; menu_item "14) Remove Xtreamity Playlist"; menu_item "16) Factory Reset"; menu_bot
    footer_back
    printf "Your choice: "; read _t || return 0
    case "$_t" in 1) tools_change_password ;; 2) tools_delete_password ;; 3) tools_delete_crashlog ;; 4) tools_delete_all_emu ;; 5) tools_delete_ncam ;; 6) tools_delete_oscam ;; 7) tools_remove_config ;; 8) tools_remove_emu_config ;; 9) tools_delete_servers ;; 10) tools_delete_channels ;; 11) tools_remove_bootlogo ;; 12) tools_abertis_astra ;; 13) tools_remove_tuner ;; 14) tools_remove_xtreamity ;; 15) tools_remove_jedi ;; 16) factory_reset_menu ;; 0) return 0 ;; *) wrong_choice ;; esac
  done
}
# V20.1 - Setup safety snapshot (BeforeSetup) - does NOT touch the main backup, so restore still uses the old backup
setup_snapshot() {
  _SS="$UPANEL_ROOT/BeforeSetup-$(date +%Y%m%d_%H%M%S)"
  mkdir -p "$_SS/tuxbox_config"
  cp -a /etc/enigma2/settings "$_SS/settings" 2>/dev/null
  cp -a /etc/enigma2/lamedb "$_SS/lamedb" 2>/dev/null
  cp -a /etc/enigma2/*.bouquet "$_SS/" 2>/dev/null
  cp -a /etc/tuxbox/config/. "$_SS/tuxbox_config/" 2>/dev/null
  ls /usr/lib/enigma2/python/Plugins/Extensions/ > "$_SS/plugins_extensions.txt" 2>/dev/null
  echo "$_SS"
}

# V20.1 - Channel List installers (Emil / Mnasr / Khaled / Hazem Wahba) - picked after Restore + BootLogo
install_channel_list() {
  case "$1" in
    emil)  secure_run "https://raw.githubusercontent.com/emilnabil/channel-emil-nabil/main/installer.sh" "channel-emil-installer.sh" ;;
    mnasr) secure_run "https://raw.githubusercontent.com/emilnabil/channel-mnasr/main/installer.sh" "channel-mnasr-installer.sh" ;;
    khaled) secure_run "https://raw.githubusercontent.com/emilnabil/channel-khaled/main/installer.sh" "channel-khaled-installer.sh" ;;
    hazem) secure_run "https://raw.githubusercontent.com/emilnabil/channel-hazem-wahba/main/installer.sh" "channel-hazem-installer.sh" ;;
    *) echo "Unknown channel list: $1" ;;
  esac
}

# V20.1 - Channel List picker - sets CHANNEL_SEL (emil|mnasr|khaled|hazem|none)
choose_channel_list() {
  echo ""; line; info "Channel List - Change channel list? (after Restore + BootLogo)"
  echo "  1) Emil Nabil channel list"
  echo "  2) Mnasr channel list"
  echo "  3) Khaled channel list"
  echo "  4) Hazem Wahba channel list"
  echo "  0) No - keep current channel list"
  printf "Your choice: "; read _ch || return 0
  case "$_ch" in
    1) CHANNEL_SEL="emil" ;;
    2) CHANNEL_SEL="mnasr" ;;
    3) CHANNEL_SEL="khaled" ;;
    4) CHANNEL_SEL="hazem" ;;
    *) CHANNEL_SEL="none"; echo "Channel list unchanged - keeping current channels" ;;
  esac
  if [ "$CHANNEL_SEL" != "none" ]; then echo "Installing channel list: $CHANNEL_SEL..."; install_channel_list "$CHANNEL_SEL"; fi
}

# V20.1 - Setup restore picker: ask y/n per category, run chosen restores, record codes in RESTORE_SEL
setup_restore_picker() {
  RESTORE_SEL=""
  ensure_files_backup_extracted
  if [ ! -d "$BKDIR" ]; then echo "[INFO] No Files backup found ($BKDIR) - restore skipped - do Backup first"; return 1; fi
  echo ""; line; info "Restore Files - pick categories to restore (from backup: $BKDIR)"
  for _cat in "all:Files - All (full files restore)" "channels:Channels Only (bouquets+lamedb)" "skin:Skin" "emu:Emu (Oscam config + binaries)" "keys:Keys (autosub/groqapi)" "network:Network (hostname/resolv/interfaces)" "bootlogo:BootLogo Auto"; do
    _code="${_cat%%:*}"; _desc="${_cat#*:}"
    printf "Restore %s ? (y/n): " "$_desc"; read _ry
    case "$_ry" in y|Y) RESTORE_SEL="$RESTORE_SEL $_code" ;; *) echo "  Skipped: $_desc" ;; esac
  done
  echo "Restore selection: ${RESTORE_SEL:-none}"
  run_recorded_restore "$RESTORE_SEL"
}

# V20.1 - Run recorded restore codes (space-separated): all channels skin emu keys network bootlogo (picons REMOVED)
run_recorded_restore() {
  _codes="$1"
  [ -z "$_codes" ] && { echo "Restore: none selected - skipped"; return 0; }
  for _c in $_codes; do
    case "$_c" in
      n|none) ;;
      all) restore_files_setup ;;
      channels) selective_restore_channels ;;
      skin) selective_restore_skin ;;
      emu) selective_restore_emu ;;
      keys) selective_restore_keys ;;
      network) selective_restore_network ;;
      bootlogo) selective_restore_bootlogo ;;
      *) echo "Unknown restore code: $_c" ;;
    esac
  done
}

# V20.1 - Run recorded channel (emil|mnasr|khaled|hazem|none)
run_recorded_channel() {
  if [ "$1" = "none" ] || [ -z "$1" ]; then echo "Channel list unchanged - keeping current channels"; return 0; fi
  echo "Installing recorded channel list: $1..."
  install_channel_list "$1"
}

save_favourite() {
  # Args: 1=plugins 2=channel(emil|mnasr|khaled|hazem|none) 3=restore(space-separated codes, or n) 4=bootlogo 5=fullbackup
  echo "# U-Panel Favourite - Saved from Setup your Enigma - Group $BK" > "$FAV_FILE"
  echo "FAV_DATE=\"$(date)\"" >> "$FAV_FILE"; echo "FAV_BOX=\"$BOX\"" >> "$FAV_FILE"; echo "FAV_IMAGE=\"$IMAGE\"" >> "$FAV_FILE"; echo "FAV_GROUP=\"$BK\"" >> "$FAV_FILE"; echo "FAV_PLUGINS=\"$1\"" >> "$FAV_FILE"; echo "FAV_CHANNEL=\"$2\"" >> "$FAV_FILE"; echo "FAV_RESTORE=\"$3\"" >> "$FAV_FILE"; echo "FAV_BOOTLOGO=\"$4\"" >> "$FAV_FILE"; echo "FAV_BOOTLOGO_AUTO=\"yes\"" >> "$FAV_FILE"; echo "FAV_ABERTIS=\"yes\"" >> "$FAV_FILE"; echo "FAV_FULLBACKUP=\"${5:-n}\"" >> "$FAV_FILE"
  ok "Favourite Saved: $FAV_FILE"; echo "  Plugins: $1"; echo "  Channel: $2"; echo "  Restore: $3"; echo "  BootLogo: $4"; echo "  FullBackup: ${5:-n}"; echo "  Group: $BK"
}
# V5.90 - Image Build with Essentials: plugin NUMBERS (same numbering as PLUGINS_WEB / install_plugin_by_num - installers pick per image + Python themselves).
# User-sent essentials list - installed in this exact order by Image Build with Essentials.
# USER LIST (confirmed): 19 LukaTV, 47 LukaConnect, 34 SubExtractorLite, 42 ServerColoring-Fury, 22 Aglare, 41 MohamedStore, 39 Chromium, 37 JediMakerXtream, 29 netusagepro, 26 auto-dcw-key-add, 24 NewVirtualKeyBoard, 21 ipaudiplus, 20 novalerStore, 18 FootOnsat, 17 buttonpatcher, 16 SimplySports, 15 ArabicSavior, 11 crashlogviewer, 10 customchannelselection, 7 IPAudioPro, 5 internet-speedtest, 1 MyStreamer, + 3 AJPanel, 4 SubsSupportPro + 6 EmuInstaller, 8 Epg-Grabber, 32 oscam-by-lenuxsat, 33 AutoSub (added later).
ESSENTIALS_PLUGINS="19 47 34 42 22 41 39 37 29 26 24 21 20 18 17 16 15 11 10 7 5 1 3 4 6 8 32 33"
image_build_essentials() {
  # $1 = mode: "" = Terminal, "web" = Web UI job
  setup_reboot_guard "Image Build with Essentials"
  show_banner; line; info "Image Build with Essentials - Packages -> Essentials Plugins -> BootLogo Auto -> Khalid Ali Channel List -> ONE Reboot at the END only - Reboot Guard V4 ON"
  echo "Image: $IMAGE | Box: $BOX | Python: $PY_MM"
  echo "Essentials plugins: $ESSENTIALS_PLUGINS"
  echo "BootLogo: Auto by image + device | Channel list: khaled (Khalid Ali)"
  if [ "$1" != "web" ]; then printf "Press ENTER to start Image Build with Essentials - or 0 to go back: "; read _go; [ "$_go" = "0" ] && return 0; fi
  check_hdd_space "Image Build with Essentials" || return 1
  setup_reboot_guard "Image Build - Running"
  migrate_setup_cache
  SETUP_BATCH=1
  line; info "Step 0 - Safety Snapshot (BeforeSetup) - Reboot Guard V4 ON"
  _SSNAP=$(setup_snapshot); echo "Safety snapshot: $_SSNAP"
  line; info "Step 1 - Packages (package commands) - Reboot Guard V4 ON"; install_packages
  line; info "Step 2 - Essentials Plugins: $ESSENTIALS_PLUGINS - Reboot Guard V4 ON"
  for n in $ESSENTIALS_PLUGINS; do install_plugin_by_num $n; done; ok "Essentials Plugins Installed - No Reboot"
  line; info "Step 3 - BootLogo Auto - Image: $IMAGE -> $(get_bootlogo_by_image) - Reboot Guard V4 ON"; install_bootlogo_auto
  line; info "Step 4 - Channel List: khaled (Khalid Ali) - Enigma stopped (Bypass)"
  selective_stop_enigma
  run_recorded_channel "khaled"
  SETUP_BATCH=0
  echo ""; line; echo "Image Build with Essentials Done - ALL steps finished - Rebooting NOW (first and only reboot)"
  if [ "$1" = "web" ]; then echo "Receiver will reboot in 8 seconds - you can close this page."; (sleep 8; /sbin/reboot) >/dev/null 2>&1 & else echo "Rebooting now..."; /sbin/reboot; fi
}
favourite_setup() {
  setup_reboot_guard "Ur Favourite Setup"
  show_banner; line; info "Ur Favourite Setup - Auto: Runs Recorded Setup your Enigma Steps - Reboot Guard V4 ON - SMART: installers replay from Setup-Cache if net fails"
  if [ ! -f "$FAV_FILE" ]; then echo "[ERROR] No Favourite Found!"; echo "Run Setup your Enigma first - to save your choices"; echo "File not found: $FAV_FILE"; echo "Available:"; ls -l $UPANEL_ROOT-Favourite* 2>/dev/null; printf "Press ENTER... "; read _back; return 0; fi
  if grep -qv -E '^(FAV_[A-Z_]+=|#|$)' "$FAV_FILE"; then echo "[ERROR] Favourite file has unexpected lines - refusing to load (V20 safety)"; printf "Press ENTER... "; read _back; return 0; fi
  # V35: Favourite replays installers (reads cache, may re-save) - same space guard.
  check_hdd_space "Ur Favourite Setup" || return 1
  . "$FAV_FILE"
  echo "Favourite Found - Date: $FAV_DATE"; echo "Saved Box: $FAV_BOX | Saved Image: $FAV_IMAGE"; echo "Current Box: $BOX | Current Image: $IMAGE"; echo "Plugins: $FAV_PLUGINS"; echo "Restore: ${FAV_RESTORE:-none} | Channel: ${FAV_CHANNEL:-none}"; echo "BootLogo: $FAV_BOOTLOGO | FullBackup: $FAV_FULLBACKUP"
  echo "Will run recorded steps: Safety Snapshot -> Packages -> Plugins ($FAV_PLUGINS) -> Restore ($FAV_RESTORE) -> BootLogo Auto -> Channel ($FAV_CHANNEL) -> Full Backup ($FAV_FULLBACKUP)"
  printf "Press ENTER to start Ur Favourite Setup - or 0 to go back: "; read _go; [ "$_go" = "0" ] && return 0
  setup_reboot_guard "Favourite - Running"
  migrate_setup_cache
  SETUP_BATCH=1
  line; info "Favourite Step 0 - Safety Snapshot (BeforeSetup) - Reboot Guard V4 ON"
  _SSNAP=$(setup_snapshot); echo "Safety snapshot: $_SSNAP"
  line; info "Favourite Step 1 - Packages - Reboot Guard V4 ON"; install_packages
  line; info "Favourite Step 2 - Plugins: $FAV_PLUGINS - Reboot Guard V4 ON"
  if [ -n "$FAV_PLUGINS" ] && [ "$FAV_PLUGINS" != "none" ]; then if [ "$FAV_PLUGINS" = "all" ]; then install_all_plugins; else for n in $FAV_PLUGINS; do install_plugin_by_num $n; done; fi; ok "Favourite Plugins Installed - No Reboot"; fi
  line; info "Favourite Step 3 - Restore Files (recorded): ${FAV_RESTORE:-none} - Reboot Guard V4 ON"
  if [ -n "$FAV_RESTORE" ] && [ "$FAV_RESTORE" != "n" ] && [ "$FAV_RESTORE" != "none" ]; then run_recorded_restore "$FAV_RESTORE"; else echo "Restore: none recorded - skipped"; fi
  line; info "Favourite Step 4 - BootLogo Auto - Image: $IMAGE -> $(get_bootlogo_by_image) - Reboot Guard V4 ON"; install_bootlogo_auto
  line; info "Favourite Step 5 - Channel List: ${FAV_CHANNEL:-none} - Enigma stopped (Bypass)"
  selective_stop_enigma
  run_recorded_channel "${FAV_CHANNEL:-none}"
  case "$FAV_FULLBACKUP" in y|Y) echo "Recorded FullBackup = y - Running Full Image Backup..."; backup_full_image ;; *) echo "Recorded FullBackup = n - Skipped" ;; esac
  SETUP_BATCH=0
  echo ""; line; echo "Ur Favourite Setup Done - No Reboot - No Restart"
  ask_retrieve_enigma
  printf "Press ENTER to return to Main Menu... "; read _rb; return 0
}
setup_your_enigma() {
  setup_reboot_guard "Setup your Enigma"
  show_banner; line; info "Setup your Enigma - Safety Snapshot -> Packages -> Plugins -> Restore Files -> BootLogo Auto -> Channel List - Reboot Guard V4 ON - SMART: every installer is cached to Setup-Cache as it runs"
  echo "Steps: 0) Safety Snapshot (BeforeSetup)  1) Packages  2) Plugins (you choose)  3) Restore Files (you pick categories)  4) BootLogo Auto  5) Channel List (Enigma stopped)"
  echo "Your choices will be saved in Ur Favourite Setup - Restore lives in Setup + Full Restore"
  printf "Press ENTER to start Setup your Enigma - or 0 to go back: "; read _go; [ "$_go" = "0" ] && return 0
  # V35: Setup records installers into Setup-Cache as it runs - same space guard as Backup/Cache.
  check_hdd_space "Setup your Enigma" || return 1
  setup_reboot_guard "Setup - Running"
  migrate_setup_cache; echo "[SETUP-CACHE] This image cache: $(setup_cache_dir)/installers/ (per IMAGE + Python)"
  SETUP_BATCH=1
  SELECTED_ALL=""; FAV_PLUGINS_SEL="none"; FAV_BOOTLOGO_SEL="Auto"; FAV_FULLBACKUP_SEL="n"; FAV_CHANNEL_SEL="none"; RESTORE_SEL=""
  line; info "Step 0 - Safety Snapshot (BeforeSetup) - Reboot Guard V4 ON"
  _SSNAP=$(setup_snapshot); echo "Safety snapshot: $_SSNAP"
  line; info "Step 1 - Packages - Reboot Guard V4 ON"; install_packages; echo ""; echo "Packages Done - No Reboot"; printf "Press ENTER to Continue to Plugins Categories... "; read _c1
  show_plugins_menu; FAV_PLUGINS_SEL="$SELECTED_ALL"
  if [ -z "$FAV_PLUGINS_SEL" ]; then echo "No Plugins Selected - Returning to Main Menu"; SETUP_BATCH=0; return 0; fi
  echo ""; printf "Press ENTER to Continue to Restore Files... "; read _c2
  setup_restore_picker
  echo ""; printf "Press ENTER to Continue to BootLogo Auto... "; read _c3
  show_banner; line; info "Step - BootLogo Auto - Image: $IMAGE -> $(get_bootlogo_by_image) - Reboot Guard V4 ON"
  echo "Installing BootLogo Auto - No Prompt - By Your Image..."; install_bootlogo_auto; FAV_BOOTLOGO_SEL="Auto"
  # Channel List while Enigma is CLOSED (Bypass: stop Enigma, pick channel, then start at end)
  line; info "Step - Channel List - Enigma stopped (Bypass) - pick channel file"
  selective_stop_enigma
  choose_channel_list; FAV_CHANNEL_SEL="$CHANNEL_SEL"
  printf "Do Full Image Backup now? (y/n): "; read _fb; case "$_fb" in y|Y) FAV_FULLBACKUP_SEL="y"; backup_full_image ;; *) FAV_FULLBACKUP_SEL="n"; echo "Full Backup Skipped" ;; esac
  echo "[SETUP-CACHE] All installers executed in this Setup are cached in: $(setup_cache_dir)/installers/ - Ur Favourite Setup will replay from there if net fails"
  save_favourite "$FAV_PLUGINS_SEL" "$FAV_CHANNEL_SEL" "$RESTORE_SEL" "$FAV_BOOTLOGO_SEL" "$FAV_FULLBACKUP_SEL"
  SETUP_BATCH=0
  echo ""; line; echo "Setup your Enigma Done - Favourite Saved - BootLogo Auto Done - No Reboot - No Restart"
  ask_retrieve_enigma
  printf "Press ENTER to return to Main Menu... "; read _rb; return 0
}
show_summary() { line; echo "Summary - U-Panel V20"; echo "Box: $BOX | Image: $IMAGE | Group: $BK | BackupRoot: $BACKUP_ROOT"; if [ -f /tmp/upanel_last_result ]; then cat /tmp/upanel_last_result; else echo "No restore run in this session - see $LOG"; fi; echo "Log: $LOG"; line; }



show_banner; echo ""; echo "Box: $BOX"; echo "Image: $IMAGE"; echo "Python: $PYTHON_V - Folder Python: $PY_MM"; echo "Aglare: $AGLARE"; echo "Backup Group: $BK"; echo "Backup Folder: $BKDIR"; echo "Reboot Guard: V4 ON"; echo ""; line; echo "Press ENTER To Continue  |  Press e to End"; line; if [ -t 0 ]; then printf "Your choice: "; read _start || return 0; [ "$_start" = "e" ] && exit 0; fi

# --- PERSONAL WRAPPERS - reuse original functions verbatim ---
personal_setup() {
  setup_your_enigma
}
# V4.26: U-Panel Setting gains 5) UI Style + 6) UI Color - Style: Premium/Classic/Compact/Minimal (banner + menu shapes), Color: Gold/Blue/Green/Red/Purple/Mono (palette on any Style), saved in /etc/u-panel-ui.conf, preview after every pick
# V4.25: one central confirm helper - ANY yes-like answer counts: YES / Yes / yes / y / Y (spaces ignored)
confirm_word() { _CW=$(echo "$1" | tr -d '[:space:]' | tr 'A-Z' 'a-z'); [ "$_CW" = "$2" ]; }
is_yes() { confirm_word "$1" "yes" || confirm_word "$1" "y"; }
full_restore() {
  setup_reboot_guard "Full Restore"
  # V23.0 CACHE-DIAG-FIX: (1) BusyBox od -A unsupported -> python3 magic check, (2) opkg files on OpenATV has NO leading space -> parse ^/ lines, (3) FootOnSat via secure_fetch 3 tries + curl fallback, (4) cache logs opkg update rc + one sample download error.
# V22.9 NO-BACKUP-SUBMENU: Backup submenu removed. Main menu: 5) Backup Ur Data (= old All), 6) Backup Ur Files (= files only). Renumbered 7-12.
# V22.8 RENAME: Full Restore -> Smart Restore, Custom Restore -> Custom Restore, no parenthetical text beside them.
# V22.7 DREAMOS-APT: DreamOS/apt Tier 4 - apt download + dpkg-repack rebuild .deb, offline_install_pkg handles .deb via dpkg.
# V22.6 CACHE-MISS-FIX: cache_offline_assets 3-tier (download -> download-only --force-reinstall -> rebuild .ipk from installed pkg). Fixes CACHE-MISS for already-installed / feed-missing packages.
# V22.5 SETUP-CACHE-PER-IMAGE: Setup-Cache + Hash-Pin per IMAGE + Python (like Backup-Cache), auto-migrate old Group cache.
# V22.4 SMART-ALL: Custom Restore + Setup-Cache (every secure_run installer cached at Setup time, Favourite replays from cache if net fails) + Files Oscam Smart.
# V22.3 SMART-RESTORE: renamed Smart Restore -> Smart Restore. Same unified logic.
# V22.2 SMART-RESTORE: do NOT force OFFLINE_MODE - try ONLINE first, each step falls back to cache on its own if net fails.
  if offline_is_on; then echo "[OFFLINE] Smart Restore - OFFLINE - ZERO net calls - cache only"; else echo "[SMART] Smart Restore - ONLINE first, cache fallback per-step if net fails"; fi
  show_banner; line; info "Smart Restore - Packages -> Plugins + Extras -> Files -> BootLogo Auto (END) - Online first, cache fallback"
  echo "Restore Order (AUTO, no mid prompts): 1) Packages  2) Plugins + Force Tarball + Verify + FootOnSat  3) Files (verify)  4) BootLogo Auto - END"
  printf "Press ENTER to start Full Restore AUTO - or 0 to go back: "; read _go; [ "$_go" = "0" ] && return 0
  FULL_AUTO=1
  # V30: Smart Restore has its OWN cache - pre-fill Offline-Cache (packages + FootOnSat + BootLogo) while online,
  # so if net drops mid-restore, Packages/FootOnSat fall back to cache instead of failing.
  if ! offline_is_on; then
    PLUGINS_BKDIR="$(get_plugins_backup_dir)"
    _OC_HAS="$(ls "$(offline_cache_dir)/packages/"*.ipk "$(offline_cache_dir)/packages/"*.deb 2>/dev/null | wc -l)"
    if [ "$_OC_HAS" = "0" ]; then echo "[SMART-CACHE] Offline-Cache empty - preloading Packages + FootOnSat + BootLogo (online, once)..."; cache_offline_assets; else echo "[SMART-CACHE] Offline-Cache ready: $_OC_HAS packages cached"; fi
  else echo "[SMART-CACHE] OFFLINE mode - using existing Offline-Cache only, no downloads"; fi
  line; info "Full Restore Step 1/4 - Packages (AUTO)"; install_packages
  line; info "Full Restore - Stopping Enigma ONCE for Plugins + Files"; /sbin/init 4 2>/dev/null || /usr/sbin/init 4 2>/dev/null || /bin/init 4 2>/dev/null; sleep 3; /usr/bin/killall -9 enigma2 2>/dev/null || /bin/killall -9 enigma2 2>/dev/null; sleep 2
  line; info "Full Restore Step 2-3/4 - Restore Plugins then Files (Plugins First, AUTO)"
  restore_plugins_then_files
  _FULL_RC=$?
  echo "Full Restore rc=$_FULL_RC - plugins_verify=${PLUGINS_VERIFY_RC:-?}" > /tmp/upanel_last_result
  if [ "$_FULL_RC" != "0" ]; then echo "Full Restore stopped early (rc=$_FULL_RC) - Enigma left as you chose, BootLogo skipped"; FULL_AUTO=0; printf "Press ENTER to return... "; read _back; return $_FULL_RC; fi
  line; info "Full Restore Step 4/4 - BootLogo Auto - Image: $IMAGE -> $(get_bootlogo_by_image) - END"; install_bootlogo_auto
  if offline_is_on; then echo "[OFFLINE] Abertis skipped (needs net)"; elif ! check_net 2>/dev/null; then echo "[SMART-FALLBACK] Abertis skipped (no net - cache has no Abertis)"; else tools_abertis_astra auto; fi
  write_unified_report
  show_summary; echo "Full Restore Done - AUTO - Ended after BootLogo - No Reboot"
  OFFLINE_MODE=0
  FULL_AUTO=0
  ask_retrieve_enigma
  printf "Press ENTER to return to Main Menu... "; read _back; return 0
}
packages_only_menu() {
  show_banner; line; info "Packages Only - install system packages, no Plugins / Files / BootLogo"
  printf "Press ENTER to install Packages - or 0 to go back: "; read _go; [ "$_go" = "0" ] && return 0
  install_packages
  echo "Packages Only Done"
  printf "Press ENTER to return... "; read _back; return 0
}
