  full_restore
}

# V23.1 BOOT SLOT MANAGER: Show / Switch / Backup Current Slot / Restore to Slot.
# SAFETY: restore writes to the RUNNING system only - restoring to another slot means:
# Switch to that slot + reboot FIRST, then Restore there. Never pretend to write to a non-running slot.
current_boot_slot() {
  # Novaler truth: /proc/cmdline has root=/dev/mmcblk0p23 rootsubdir=linuxrootfs<N>
  # (slots 1-4 share one partition, each in its own subdir) or root=/dev/mmcblk1p<N>
  # (SD slots 6/7). The STARTUP_LINUX_<N> whose bootargs carry the SAME root+subdir is current.
  _CR=$(grep -oE 'root=/dev/[^ ]+' /proc/cmdline 2>/dev/null | head -1)
  _CSUB=$(grep -oE 'rootsubdir=[^ ]+' /proc/cmdline 2>/dev/null | head -1)
  for _SF in /boot/STARTUP_LINUX_[0-9]*; do
    [ -f "$_SF" ] || continue
    _BA=$(grep '^bootargs=' "$_SF" 2>/dev/null)
    case "$_BA" in *"$_CR"*)
      if [ -n "$_CSUB" ]; then case "$_BA" in *"$_CSUB"*) echo "$_SF" | grep -oE '[0-9]+$' | head -1; return 0;; esac
      else echo "$_SF" | grep -oE '[0-9]+$' | head -1; return 0; fi ;;
    esac
  done
  # Fallback: rootsubdir number straight from cmdline
  _N=$(echo "$_CSUB" | grep -oE '[0-9]+$' | head -1); [ -n "$_N" ] && { echo "$_N"; return 0; }
  if [ -f /boot/STARTUP ]; then
    for _SF in /boot/STARTUP_LINUX_[0-9]*; do [ -f "$_SF" ] || continue; cmp -s /boot/STARTUP "$_SF" 2>/dev/null && { echo "$_SF" | grep -oE '[0-9]+$' | head -1; return 0; }; done
  fi
  echo "?"
}
# ============================================================
# BOOT SLOT MANAGER - rebuilt from scratch (V23.2)
# One prefix: upanel_*. NO persistent cache: every read is fresh,
# so a slot can never stay stuck on a stale "Empty".
#
# Layout (Novaler Multibox Pro, learned from the box itself):
#   eMMC mmcblk0 : slots 1-4 share ONE rootfs partition,
#                  subdirs linuxrootfs1..linuxrootfs4
#   SD   mmcblk1 : slots 6+ have their OWN partition each,
#                  LABEL=linux6, linux7, ...
#   Boot partition: FAT, holds STARTUP_LINUX_N. /boot is
#   often NOT mounted by the running image -> we find it
#   by scanning partitions and verifying rootsubdir.
# Names: /etc/image-version inside each slot rootfs,
#   read with debugfs (no mount needed).
# ============================================================

# --- find + mount the real boot partition (FAT, STARTUP files) ---
upanel_boot_mount() {
  grep -qs " /boot " /proc/mounts && return 0
  mkdir -p /boot 2>/dev/null
  _CURSUB=$(grep -oE 'rootsubdir=[^ ]+' /proc/cmdline 2>/dev/null | cut -d= -f2)
  _CURSLOT=$(echo "$_CURSUB" | grep -oE '[0-9]+$')
  _CANDS=""
  for _d in $(blkid 2>/dev/null | grep -iE 'LABEL="(boot|BOOT)"' | cut -d: -f1); do
    case " $_CANDS " in *" $_d "*) ;; *) _CANDS="$_CANDS $_d";; esac
  done
  for _d in /dev/block/by-name/boot* /dev/block/by-name/BOOT* /dev/mmcblk0p* /dev/mmcblk1p* /dev/mmcblk2p* /dev/sda* /dev/sdb* /dev/sdc* /dev/mmcblk0boot0 /dev/mmcblk0boot1; do
    [ -b "$_d" ] || continue
    case " $_CANDS " in *" $_d "*) ;; *) _CANDS="$_CANDS $_d";; esac
  done
  # V6.20 FIX: try the BOOT partition of the disk we booted from FIRST.
  # The bootloader reads STARTUP from there at power-on (Recovery + Multiboot
  # selection). Old order was blkid order - with SD/USB inserted, /boot could
  # mount from the EXTERNAL disk, hiding the internal flash slots.
  _BROOTSRC=$(awk '$2 == "/" {print $1; exit}' /proc/mounts 2>/dev/null)
  if [ "$_BROOTSRC" = "/dev/root" ] || [ -z "$_BROOTSRC" ]; then _BROOTSRC=$(grep -oE 'root=/dev/[^ ]+' /proc/cmdline 2>/dev/null | cut -d= -f2 | head -1); fi
  _BROOTDISK="${_BROOTSRC#/dev/}"; case "$_BROOTDISK" in mmcblk*|nvme*) _BROOTDISK="${_BROOTDISK%%p*}";; *) _BROOTDISK="${_BROOTDISK%%[0-9]*}";; esac
  _BSEP=""; case "$_BROOTDISK" in mmcblk*|nvme*) _BSEP="p";; esac
  _BROOTBP="/dev/${_BROOTDISK}${_BSEP}1"
  if [ -b "$_BROOTBP" ]; then case " $_CANDS " in *" $_BROOTBP "*) ;; *) _CANDS="$_BROOTBP $_CANDS";; esac; fi
  _FALLBACK=""
  for _CAND in $_CANDS; do
    # V6.20 FIX (26 Nov): only vfat can be a BOOT partition. The old code tried
    # EVERY partition (ext4 slots, exfat storage) - the fallback `mount -o ro`
    # mounted exfat via FUSE, whose daemon printed "FUSE exfat 1.4.0 (libfuse2)"
    # into the log, and briefly mounted a storage partition onto /boot. Skip
    # slot partitions (LABEL=linuxN) and any known non-vfat filesystem.
    _CT=$(blkid "$_CAND" 2>/dev/null | grep -o 'TYPE="[^"]*"' | cut -d'"' -f2)
    _CL=$(blkid "$_CAND" 2>/dev/null | grep -o 'LABEL="[^"]*"' | cut -d'"' -f2)
    case "$_CL" in linux*) continue;; esac
    case "$_CT" in vfat|fat12|fat16|fat32|msdos|"") ;; *) continue;; esac
    _MERR=$(mount -t vfat -o ro "$_CAND" /boot 2>&1) || _MERR=$(mount -o ro "$_CAND" /boot 2>&1) || { echo "[BOOT-MOUNT] $_CAND: mount failed: $_MERR"; continue; }
    if grep -qs " /boot " /proc/mounts; then
      _OK=0
      if [ -n "$_CURSLOT" ]; then
        for _sf in "/boot/STARTUP_LINUX_$_CURSLOT" "/boot/STARTUP_$_CURSLOT"; do
          [ -f "$_sf" ] && { _OK=2; break; }
        done
      fi
      if [ "$_OK" = "0" ]; then
        for _sf in /boot/STARTUP_LINUX_* /boot/STARTUP_* /boot/STARTUP; do
          [ -f "$_sf" ] && { _OK=1; break; }
        done
      fi
      if [ "$_OK" = "0" ]; then
        ls /boot/uImage* /boot/zImage* /boot/kernel* /boot/Image* /boot/*.dtb >/dev/null 2>&1 && _OK=1
      fi
      if [ "$_OK" = "2" ]; then echo "[BOOT-MOUNT] /boot = $_CAND (holds running SLOT $_CURSLOT STARTUP)"; mount -o remount,rw /boot >/dev/null 2>&1; return 0; fi
      if [ "$_OK" = "1" ]; then [ -z "$_FALLBACK" ] && _FALLBACK="$_CAND"; fi
      umount /boot >/dev/null 2>&1
    fi
  done
  if [ -n "$_FALLBACK" ]; then
    mount -o ro "$_FALLBACK" /boot >/dev/null 2>&1 && { echo "[BOOT-MOUNT] WARNING: /boot = $_FALLBACK (has STARTUP files, but not for running SLOT $_CURSLOT)"; mount -o remount,rw /boot >/dev/null 2>&1; grep -qs " /boot " /proc/mounts && return 0; }
  fi
  echo "[BOOT-MOUNT] FAIL: no boot partition found - tried:$_CANDS"
  return 1
}

# --- current slot number (from kernel cmdline) ---
upanel_current() {
  _S=$(grep -oE 'rootsubdir=[^ ]+' /proc/cmdline 2>/dev/null | cut -d= -f2 | grep -oE '[0-9]+$')
  [ -n "$_S" ] && { echo "$_S"; return 0; }
  _S=$(grep -oE 'boot_slot=[^ ]+' /proc/cmdline 2>/dev/null | cut -d= -f2)
  [ -n "$_S" ] && { echo "$_S"; return 0; }
  # V4.3 fallback: /boot/STARTUP is the active slot (symlink or copy of STARTUP_LINUX_N)
  # cmdline on some images carries neither rootsubdir nor boot_slot - without this, current slot was "?"
  if [ -f /boot/STARTUP ]; then
    _RL=$(readlink /boot/STARTUP 2>/dev/null)
    _S=$(echo "$_RL" | grep -oE '[0-9]+$')
    [ -n "$_S" ] && { echo "$_S"; return 0; }
    for _F in /boot/STARTUP_LINUX_*; do
      [ -f "$_F" ] || continue
      if cmp -s "$_F" /boot/STARTUP; then _S=$(basename "$_F" | grep -oE '[0-9]+$'); [ -n "$_S" ] && { echo "$_S"; return 0; }; fi
    done
  fi
  echo "?"
}

# --- all known slots, sorted, unique ---
upanel_slots() {
  _SL=""
  _SHARED=$(grep -oE 'root=/dev/[^ ]+' /proc/cmdline 2>/dev/null | cut -d= -f2 | head -1)
  [ -z "$_SHARED" ] && _SHARED=$(grep " / " /proc/mounts 2>/dev/null | awk '{print $1}' | head -1)
  if [ -n "$_SHARED" ] && [ ! -b "$_SHARED" ]; then
    _RESOLVED=$(readlink -f "$_SHARED" 2>/dev/null)
    [ -n "$_RESOLVED" ] && [ -b "$_RESOLVED" ] && _SHARED="$_RESOLVED"
  fi
  # eMMC slots: subdirs on the shared rootfs partition (debugfs ls, no mount, no /boot)
  if [ -n "$_SHARED" ] && [ -b "$_SHARED" ] && command -v debugfs >/dev/null 2>&1; then
    for _n in $(debugfs -R "ls /" "$_SHARED" 2>/dev/null | grep -oE 'linuxrootfs[0-9]+' | grep -oE '[0-9]+'); do
      case " $_SL " in *" $_n "*) ;; *) _SL="$_SL $_n";; esac
    done
  fi
  # SD slots: partitions with LABEL=linuxN
  # (the old code used grep -oE '[0-9]+$' which NEVER matched - the line ends with a quote: LABEL="linux6")
  for _n in $(blkid 2>/dev/null | grep -oE 'LABEL="linux[0-9]+"' | grep -oE '[0-9]+'); do
    case " $_SL " in *" $_n "*) ;; *) _SL="$_SL $_n";; esac
  done
  # STARTUP files (only if /boot happens to be mounted)
  for _f in /boot/STARTUP_LINUX_* /boot/STARTUP_*; do
    [ -f "$_f" ] || continue
    _n=$(basename "$_f" | grep -oE '[0-9]+$')
    [ -n "$_n" ] && case " $_SL " in *" $_n "*) ;; *) _SL="$_SL $_n";; esac
  done
  [ -z "$_SL" ] && _SL="1 2 3 4"
  echo "$_SL" | tr ' ' '\n' | grep -E '^[0-9]+$' | sort -n | uniq | tr '\n' ' ' | sed 's/ *$//'
}

# --- root device + subdir for a slot. Prints: DEV|SUBDIR (SUBDIR may be empty) ---
upanel_root() {
  _SN="$1"; _RP=""; _SUB=""
  # SD slots: own partition with LABEL=linuxN
  _RP=$(blkid 2>/dev/null | grep "LABEL=\"linux$_SN\"" | cut -d: -f1 | head -1)
  if [ -n "$_RP" ]; then echo "$_RP|"; return 0; fi
  # V4.4: STARTUP_LINUX_N is authoritative for THIS slot - its root= + rootsubdir=
  # are exactly what the slot boots. The old code assumed subdir linuxrootfsN and
  # ignored STARTUP, so slots whose real subdir differs (1-4 on some layouts)
  # were looked up in a folder that does not exist -> no-image-version.
  if [ -f "/boot/STARTUP_LINUX_$_SN" ]; then
    _RP=$(grep -oE 'root=/dev/[^ ]+' "/boot/STARTUP_LINUX_$_SN" 2>/dev/null | cut -d= -f2 | head -1)
    _SUB=$(grep -oE 'rootsubdir=[^ ]+' "/boot/STARTUP_LINUX_$_SN" 2>/dev/null | cut -d= -f2 | head -1)
    if [ -n "$_RP" ]; then echo "$_RP|$_SUB"; return 0; fi
  fi
  # eMMC slots: shared rootfs partition (the one we booted from) + subdir linuxrootfsN
  _SHARED=$(grep -oE 'root=/dev/[^ ]+' /proc/cmdline 2>/dev/null | cut -d= -f2 | head -1)
  [ -z "$_SHARED" ] && _SHARED=$(grep " / " /proc/mounts 2>/dev/null | awk '{print $1}' | head -1)
  if [ -n "$_SHARED" ] && [ ! -b "$_SHARED" ]; then
    _RESOLVED=$(readlink -f "$_SHARED" 2>/dev/null)
    [ -n "$_RESOLVED" ] && [ -b "$_RESOLVED" ] && _SHARED="$_RESOLVED"
  fi
  if [ -n "$_SHARED" ] && [ -e "$_SHARED" ]; then
    _RP="$_SHARED"; _SUB="linuxrootfs$_SN"
    echo "$_RP|$_SUB"; return 0
  fi
  # fallback: STARTUP file (only if /boot happens to be mounted)
  if [ -f "/boot/STARTUP_LINUX_$_SN" ]; then
    _RP=$(grep -oE 'root=/dev/[^ ]+' "/boot/STARTUP_LINUX_$_SN" 2>/dev/null | cut -d= -f2 | head -1)
    _SUB=$(grep -oE 'rootsubdir=[^ ]+' "/boot/STARTUP_LINUX_$_SN" 2>/dev/null | cut -d= -f2 | head -1)
  fi
  if [ -z "$_RP" ]; then
    for _c in /dev/block/by-name/rootfs$_SN /dev/block/by-name/rootfs_$_SN /dev/block/by-name/linux$_SN; do
      [ -e "$_c" ] && { _RP="$_c"; break; }
    done
  fi
  echo "$_RP|$_SUB"
}

# --- make sure debugfs exists (install once per 2 min if network works) ---
upanel_ensure_debugfs() {
  command -v debugfs >/dev/null 2>&1 && return 0
  if [ -f /tmp/upanel_e2fs_tried ]; then
    if [ -n "$(find /tmp/upanel_e2fs_tried -mmin +2 2>/dev/null)" ]; then rm -f /tmp/upanel_e2fs_tried; else return 1; fi
  fi
  touch /tmp/upanel_e2fs_tried
  if command -v opkg >/dev/null 2>&1; then
    opkg update >/dev/null 2>&1; opkg install e2fsprogs >/dev/null 2>&1
  elif command -v apt-get >/dev/null 2>&1; then
    apt-get update >/dev/null 2>&1; apt-get install -y e2fsprogs >/dev/null 2>&1
  else
    return 1
  fi
  command -v debugfs >/dev/null 2>&1
}

# --- read one field (distro= / version= / creator=) from image-version text ---
upanel_iv_field() {
  echo "$1" | grep -i "^$2=" | cut -d= -f2 | tr -d '"\r' | head -1
}

# --- image name for a slot. Fresh read every time, no cache. ---
upanel_name() {
  _SN="$1"; _NAME=""; _USLOT_WHY="no-root"
  # current slot: it IS the running system - no disk read needed
  if [ "$_SN" = "$(upanel_current)" ]; then _USLOT_WHY="ok"; echo "$_USLOT_WHY" > /tmp/upanel_why_$$ 2>/dev/null; echo "$IMAGE"; return 0; fi
  _RS=$(upanel_root "$_SN"); _RP="${_RS%%|*}"; _SUB="${_RS#*|}"
  upanel_ensure_debugfs
  # 1) STRATEGY A: root partition already mounted somewhere? Read from that mountpoint.
  if [ -n "$_RP" ] && [ -e "$_RP" ]; then
    _EM=$(grep -m1 "^$_RP " /proc/mounts 2>/dev/null | awk '{print $2}')
    if [ -n "$_EM" ] && [ "$_EM" != "/" ]; then
      _IVF="$_EM/etc/image-version"; [ -n "$_SUB" ] && _IVF="$_EM/$_SUB/etc/image-version"
      if [ -f "$_IVF" ]; then
        _D=$(grep -i '^distro=' "$_IVF" | cut -d= -f2 | tr -d '"\r' | head -1)
        _V=$(grep -i '^version=' "$_IVF" | cut -d= -f2 | tr -d '"\r' | head -1)
        _C=$(grep -i '^creator=' "$_IVF" | cut -d= -f2 | tr -d '"\r' | head -1)
        [ -n "$_D" ] && _NAME="$_D $_V"
        [ -z "$_NAME" ] && [ -n "$_C" ] && _NAME="$_C $_V"
      fi
      if [ -z "$_NAME" ]; then
        _ISF="$_EM/etc/issue"; [ -n "$_SUB" ] && _ISF="$_EM/$_SUB/etc/issue"
        [ -f "$_ISF" ] && _NAME=$(head -1 "$_ISF" | sed 's/ *\\.*//;s/ *$//')
      fi
    fi
  fi
  # 2) debugfs: read image-version without mounting
  if [ -z "$_NAME" ] && [ -n "$_RP" ] && [ -e "$_RP" ] && command -v debugfs >/dev/null 2>&1; then
    _DP="/etc/image-version"; [ -n "$_SUB" ] && _DP="/$_SUB/etc/image-version"
    _IV=$(debugfs -R "cat $_DP" "$_RP" 2>/dev/null)
    _D=$(upanel_iv_field "$_IV" distro); _V=$(upanel_iv_field "$_IV" version); _C=$(upanel_iv_field "$_IV" creator)
    [ -n "$_D" ] && _NAME="$_D $_V"
    [ -z "$_NAME" ] && [ -n "$_C" ] && _NAME="$_C $_V"
  fi
  # 3) mount read-only and read the file
  if [ -z "$_NAME" ] && [ -n "$_RP" ] && [ -e "$_RP" ]; then
    _MP="/tmp/upanel_rd"; mkdir -p "$_MP"
    if mount -o ro "$_RP" "$_MP" >/dev/null 2>&1; then
      _IVF="$_MP/etc/image-version"; [ -n "$_SUB" ] && _IVF="$_MP/$_SUB/etc/image-version"
      if [ -f "$_IVF" ]; then
        _D=$(grep -i '^distro=' "$_IVF" | cut -d= -f2 | tr -d '"\r' | head -1)
        _V=$(grep -i '^version=' "$_IVF" | cut -d= -f2 | tr -d '"\r' | head -1)
        _C=$(grep -i '^creator=' "$_IVF" | cut -d= -f2 | tr -d '"\r' | head -1)
        [ -n "$_D" ] && _NAME="$_D $_V"
        [ -z "$_NAME" ] && [ -n "$_C" ] && _NAME="$_C $_V"
      fi
      if [ -z "$_NAME" ]; then
        _ISF="$_MP/etc/issue"; [ -n "$_SUB" ] && _ISF="$_MP/$_SUB/etc/issue"
        [ -f "$_ISF" ] && _NAME=$(head -1 "$_ISF" | sed 's/ *\\.*//;s/ *$//')
      fi
      umount "$_MP" >/dev/null 2>&1
    fi
  fi
  # 4) last resort: distro name from the STARTUP file itself
  if [ -z "$_NAME" ] && [ -f "/boot/STARTUP_LINUX_$_SN" ]; then
    _NAME=$(grep -oiE 'OpenATV|OpenPLi|OpenViX|EGAMI|OpenBh|Pure2|OpenDroid|TeamBlue|OpenHDF|OpenSPA|OpenEight|OpenTR|NonSoloSat' "/boot/STARTUP_LINUX_$_SN" 2>/dev/null | head -1)
  fi
  _NAME=$(echo "$_NAME" | head -1 | sed 's/ *$//')
  case "$_NAME" in *FUSE*|*exfat*|*exFAT*|*NTFS*|*already*|*denied*) _NAME="";; esac
  if [ -z "$_NAME" ] && [ -f "$(upanel_label_file "$_SN")" ]; then _NAME=$(head -1 "$(upanel_label_file "$_SN")" 2>/dev/null); fi
  if [ -z "$_NAME" ]; then
    _NAME="Empty / Unknown"
    if [ -z "$_RP" ] || [ ! -e "$_RP" ]; then _USLOT_WHY="no-root-dev[$_RP]";
    elif ! command -v debugfs >/dev/null 2>&1; then _USLOT_WHY="no-debugfs";
    elif [ -n "$_SUB" ] && ! debugfs -R "ls /" "$_RP" 2>/dev/null | grep -q "$_SUB"; then _USLOT_WHY="no-subdir[$_SUB]";
    else _USLOT_WHY="no-image-version"; fi
  else
    _USLOT_WHY="ok"
  fi
  echo "$_USLOT_WHY" > /tmp/upanel_why_$$ 2>/dev/null
  echo "$_NAME"
}

# --- diagnose: everything about slots on one screen ---
upanel_diagnose() {
  show_banner; line; info "Boot Slot Diagnose - send a screenshot of this screen"
  upanel_boot_mount
  echo "BOOT mount: $(grep " /boot " /proc/mounts 2>/dev/null || echo NOT-MOUNTED)"
  echo "TOOLS: debugfs=$(command -v debugfs) fuse2fs=$(command -v fuse2fs)"
  echo "CMDLINE: $(cat /proc/cmdline 2>/dev/null)"
  for _N in $(upanel_slots); do
    _RS=$(upanel_root "$_N"); _RP="${_RS%%|*}"; _SUB="${_RS#*|}"
    echo "== SLOT $_N ==  root=[$_RP] subdir=[$_SUB]  name=[$(upanel_name "$_N")]"
    [ -n "$_RP" ] && [ -e "$_RP" ] && echo "  blkid: $(blkid "$_RP" 2>/dev/null)"
  done
  line; echo "--- OPKG TEST (verbose - this installs debugfs if network works) ---"
  opkg update 2>&1 | tail -3
  opkg install e2fsprogs 2>&1 | tail -5
  echo "debugfs now: $(command -v debugfs || echo STILL MISSING)"
    line; echo "--- BOOT SCAN (try every partition, show which one has STARTUP files) ---"
  for _CAND in /dev/mmcblk0p* /dev/mmcblk1p* /dev/mmcblk0boot0 /dev/mmcblk0boot1; do
    [ -b "$_CAND" ] || continue
    _MP2="/tmp/upanel_scan"; mkdir -p "$_MP2"
    if mount -o ro "$_CAND" "$_MP2" >/dev/null 2>&1; then
      _CNT=$(ls "$_MP2"/STARTUP_LINUX_* 2>/dev/null | wc -l)
      echo "  $_CAND : mounted, STARTUP files: $_CNT $(ls "$_MP2" 2>/dev/null | head -3 | tr '\n' ' ')"
      umount "$_MP2" >/dev/null 2>&1
    else
      echo "  $_CAND : mount FAILED"
    fi
  done
  line; echo "STARTUP files:"; for _f in /boot/STARTUP_LINUX_* /boot/STARTUP_*; do [ -f "$_f" ] || continue; echo "  $(basename "$_f"): $(grep -oE 'root=[^ ]+ rootsubdir=[^ ]+' "$_f" 2>/dev/null)"; done
  printf "Press ENTER to return... "; read _b
}

# --- test switch without rebooting: is /boot real + writable? ---
upanel_probe() {
  show_banner; line; info "Boot Switch Test - NO reboot, only diagnosis"
  upanel_boot_mount
  echo "BOOT mount line: $(grep " /boot " /proc/mounts 2>/dev/null)"
  echo "BOOT is mountpoint: $(grep -qs " /boot " /proc/mounts && echo YES || echo NO)"
  echo "by-name boot: $(ls /dev/block/by-name/ 2>/dev/null | grep -i boot | tr '\n' ' ')"
  echo "STARTUP files:"; ls -l /boot/STARTUP* 2>/dev/null
  echo "--- /boot/STARTUP NOW (first 2 lines):"; head -2 /boot/STARTUP 2>/dev/null
  echo "--- fw env:"; command -v fw_printenv >/dev/null 2>&1 && { fw_printenv boot_slot 2>/dev/null; fw_printenv bootcmd 2>/dev/null | head -3; } || echo "fw_printenv NOT FOUND"
  echo "--- cmdline:"; cat /proc/cmdline 2>/dev/null
  line; echo "TEST: copy SLOT 1 STARTUP -> /boot/STARTUP (then restore)"
  _KEEP=$(cat /boot/STARTUP 2>/dev/null)
  mount -o remount,rw /boot 2>/dev/null
  if grep -qs " /boot " /proc/mounts; then echo "after remount: $(grep " /boot " /proc/mounts)"; fi
  _SRC=""; for _s in /boot/STARTUP_LINUX_1 /boot/STARTUP_1; do [ -f "$_s" ] && { _SRC="$_s"; break; }; done
  if [ -z "$_SRC" ]; then echo "TEST ABORTED: no STARTUP file for SLOT 1 found on /boot"; printf "Press ENTER... "; read _b; return 0; fi
  if cp "$_SRC" /boot/STARTUP 2>/tmp/upanel_cp_err; then echo "CP OK ($_SRC)"; cmp -s "$_SRC" /boot/STARTUP && echo "CMP OK - /boot IS writable and real" || echo "CMP FAIL"; else echo "CP FAILED: $(cat /tmp/upanel_cp_err)"; fi
  echo "$_KEEP" > /boot/STARTUP 2>/dev/null; sync
  echo "RESTORED. /boot/STARTUP back to: $(head -1 /boot/STARTUP 2>/dev/null)"
  printf "Press ENTER to return... "; read _b
}

# --- V4.23: Wipe Slot - erase the image on a slot COMPLETELY (no new image flashed) ---
# Subdir slots (1-4 eMMC): only the subdir is deleted, the shared rootfs partition is NEVER formatted.
# Partition slots (SD, LABEL=linuxN): the partition is formatted ext4 (same as upanel_flash).
# SAFETY: running slot is ALWAYS refused. STARTUP_LINUX_N is KEPT so the slot stays listed as Empty and can be flashed later.
upanel_wipe() {
  show_banner; line; info "Wipe Slot - erase the image on a slot completely - the slot stays Empty, ready to flash later"
  _CS=$(upanel_current); _SL=$(upanel_slots)
  echo "Current Slot: SLOT $_CS - $IMAGE - THIS SLOT CAN NEVER BE WIPED"
  echo "Slots:"
  for _N in $_SL; do
    _NM=$(upanel_name "$_N")
    if [ "$_N" = "$_CS" ]; then echo "  [$_N] SLOT $_N - $_NM  <-- YOU ARE HERE (PROTECTED)"; else echo "  [$_N] SLOT $_N - $_NM"; fi
  done
  printf "Wipe which SLOT (1-4 internal, 6-50 external: SD 6-20 / HDD 21-50, 0 = cancel)? "; read _WS
  [ "$_WS" = "0" ] && return 0
  case "$_WS" in *[!0-9]*|"") echo "Bad slot number."; printf "Press ENTER... "; read _b; return 0;; esac
  if [ "$_WS" = "5" ]; then echo "REFUSED: SLOT 5 is the hidden internal Enigma/Android switcher - it can NEVER be wiped."; printf "Press ENTER... "; read _b; return 0; fi
  if [ "$_WS" -lt 1 ] || [ "$_WS" -gt 50 ]; then echo "Slot must be 1-4 (internal) or 6-50 (external: SD 6-20 / HDD 21-50)."; printf "Press ENTER... "; read _b; return 0; fi
  case " $_SL " in *" $_WS "*) ;; *) echo "SLOT $_WS not found. Available: $_SL"; printf "Press ENTER... "; read _b; return 0;; esac
  if [ "$_WS" = "$_CS" ]; then echo "REFUSED: you are RUNNING on SLOT $_CS - you cannot wipe the running slot. Switch to another slot first."; printf "Press ENTER... "; read _b; return 0; fi
  _OLD=$(upanel_name "$_WS")
  if [ "$_OLD" = "Empty / Unknown" ]; then echo "SLOT $_WS is already Empty - nothing to wipe."; printf "Press ENTER... "; read _b; return 0; fi
  # V6.29: SD slots (6..20) wipe EXACTLY like the plugin (wipe_slot:
  # format + conf Empty + remove STARTUP). Internal slots keep the Panel wipe.
  if [ "$_WS" -ge 6 ] 2>/dev/null; then upanel_plugin_wipe_slot "$_WS"; rm -f "$(upanel_label_file "$_WS")"; printf "Press ENTER to return... "; read _b; return 0; fi
  _RS=$(upanel_root "$_WS"); _RP="${_RS%%|*}"; _SUB="${_RS#*|}"
  [ -z "$_RP" ] && { echo "[WIPE-FAIL] No root device found for SLOT $_WS - NOTHING was changed."; printf "Press ENTER... "; read _b; return 0; }
  # NEVER touch the running root partition as a whole partition - only its subdir may be deleted
  _RUNROOT=$(grep -oE 'root=/dev/[^ ]+' /proc/cmdline 2>/dev/null | cut -d= -f2 | head -1)
  [ -z "$_RUNROOT" ] && _RUNROOT=$(grep " / " /proc/mounts 2>/dev/null | awk '{print $1}' | head -1)
  _RUNROOT_RES=$(readlink -f "$_RUNROOT" 2>/dev/null || echo "$_RUNROOT")
  _RP_RES=$(readlink -f "$_RP" 2>/dev/null || echo "$_RP")
  if [ -z "$_SUB" ] && [ -n "$_RUNROOT_RES" ] && [ "$_RP_RES" = "$_RUNROOT_RES" ]; then echo "[WIPE-FAIL] SLOT $_WS uses the running root partition with no subdir - refusing to format it."; printf "Press ENTER... "; read _b; return 0; fi
  # NEVER format boot / boot0 / boot1 / raw mmcblk device (no partition number)
  case "$_RP" in *boot*|/dev/mmcblk[0-9]|/dev/mmcblk[0-9]boot*|/dev/sd[a-z]) if [ -z "$_SUB" ]; then echo "[WIPE-FAIL] $_RP looks like a boot/raw device, not a slot partition - refusing."; printf "Press ENTER... "; read _b; return 0; fi;; esac
  echo "TARGET: SLOT $_WS (now: $_OLD)"
  if [ -n "$_SUB" ]; then echo "MODE: subdir slot - will delete ONLY: $_RP / $_SUB"; else echo "MODE: partition slot - will FORMAT: $_RP (LABEL=linux$_WS)"; fi
  echo "WARNING: SLOT $_WS will be ERASED completely. This CANNOT be undone (take a Backup first if you need it)."
  printf "Type WIPE (wipe / w also works) to confirm - first WIPE: "; read _W1
  printf "Second WIPE: "; read _W2
  if ! confirm_word "$_W1" "wipe" || ! confirm_word "$_W2" "wipe"; then echo "Cancelled - type WIPE twice to wipe."; printf "Press ENTER... "; read _b; return 0; fi
  upanel_boot_mount
  mount -o remount,rw /boot 2>/dev/null
  if [ -n "$_SUB" ]; then
    _MP=/tmp/upanel_wipe_mnt; mkdir -p "$_MP"
    mount "$_RP" "$_MP" 2>/tmp/upanel_wipe_err || { echo "[WIPE-FAIL] Cannot mount $_RP: $(cat /tmp/upanel_wipe_err) - NOTHING was changed."; printf "Press ENTER... "; read _b; return 0; }
    _DEST="$_MP/$_SUB"
    [ -d "$_DEST" ] || { echo "SLOT $_WS subdir $_SUB not found - already Empty."; umount "$_MP" 2>/dev/null; printf "Press ENTER... "; read _b; return 0; }
    echo "[WIPE] Erasing $_DEST..."
    rm -rf "$_DEST" && mkdir -p "$_DEST" || { echo "[WIPE-FAIL] Cannot erase subdir."; umount "$_MP" 2>/dev/null; printf "Press ENTER... "; read _b; return 0; }
    sync; umount "$_MP" 2>/dev/null
  else
    echo "[WIPE] Unmounting $_RP (the running image may have auto-mounted it)..."
    if ! upanel_unmount_device "$_RP"; then echo "[WIPE-FAIL] SLOT $_WS partition $_RP is STILL mounted at: $(awk -v d="$_RP" '$1==d {print $2}' /proc/mounts 2>/dev/null | tr '\n' ' ') - it is in use by the running image. NOTHING was changed."; printf "Press ENTER... "; read _b; return 0; fi
    echo "[WIPE] Formatting $_RP as ext4 (LABEL=linux$_WS)..."
    mkfs.ext4 -L "linux$_WS" -F "$_RP" >/dev/null 2>/tmp/upanel_wipe_err || { echo "[WIPE-FAIL] mkfs failed: $(cat /tmp/upanel_wipe_err)"; printf "Press ENTER... "; read _b; return 0; }
    sync
  fi
  rm -f "$(upanel_label_file "$_WS")"
  echo "[WIPE] SLOT $_WS wiped - now: $(upanel_name "$_WS")"
  upanel_startup_delete_for_slot "$_WS" >/dev/null
  echo "[WIPE] STARTUP_LINUX_$_WS removed (backed up) - the wiped slot no longer"
  echo "[WIPE] shows in Recovery. The Panel still lists it (from LABEL=linux$_WS),"
  echo "[WIPE] flash a new image into it anytime - Flash recreates its STARTUP."
  printf "Press ENTER to return... "; read _b; return 0
}

# --- flash a downloaded image into any slot (1-20) ---
upanel_unmount_device() { # $1=device - unmount ALL mountpoints of a device; returns 0 only when FULLY unmounted (never touches /)
  _UD="$1"
  _MPS=$(awk -v d="$_UD" '$1==d {print $2}' /proc/mounts 2>/dev/null)
  case " $_MPS " in *" / "*) echo "[UNMOUNT] REFUSED: $_UD is the running root (/) - will NOT unmount."; return 2;; esac
  _TRY=0
  while grep -qF "$_UD " /proc/mounts 2>/dev/null; do
    _MPS=$(awk -v d="$_UD" '$1==d {print $2}' /proc/mounts 2>/dev/null)
    for _MP in $_MPS; do umount "$_MP" 2>/dev/null; done
    umount "$_UD" 2>/dev/null
    _TRY=$((_TRY+1)); [ "$_TRY" -ge 3 ] && break
    sleep 1
  done
  if grep -qF "$_UD " /proc/mounts 2>/dev/null; then
    _MPS=$(awk -v d="$_UD" '$1==d {print $2}' /proc/mounts 2>/dev/null)
    for _MP in $_MPS; do umount -l "$_MP" 2>/dev/null; done
    umount -l "$_UD" 2>/dev/null
    sleep 1
  fi
  if grep -qF "$_UD " /proc/mounts 2>/dev/null; then return 1; fi
  return 0
}
upanel_flash() {
  show_banner; line; info "Flash Image to Slot - installs a downloaded image from HDD into any slot (1-14)"
  _CS=$(upanel_current)
  rm -f /tmp/upanel_imgs.txt
  for _d in /media/hdd/*/ /media/usb/*/ /media/mmc/*/; do
    [ -d "$_d" ] || continue
    _bn=$(basename "$_d")
    case "$_bn" in U-Panel-Backup-*|timeshift|movie|movies|lost+found|picon|EPG*) continue;; esac
    echo "DIR|$_d" >> /tmp/upanel_imgs.txt
  done
  for _z in /media/hdd/*.zip /media/usb/*.zip /media/mmc/*.zip; do
    [ -f "$_z" ] || continue
    echo "ZIP|$_z" >> /tmp/upanel_imgs.txt
  done
  if [ ! -s /tmp/upanel_imgs.txt ]; then echo "No images found on /media/hdd - download an image first (Menu > Image Manager / Multiboot Download)."; printf "Press ENTER... "; read _b; return 0; fi
  echo "Downloaded images:"
  _i=0; while IFS='|' read -r _T _P; do _i=$((_i+1)); echo "  [$_i] $(basename "$_P")  <$_T>"; done < /tmp/upanel_imgs.txt
  if [ -n "$U_PANEL_FLASH_PATH" ]; then
    _IP="$U_PANEL_FLASH_PATH"
    case "$_IP" in *.zip) _IT=ZIP;; *) if [ -d "$_IP" ]; then _IT=DIR; else echo "Flash path not found: $_IP"; printf "Press ENTER... "; read _b; return 0; fi;; esac
    echo "Flashing (from Panel UI): $(basename "$_IP")  <$_IT>"
  else
    printf "Pick image number (0 = cancel): "; read _PI
    [ "$_PI" = "0" ] && return 0
    _SEL=$(sed -n "${_PI}p" /tmp/upanel_imgs.txt)
    [ -z "$_SEL" ] && { echo "Bad choice."; printf "Press ENTER... "; read _b; return 0; }
    _IT=$(echo "$_SEL" | cut -d'|' -f1); _IP=$(echo "$_SEL" | cut -d'|' -f2-)
  fi
  _WK=/tmp/upanel_flash; rm -rf "$_WK"; mkdir -p "$_WK"
  if [ "$_IT" = "ZIP" ]; then
    echo "Unzipping $(basename "$_IP")..."; unzip -o -q "$_IP" -d "$_WK" || { echo "Unzip failed."; printf "Press ENTER... "; read _b; return 0; }
  else
    _ZIPIN=$(ls "$_IP"/*.zip 2>/dev/null | head -1)
    if [ -n "$_ZIPIN" ]; then echo "Unzipping $(basename "$_ZIPIN")..."; unzip -o -q "$_ZIPIN" -d "$_WK" || { echo "Unzip failed."; printf "Press ENTER... "; read _b; return 0; }
    else cp -a "$_IP" "$_WK/img" 2>/dev/null; _WK="$_WK/img"; fi
  fi
  _IMGDIR="$_WK"; [ -d "$_WK/noveler" ] && _IMGDIR="$_WK/noveler"
  _ROOTFS=$(find "$_IMGDIR" -maxdepth 3 -name 'rootfs.tar*' 2>/dev/null | head -1)
  _ROOTDIR=$(find "$_IMGDIR" -maxdepth 3 -type d -name 'rootfs' 2>/dev/null | head -1)
  # V6.20 FIX: was ls on depth-1 only - Egami multiboot zips keep the kernel at
  # novaler4kpro/kernel.bin (depth 2), so _KERN came out empty, no kernel was
  # copied, and verify failed on the missing kernel file. find, depth 3.
  _KERN=$(find "$_IMGDIR" -maxdepth 3 \( -name 'kernel*.bin' -o -name 'uImage*' -o -name 'vmlinux*' -o -name 'zImage*' -o -name 'Image*' \) 2>/dev/null | grep -v -i 'rootfs' | head -1)
  if [ -z "$_ROOTFS" ] && [ -z "$_ROOTDIR" ]; then echo "No rootfs found in this image (need rootfs.tar.* or a rootfs/ folder)."; printf "Press ENTER... "; read _b; return 0; fi
  echo "Image: $(basename "$_IP") | rootfs: ${_ROOTFS:-$_ROOTDIR} | kernel: $(basename "$_KERN" 2>/dev/null || echo none)"
  printf "Flash to which SLOT (1-4 internal, 6-50 external: SD 6-20 / HDD 21-50, 5 = hidden switcher - NOT usable, 0 = cancel)? "; read _TS
  while [ -z "$_TS" ]; do printf "Flash to which SLOT (1-4, 6-50, 0 = cancel)? "; read _TS || return 0; done
  [ "$_TS" = "0" ] && return 0
  case "$_TS" in *[!0-9]*|"") echo "Bad slot number."; printf "Press ENTER... "; read _b; return 0;; esac
  if [ "$_TS" = "5" ]; then echo "REFUSED: SLOT 5 is the hidden internal Enigma/Android switcher - you cannot flash an image into it. External slots start at 6."; printf "Press ENTER... "; read _b; return 0; fi
  if [ "$_TS" -lt 1 ] || [ "$_TS" -gt 50 ]; then echo "Slot must be 1-4 (internal) or 6-50 (external: SD 6-20 / HDD 21-50)."; printf "Press ENTER... "; read _b; return 0; fi
  if [ "$_TS" = "$_CS" ]; then echo "REFUSED: you are RUNNING on SLOT $_CS. Switch to another slot first, then flash this one."; printf "Press ENTER... "; read _b; return 0; fi
  _OLD=$(upanel_name "$_TS")
  echo "TARGET: SLOT $_TS (now: $_OLD) <- $(basename "$_IP")"
  echo "WARNING: SLOT $_TS will be ERASED completely."
  printf "Type FLASH (flash also works) to confirm: "; read _CF; if confirm_word "$_CF" "flash"; then :; else echo "Cancelled."; printf "Press ENTER... "; read _b; return 0; fi
  # V6.29: SD slots (6..20) install EXACTLY like the plugin (install_image:
  # format + unzip rootfs.tar.bz2 + plugin STARTUP + inject plugin). The
  # Panel's kernel-copy / transfer steps do NOT run here - the plugin has
  # none (kernel comes from the fixed eMMC offset 0x3D5000 via bootcmd).
  if [ "$_TS" -ge 6 ] 2>/dev/null; then
    if [ "$_IT" != "ZIP" ]; then echo "[FLASH] Plugin install needs a .zip image (with rootfs.tar.bz2 inside) - pick the ZIP file, not a folder."; printf "Press ENTER... "; read _b; return 0; fi
    rm -f "$(upanel_label_file "$_TS")"
    if upanel_plugin_install_image "$_TS" "$_IP"; then
      upanel_push_boot_file "/boot/STARTUP_LINUX_$_TS" >/dev/null 2>&1
      sync; rm -rf "$_WK" /tmp/upanel_flash_mnt
      if ! upanel_verify_after_flash "$_TS"; then echo "[FLASH-FAIL] SLOT $_TS did NOT verify - do NOT boot it. Flash it again or pick another slot."; printf "Press ENTER to return... "; read _b; return 0; fi
      _MP2=/tmp/upanel_flash_mnt2; mkdir -p "$_MP2"
      _FB_DK=$(upanel_plugin_disk); _FB_SP=$(upanel_plugin_sep "$_FB_DK"); if mount "/dev/${_FB_DK}${_FB_SP}$((_TS-5))" "$_MP2" 2>/dev/null; then upanel_install_rollback_checker "$_MP2"; umount "$_MP2" 2>/dev/null; fi
      _NM=$(upanel_name "$_TS")
      if [ "$_NM" = "Empty / Unknown" ]; then _LBL2=$(basename "$_IP" | sed -e 's/\.zip$//' -e 's/[-_]/ /g' | cut -c1-40); echo "$_LBL2" > "$(upanel_label_file "$_TS")" 2>/dev/null && echo "[SLOT] Named SLOT $_TS: $_LBL2"; fi
      echo "[FLASH] DONE - SLOT $_TS now has: $(upanel_name "$_TS")"
      echo "Use [3] Reboot to Selected Slot to boot into SLOT $_TS (rollback guard will arm on switch)."
    fi
    printf "Press ENTER to return... "; read _b; return 0
  fi
  # V 3.4: drop any stale custom label for this slot (it is being erased)
  rm -f "$(upanel_label_file "$_TS")"
  _RS=$(upanel_root "$_TS"); _RP="${_RS%%|*}"; _SUB="${_RS#*|}"
  upanel_boot_mount
  mount -o remount,rw /boot 2>/dev/null
  if [ -n "$_SUB" ]; then
    echo "[FLASH] SLOT $_TS is a subdir slot: $_RP / $_SUB"
    _MP=/tmp/upanel_flash_mnt; mkdir -p "$_MP"
    mount "$_RP" "$_MP" 2>/tmp/upanel_flash_err || { echo "[FLASH-FAIL] Cannot mount $_RP: $(cat /tmp/upanel_flash_err) - NOTHING was changed."; printf "Press ENTER... "; read _b; return 0; }
    _DEST="$_MP/$_SUB"
    echo "[FLASH] Erasing $_DEST..."; rm -rf "$_DEST" && mkdir -p "$_DEST" || { echo "[FLASH-FAIL] Cannot erase subdir."; umount "$_MP" 2>/dev/null; printf "Press ENTER... "; read _b; return 0; }
  else
    [ -z "$_RP" ] && { echo "[FLASH-FAIL] No root partition found for SLOT $_TS (no STARTUP file, no LABEL=linux$_TS). Create its STARTUP_LINUX_$_TS first or pick another slot."; printf "Press ENTER... "; read _b; return 0; }
    echo "[FLASH] SLOT $_TS is a partition slot: $_RP"
    echo "[FLASH] Unmounting $_RP (the running image may have auto-mounted it)..."
    if ! upanel_unmount_device "$_RP"; then echo "[FLASH-FAIL] SLOT $_TS partition $_RP is STILL mounted at: $(awk -v d="$_RP" '$1==d {print $2}' /proc/mounts 2>/dev/null | tr '\n' ' ') - it is in use by the running image. NOTHING was changed. Reboot to another slot and try again."; printf "Press ENTER... "; read _b; return 0; fi
    echo "[FLASH] Formatting $_RP as ext4 (LABEL=linux$_TS)..."; mkfs.ext4 -L "linux$_TS" -F "$_RP" >/dev/null 2>/tmp/upanel_flash_err || { echo "[FLASH-FAIL] mkfs failed: $(cat /tmp/upanel_flash_err)"; printf "Press ENTER... "; read _b; return 0; }
    _MP=/tmp/upanel_flash_mnt; mkdir -p "$_MP"
    mount "$_RP" "$_MP" 2>/tmp/upanel_flash_err || { echo "[FLASH-FAIL] Cannot mount fresh $_RP: $(cat /tmp/upanel_flash_err)"; printf "Press ENTER... "; read _b; return 0; }
    _DEST="$_MP"
  fi
  if [ -n "$_ROOTFS" ]; then
    case "$_ROOTFS" in *.bz2) tar -xjf "$_ROOTFS" -C "$_DEST";; *.gz|*.tgz) tar -xzf "$_ROOTFS" -C "$_DEST";; *.xz) tar -xJf "$_ROOTFS" -C "$_DEST";; *) tar -xf "$_ROOTFS" -C "$_DEST";; esac
  else
    cp -a "$_ROOTDIR"/. "$_DEST"/
  fi
  if [ ! -f "$_DEST/etc/image-version" ] && [ ! -f "$_DEST/usr/bin/enigma2" ]; then echo "[FLASH-FAIL] Extraction looks wrong - no etc/image-version or enigma2 in target. Slot may be incomplete."; umount "$_MP" 2>/dev/null; printf "Press ENTER... "; read _b; return 0; fi
  sync
  umount "$_MP" 2>/dev/null
  _TK=""
  mount -o remount,rw /boot 2>/dev/null
  if [ -n "$_KERN" ]; then
    _CK=$(grep -oE 'kernel=[^ ]+' "/boot/STARTUP_LINUX_$_CS" 2>/dev/null | head -1 | sed 's/kernel=//')
    if [ -n "$_CK" ]; then _TK=$(echo "$_CK" | sed "s/$_CS/$_TS/g"); [ "$_TK" = "$_CK" ] && _TK="${_CK%.*}$_TS.${_CK##*.}"; cp "$_KERN" "$_TK" 2>/dev/null && echo "[FLASH] Kernel -> $_TK"; else _TK="/boot/kernel$_TS.bin"; cp "$_KERN" "$_TK" 2>/dev/null && echo "[FLASH] Kernel -> $_TK"; fi
    # V6.20 FIX: point the TARGET slot's STARTUP at the kernel we just copied.
    # Before, STARTUP_LINUX_TS (written by Prepare) kept the OLD slot's kernel=
    # while verify checked it - so verify failed on a kernel that was never the
    # new image's, and the slot would have booted the old kernel.
    if [ -n "$_TK" ] && [ -f "$_TK" ] && [ -f "/boot/STARTUP_LINUX_$_TS" ]; then sed -i "s|kernel=[^ ]*|kernel=$_TK|" "/boot/STARTUP_LINUX_$_TS" 2>/dev/null && echo "[FLASH] STARTUP_LINUX_$_TS kernel= -> $_TK"; fi
  else echo "[FLASH] No kernel file in image - keeping existing kernel (image may use shared kernel)."; fi
  if [ ! -f "/boot/STARTUP_LINUX_$_TS" ]; then
    if [ -f "/boot/STARTUP_LINUX_$_CS" ]; then
      sed -e "s/$_CS/$_TS/g" -e "s/root=[^ ]*/root=$_RP/" -e "s/rootsubdir=[^ ]*/rootsubdir=$_SUB/" "/boot/STARTUP_LINUX_$_CS" > "/boot/STARTUP_LINUX_$_TS" && echo "[FLASH] Created /boot/STARTUP_LINUX_$_TS"
      [ -z "$_SUB" ] && upanel_startup_fix_rootsubdir "/boot/STARTUP_LINUX_$_TS"
    else echo "[FLASH] WARNING: /boot/STARTUP_LINUX_$_TS does not exist and no template - create it manually or the slot will not boot."; fi
  fi
  # V6.24 FIX: push the new slot's STARTUP + kernel to EVERY BOOT partition -
  # the bootloader may read a different BOOT than the mounted /boot.
  [ -n "$_TK" ] && [ -f "$_TK" ] && upanel_push_boot_file "$_TK"
  [ -f "/boot/STARTUP_LINUX_$_TS" ] && upanel_push_boot_file "/boot/STARTUP_LINUX_$_TS"
  sync; rm -rf "$_WK" /tmp/upanel_flash_mnt
  # V 3.4: verify the flashed slot BEFORE calling it done
  if ! upanel_verify_after_flash "$_TS"; then
    echo "[FLASH-FAIL] SLOT $_TS did NOT verify - do NOT boot it. Flash it again or pick another slot."
    printf "Press ENTER to return... "; read _b; return 0
  fi
  # V 3.4: install the rollback checker INTO the new slot (arms only on switch)
  _MP2=/tmp/upanel_flash_mnt2; mkdir -p "$_MP2"
  if mount "$_RP" "$_MP2" 2>/dev/null; then
    _IDEST="$_MP2"; [ -n "$_SUB" ] && _IDEST="$_MP2/$_SUB"
    upanel_install_rollback_checker "$_IDEST"
    umount "$_MP2" 2>/dev/null
  fi
  # V 3.4: transfer channels/settings/keys from the running slot
  printf "Transfer channels + settings + keys from THIS slot into SLOT $_TS? (y/n): "; read _XF
  case "$_XF" in y|Y) upanel_transfer_from_current "$_TS" "$_RP" "$_SUB" ;; *) echo "Skipped - install plugins + restore settings after first boot." ;; esac
  # V 3.4: name the slot from the image if it would otherwise read "Empty / Unknown"
  _NM=$(upanel_name "$_TS")
  if [ "$_NM" = "Empty / Unknown" ]; then
    _LBL2=$(basename "$_IP" | sed -e 's/\.zip$//' -e 's/[-_]/ /g' | cut -c1-40)
    echo "$_LBL2" > "$(upanel_label_file "$_TS")" 2>/dev/null && echo "[SLOT] Named SLOT $_TS: $_LBL2"
  fi
  echo "[FLASH] DONE - SLOT $_TS now has: $(upanel_name "$_TS")"
  echo "Use [2] Switch to boot into SLOT $_TS (rollback guard will arm on switch)."
  printf "Press ENTER to return... "; read _b

}

# --- the manager menu (entry point, called from main menu option 13) ---


# ===== Novaler Downloader - robust detection (V23.5 FIX) =====
# Real plugin folder name varies: novalerdownloader / NovalerDownloader / Novaler-Downloader ...
# So we search case-insensitively + check opkg, instead of one hardcoded path.
find_novaler_downloader_dir() {
  _ND=""
  # 1) Any Extensions folder with novaler+download in any case / separator
  for _d in /usr/lib/enigma2/python/Plugins/Extensions/*; do
    [ -d "$_d" ] || continue
    _BN=$(basename "$_d" | tr 'A-Z' 'a-z' | tr -d ' _-')
    case "$_BN" in *novaler*download*|*download*novaler*) _ND="$_d"; break ;; esac
  done
  # 2) Deep search: plugin.py whose path mentions novaler+download
  if [ -z "$_ND" ]; then
    _ND=$(find /usr/lib/enigma2/python/Plugins -maxdepth 4 -type d -iname '*novaler*download*' 2>/dev/null | head -1)
  fi
  # 3) opkg: package name -> its file list
  if [ -z "$_ND" ] && command -v opkg >/dev/null 2>&1; then
    _PKG=$(opkg list-installed 2>/dev/null | grep -i -E 'novaler.*download|download.*novaler' | head -1 | cut -d' ' -f1)
    if [ -n "$_PKG" ]; then _ND=$(opkg files "$_PKG" 2>/dev/null | grep -i -E 'Extensions/.*plugin.py' | head -1 | xargs dirname 2>/dev/null); fi
  fi
  echo "$_ND"
}
is_novaler_downloader_installed() {
  [ -n "$(find_novaler_downloader_dir)" ] && return 0
  opkg list-installed 2>/dev/null | grep -qi 'novaler.*download' && return 0
  # plugin.py / plugin.pyo inside any novaler folder
  find /usr/lib/enigma2/python/Plugins/Extensions -maxdepth 2 -iname 'plugin.py*' 2>/dev/null | grep -i novaler | grep -qi download && return 0
  return 1
}
# Show what the script actually sees - for diagnosis
diagnose_novaler_downloader() {
  echo "--- Diagnose ---"
  echo "BOX=[$BOX]  FULL_MACHINE=[$FULL_MACHINE]  MACHINE=[$MACHINE]"
  echo "is_novaler: $(is_novaler && echo YES || echo NO) - Model: $(novaler_model_name)"
  echo "STB info:"; for _f in /proc/stb/info/brand /proc/stb/info/model /proc/stb/info/boxtype /proc/stb/info/machine /proc/stb/info/manufacturer; do [ -f "$_f" ] && echo "  $_f: $(cat "$_f" 2>/dev/null)"; done
  echo "Plugin dir found: [$(find_novaler_downloader_dir)]"
  echo "Plugin installed: $(is_novaler_downloader_installed && echo YES || echo NO)"
  echo "opkg (novaler):"
  opkg list-installed 2>/dev/null | grep -i novaler | sed 's/^/  /' || echo "  (none)"
  echo "Extensions folders with novaler (no duplicates):"
  _EXT_FOUND=0
  for _d in $(find /usr/lib/enigma2/python/Plugins/Extensions -maxdepth 1 -type d -iname '*novaler*' 2>/dev/null | sort -u); do echo "  $_d"; _EXT_FOUND=1; done
  [ "$_EXT_FOUND" = "0" ] && echo "  (none found)"
  echo "ZIP images found on HDD/USB (recursive):"
  _ZIP_FOUND=0
  for _z in $(find /media/hdd /media/usb /media/mmc -maxdepth 4 -type f -iname '*.zip' 2>/dev/null | sort -u); do ls -lh "$_z" 2>/dev/null | awk '{print "  "$5"  "$6" "$7" "$8"  "$9}'; _ZIP_FOUND=1; done
  [ "$_ZIP_FOUND" = "0" ] && echo "  (no .zip found)"
  echo "--- Verdict ---"
  if is_novaler && is_novaler_downloader_installed && [ "$_ZIP_FOUND" = "1" ]; then
    echo "[OK] All good: Novaler detected + Downloader installed + images found."
    echo "     Use: Download Image > [3] Show Downloaded Images to flash one."
  elif is_novaler && is_novaler_downloader_installed; then
    echo "[OK] Novaler + Downloader OK, but no .zip yet - download one from the Downloader first."
  elif is_novaler; then
    echo "[WARN] Novaler detected but Downloader NOT installed - use Download Image > [1] to install it."
  else
    echo "[INFO] Not a Novaler box - Novaler Downloader is not available, use External Link only."
  fi
}
# List ANY .zip the Novaler Downloader (or user) downloaded - then flash it
list_downloaded_images() {
  echo "Images found (all Novaler Downloader / manual download folders):"
  _IDX=0; _LIST=""
  # Recursive scan: Novaler Downloader saves to different folders per model/version
  # (/media/hdd, /media/hdd/Novaler, /media/hdd/download, /media/hdd/images, plugin folder, /tmp)
  for _z in $(find /media/hdd /media/usb /media/mmc /tmp -maxdepth 4 -type f -iname '*.zip' 2>/dev/null | sort); do
    [ -f "$_z" ] || continue
    _IDX=$((_IDX+1)); echo "  [$_IDX] $_z ($(du -h "$_z" 2>/dev/null | cut -f1))"
    _LIST="$_LIST|$_z"
  done
  [ "$_IDX" = "0" ] && { echo "  No .zip images found. Download one first (Novaler Downloader / External Link)."; return 1; }
  printf "Pick image number to Flash (0 = cancel): "; read _PN
  [ "$_PN" = "0" ] && return 1
  _SEL=$(echo "$_LIST" | cut -d'|' -f$((_PN+1)))
  [ -z "$_SEL" ] && { echo "Bad number."; return 1; }
  echo "Selected: $_SEL"
  case "$_SEL" in /media/hdd/*.zip) ;; *) cp "$_SEL" /media/hdd/ 2>/dev/null && echo "Copied to /media/hdd for flashing." ;; esac
  printf "Flash it now? (y/n): "; read _FL2
  case "$_FL2" in y|Y) upanel_flash ;; *) echo "Saved - flash later from Multiboot Manager > Flash Image to Slot." ;; esac
  return 0
}

# ===== Download Image from Internet - V23.5 =====
# Novaler: 1) Novaler Downloader plugin + 2) External link
# Other devices: External link ONLY (Novaler Downloader is Novaler-only)


# ===== Novaler Image Links - V23.9 - LIVE from official servers =====
# Finding from research (Nov 2026):
# - Real Novaler slugs used by image teams: novaler4k (standard) / novaler4kse (SE) / novaler4kpro (PRO)
#   On-box /proc/stb/info/model says multiboxpro - that is the HARDWARE name, NOT the image slug.
#   Images on servers are named noveler4kpro / novaler4kpro - never multiboxpro.
# - Direct .zip URLs are NOT published as a static list - OpenATV/Egami pages list
#   a NEW build every day, so a hardcoded link dies in 24h. The fix: fetch the
#   official page LIVE and extract the current .zip links from it. No dead links.
# - Teams with no public direct .zip page (OpenViX/OpenBH/PurE2/OpenHDF/OpenSPA/TeamBlue):
#   we link to Novaler's own official per-model page, which lists their clean images
#   + Full-Backups. OpenPLi official has NO Novaler build (only Maxytec Multibox SE
#   on openpli.org - NOT the same box - so it is deliberately NOT listed).
novaler_image_slug() {
  # FULL_MACHINE wins: BOX text can be stale/generic, FULL_MACHINE is the hardware slug.
  _FM=$(echo "$FULL_MACHINE" | tr 'A-Z' 'a-z' | tr -d ' _-')
  case "$_FM" in *novaler4kpro*|*multiboxpro*|*noveler4kpro*) echo "novaler4kpro"; return 0 ;; *novaler4kse*|*multiboxse*|*noveler4kse*) echo "novaler4kse"; return 0 ;; *novaler4k*|*multibox*|*novaler*) echo "novaler4k"; return 0 ;; esac
  _S=$(echo "$BOX $MACHINE" | tr 'A-Z' 'a-z' | tr -d ' _-')
  case "$_S" in *novaler4kpro*|*multiboxpro*|*noveler4kpro*) echo "novaler4kpro" ;; *novaler4kse*|*multiboxse*|*noveler4kse*) echo "novaler4kse" ;; *novaler4k*|*multibox*|*novaler*) echo "novaler4k" ;; *) echo "" ;; esac
}
novaler_model_label() {
  case "$(novaler_image_slug)" in
    novaler4kpro) echo "Novaler Multibox 4K PRO" ;;
    novaler4kse) echo "Novaler Multibox 4K SE" ;;
    novaler4k) echo "Novaler Multibox 4K (Standard)" ;;
    *) echo "$(novaler_model_name)" ;;
  esac
}
novaler_official_page() {
  case "$(novaler_image_slug)" in
    novaler4kpro) echo "https://novaler.com/downloads/enigma2/multibox-4k-pro-ultra-hd" ;;
    novaler4k) echo "https://novaler.com/downloads/enigma2/multibox-4k-ultra-hd" ;;
    novaler4kse) echo "https://novaler.com/downloads/enigma2-backups2/multibox-4k-se-ultra-hd" ;;
    *) echo "https://novaler.com/downloads/enigma2" ;;
  esac
}
# Fetch a download page, extract .zip links, print "LABEL|URL" lines
# $1 = page URL, $2 = base URL for relative links, $3 = label prefix
# RAW page fetch - secure_fetch() REJECTS HTML on purpose (it thinks HTML = 404),
# so it can NEVER fetch a download page. This fetcher is for HTML pages only:
# silent (no stdout pollution), returns 1 on failure, never writes error text into the links file.
novaler_fetch_page() {
  _PU="$1"; _PD="$2"; rm -f "$_PD" "$_PD.tmp"
  echo "  ... fetching $(echo "$_PU" | cut -c1-70)" >&2
  # Hard 12s cap: a slow/dead image server must NEVER hang the whole menu
  if command -v timeout >/dev/null 2>&1; then _TO="timeout 12"; else _TO=""; fi
  if command -v wget >/dev/null 2>&1; then
    $_TO wget --no-check-certificate --timeout=10 --dns-timeout=5 --connect-timeout=5 --tries=1 -U "Mozilla/5.0" -O "$_PD.tmp" "$_PU" >/dev/null 2>&1
  elif command -v curl >/dev/null 2>&1; then
    $_TO curl -k -sL -A "Mozilla/5.0" --max-time 10 --connect-timeout 5 -o "$_PD.tmp" "$_PU" >/dev/null 2>&1
  else return 1; fi
  if [ -s "$_PD.tmp" ]; then mv "$_PD.tmp" "$_PD"; echo "  [OK] got $(wc -c < "$_PD" | tr -d ' ') bytes" >&2; return 0; fi
  echo "  [SKIP] server slow / no page - skipping this team" >&2
  return 1
}
extract_zips_from_page() {
  _PAGE="$1"; _BASE="$2"; _LBL="$3"
  rm -f /tmp/novaler_page.html
  novaler_fetch_page "$_PAGE" "/tmp/novaler_page.html" || return 1
  [ -f /tmp/novaler_page.html ] || return 1
  _SLUG1=$(novaler_image_slug); _SLUG2=$(echo "$_SLUG1" | sed 's/^novaler/noveler/')
  { grep -oE 'href="[^"]*\.zip[^"]*"' /tmp/novaler_page.html 2>/dev/null | sed -e 's/href="//' -e 's/"$//'; grep -oE '[A-Za-z0-9._~%+-]*('$_SLUG1'|'"$_SLUG2"')[A-Za-z0-9._~%+-]*_multi\.zip' /tmp/novaler_page.html 2>/dev/null; } | sort -u | while read -r _H; do
    case "$_H" in http*) _U="$_H" ;; /*) _U="${_BASE%/*}$_H" ;; *) _U="$_BASE$_H" ;; esac
    # Only THIS model's files (either spelling), only _multi.zip, NOT recovery
    case "$_U" in *"$_SLUG1"*"_multi.zip"*|*"$_SLUG2"*"_multi.zip"*) echo "$_LBL|$_U" ;; esac
  done
}
# OpenBH has no per-model page: 6.0/ lists device folders - walk into this model's folder
openbh_links() {
  rm -f /tmp/openbh_index.html
  novaler_fetch_page "https://images.openbh.net/6.0/" "/tmp/openbh_index.html" || return 1
  _SLUG1=$(novaler_image_slug); _SLUG2=$(echo "$_SLUG1" | sed 's/^novaler/noveler/')
  _DIR=$(grep -oE 'href="[^"]*('$_SLUG1'|'"$_SLUG2"')[^"]*/"' /tmp/openbh_index.html 2>/dev/null | sed -e 's/href="//' -e 's/"$//' | head -1)
  [ -z "$_DIR" ] && { echo "  [SKIP] OpenBH: no $_SLUG1 folder in 6.0/ index" >&2; return 1; }
  extract_zips_from_page "https://images.openbh.net/6.0/$_DIR" "https://images.openbh.net/6.0/$_DIR" "OpenBH 6.0"
}

# Extract team links from Novaler's own per-model page (novaler.com).
# Page lists clean images + Full-Backups; we keep only files whose name matches
# this model's slug (either spelling) and a known team, and _multi.zip / _usb.zip.
novaler_page_links() {
  rm -f /tmp/novaler_official.html
  novaler_fetch_page "$(novaler_official_page)" "/tmp/novaler_official.html" || return 1
  _SLUG1=$(novaler_image_slug); _SLUG2=$(echo "$_SLUG1" | sed 's/^novaler/noveler/')
  { grep -oE 'href="[^"]*\.zip[^"]*"' /tmp/novaler_official.html 2>/dev/null | sed -e 's/href="//' -e 's/"$//'; grep -oE '[A-Za-z0-9._~%+/,?:=&-]*('$_SLUG1'|'"$_SLUG2"')[A-Za-z0-9._~%+/,?:=&-]*\.zip' /tmp/novaler_official.html 2>/dev/null; } | sort -u | while read -r _H; do
    case "$_H" in http*) _U="$_H" ;; //*) _U="https:$_H" ;; /*) _U="https://novaler.com$_H" ;; *) _U="https://novaler.com/$_H" ;; esac
    _LOW=$(echo "$_U" | tr 'A-Z' 'a-z')
    case "$_LOW" in *"$_SLUG1"*|*"$_SLUG2"*) ;; *) continue ;; esac
    case "$_LOW" in *recovery*) continue ;; esac
    case "$_LOW" in *openvix*|*vix*) _LBL="OpenViX" ;; *openbh*|*blackhole*) _LBL="OpenBH" ;; *pure2*|*pure-2*) _LBL="PurE2" ;; *openhdf*|*hdf*) _LBL="OpenHDF" ;; *openspa*|*spa*) _LBL="OpenSPA" ;; *teamblue*|*team-blue*) _LBL="TeamBlue" ;; *) continue ;; esac
    echo "$_LBL|$_U"
  done
}



# ===== Image Download Safety - V 3.2 =====
# 1) VERIFY every downloaded image BEFORE flashing (zip integrity + content
#    must match THIS box). Bad file = deleted, NEVER flashed.
# 2) NO auto-backup before flash (V 3.3): slot flash already cleans the slot
#    before flashing, so the pre-flash backup was redundant. Manual backup is
#    still available anytime: Boot Slot Manager > [3] Backup Current Slot.
# 3) HDD SPACE check BEFORE downloading (image size + 50MB margin).
# 4) OpenSPA + OpenHDF for Octagon / Zgemma / VU+ (ATTEMPTED sources):
#    OpenSPA's server (openspa.webhop.info) is a JavaScript file browser -
#    curl only gets an empty shell - and OpenHDF lives on HDFreaks (login).
#    So these two are fetched with the SAME self-validating rules as the rest:
#    if the server does not actually list files for this slug, NOTHING is
#    shown - never a wrong link. If they are missing on your box, use
#    [5] My Image Links with a direct .zip link from the team's site.
# 5) SAVED exact model: when detection is ambiguous (bare h9, ...) the pick
#    is saved once to U-Panel/.saved_device_model and reused automatically.
#    Pick [C] in the menu to forget it and pick again.
# 6) MY IMAGE LINKS: any other brand adds its OWN links in
#    U-Panel/user_image_links.conf - same verification rules as built-ins.
# FIX: device_image_pick_model used to print its menu on stdout, the same
# stream its result is captured from - the ambiguous-model path was broken.
# All prompts now go to stderr; only the picked slug goes to stdout.

# $1=zip $2=brand (vuplus/octagon/zgemma/novaler/<user brand>/any) $3=slug
image_verify_downloaded() {
  _VF="$1"; _VB="$2"; _VS="$3"
  [ -f "$_VF" ] || { echo "[VERIFY-FAIL] File missing: $_VF"; return 1; }
  _VLOW=$(basename "$_VF" | tr 'A-Z' 'a-z')
  case "$_VLOW" in *recovery*) echo "[VERIFY-FAIL] Recovery image - NEVER flash: $(basename "$_VF")"; rm -f "$_VF"; return 1 ;; esac
  is_zip_file "$_VF" || { echo "[VERIFY-FAIL] Not a ZIP - deleting: $(basename "$_VF")"; rm -f "$_VF"; return 1; }
  if command -v unzip >/dev/null 2>&1; then
    unzip -t "$_VF" >/dev/null 2>&1 || { echo "[VERIFY-FAIL] ZIP integrity test FAILED (corrupt / truncated download) - deleting, NOT flashing."; rm -f "$_VF"; return 1; }
    _VLIST=$(unzip -l "$_VF" 2>/dev/null | awk '{print $4}' | tr 'A-Z' 'a-z')
  elif command -v python3 >/dev/null 2>&1; then
    python3 -c "import sys,zipfile; z=zipfile.ZipFile(sys.argv[1]); sys.exit(1 if z.testzip() else 0)" "$_VF" 2>/dev/null || { echo "[VERIFY-FAIL] ZIP integrity test FAILED - deleting, NOT flashing."; rm -f "$_VF"; return 1; }
    _VLIST=$(python3 -c "import sys,zipfile; print('\n'.join(zipfile.ZipFile(sys.argv[1]).namelist()))" "$_VF" 2>/dev/null | tr 'A-Z' 'a-z')
  else
    echo "[VERIFY-WARN] No unzip/python3 - integrity test skipped (PK header only)."
    _VLIST=""
  fi
  case "$_VB" in
    vuplus) _VEXP="vuplus" ;;
    octagon) _VEXP="octagon" ;;
    zgemma) _VEXP="zgemma" ;;
    novaler) _VEXP="novaler" ;;
    unknown|any|"") _VEXP="" ;;
    *) _VEXP="$_VB" ;;
  esac
  # HARD REJECT: zip contains a KNOWN brand folder that is NOT this box's brand
  # (an Octagon zip must NEVER pass on a VU+ box, even if it has kernel+rootfs).
  if [ -n "$_VEXP" ]; then
    _VFOUND=$(echo "$_VLIST" | grep -oE "^(vuplus|octagon|zgemma|novaler|multibox|gigablue|dreambox|edision|formuler|uclan|mutant|xtrend|amiko|ax|dinobot|qviart|protek|hitube|izibox|airdigital)/" | sort -u | head -1)
    if [ -n "$_VFOUND" ]; then
      _VFOUND="${_VFOUND%/}"
      case "$_VFOUND" in "$_VEXP"|multibox) ;; *) echo "[VERIFY-FAIL] ZIP is for another brand (folder: $_VFOUND, this box: $_VEXP) - WRONG image - deleting, NOT flashing."; rm -f "$_VF"; return 1 ;; esac
    fi
  fi
  _VOK=0
  if [ -n "$_VEXP" ]; then
    echo "$_VLIST" | grep -q "^$_VEXP/" && _VOK=1
    [ "$_VB" = "novaler" ] && echo "$_VLIST" | grep -q "^multibox" && _VOK=1
  fi
  [ -n "$_VS" ] && echo "$_VLIST" | grep -q "^$_VS/" && _VOK=1
  [ -z "$_VEXP" ] && echo "$_VLIST" | grep -q -E "^(vuplus|octagon|zgemma|novaler|multibox|gigablue|dreambox|edision|formuler|uclan|mutant|xtrend|amiko|ax|dinobot|qviart|protek|hitube|izibox|airdigital)/" && _VOK=1
  if [ "$_VOK" = "0" ]; then
    _VK=0; _VR=0
    echo "$_VLIST" | grep -q -E "(^|/)(kernel\.bin|uimage|kernel-.*\.bin)$" && _VK=1
    echo "$_VLIST" | grep -q -E "(^|/)(rootfs\.tar\.bz2|rootfs\.tar\.gz|rootfs\.ubi|rootfs\.ext4|rootfs\.tar\.xz|disk\.img|rootfs\.jffs2)$" && _VR=1
    [ "$_VK" = "1" ] && [ "$_VR" = "1" ] && _VOK=1
    echo "$_VLIST" | grep -q -E "(^|/)imageversion$" && [ "$_VK" = "1" ] && _VOK=1
  fi
  if [ "$_VOK" = "0" ]; then
    echo "[VERIFY-FAIL] ZIP has NO folder/payload for this box (expected: ${_VEXP:-any brand folder} or kernel+rootfs) - WRONG image or corrupt - deleting, NOT flashing."
    rm -f "$_VF"; return 1
  fi
  echo "[VERIFY-OK] $(basename "$_VF") - ZIP integrity OK, content matches ${_VEXP:-this box}."
  return 0
}

image_remote_size() {
  _RS=""
  if command -v curl >/dev/null 2>&1; then _RS=$(curl -k -sI --max-time 10 "$1" 2>/dev/null | grep -i '^content-length' | tr -d '\r' | awk '{print $2}' | head -1); fi
  if [ -z "$_RS" ] && command -v wget >/dev/null 2>&1; then _RS=$(wget --no-check-certificate --spider -S "$1" 2>&1 | grep -i 'content-length' | tail -1 | awk '{print $2}'); fi
  echo "$_RS" | tr -dc '0-9'
}

# $1=URL $2=dest dir - block the download if the HDD cannot hold it
image_check_space_for() {
  _CU="$1"; _CD="${2:-/media/hdd}"
  _FREE_KB=$(df "$_CD" 2>/dev/null | tail -n 1 | awk '{print $4}'); [ -z "$_FREE_KB" ] && _FREE_KB=0
  _SZ=$(image_remote_size "$_CU")
  if [ -n "$_SZ" ]; then _NEED_KB=$(( (_SZ / 1024) + 51200 )); else _NEED_KB=307200; fi
  if [ "$_FREE_KB" -lt "$_NEED_KB" ]; then
    echo "[SPACE-FAIL] Image download blocked: need ~$((_NEED_KB/1024))MB free on $_CD, have $((_FREE_KB/1024))MB."
    [ -n "$_SZ" ] && echo "  Image size: $((_SZ/1024/1024))MB + 50MB margin."
    return 1
  fi
  echo "[SPACE-OK] Free: $((_FREE_KB/1024))MB, need ~$((_NEED_KB/1024))MB."
  return 0
}

# Full backup of the CURRENT slot before any flash. Returns 1 = do NOT flash.

# $1=URL $2=dest dir $3=brand $4=slug - ONE shared flow for ALL image downloads:
# space check -> download -> verify (bad file deleted) -> flash (slot flash cleans first)
image_download_url() {
  _DU="$1"; _DD="$2"; _DB="$3"; _DS="$4"
  mkdir -p "$_DD" 2>/dev/null; [ -d "$_DD" ] || _DD="/tmp"
  _DFN=$(basename "$_DU" | cut -d'?' -f1); [ -z "$_DFN" ] && _DFN="downloaded-image-$(date +%Y%m%d-%H%M).zip"
  case "$_DFN" in *.zip) ;; *) _DFN="$_DFN.zip" ;; esac
  echo "Saving to: $_DD/$_DFN"
  image_show_info "$_DU"
  image_check_space_for "$_DU" "$_DD" || { printf "Press ENTER... "; read _b; return 1; }
  if [ -f "$_DD/$_DFN" ]; then printf "File already exists - overwrite? (y/n): "; read _OW; case "$_OW" in y|Y) ;; *) echo "Cancelled."; return 0 ;; esac; fi
  secure_fetch_file "$_DU" "$_DD/$_DFN" "image-$_DFN"
  [ -f "$_DD/$_DFN" ] || { echo "[FAIL] Download failed - check the link / internet and try again."; printf "Press ENTER... "; read _b; return 1; }
  echo "[OK] Downloaded: $_DD/$_DFN ($(du -h "$_DD/$_DFN" 2>/dev/null | cut -f1))"
  image_verify_downloaded "$_DD/$_DFN" "$_DB" "$_DS" || { echo "Bad file deleted - download it again or pick another link."; printf "Press ENTER... "; read _b; return 1; }
  images_cleanup_keep2
  printf "Flash it now to a slot? (y/n): "; read _FL
  case "$_FL" in y|Y) upanel_flash ;; *) echo "Done - flash later from: Multiboot Manager > Flash Image to Slot" ;; esac
  printf "Press ENTER... "; read _b
  return 0
}

# /tmp/novaler_links.txt must hold "LABEL|URL" lines.
# Keeps only the NEWEST build per team, shows the list, downloads the pick.
# $1=brand $2=slug $3=saved-model flag (non-empty = [C] forget-model offered)
image_links_pick_and_download() {
  _PB="$1"; _PS="$2"; _PSAVED="$3"
  grep -E '^[^|]+\|https?://[^|]*(_multi|_usb|_mmc|_multiboot)\.zip$' /tmp/novaler_links.txt | grep -vi 'recovery' > /tmp/novaler_links_clean.txt 2>/dev/null || : > /tmp/novaler_links_clean.txt
  sort -u /tmp/novaler_links_clean.txt > /tmp/novaler_links_dedup.txt
  rm -f /tmp/novaler_links.txt; touch /tmp/novaler_links.txt
  cut -d'|' -f1 /tmp/novaler_links_dedup.txt | sort -u > /tmp/novaler_labels.txt
  while IFS= read -r _LBL; do
    [ -z "$_LBL" ] && continue
    grep -F "$_LBL|" /tmp/novaler_links_dedup.txt | sort -t'|' -k2 | while IFS='|' read -r _L _U; do _D=$(echo "$_U" | grep -oE '[0-9]{8}' | sort -n | tail -1); [ -z "$_D" ] && _D="00000000"; echo "$_D|$_L|$_U"; done | sort -r | head -1 | cut -d'|' -f2- >> /tmp/novaler_links.txt
  done < /tmp/novaler_labels.txt
  sort -u /tmp/novaler_links.txt -o /tmp/novaler_links.txt
  awk -F'|' '!seen[$2]++' /tmp/novaler_links.txt > /tmp/novaler_links2.txt && mv /tmp/novaler_links2.txt /tmp/novaler_links.txt
  echo ""
  if [ -s /tmp/novaler_links.txt ]; then
    echo "Clean-image links - pick one to download:"
    _i=0; while IFS='|' read -r _LBL3 _U; do _i=$((_i+1)); echo "  [$_i] $_LBL3 - $(basename "$_U")"; done < /tmp/novaler_links.txt
    _N=$_i
  else
    echo "[WARN] Live fetch found no .zip links (server busy / page changed)."
    echo "       Use External Link / My Image Links with the fresh URL from the team's site."
    _N=0
  fi
  echo ""
  [ -n "$_PSAVED" ] && echo "  [C] Forget saved model + pick another"
  echo "  [0] Back"
  [ "$_N" = "0" ] && { printf "Press ENTER... "; read _b; return 0; }
  printf "Pick a link to DOWNLOAD (0 = cancel): "; read _LN
  [ "$_LN" = "0" ] && return 0
  case "$_LN" in C|c) [ -n "$_PSAVED" ] && { rm -f "$(device_model_save_file)"; echo "[SAVED] Forgotten - pick your model again:"; device_image_links_menu; return 0; } ;; esac
  _SEL=$(sed -n "${_LN}p" /tmp/novaler_links.txt)
  [ -z "$_SEL" ] && { echo "Bad number."; printf "Press ENTER... "; read _b; return 0; }
  _URL=$(echo "$_SEL" | cut -d'|' -f2-)
  echo "Downloading: $_URL"
  image_download_url "$_URL" "/media/hdd" "$_PB" "$_PS"
}

# ---- Saved exact model (item 5) ----
device_model_save_file() { echo "$UPANEL_ROOT/.saved_device_model"; }
device_model_saved() {
  _SF=$(device_model_save_file); [ -f "$_SF" ] || return 1
  _SV=$(head -1 "$_SF" 2>/dev/null | tr -d ' \r\n')
  _SVB="${_SV%%:*}"; _SVM="${_SV##*:}"
  [ "$_SVB" = "$1" ] || return 1
  device_image_model_list "$1" | cut -d: -f1 | grep -qx "$_SVM" || return 1
  echo "$_SVM"
}

# Generic .zip extractor for ANY brand/team page (OpenSPA / OpenHDF / My Links).
# $1=page $2=base $3=label $4=slug - prints "LABEL|URL". Same rules as built-ins:
# filename MUST contain the exact slug, MUST end _usb/_mmc/_multiboot/_multi.zip,
# recovery ALWAYS excluded. A page that lists nothing yields NOTHING.
extract_image_zips_generic() {
  _GP="$1"; _GB="$2"; _GL="$3"; _GS="$4"
  rm -f /tmp/upanel_img_page.html
  novaler_fetch_page "$_GP" /tmp/upanel_img_page.html || return 1
  [ -f /tmp/upanel_img_page.html ] || return 1
  grep -oE 'href="[^"]*\.zip[^"]*"' /tmp/upanel_img_page.html 2>/dev/null | sed -e 's/href="//' -e 's/"$//' | sort -u | while read -r _GH; do
    case "$_GH" in http*) _GU="$_GH" ;; //*) _GU="https:$_GH" ;; /*) _GU="${_GB%/*}$_GH" ;; *) _GU="$_GB$_GH" ;; esac
    _GUL=$(echo "$_GU" | tr 'A-Z' 'a-z')
    case "$_GUL" in *"$_GS"*) ;; *) continue ;; esac
    case "$_GUL" in *recovery*) continue ;; esac
    case "$_GUL" in *_usb.zip*|*_mmc.zip*|*_multiboot.zip*|*_multi.zip*) echo "$_GL|$_GU" ;; esac
  done
}

# $1=brand $2=slug
openspa_links() { extract_image_zips_generic "https://openspa.webhop.info/" "https://openspa.webhop.info/" "OpenSPA" "$2"; }
openhdf_links() { extract_image_zips_generic "https://images.openhdf.com/" "https://images.openhdf.com/" "OpenHDF" "$2"; }

# ---- My Image Links: any other brand adds its OWN links (item 6) ----
user_links_file() { echo "$UPANEL_ROOT/user_image_links.conf"; }
user_links_ensure() {
  _UF=$(user_links_file)
  [ -f "$_UF" ] && return 0
  cat > "$_UF" <<'EOF'
# ===== My Image Links - ADD YOUR OWN BRAND (V 3.2) =====
# One brand per line. Format (fields separated by | - NO spaces around |):
# BRAND|MODEL_SLUG|MODEL_LABEL|TEAM_LABEL|PAGE_URL|BASE_URL
# BRAND      = lowercase brand name, e.g. gigablue
# MODEL_SLUG = exact model slug used in the image filenames, e.g. gbquad4k
# MODEL_LABEL= display name, e.g. GigaBlue Quad 4K
# TEAM_LABEL = image team name shown in the menu, e.g. OpenATV
# PAGE_URL   = the team's per-model download page (must list .zip links)
# BASE_URL   = base for relative links on that page (usually the page folder)
# RULES (same as built-in links, enforced by the script):
# - the .zip filename MUST contain MODEL_SLUG, MUST end _usb/_mmc/_multiboot/_multi.zip
# - recovery files are ALWAYS excluded, wrong-model files NEVER shown
# - the script NEVER guesses links: if the page lists nothing for your slug, nothing is shown
# Example (commented out - remove the # to try it):
# gigablue|gbquad4k|GigaBlue Quad 4K|OpenATV|https://images.mynonpublic.com/openatv/index.php?v=8.1&open=gbquad4k|https://images.mynonpublic.com/openatv/8.1/
EOF
  echo "[MY-LINKS] Created: $_UF"
}
user_links_entries() { user_links_ensure; grep -v '^[[:space:]]*#' "$(user_links_file)" 2>/dev/null | grep -v '^[[:space:]]*$'; }
user_links_brands() { user_links_entries | cut -d'|' -f1 | sort -u; }
# Match this box against user-added brands (brand name OR any saved model slug in the raw machine strings)
user_links_match_brand() {
  _URAW=$(device_image_raw)
  user_links_brands | while IFS= read -r _UB; do
    [ -z "$_UB" ] && continue
    case "$_URAW" in *"$_UB"*) echo "$_UB"; continue ;; esac
    _USLUGS=$(user_links_entries | awk -F'|' -v b="$_UB" '$1==b {print $2}')
    echo "$_USLUGS" | while IFS= read -r _US; do
      [ -z "$_US" ] && continue
      case "$_URAW" in *"$_US"*) echo "$_UB"; break ;; esac
    done
  done | head -1
}
user_links_add() {
  show_banner; line; info "My Image Links - Add your own brand"
  user_links_ensure
  echo "Enter the fields exactly - the script TESTS the page before saving."
  printf "Brand (lowercase, e.g. gigablue): "; read _AB
  case "$_AB" in ''|*[!a-z0-9-]*) echo "[FAIL] Brand must be lowercase letters/digits."; printf "Press ENTER... "; read _b; return 0 ;; esac
  printf "Model slug (exact, e.g. gbquad4k): "; read _AS
  case "$_AS" in ''|*[!a-z0-9_-]*) echo "[FAIL] Slug must be lowercase letters/digits."; printf "Press ENTER... "; read _b; return 0 ;; esac
  printf "Model label (e.g. GigaBlue Quad 4K): "; read _AL
  [ -z "$_AL" ] && { echo "[FAIL] Label is empty."; printf "Press ENTER... "; read _b; return 0; }
  printf "Team label (e.g. OpenATV): "; read _AT
  [ -z "$_AT" ] && { echo "[FAIL] Team is empty."; printf "Press ENTER... "; read _b; return 0; }
  printf "Page URL (team per-model page): "; read _AP
  case "$_AP" in http://*|https://*) ;; *) echo "[FAIL] Page URL must start with http:// or https://"; printf "Press ENTER... "; read _b; return 0 ;; esac
  printf "Base URL (page folder, for relative links): "; read _ABASE
  case "$_ABASE" in http://*|https://*) ;; *) echo "[FAIL] Base URL must start with http:// or https://"; printf "Press ENTER... "; read _b; return 0 ;; esac
  echo "Testing the page for .zip files with slug '$_AS'..."
  _TEST=$(extract_image_zips_generic "$_AP" "$_ABASE" "$_AT" "$_AS" | head -3)
  if [ -z "$_TEST" ]; then
    echo "[MY-LINKS-WARN] Page test found NO .zip for slug '$_AS' (page may be JS-only / down / wrong slug)."
    printf "Save anyway? (y/n): "; read _SA; case "$_SA" in y|Y) ;; *) echo "Not saved."; printf "Press ENTER... "; read _b; return 0 ;; esac
  else
    echo "[MY-LINKS-OK] Page test found:"
    echo "$_TEST" | while IFS='|' read -r _TL _TU; do echo "  $_TL - $(basename "$_TU")"; done
  fi
  echo "$_AB|$_AS|$_AL|$_AT|$_AP|$_ABASE" >> "$(user_links_file)"
  echo "[MY-LINKS] Saved: $_AB / $_AS - $_AT"
  printf "Press ENTER... "; read _b
}
user_links_delete() {
  show_banner; line; info "My Image Links - Delete a saved link"
  _UE=$(user_links_entries)
  [ -z "$_UE" ] && { echo "Nothing saved yet."; printf "Press ENTER... "; read _b; return 0; }
  echo "$_UE" | awk -F'|' '{print "  [" NR "] " $1 " / " $2 " - " $4 " (" $3 ")"}'
  _EMAX=$(echo "$_UE" | wc -l | tr -d ' ')
  echo "  [0] Cancel"
  printf "Delete which number: "; read _DN
  [ "$_DN" = "0" ] && return 0
  case "$_DN" in ''|*[!0-9]*) echo "[FAIL] Bad number."; printf "Press ENTER... "; read _b; return 0 ;; esac
  [ "$_DN" -lt 1 ] || [ "$_DN" -gt "$_EMAX" ] && { echo "[FAIL] Bad number."; printf "Press ENTER... "; read _b; return 0; }
  awk -v n="$_DN" 'BEGIN{c=0} /^[[:space:]]*#/||/^[[:space:]]*$/{print; next} {c++; if (c!=n) print}' "$(user_links_file)" > /tmp/user_links_tmp.conf && mv /tmp/user_links_tmp.conf "$(user_links_file)"
  echo "[MY-LINKS] Deleted entry $_DN."
  printf "Press ENTER... "; read _b
}
# $1=brand - pick a saved model for this brand, fetch its links, download
user_links_menu_for_brand() {
  _MB="$1"
  show_banner; line; info "My Image Links - $_MB (your own links)"
  _MODELS=$(user_links_entries | awk -F'|' -v b="$_MB" '$1==b {print $2":"$3}' | sort -u)
  [ -z "$_MODELS" ] && { echo "[FAIL] No models saved for $_MB - add one first."; printf "Press ENTER... "; read _b; return 0; }
  echo "Pick your exact model (a wrong image will NOT boot):"
  echo "$_MODELS" | awk -F: '{print "  [" NR "] " $2}'
  _MMAX=$(echo "$_MODELS" | wc -l | tr -d ' ')
  echo "  [0] Cancel"
  printf "Pick your exact model: "; read _MP
  [ "$_MP" = "0" ] && return 0
  case "$_MP" in ''|*[!0-9]*) echo "[FAIL] Bad number."; printf "Press ENTER... "; read _b; return 0 ;; esac
  [ "$_MP" -lt 1 ] || [ "$_MP" -gt "$_MMAX" ] && { echo "[FAIL] Bad number."; printf "Press ENTER... "; read _b; return 0; }
  _MSLUG=$(echo "$_MODELS" | sed -n "${_MP}p" | cut -d: -f1)
  _MLBL=$(echo "$_MODELS" | sed -n "${_MP}p" | cut -d: -f2-)
  echo "Your box: $_MLBL  |  Image slug: $_MSLUG"
  echo "Only links for THIS exact model are shown - a wrong image will NOT boot."
  echo "Fetching LIVE links from YOUR saved pages (this takes a few seconds)..."
  rm -f /tmp/novaler_links.txt; touch /tmp/novaler_links.txt
  user_links_entries | awk -F'|' -v b="$_MB" -v s="$_MSLUG" '$1==b && $2==s' | while IFS='|' read -r _B _S _L _T _PG _BS; do
    echo "--- $_T (your link) ---"
    extract_image_zips_generic "$_PG" "$_BS" "$_T" "$_S" >> /tmp/novaler_links.txt
  done
  image_links_pick_and_download "$_MB" "$_MSLUG" ""
}
user_links_menu() {
  while true; do
    show_banner; line; info "My Image Links - add your own brand (V 3.2)"
    user_links_ensure
    echo "Your saved brands:"
    _UBR=$(user_links_brands)
    if [ -z "$_UBR" ]; then _UMAX=0; echo "  (none yet - add your first brand below)"; else
      _UMAX=$(echo "$_UBR" | wc -l | tr -d ' ')
      echo "$_UBR" | awk '{print "  [" NR "] " $0}'
    fi
    echo "  [A] Add a brand / model link"
    echo "  [D] Delete a saved link"
    echo "  [0] Back"
    printf "Your choice: "; read _UC || return 0
    case "$_UC" in
      0) return 0 ;;
      A|a) user_links_add ;;
      D|d) user_links_delete ;;
      ''|*[!0-9]*) wrong_choice ;;
      *) if [ "$_UC" -ge 1 ] && [ "$_UC" -le "$_UMAX" ]; then _UB=$(echo "$_UBR" | sed -n "${_UC}p"); user_links_menu_for_brand "$_UB"; else wrong_choice; fi ;;
    esac
  done
}


# ===== Image Safety + Management - V 3.4 =====
# 1) POST-FLASH VERIFY: after flashing, the slot is remounted read-only and
#    checked (image-version + enigma2 + file count + kernel file). A slot
#    that does NOT verify is NEVER reported as done - re-flash it.
# 2) AUTO-ROLLBACK: when you SWITCH to a new slot, a guard is ARMED
#    (/boot/u-panel-rollback.conf + backup of the old /boot/STARTUP).
#    The flashed slot carries a checker (/etc/init.d/upanel-rollback):
#    ~90s after boot, if Enigma2 is NOT running, it restores the old STARTUP
#    and reboots - back to the working slot, automatically. If Enigma2 IS
#    running, the guard deletes itself. Boot Slot Manager > [9] shows/disarm.
# 3) RESUME downloads: secure_fetch keeps a partial .tmp and continues it
#    (wget -c / curl -C -) instead of restarting a 300MB image from zero.
# 4) AUTO-CLEANUP: after every download, keep the newest 2 .zip images per
#    drive, delete older ones. PINNED images are never deleted.
#    My Images > [C] runs the same cleanup manually.
# 5) SIZE + BUILD DATE before download: every download prints the image
#    size (HEAD) and build date (from the filename, else Last-Modified).
# 6) TRANSFER SETTINGS after flash: upanel_flash offers to copy channels +
#    settings + keys + oscam config from the RUNNING slot into the new slot
#    (the SAFE set - never skins/binaries). Plugins: install after first boot.
# 7) SLOT RENAME: after flash, a slot that would read "Empty / Unknown"
#    gets named from the image filename; Boot Slot Manager > [R] sets or
#    clears a custom label anytime. A real image-version always wins over
#    a stored label, and flashing a slot drops its stale label.
# 8) MY IMAGES manager: Download Image > [6] lists every downloaded .zip
#    (size, date, PINNED) with Flash / Delete / Pin-unpin / Cleanup.
# 9) PIN: My Images > [P] pins an image - auto-cleanup will never delete it.

# ---- Rollback guard (item 2) ----
rollback_guard_file() { echo "/boot/u-panel-rollback.conf"; }
rollback_startup_bak() { echo "/boot/u-panel-STARTUP.bak"; }
# $1=old slot $2=new slot - arm at SWITCH time (before reboot)
rollback_guard_arm() {
  _GO="$1"; _GN="$2"
  upanel_boot_mount; mount -o remount,rw /boot 2>/dev/null
  [ -f /boot/STARTUP ] && cp /boot/STARTUP "$(rollback_startup_bak)" 2>/dev/null
  echo "$_GO|$_GN|$(date +%Y%m%d-%H%M)" > "$(rollback_guard_file)" 2>/dev/null && sync && echo "[ROLLBACK] Guard ARMED: if SLOT $_GN fails to boot, the box returns to SLOT $_GO automatically (checked ~90s after boot)."
}
rollback_guard_status() {
  if [ -f "$(rollback_guard_file)" ]; then
    _GO=$(cut -d'|' -f1 "$(rollback_guard_file)" 2>/dev/null); _GN=$(cut -d'|' -f2 "$(rollback_guard_file)" 2>/dev/null); _GD=$(cut -d'|' -f3 "$(rollback_guard_file)" 2>/dev/null)
    echo "Rollback guard ARMED: SLOT $_GN -> back to SLOT $_GO if it fails to boot (armed $_GD)."
    printf "Disarm it? (y/n): "; read _DA; case "$_DA" in y|Y) rm -f "$(rollback_guard_file)" "$(rollback_startup_bak)"; echo "Disarmed." ;; *) echo "Kept armed." ;; esac
  else
    echo "No rollback guard armed."
  fi
  printf "Press ENTER... "; read _b
}
# $1 = rootfs dir of the JUST-FLASHED slot - install the boot-time checker there
upanel_install_rollback_checker() {
  _CD="$1"
  mkdir -p "$_CD/etc/init.d" "$_CD/etc/rc3.d" 2>/dev/null
  cat > "$_CD/etc/init.d/upanel-rollback" <<'EOF'
#!/bin/sh
# U-Panel rollback guard: if this slot was booted via U-Panel switch and
# Enigma2 never comes up, return to the previous slot automatically.
# No guard file = do nothing (normal boot).
### BEGIN INIT INFO
# Provides:          upanel-rollback
# Required-Start:    $local_fs
# Default-Start:     3
# Short-Description: U-Panel rollback guard
### END INIT INFO
_e2_running() { pidof enigma2 >/dev/null 2>&1 || ps 2>/dev/null | grep -q "[e]nigma2"; }
case "$1" in
  start)
    mount /boot 2>/dev/null
    [ -f /boot/u-panel-rollback.conf ] || exit 0
    (
      _NEW=$(cut -d'|' -f2 /boot/u-panel-rollback.conf 2>/dev/null)
      if [ -n "$_NEW" ] && [ -f "/boot/STARTUP_LINUX_$_NEW" ] && ! cmp -s /boot/STARTUP /boot/STARTUP_LINUX_$_NEW; then
        rm -f /boot/u-panel-rollback.conf /boot/u-panel-STARTUP.bak
        exit 0
      fi
      sleep 90
      _e2_running || sleep 30
      if _e2_running; then
        rm -f /boot/u-panel-rollback.conf /boot/u-panel-STARTUP.bak
        exit 0
      fi
      mount -o remount,rw /boot 2>/dev/null
      if [ -f /boot/u-panel-STARTUP.bak ] && [ -s /boot/u-panel-STARTUP.bak ]; then cp /boot/u-panel-STARTUP.bak /boot/STARTUP 2>/dev/null; for _RB_BP in /dev/mmcblk*p* /dev/sd*[0-9]*; do [ -b "$_RB_BP" ] || continue; [ "$(blkid "$_RB_BP" 2>/dev/null | grep -o 'LABEL="[^"]*"' | cut -d'"' -f2)" = "BOOT" ] || continue; _RB_MP=$(awk -v _d="$_RB_BP" '$1 == _d {print $2; exit}' /proc/mounts 2>/dev/null); if [ -n "$_RB_MP" ] && [ "$_RB_MP" != "/boot" ]; then cp /boot/u-panel-STARTUP.bak "$_RB_MP/STARTUP" 2>/dev/null; fi; done; fi
      sync
      rm -f /boot/u-panel-rollback.conf
      reboot -f 2>/dev/null; sleep 3; init 6 2>/dev/null
    ) >/dev/null 2>&1 &
    ;;
esac
exit 0
EOF
  chmod +x "$_CD/etc/init.d/upanel-rollback" 2>/dev/null
  ln -sf ../init.d/upanel-rollback "$_CD/etc/rc3.d/S99upanel-rollback" 2>/dev/null
  echo "[ROLLBACK] Guard checker installed into the new slot (arms only on switch)."
}

# ---- Post-flash verify (item 1) ----
# $1=slot - remount read-only, check image-version + enigma2 + file count + kernel
upanel_verify_after_flash() {
  _VS="$1"
  _VRS=$(upanel_root "$_VS")
  case "$_VRS" in *"|"*) _VRP="${_VRS%%|*}"; _VSUB="${_VRS#*|}" ;; *) _VRP="$_VRS"; _VSUB="" ;; esac
  [ -z "$_VRP" ] && { echo "[VERIFY-FAIL] No root partition for SLOT $_VS."; return 1; }
  _VMP=/tmp/upanel_verify_mnt; mkdir -p "$_VMP"
  mount -o ro "$_VRP" "$_VMP" 2>/dev/null || { echo "[VERIFY-FAIL] Cannot mount SLOT $_VS root for verification."; return 1; }
  _VD="$_VMP"; [ -n "$_VSUB" ] && _VD="$_VMP/$_VSUB"
  _VOK=1; _VWHY=""
  [ -f "$_VD/etc/image-version" ] || [ -f "$_VD/usr/bin/enigma2" ] || { _VOK=0; _VWHY="no image-version / enigma2 in target"; }
  if [ "$_VOK" = "1" ]; then
    _VFC=$(find "$_VD/etc" -type f 2>/dev/null | wc -l | tr -d ' '); [ -z "$_VFC" ] && _VFC=0
    [ "$_VFC" -lt 20 ] && { _VOK=0; _VWHY="too few files in /etc ($(( _VFC ))) - incomplete extraction"; }
  fi
  if [ "$_VOK" = "1" ]; then
    _VK=$(grep -oE 'kernel=[^ ]+' "/boot/STARTUP_LINUX_$_VS" 2>/dev/null | head -1 | sed 's/kernel=//')
    [ -n "$_VK" ] && [ ! -f "$_VK" ] && { _VOK=0; _VWHY="kernel file missing: $_VK"; }
  fi
  umount "$_VMP" 2>/dev/null
  if [ "$_VOK" = "1" ]; then echo "[VERIFY-OK] SLOT $_VS - image-version + enigma2 + kernel present."; return 0; fi
  echo "[VERIFY-FAIL] SLOT $_VS - $_VWHY - do NOT boot this slot, re-flash it."
  return 1
}

# ---- Transfer settings into a flashed slot (item 6) ----
# $1=slot $2=root partition $3=subdir
upanel_transfer_from_current() {
  _XS="$1"; _XRP="$2"; _XSUB="$3"
  echo "--- Transferring channels + settings + keys from SLOT $(upanel_current) into SLOT $_XS ---"
  _XMP=/tmp/upanel_xfer_mnt; mkdir -p "$_XMP"
  mount "$_XRP" "$_XMP" 2>/dev/null || { echo "[XFER-FAIL] Cannot mount SLOT $_XS."; return 1; }
  _XD="$_XMP"; [ -n "$_XSUB" ] && _XD="$_XMP/$_XSUB"
  [ -d "$_XD/etc" ] || { echo "[XFER-FAIL] No /etc in target slot."; umount "$_XMP" 2>/dev/null; return 1; }
  _XN=0
  for _XP in "etc/enigma2" "etc/tuxbox/config" "etc/CCcam.cfg" "usr/keys"; do
    [ -e "/$_XP" ] || continue
    mkdir -p "$_XD/$(dirname "$_XP")" 2>/dev/null
    if [ -d "/$_XP" ]; then cp -a "/$_XP/." "$_XD/$_XP/" 2>/dev/null && _XN=$((_XN+1)) && echo "  copied: /$_XP"
    else cp -a "/$_XP" "$_XD/$_XP" 2>/dev/null && _XN=$((_XN+1)) && echo "  copied: /$_XP"; fi
  done
  sync; umount "$_XMP" 2>/dev/null
  echo "[XFER-OK] $_XN path(s) copied (channels + settings + keys + oscam config). Install plugins after first boot (Cross-Image Restore)."
  return 0
}

# ---- Size + build date before download (item 5) ----
image_remote_head() {
  _RH_S=""; _RH_L=""
  if command -v curl >/dev/null 2>&1; then
    _RH=$(curl -k -sI --max-time 10 "$1" 2>/dev/null)
    _RH_S=$(echo "$_RH" | grep -i '^content-length' | tr -d '\r' | awk '{print $2}' | head -1)
    _RH_L=$(echo "$_RH" | grep -i '^last-modified' | cut -d' ' -f2- | tr -d '\r' | head -1)
  elif command -v wget >/dev/null 2>&1; then
    _RH=$(wget --no-check-certificate --spider -S "$1" 2>&1)
    _RH_S=$(echo "$_RH" | grep -i 'content-length' | tail -1 | awk '{print $2}')
    _RH_L=$(echo "$_RH" | grep -i 'last-modified' | tail -1 | cut -d: -f2- | sed 's/^ //')
  fi
  echo "${_RH_S}|${_RH_L}"
}
image_show_info() {
  _IU="$1"; _IFN=$(basename "$_IU" | cut -d'?' -f1)
  _IDATE=$(echo "$_IFN" | grep -oE '[0-9]{8}' | head -1)
  _IH=$(image_remote_head "$_IU"); case "$_IH" in *"|"*) _ISZ="${_IH%%|*}"; _ILM="${_IH#*|}" ;; *) _ISZ="$_IH"; _ILM="" ;; esac
  _ISZ_TXT="unknown"; [ -n "$_ISZ" ] && _ISZ_TXT="$((_ISZ/1024/1024))MB"
  _ID_TXT="unknown"
  if [ -n "$_IDATE" ]; then _ID_TXT="$(echo "$_IDATE" | cut -c1-4)-$(echo "$_IDATE" | cut -c5-6)-$(echo "$_IDATE" | cut -c7-8)"
  elif [ -n "$_ILM" ]; then _ID_TXT="$_ILM"; fi
  echo "Image: $_IFN | Size: $_ISZ_TXT | Build: $_ID_TXT"
}

# ---- Pin + cleanup (items 4 + 9) ----
image_pin_file() { echo "$UPANEL_ROOT/.pinned_images"; }
image_is_pinned() { _PF=$(image_pin_file); [ -f "$_PF" ] && grep -qxF "$1" "$_PF" 2>/dev/null; }
images_cleanup_keep2() {
  for _CD in /media/hdd /media/usb /media/mmc "$UPANEL_ROOT/Downloads"; do
    [ -d "$_CD" ] || continue
    _CNT=0
    for _ZF in $(ls -t "$_CD"/*.zip 2>/dev/null); do
      [ -f "$_ZF" ] || continue
      _CNT=$((_CNT+1)); [ "$_CNT" -le 2 ] && continue
      _ZB=$(basename "$_ZF")
      if image_is_pinned "$_ZB"; then echo "[CLEANUP] Kept (pinned): $_ZB"; continue; fi
      rm -f "$_ZF" && echo "[CLEANUP] Deleted old image: $_ZB"
    done
  done
}

# ---- My Images manager (item 8) ----
my_images_menu() {
  while true; do
    show_banner; line; info "My Images - downloaded images (HDD / USB / MMC)"
    rm -f /tmp/my_images.txt; touch /tmp/my_images.txt
    for _Z in /media/hdd/*.zip /media/usb/*.zip /media/mmc/*.zip "$UPANEL_ROOT/Downloads"/*.zip; do
      [ -f "$_Z" ] || continue
      echo "$_Z" >> /tmp/my_images.txt
    done
    sort -u /tmp/my_images.txt -o /tmp/my_images.txt
    if [ ! -s /tmp/my_images.txt ]; then echo "  (no downloaded images yet)"
    else
      _i=0; while IFS= read -r _ZP; do _i=$((_i+1))
        _ZB=$(basename "$_ZP"); _ZS=$(du -h "$_ZP" 2>/dev/null | cut -f1); _ZD=$(stat -c %y "$_ZP" 2>/dev/null | cut -d' ' -f1)
        _PIN=""; image_is_pinned "$_ZB" && _PIN=" [PINNED]"
        echo "  [$_i] $_ZB - $_ZS - $_ZD$_PIN"
      done < /tmp/my_images.txt
    fi
    echo "  [F] Flash a picked image"
    echo "  [D] Delete a picked image"
    echo "  [P] Pin / unpin a picked image (protect from cleanup)"
    echo "  [C] Cleanup - keep newest 2, delete the rest"
    echo "  [0] Back"
    printf "Your choice: "; read _MC || return 0
    case "$_MC" in
      0) return 0 ;;
      C|c) images_cleanup_keep2; printf "Press ENTER... "; read _b ;;
      F|f|D|d|P|p)
        [ -s /tmp/my_images.txt ] || { echo "No images."; printf "Press ENTER... "; read _b; continue; }
        printf "Pick image number: "; read _MP
        case "$_MP" in ''|*[!0-9]*) echo "[FAIL] Bad number."; printf "Press ENTER... "; read _b; continue ;; esac
        _MSEL=$(sed -n "${_MP}p" /tmp/my_images.txt)
        [ -z "$_MSEL" ] && { echo "Bad number."; printf "Press ENTER... "; read _b; continue; }
        case "$_MC" in
          F|f) upanel_flash ;;
          D|d) printf "Delete $(basename "$_MSEL")? Type YES / y: "; read _DY; if is_yes "$_DY"; then rm -f "$_MSEL" && echo "Deleted."; else echo "Cancelled."; fi; printf "Press ENTER... "; read _b ;;
          P|p) _PB=$(basename "$_MSEL")
            if image_is_pinned "$_PB"; then grep -vxF "$_PB" "$(image_pin_file)" > /tmp/pin_tmp 2>/dev/null && mv /tmp/pin_tmp "$(image_pin_file)"; echo "Unpinned: $_PB"
            else echo "$_PB" >> "$(image_pin_file)"; echo "Pinned: $_PB (cleanup will never delete it)"; fi
            printf "Press ENTER... "; read _b ;;
        esac ;;
      *) wrong_choice ;;
    esac
  done
}

# ---- Slot labels (item 7) ----
upanel_label_file() { echo "/boot/u-panel-slot-$1.label"; }
upanel_rename_menu() {
  show_banner; line; info "Rename a slot (custom label)"
  printf "Which SLOT (1-14, 0 = cancel)? "; read _RN
  [ "$_RN" = "0" ] && return 0
  case "$_RN" in ''|*[!0-9]*) echo "[FAIL] Bad number."; printf "Press ENTER... "; read _b; return 0 ;; esac
  echo "SLOT $_RN now: $(upanel_name "$_RN")"
  printf "New label (empty = clear custom label): "; read _NL
  upanel_boot_mount; mount -o remount,rw /boot 2>/dev/null
  if [ -z "$_NL" ]; then rm -f "$(upanel_label_file "$_RN")"; echo "Label cleared."
  else echo "$_NL" | head -c 60 > "$(upanel_label_file "$_RN")"; echo "SLOT $_RN labelled: $_NL"; fi
  printf "Press ENTER... "; read _b
}

# ===== Device Image Links - V 3.1 - Octagon / Zgemma / VU+ =====
# Verified Nov 2026 (only official servers, LIVE fetch - NO hardcoded .zip links):
# - OpenATV:  images.mynonpublic.com/openatv/index.php?v=8.1&open=<slug>  (per-model page, daily builds)
# - Egami:    image.egami-image.com/11.0/index.php?open=<slug>
# - OpenPLi:  openpli.org/download/<Brand>/<Model>  (files on downloads.openpli.org, _usb.zip + _multiboot.zip)
#              SF8008 page covers SF8008/Twin/Combo; Supreme from 9.0 up (latest file is 9.2, so OK).
#              VU+ pages exist but OpenPLi no longer actively supports Vu+ (still lists 9.2 builds).
# - OpenViX:  openvix.co.uk/index.php/downloads/<brand>-images/<model>/  (octagon-images, zgemma-images verified)
# - OpenBH:   images.openbh.net/?b=<ver>/<brand>/<model>  (?b=5.3/vuplus/vuduo4k, ?b=5.6/octagon/sf8008 verified pattern)
# - PurE2:    pur-e2.club/OU/images/index.php?dir=7.6/<slug>/
# NOT included on purpose: TeamBlue = GigaBlue ONLY (their own site says so).
# SAFETY: every source is fetched LIVE and the filename must contain THIS model's
# exact slug. A wrong guess yields NO link - never a wrong link. Recovery files
# (_recovery_emmc) are always excluded.
# DANGER this fixes: the script's FULL_MACHINE normalizer collapses h9se->h9 and
# sf8008m->sf8008, which would flash the WRONG image. So this code reads the RAW
# machine strings (no collapsing) and, when the model is ambiguous (bare h9, bare
# zgemma, ...), it ASKS the user to pick the exact model instead of guessing.
device_image_raw() {
  _R=""
  for _f in /proc/stb/info/*; do
    [ -f "$_f" ] || continue
    _R="$_R $(cat "$_f" 2>/dev/null | head -1)"
  done
  _R="$_R $(grep '^machine=' /etc/image-version 2>/dev/null | cut -d= -f2) $FULL_MACHINE $BOX $MACHINE"
  echo "$_R" | tr 'A-Z' 'a-z' | tr -d ' _.\r\n-'
}
device_image_exact_model() {
  _RAW=$(device_image_raw)
  case "$_RAW" in
    *octagon*|*sf8008*|*sf4008*|*sf3038*|*sx88*) _BR=octagon ;;
    *zgemma*|*h9*|*h7*|*h8*|*h11*|*h17*|*h10*|*h5*|*h3*|*h2*) _BR=zgemma ;;
    *vuplus*|*vuduo*|*vuuno*|*vuultimo*|*vusolo*|*vuzero*|*duo4k*|*uno4k*|*ultimo4k*|*solo4k*|*zero4k*) _BR=vuplus ;;
    *) echo "unknown:"; return 0 ;;
  esac
  case "$_BR" in
    octagon)
      case "$_RAW" in
        *sf8008supreme*) echo "octagon:sf8008supreme" ;;
        *sf8008mini*|*sf8008m*) echo "octagon:sf8008m" ;;
        *sf8008twin*) echo "octagon:sf8008twin" ;;
        *sf8008combo*) echo "octagon:sf8008combo" ;;
        *sf8008*) echo "octagon:sf8008" ;;
        *sf4008*) echo "octagon:sf4008" ;;
        *sf3038*) echo "octagon:sf3038" ;;
        *sx88v2*) echo "octagon:sx88v2" ;;
        *sx88*) echo "octagon:sx88" ;;
        *) echo "octagon:AMBIG" ;;
      esac ;;
    zgemma)
      case "$_RAW" in
        *h9combose*) echo "zgemma:h9combose" ;;
        *h9combo*) echo "zgemma:h9combo" ;;
        *h9twinse*) echo "zgemma:h9twinse" ;;
        *h9twin*) echo "zgemma:h9twin" ;;
        *h92hse*) echo "zgemma:h92hse" ;;
        *h92h*) echo "zgemma:h92h" ;;
        *h92s*) echo "zgemma:h92s" ;;
        *h9se*|*h9sse*) echo "zgemma:h9se" ;;
        *h9s*) echo "zgemma:h9s" ;;
        *h9*) echo "zgemma:AMBIG" ;;
        *h17combo*) echo "zgemma:h17combo" ;;
        *h17*) echo "zgemma:h17" ;;
        *h11*) echo "zgemma:h11" ;;
        *h10*) echo "zgemma:h10" ;;
        *h82h*) echo "zgemma:h82h" ;;
        *h8*) echo "zgemma:h8" ;;
        *h7*) echo "zgemma:h7" ;;
        *h5*) echo "zgemma:h5" ;;
        *h3*) echo "zgemma:h3" ;;
        *h2*) echo "zgemma:h2" ;;
        *) echo "zgemma:AMBIG" ;;
      esac ;;
    vuplus)
      case "$_RAW" in
        *duo4kse*) echo "vuplus:vuduo4kse" ;;
        *duo4k*) echo "vuplus:vuduo4k" ;;
        *uno4kse*) echo "vuplus:vuuno4kse" ;;
        *uno4k*) echo "vuplus:vuuno4k" ;;
        *ultimo4k*) echo "vuplus:vuultimo4k" ;;
        *solo4k*) echo "vuplus:vusolo4k" ;;
        *zero4k*) echo "vuplus:vuzero4k" ;;
        *duo2*) echo "vuplus:vuduo2" ;;
        *solo2*) echo "vuplus:vusolo2" ;;
        *solose*) echo "vuplus:vusolose" ;;
        *zero*) echo "vuplus:vuzero" ;;
        *duo*) echo "vuplus:vuduo" ;;
        *solo*) echo "vuplus:vusolo" ;;
        *) echo "vuplus:AMBIG" ;;
      esac ;;
  esac
}
device_image_model_list() {
  case "$1" in
    octagon)
      echo "sf8008:Octagon SF8008 4K"; echo "sf8008m:Octagon SF8008 MINI 4K"; echo "sf8008supreme:Octagon SF8008 Supreme"
      echo "sf8008twin:Octagon SF8008 Twin"; echo "sf8008combo:Octagon SF8008 Combo"; echo "sf4008:Octagon SF4008"
      echo "sf3038:Octagon SF3038"; echo "sx88v2:Octagon SX88 V2"; echo "sx88:Octagon SX88" ;;
    zgemma)
      echo "h9s:Zgemma H9S"; echo "h9se:Zgemma H9S SE"; echo "h92h:Zgemma H9.2H"; echo "h92hse:Zgemma H9.2H SE"; echo "h92s:Zgemma H9.2S"
      echo "h9combo:Zgemma H9 Combo"; echo "h9combose:Zgemma H9 Combo SE"; echo "h9twin:Zgemma H9 Twin"; echo "h9twinse:Zgemma H9 Twin SE"
      echo "h7:Zgemma H7S / H7C"; echo "h82h:Zgemma H8.2H"; echo "h8:Zgemma H8"; echo "h17combo:Zgemma H17 Combo"; echo "h17:Zgemma H17"
      echo "h11:Zgemma H11"; echo "h10:Zgemma H10"; echo "h5:Zgemma H5"; echo "h3:Zgemma H3"; echo "h2:Zgemma H2" ;;
    vuplus)
      echo "vuduo4k:VU+ Duo 4K"; echo "vuduo4kse:VU+ Duo 4K SE"; echo "vuuno4k:VU+ Uno 4K"; echo "vuuno4kse:VU+ Uno 4K SE"
      echo "vuultimo4k:VU+ Ultimo 4K"; echo "vusolo4k:VU+ Solo 4K"; echo "vuzero4k:VU+ Zero 4K"; echo "vuduo2:VU+ Duo2"
      echo "vusolo2:VU+ Solo2"; echo "vusolose:VU+ Solo SE"; echo "vuzero:VU+ Zero"; echo "vuduo:VU+ Duo"; echo "vusolo:VU+ Solo" ;;
  esac
}
device_image_pick_model() {
  echo "Could not detect your EXACT model - pick it (a wrong image will NOT boot):" >&2
  _i=0
  device_image_model_list "$1" | while IFS=: read -r _K _L; do _i=$((_i+1)); echo "  [$_i] $_L" >&2; done
  _MAX=$(device_image_model_list "$1" | wc -l | tr -d ' ')
  echo "  [0] Cancel" >&2
  printf "Pick your exact model: " >&2; read _P
  [ "$_P" = "0" ] && return 1
  case "$_P" in ''|*[!0-9]*) echo "[FAIL] Bad number." >&2; return 1 ;; esac
  [ "$_P" -lt 1 ] || [ "$_P" -gt "$_MAX" ] && { echo "[FAIL] Bad number." >&2; return 1; }
  _PICKED=$(device_image_model_list "$1" | sed -n "${_P}p" | cut -d: -f1)
  if [ -n "$_PICKED" ]; then
    echo "$1:$_PICKED" > "$(device_model_save_file)" 2>/dev/null
    echo "[SAVED] Model saved: $1:$_PICKED - next time it is used automatically (pick [C] in the menu to change it)." >&2
  fi
  echo "$_PICKED"
}
