    vuplus:vusolo2) echo "vusolo2|vusolo2|vuplus/vusolo2|vuplus-images/vusolo2|vuplus/vusolo2|vusolo2|vusolo2|VU+ Solo2" ;;
    vuplus:vusolose) echo "vusolose|vusolose|vuplus/vusolose|vuplus-images/vusolose|vuplus/vusolose|vusolose|vusolose|VU+ Solo SE" ;;
    vuplus:vuzero) echo "vuzero|vuzero|vuplus/vuzero|vuplus-images/vuzero|vuplus/vuzero|vuzero|vuzero|VU+ Zero" ;;
    vuplus:vuduo) echo "vuduo|vuduo|vuplus/vuduo|vuplus-images/vuduo|vuplus/vuduo|vuduo|vuduo|VU+ Duo" ;;
    vuplus:vusolo) echo "vusolo|vusolo|vuplus/vusolo|vuplus-images/vusolo|vuplus/vusolo|vusolo|vusolo|VU+ Solo" ;;
    *) echo "" ;;
  esac
}
# OpenPLi: $1 = "brand/Model" page path, $2 = file slug. Prints "OpenPLi-USB|URL" / "OpenPLi-Multiboot|URL".
# _multiboot.zip = flash via receiver "Flash Image" menu (NOT classic USB flash). _usb.zip = classic USB flash.
openpli_links() {
  [ -n "$1" ] && [ -n "$2" ] || return 1
  rm -f /tmp/pli_page.html
  novaler_fetch_page "https://openpli.org/download/$1" "/tmp/pli_page.html" || return 1
  [ -f /tmp/pli_page.html ] || return 1
  grep -oE 'href="[^"]*\.zip[^"]*"' /tmp/pli_page.html 2>/dev/null | sed -e 's/href="//' -e 's/"$//' | sort -u | while read -r _H; do
    case "$_H" in http*) _U="$_H" ;; //*) _U="https:$_H" ;; /*) _U="https://openpli.org$_H" ;; *) _U="https://downloads.openpli.org/$_H" ;; esac
    _LOW=$(echo "$_U" | tr 'A-Z' 'a-z')
    case "$_LOW" in *recovery*) continue ;; esac
    case "$_LOW" in *"-$2"-*|*"-$2"_*) ;; *) continue ;; esac
    case "$_LOW" in *_usb.zip*) echo "OpenPLi-USB|$_U" ;; *_multiboot.zip*) echo "OpenPLi-Multiboot|$_U" ;; esac
  done
}
# OpenViX: $1 = "brand-images/model" page path, $2 = file slug (Zgemma files are named zgemmah9s, ...).
openvix_links() {
  [ -n "$1" ] && [ -n "$2" ] || return 1
  rm -f /tmp/vix_page.html
  novaler_fetch_page "https://www.openvix.co.uk/index.php/downloads/$1/" "/tmp/vix_page.html" || return 1
  [ -f /tmp/vix_page.html ] || return 1
  grep -oE 'href="[^"]*\.zip[^"]*"' /tmp/vix_page.html 2>/dev/null | sed -e 's/href="//' -e 's/"$//' | sort -u | while read -r _H; do
    case "$_H" in http*) _U="$_H" ;; //*) _U="https:$_H" ;; /*) _U="https://www.openvix.co.uk$_H" ;; *) _U="https://www.openvix.co.uk/$_H" ;; esac
    _LOW=$(echo "$_U" | tr 'A-Z' 'a-z')
    case "$_LOW" in *recovery*) continue ;; esac
    case "$_LOW" in *"-$2"-*|*"-$2"_*) ;; *) continue ;; esac
    case "$_LOW" in *_mmc.zip*|*_usb.zip*) echo "OpenViX|$_U" ;; esac
  done
}
# OpenBH: $1 = "brand/model" path, $2 = file slug. Tries 6.0 then 5.6 (?b= pages are a JS app - grep may find nothing -> safe SKIP).
openbh_brand_links() {
  [ -n "$1" ] && [ -n "$2" ] || return 1
  for _V in 6.0 5.6; do
    rm -f /tmp/bh_page.html
    novaler_fetch_page "https://images.openbh.net/?b=$_V%2F$1" "/tmp/bh_page.html" || continue
    [ -f /tmp/bh_page.html ] || continue
    grep -oE 'href="[^"]*\.zip[^"]*"' /tmp/bh_page.html 2>/dev/null | sed -e 's/href="//' -e 's/"$//' | sort -u | while read -r _H; do
      case "$_H" in http*) _U="$_H" ;; //*) _U="https:$_H" ;; /*) _U="https://images.openbh.net$_H" ;; *) _U="https://images.openbh.net/$_H" ;; esac
      _LOW=$(echo "$_U" | tr 'A-Z' 'a-z')
      case "$_LOW" in *recovery*) continue ;; esac
      case "$_LOW" in *"-$2"-*|*"-$2"_*) ;; *) continue ;; esac
      case "$_LOW" in *_mmc.zip*) echo "OpenBH|$_U" ;; esac
    done > /tmp/bh_found.txt
    [ -s /tmp/bh_found.txt ] && { cat /tmp/bh_found.txt; return 0; }
  done
  return 1
}
device_image_links_menu() {
  show_banner; line; info "Image Links - Octagon / Zgemma / VU+ (official servers)"
  _DM=$(device_image_exact_model)
  _DBRAND="${_DM%%:*}"; _DMODEL="${_DM##*:}"
  _SAVED_USED=""
  if [ "$_DMODEL" = "AMBIG" ] || [ -z "$_DMODEL" ] || [ "$_DBRAND" = "unknown" ]; then
    if [ "$_DBRAND" = "unknown" ] || [ -z "$_DBRAND" ]; then
      _UM=$(user_links_match_brand)
      if [ -n "$_UM" ]; then echo "[MY-LINKS] Brand not built-in - using YOUR saved links for: $_UM"; user_links_menu_for_brand "$_UM"; return 0; fi
      echo "[FAIL] Could not detect your box brand (FULL_MACHINE=$FULL_MACHINE)."
      echo "       Add it yourself: Download Image > [5] My Image Links."
      printf "Press ENTER... "; read _b; return 0
    fi
    _DMODEL=$(device_model_saved "$_DBRAND")
    if [ -n "$_DMODEL" ]; then echo "[SAVED] Using your saved model: $_DMODEL (pick [C] below to change it)"; _SAVED_USED=1
    else _DMODEL=$(device_image_pick_model "$_DBRAND") || return 0; fi
    [ -z "$_DMODEL" ] && return 0
  fi
  _P=$(device_image_source_params "$_DBRAND:$_DMODEL")
  [ -z "$_P" ] && { echo "[FAIL] No image sources known for $_DBRAND/$_DMODEL."; printf "Press ENTER... "; read _b; return 0; }
  _ATV=$(echo "$_P" | cut -d'|' -f1); _EGAMI=$(echo "$_P" | cut -d'|' -f2); _PLI=$(echo "$_P" | cut -d'|' -f3)
