  _VIXFILE=$(echo "$_P" | cut -d'|' -f7); _LBL=$(echo "$_P" | cut -d'|' -f8)
  echo "Your box: $_LBL  |  Image slug: $_ATV"
  echo "Only links for THIS exact model are shown - a wrong image will NOT boot."
  echo ""
