  extract_zips_from_page "https://images.mynonpublic.com/openatv/index.php?v=8.0&open=$_ATV" "https://images.mynonpublic.com/openatv/8.0/" "OpenATV 8.0" >> /tmp/novaler_links.txt
  echo "--- Egami (clean images) ---"
