    *) return 1 ;;
  esac
}
cross_preload_cache() {
  # $1 = optional source plugins dir (default CROSS_SRC_PLUGINS). Downloads, WITHOUT installing:
  #   a) Packages (PACKAGESPY3) -> Cross-Cache/packages/*.ipk  (online: opkg download | offline: reuse already-cached)
  #   b) Plugin .ipk from feed -> Cross-Cache/<plugin>.ipk (opkg download, no install)
  #   c) Plugin installer .sh -> Cross-Cache/setup-installers/<plugin>.sh (+ sha256) (secure_fetch only, NOT run)
  # After this, cross_image_restore_plugins can run fully OFFLINE. Safe to run twice (skips what is cached).
  _PL_SRC="${1:-$CROSS_SRC_PLUGINS}"
  [ -d "$_PL_SRC" ] || { echo "[PRELOAD] No source plugins dir: $_PL_SRC - pick source first (1)"; return 1; }
  # V35: same guard - preload downloads packages + installers, must not start on a full HDD.
  check_hdd_space "Cross Preload Cache" || return 1
  line; info "Cross Preload Cache - download Packages + Plugins NOW (online) so Cross Restore works OFFLINE later"
  _PC_DIR="$(cross_cache_dir)"; _PC_SRC="$(cross_cache_src_dir)"
  mkdir -p "$_PC_DIR/packages" "$_PC_DIR/setup-installers" 2>/dev/null
  if [ -n "$_PC_SRC" ]; then mkdir -p "$_PC_SRC/packages" "$_PC_SRC/setup-installers" 2>/dev/null; fi
  _ONLINE=0; check_net 2>/dev/null && _ONLINE=1
  if [ "$_ONLINE" = "0" ]; then echo "[PRELOAD] OFFLINE - no downloads possible. Showing what is ALREADY cached:"; echo "  .ipk: $(ls "$_PC_DIR"/*.ipk "$_PC_SRC"/*.ipk 2>/dev/null | wc -l) | installers: $(ls "$_PC_DIR"/setup-installers/*.sh "$_PC_SRC"/setup-installers/*.sh 2>/dev/null | wc -l) | packages: $(ls "$_PC_DIR"/packages/*.ipk "$_PC_SRC"/packages/*.ipk 2>/dev/null | wc -l)"; return 0; fi
  # --- a) Packages ---
  _PKG_OK=0; _PKG_MISS=""
  for _PP in $PACKAGESPY3; do
    _PPF="$_PC_DIR/packages/${_PP}_cached.ipk"
    if [ -f "$_PPF" ] || ls "$_PC_DIR/packages/${_PP}_"*.ipk "$_PC_DIR/packages/${_PP}-"*.ipk 2>/dev/null | head -1 | grep -q .; then _PKG_OK=$((_PKG_OK+1)); continue; fi
    (cd "$_PC_DIR/packages" && opkg download "$_PP" >/dev/null 2>&1)
    if ls "$_PC_DIR/packages/${_PP}_"*.ipk "$_PC_DIR/packages/${_PP}-"*.ipk 2>/dev/null | head -1 | grep -q .; then _PKG_OK=$((_PKG_OK+1)); else _PKG_MISS="$_PKG_MISS $_PP"; fi
  done
  echo "  [PRELOAD] Packages: cached $_PKG_OK / missing:$_PKG_MISS"
  # --- b+c) Plugins from source list ---
  _PLUGS=""; [ -f "$_PL_SRC/plugins_extensions.txt" ] && _PLUGS="$(cat "$_PL_SRC/plugins_extensions.txt")"
  _IPK_OK=0; _INS_OK=0; _MISS=""
  for _PL in $_PLUGS; do
    _PLN="$(cross_cache_name "$_PL")"
    # .ipk from feed (only if not already cached)
    if [ ! -f "$_PC_DIR/$_PLN.ipk" ] && [ ! -f "$_PC_SRC/$_PLN.ipk" ]; then
      _PLPKG="$(grep -i -m1 "$_PL" "$_PL_SRC/plugins_opkg.txt" 2>/dev/null | awk '{print $1}')"
      if [ -n "$_PLPKG" ]; then (cd "$_PC_DIR" && opkg download "$_PLPKG" >/dev/null 2>&1); _GOT="$(ls "$_PC_DIR/${_PLPKG}_"*.ipk "$_PC_DIR/${_PLPKG}-"*.ipk 2>/dev/null | head -1)"; if [ -n "$_GOT" ]; then cp -a "$_GOT" "$_PC_DIR/$_PLN.ipk" 2>/dev/null; rm -f "$_GOT"; echo "$_PLN,$_PLPKG,$(md5sum "$_PC_DIR/$_PLN.ipk" 2>/dev/null | cut -d' ' -f1),$(date +%Y-%m-%d)" >> "$_PC_DIR/manifest.csv" 2>/dev/null; _IPK_OK=$((_IPK_OK+1)); fi; fi
    else _IPK_OK=$((_IPK_OK+1)); fi
    # installer .sh (download-only, never run here)
    if [ ! -f "$_PC_DIR/setup-installers/$_PLN.sh" ] && [ ! -f "$_PC_SRC/setup-installers/$_PLN.sh" ]; then
      _URL="$(cross_installer_url "$_PL")" || continue
      if secure_fetch "$_URL" "$_PC_DIR/setup-installers/$_PLN.sh" "$_PLN" "" 2>/dev/null; then sha256sum "$_PC_DIR/setup-installers/$_PLN.sh" 2>/dev/null | cut -d' ' -f1 > "$_PC_DIR/setup-installers/$_PLN.sh.sha256" 2>/dev/null; _INS_OK=$((_INS_OK+1)); else rm -f "$_PC_DIR/setup-installers/$_PLN.sh"; _MISS="$_MISS $_PL"; fi
    else _INS_OK=$((_INS_OK+1)); fi
  done
  # Mirror global cache into portable backup cache (so it travels with the backup)
  if [ -n "$_PC_SRC" ] && [ "$_PC_SRC" != "$_PC_DIR" ]; then cp -a "$_PC_DIR"/*.ipk "$_PC_SRC/" 2>/dev/null; cp -a "$_PC_DIR"/packages/*.ipk "$_PC_SRC/packages/" 2>/dev/null; cp -a "$_PC_DIR"/setup-installers/*.sh "$_PC_SRC/setup-installers/" 2>/dev/null; cp -a "$_PC_DIR"/setup-installers/*.sha256 "$_PC_SRC/setup-installers/" 2>/dev/null; cp -a "$_PC_DIR/manifest.csv" "$_PC_SRC/manifest.csv" 2>/dev/null; fi
  echo "  [PRELOAD] Plugins .ipk cached: $_IPK_OK | installers cached: $_INS_OK | still missing:$_MISS"
  echo "  [PRELOAD] Done - Cross Restore can now run OFFLINE from: $_PC_DIR (+ portable copy in backup)"
  log_msg "Cross preload done: pkgs=$_PKG_OK ipk=$_IPK_OK installers=$_INS_OK miss=$_MISS"
  return 0
}

# ===== CROSS CACHE (V28) =====
# Problem: SMART download needs net every time. Fix: cache the RESULT of every successful download.
#   Cache = a rebuilt .ipk (from the installed package, via rebuild_ipk_from_installed - same helper Offline uses)
#   Two places, checked in this order:
#     1) <source backup>/cross-cache/  - PORTABLE, travels inside CrossImage-Backup itself (works on a fresh image, no net)
#     2) $UPANEL_ROOT-Cross-Cache/ - GLOBAL, shared by all Cross restores on this box
#   After ANY successful download (feed / installer / Custom), the installed package is rebuilt into .ipk
#   and saved to BOTH places. Next restore: cache hit -> opkg install <cached .ipk> -> py_compile -> done, no net.
#   Manifest: cross-cache/manifest.csv = plugin,pkg,md5,date - so a stale/corrupt .ipk is detected, not trusted blind.
cross_cache_dir() { echo "$UPANEL_ROOT-Cross-Cache"; }
cross_cache_src_dir() { if [ -n "${CROSS_SRC_ROOT:-}" ] && [ -d "$CROSS_SRC_ROOT/cross-cache" ]; then echo "$CROSS_SRC_ROOT/cross-cache"; elif [ -n "${CROSS_SRC_PLUGINS:-}" ] && [ -d "$(dirname "$CROSS_SRC_PLUGINS")/cross-cache" ]; then echo "$(dirname "$CROSS_SRC_PLUGINS")/cross-cache"; else echo ""; fi; }
cross_cache_name() { echo "$1" | tr 'A-Z' 'a-z' | tr -cd 'a-z0-9_.-'; }
cross_cache_ipk() { # V32 FIX: portable (per-source-backup) FIRST, then Unified, then legacy global.
  # Portable belongs to THIS backup (this image/Python) - it must win over Unified, which is shared across images.
  _CCN="$(cross_cache_name "$1")"
  for _CCD in "$(cross_cache_src_dir)"; do
    [ -n "$_CCD" ] || continue
    if [ -f "$_CCD/$_CCN.ipk" ]; then echo "$_CCD/$_CCN.ipk"; return 0; fi
  done
  for _CCD in "$(cross_cache_dir)"; do
    [ -n "$_CCD" ] || continue
    if [ -f "$_CCD/$_CCN.ipk" ]; then echo "$_CCD/$_CCN.ipk"; return 0; fi
  done
  return 1
}
cross_cache_save() {
  # $1=plugin $2=opkg pkg (may be empty) - rebuild .ipk from installed pkg, save to global + portable-if-known, update manifest
  _CS_P="$1"; _CS_PKG="$2"; [ -n "$_CS_P" ] || return 1
  _CSN="$(cross_cache_name "$_CS_P")"
  _CS_TMP="/tmp/cross_cache_save_$$.ipk"; rm -f "$_CS_TMP"
  if [ -n "$_CS_PKG" ]; then
    rebuild_ipk_from_installed "$_CS_PKG" "$_CS_TMP" >/dev/null 2>&1 || { rm -f "$_CS_TMP"; return 1; }
  else
    # No opkg pkg (installer-only plugin): no .ipk to rebuild - installer itself is already in Setup-Cache via secure_run
    return 1
  fi
  [ -f "$_CS_TMP" ] || return 1
  _CS_MD5="$(md5sum "$_CS_TMP" 2>/dev/null | cut -d' ' -f1)"
  for _CCD in "$(cross_cache_dir)" "$(cross_cache_src_dir)"; do
    [ -n "$_CCD" ] || continue
    mkdir -p "$_CCD" 2>/dev/null
    cp -a "$_CS_TMP" "$_CCD/$_CSN.ipk" 2>/dev/null
    grep -v "^$_CSN," "$_CCD/manifest.csv" 2>/dev/null > "$_CCD/manifest.csv.tmp" 2>/dev/null; mv "$_CCD/manifest.csv.tmp" "$_CCD/manifest.csv" 2>/dev/null
    echo "$_CSN,$_CS_PKG,$_CS_MD5,$(date +%Y-%m-%d)" >> "$_CCD/manifest.csv" 2>/dev/null
    echo "  [CROSS-CACHE] Saved: $_CS_P -> $_CCD/$_CSN.ipk (md5 ${_CS_MD5})"
  done
  rm -f "$_CS_TMP"; return 0
}
cross_cache_restore() {
  # $1=plugin $2=opkg pkg - try cached .ipk, verify md5 vs manifest if present, install, py_compile
  _CR_P="$1"; _CR_PKG="$2"; _CR_IPK="$(cross_cache_ipk "$_CR_P")" || return 1
  [ -f "$_CR_IPK" ] || return 1
  _CR_DIR="$(dirname "$_CR_IPK")"; _CRN="$(cross_cache_name "$_CR_P")"
  if [ -f "$_CR_DIR/manifest.csv" ]; then
    _CR_EXP="$(grep "^$_CRN," "$_CR_DIR/manifest.csv" 2>/dev/null | cut -d, -f3 | tail -1)"
    if [ -n "$_CR_EXP" ]; then _CR_GOT="$(md5sum "$_CR_IPK" 2>/dev/null | cut -d' ' -f1)"; if [ "$_CR_GOT" != "$_CR_EXP" ]; then echo "  [CROSS-CACHE] STALE/CORRUPT: $_CR_P cached .ipk md5 mismatch - ignoring cache"; return 1; fi; fi
  fi
  echo "  [CROSS-CACHE] HIT: $_CR_P <- $_CR_IPK (no net needed)"
  if command -v opkg >/dev/null 2>&1; then opkg install "$_CR_IPK" >/dev/null 2>&1 || opkg install --force-reinstall "$_CR_IPK" >/dev/null 2>&1 || return 1;
  elif command -v apt-get >/dev/null 2>&1; then apt-get install -y "$_CR_IPK" >/dev/null 2>&1 || return 1; else return 1; fi
  if ls /usr/lib/enigma2/python/Plugins/Extensions/"$_CR_P"/*.py >/dev/null 2>&1; then python3 -m py_compile /usr/lib/enigma2/python/Plugins/Extensions/"$_CR_P"/*.py 2>/dev/null || { echo "  [CROSS-CACHE] cached .ipk failed py_compile - falling through to download"; return 1; }; fi
  echo "  [SMART-OK] $_CR_P from CROSS-CACHE"; return 0
}


# ===== CROSS <-> SETUP-CACHE BRIDGE (V29) =====
# Question: can Cross use the SAME cache as "Setup your Enigma"?
# Answer: YES - but NOT by copying Setup-Cache as-is. Why:
#   Setup-Cache saves installers by LABEL (myinstaller.sh / installer.sh), and MANY plugins share the same
#   label (see mapping below). Copying it blindly could run the WRONG plugin's installer.
# Fix: Cross keeps its OWN Setup cache, keyed by PLUGIN NAME, with a sha256 sidecar:
#   <backup>/cross-cache/setup-installers/<plugin>.sh  +  <plugin>.sh.sha256   (portable, travels with backup)
#   $UPANEL_ROOT-Cross-Cache/setup-installers/<plugin>.sh (global)
# How it fills: right AFTER a successful installer download in cross_download_plugin, secure_run has JUST
#   saved that plugin's installer under its label - we copy that exact file to <plugin>.sh (mapping is
#   correct at that moment, because the file was just fetched for THIS plugin). Next restore: run
#   <plugin>.sh directly - no net, no label collision, hash verified.
# The CURRENT image's Setup-Cache is still used as a last resort via secure_run's own fallback (existing
# behaviour): if you already ran "Setup your Enigma" on the NEW image, its cached installer is tried
# when the download fails. That path is label-based, so it stays as fallback only, never as first choice.
cross_installer_label() {
  case "$(echo "$1" | tr 'A-Z' 'a-z')" in
    mystreamer) echo "myinstaller.sh" ;;
    novalerdownloader) echo "myinstaller.sh" ;;
    ajpanel) echo "installer.sh" ;;
    subssupportpro) echo "myinstaller.sh" ;;
    internet-speedtest) echo "internet-speedtest.sh" ;;
    emuinstaller) echo "myinstaller.sh" ;;
    ipaudiopro) echo "installer.sh" ;;
    epg-grabber) echo "installer.sh" ;;
    emilremovepackage) echo "EmilRemovePackage.sh" ;;
    customchannelselection) echo "myinstaller.sh" ;;
    crashlogviewer) echo "crashlogviewer_1.9.sh" ;;
    cacheflush) echo "myinstaller.sh" ;;
    bitrate) echo "bitrate.sh" ;;
    autozap-recovery) echo "installer.sh" ;;
    arabicsavior) echo "myinstaller.sh" ;;
    buttonpatcher) echo "myinstaller.sh" ;;
    footonsat) echo "installer.sh" ;;
    lukatv) echo "myinstaller.sh" ;;
    novalerstore) echo "novalerStore.sh" ;;
    ipaudiplus) echo "ipaudioplus.sh" ;;
    pli) echo "installer.sh" ;;
    aglare-fhd) echo "installer.sh" ;;
    raedquicksignal) echo "installer.sh" ;;
    newvirtualkeyboard) echo "installer.sh" ;;
    autobiss) echo "AutoBiss.sh" ;;
    auto-dcw-key-add) echo "auto-dcw-key-add.sh" ;;
    furybiss) echo "installer.sh" ;;
    hisnmuslim) echo "hisnmuslim.sh" ;;
    netusagepro) echo "netusagepro.sh" ;;
    quran) echo "installer.sh" ;;
    subextractorlite) echo "installer.sh" ;;
    furyskin) echo "installer.sh" ;;
    lukaatv-skin) echo "installer.sh" ;;
    enigmaplay-repo) echo "install.sh" ;;
    mohamedstore) echo "install.sh" ;;
    servercoloring-fury) echo "installer.sh" ;;
    sherlockmod) echo "installer.sh" ;;
    bouquetmakerxtream) echo "installer.sh" ;;
    neoboot-fury) echo "installer.sh" ;;
    *) echo "installer.sh" ;;
  esac
}
cross_setup_cache_file() { # V32 FIX: same order - portable first, then Unified, then legacy global
  _CSX_P="$(cross_cache_name "$1")"
  for _CSX_D in "$(cross_cache_src_dir)"; do
    [ -n "$_CSX_D" ] || continue
    if [ -f "$_CSX_D/setup-installers/$_CSX_P.sh" ]; then echo "$_CSX_D/setup-installers/$_CSX_P.sh"; return 0; fi
    if [ -f "$_CSX_D/$_CSX_P.sh" ]; then echo "$_CSX_D/$_CSX_P.sh"; return 0; fi
  done
  for _CSX_D in "$(cross_cache_dir)/setup-installers"; do
    [ -n "$_CSX_D" ] || continue
    if [ -f "$_CSX_D/setup-installers/$_CSX_P.sh" ]; then echo "$_CSX_D/setup-installers/$_CSX_P.sh"; return 0; fi
    if [ -f "$_CSX_D/$_CSX_P.sh" ]; then echo "$_CSX_D/$_CSX_P.sh"; return 0; fi
  done
  return 1
}
cross_setup_cache_save() {
  # $1=plugin - copy the JUST-downloaded installer (by label) from current Setup-Cache to per-plugin Cross Setup-Cache
  _CSS_P="$1"; [ -n "$_CSS_P" ] || return 1
  _CSS_LABEL="$(cross_installer_label "$_CSS_P")"
  _CSS_SRC="$(setup_cache_dir)/installers/$_CSS_LABEL"
  [ -f "$_CSS_SRC" ] || return 1
  _CSS_N="$(cross_cache_name "$_CSS_P")"
  _CSS_MD5="$(sha256sum "$_CSS_SRC" 2>/dev/null | cut -d' ' -f1)"
  for _CSS_D in "$(cross_cache_dir)/setup-installers" "$(cross_cache_src_dir)/setup-installers"; do
    [ -n "$_CSS_D" ] || continue
    mkdir -p "$_CSS_D" 2>/dev/null
    cp -a "$_CSS_SRC" "$_CSS_D/$_CSS_N.sh" 2>/dev/null
    echo "$_CSS_MD5" > "$_CSS_D/$_CSS_N.sh.sha256" 2>/dev/null
    echo "  [CROSS-SETUP-CACHE] Saved installer: $_CSS_P -> $_CSS_D/$_CSS_N.sh (from label $_CSS_LABEL)"
  done
  return 0
}
cross_setup_cache_run() {
  # $1=plugin - run per-plugin cached installer, hash-verified, no net
  _CSR_P="$1"; _CSR_F="$(cross_setup_cache_file "$_CSR_P")" || return 1
  [ -f "$_CSR_F" ] || return 1
  if [ -f "$_CSR_F.sha256" ]; then
    _CSR_EXP="$(cat "$_CSR_F.sha256" 2>/dev/null | tr -d ' \n')"; _CSR_GOT="$(sha256sum "$_CSR_F" 2>/dev/null | cut -d' ' -f1)"
    if [ -n "$_CSR_EXP" ] && [ "$_CSR_EXP" != "$_CSR_GOT" ]; then echo "  [CROSS-SETUP-CACHE] STALE/CORRUPT: $_CSR_P cached installer hash mismatch - ignoring"; return 1; fi
  fi
  echo "  [CROSS-SETUP-CACHE] HIT: $_CSR_P <- $_CSR_F (no net needed)"
  setup_reboot_guard "Cross Setup-Cache $_CSR_P"
  /bin/sh "$_CSR_F"; _CSR_RC=$?
  if [ "$_CSR_RC" = "0" ] && ls /usr/lib/enigma2/python/Plugins/Extensions/"$_CSR_P" >/dev/null 2>&1; then echo "  [SMART-OK] $_CSR_P from CROSS-SETUP-CACHE"; return 0; fi
  echo "  [CROSS-SETUP-CACHE] installer rc=$_CSR_RC or plugin folder missing - falling through"
  return 1
}

# ===== SMART CROSS-IMAGE PLUGINS RESTORE (V27) =====
# Rule: NEVER copy a plugin across images if it cannot work there.
#   NEEDS-DOWNLOAD if ANY of: SystemPlugin | has .so in source tarball | Python differs + plugin is known-installer
#   DOWNLOAD order per plugin: 1) current-image feed (opkg)  2) original installer URL (install_plugin_by_num / secure_run)
#                              3) Custom plugin command (if it was a Custom plugin)
#   COPY only: pure-.py plugins, same Python, no .so, not SystemPlugin - via the SAME normal restore logic,
#              but on a FILTERED temp copy of the source backup (download-set stripped from tarball + opkg list).
#   If NO net: warn + fall back to old same-logic copy (nothing downloaded), never silently break the image.
cross_plugin_known_num() {
  _CQ="$(echo "$1" | tr 'A-Z' 'a-z')"
  _CI=1; for _CP in $PLUGINS; do if [ "$(echo "$_CP" | tr 'A-Z' 'a-z')" = "$_CQ" ]; then echo "$_CI"; return 0; fi; _CI=$((_CI+1)); done
  return 1
}
cross_plugin_has_so() {
  # $1 = plugin folder name, $2 = source plugins dir
  _CSO_PLUG="$1"; _CSO_DIR="$2"
  if [ -f "$_CSO_DIR/plugins.tar.gz" ]; then
    # match: FootOnsat/x.so | ./FootOnsat/x.so | Extensions/FootOnsat/x.so - any depth, any prefix
    tar -tzf "$_CSO_DIR/plugins.tar.gz" 2>/dev/null | grep -i -E -q "(^|/)${_CSO_PLUG}/[^ ]*\.so(\.[0-9]+)*$" && return 0
  fi
  return 1
}
cross_plugin_needs_download() {
  # $1 = plugin name, $2 = source plugins dir ; return 0 = download, 1 = safe to copy
  _CN="$1"; _CD="$2"
  case "$_CN" in *SystemPlugins*|*systemplugins*) return 0;; esac
  _CNLOW="$(echo "$_CN" | tr 'A-Z' 'a-z')"
  for _CB in $CROSS_SYS_BLACKLIST; do if [ "$(echo "$_CB" | tr 'A-Z' 'a-z')" = "$_CNLOW" ]; then return 0; fi; case "$_CNLOW" in *systemplugins*) return 0;; esac; done
  cross_plugin_has_so "$_CN" "$_CD" && return 0
  _SPY="$(echo "$CROSS_SRC_PY" | sed 's/Python//')"
  if [ "$CROSS_SRC_PY" != "__FLAT__" ] && [ -n "$_SPY" ] && [ "$_SPY" != "$PY_MM" ]; then
    # Python differs: known-installer plugins are rebuilt from net (their installer picks the right Python);
    # unknown pure-py plugins stay copyable - verify step will catch any that still fail.
    cross_plugin_known_num "$_CN" >/dev/null 2>&1 && return 0
  fi
  return 1
}
cross_download_plugin() {
  # $1 = plugin name, $2 = opkg package name (may be empty) ; return 0 = installed+compiles, 1 = failed
  _CDP="$1"; _CDPKG="$2"
  _CDLOW="$(echo "$_CDP" | tr 'A-Z' 'a-z')"
  # 0) CROSS-CACHE (.ipk) first - portable (inside source backup) then global - NO net needed
  if cross_cache_restore "$_CDP" "$_CDPKG"; then return 0; fi
  # 0b) CROSS-SETUP-CACHE (per-plugin installer, hash-verified) - SAME cache idea as Setup your Enigma,
  #     but keyed by plugin name so label collisions (myinstaller.sh) cannot run the wrong installer
  if cross_setup_cache_run "$_CDP"; then cross_cache_save "$_CDP" "$_CDPKG"; return 0; fi
  # 1) Current-image feed first (correct Python + correct deps for THIS image)
  if [ -n "$_CDPKG" ] && ! offline_is_on 2>/dev/null; then
    echo "  [SMART-DOWNLOAD] $_CDP: feed first -> opkg install $_CDPKG"
    if opkg_with_retry "$_CDPKG" 2>/dev/null; then
      if ls /usr/lib/enigma2/python/Plugins/Extensions/"$_CDP"/*.py >/dev/null 2>&1; then
        if python3 -m py_compile /usr/lib/enigma2/python/Plugins/Extensions/"$_CDP"/*.py 2>/dev/null; then echo "  [SMART-OK] $_CDP from feed"; cross_cache_save "$_CDP" "$_CDPKG"; return 0; fi
      else echo "  [SMART-OK] $_CDP from feed (no .py to compile)"; cross_cache_save "$_CDP" "$_CDPKG"; return 0; fi
      echo "  [SMART-WARN] $_CDP from feed failed py_compile - trying installer..."
    else echo "  [SMART-WARN] $_CDP not in feed / opkg failed - trying installer..."; fi
  fi
  # 2) Original installer (known PLUGINS list) - secure_run already caches the installer in Setup-Cache
  _CDNUM="$(cross_plugin_known_num "$_CDP")"
  if [ -n "$_CDNUM" ]; then
    echo "  [SMART-DOWNLOAD] $_CDP: installer #$_CDNUM (secure_run, hash-pinned)"
    install_plugin_by_num "$_CDNUM" >/tmp/cross_dl_$$.log 2>&1; _CDRC=$?
    tail -n 3 /tmp/cross_dl_$$.log 2>/dev/null; rm -f /tmp/cross_dl_$$.log
    if [ "$_CDRC" = "0" ] && ls /usr/lib/enigma2/python/Plugins/Extensions/"$_CDP" >/dev/null 2>&1; then echo "  [SMART-OK] $_CDP from installer"; cross_cache_save "$_CDP" "$_CDPKG"; cross_setup_cache_save "$_CDP"; return 0; fi
    echo "  [SMART-WARN] $_CDP installer rc=$_CDRC"
  fi
  # 3) Custom plugin (was added by user as telnet command)
  if [ -f "$(custom_file)" ]; then
    _CCN=0; while IFS=$(printf '\t') read -r _ccat _cname _ccmd; do _CCN=$((_CCN+1)); if [ "$(echo "$_cname" | tr 'A-Z' 'a-z')" = "$_CDLOW" ]; then echo "  [SMART-DOWNLOAD] $_CDP: Custom plugin C$_CCN"; custom_run_by_num "$_CCN" >/tmp/cross_dl_$$.log 2>&1; _CDRC=$?; tail -n 3 /tmp/cross_dl_$$.log 2>/dev/null; rm -f /tmp/cross_dl_$$.log; [ "$_CDRC" = "0" ] && { echo "  [SMART-OK] $_CDP from Custom command"; cross_cache_save "$_CDP" "$_CDPKG"; return 0; }; fi; done < "$(custom_file)"
  fi
  echo "  [SMART-FAIL] $_CDP: no cache / no feed / no installer / no Custom command - SKIPPED (not copied, image stays safe)"
  return 1
}
cross_install_cached_packages() {
  # V33: the step V30/V31/V32 were MISSING - preload DOWNLOADED packages to cache, but NOTHING ever INSTALLED them.
  # This installs PACKAGESPY3 before Cross Plugins/All restore, so plugins that need those system packages work.
  # Order per package: portable Cross packages (this backup) -> global Cross packages
  #   -> if ONLINE: feed (opkg install). If OFFLINE: cache only, ZERO net calls.
  #   V3.6: NO Unified, NO Offline-Cache here - Cross reads ONLY its own cache.
  # Already-installed packages are skipped. Missing + offline = warning only, restore continues (plugins may still work).
  line; info "Cross Packages - installing system packages BEFORE Plugins (portable Cross -> global Cross -> feed)"
  _CP_ONLINE=0; check_net 2>/dev/null && _CP_ONLINE=1
  _CP_OK=0; _CP_SKIP=0; _CP_MISS=""
  for _CP in $PACKAGESPY3; do
    if is_installed "$_CP"; then _CP_SKIP=$((_CP_SKIP+1)); continue; fi
    _CP_F=""
    for _CPD in "$(cross_cache_src_dir)/packages" "$(cross_cache_dir)/packages"; do
      [ -n "$_CPD" ] || continue
      _CP_F="$(ls "$_CPD/${_CP}_"*.ipk "$_CPD/${_CP}-"*.ipk "$_CPD/${_CP}.ipk" "$_CPD/${_CP}_"*.deb "$_CPD/${_CP}-"*.deb 2>/dev/null | head -1)"
      [ -n "$_CP_F" ] && break
    done
    if [ -n "$_CP_F" ]; then
      if command -v dpkg >/dev/null 2>&1 && [ "${_CP_F##*.}" = "deb" ]; then dpkg -i "$_CP_F" >/dev/null 2>&1 && _CP_OK=$((_CP_OK+1)) || _CP_MISS="$_CP_MISS $_CP"; else opkg install "$_CP_F" >/dev/null 2>&1 && _CP_OK=$((_CP_OK+1)) || _CP_MISS="$_CP_MISS $_CP"; fi
      echo "  [CROSS-PACKAGES] $_CP <- cache: $_CP_F"
    elif [ "$_CP_ONLINE" = "1" ]; then
      opkg install "$_CP" >/dev/null 2>&1 && { _CP_OK=$((_CP_OK+1)); echo "  [CROSS-PACKAGES] $_CP <- feed (online)"; } || _CP_MISS="$_CP_MISS $_CP"
    else
      echo "  [CROSS-PACKAGES] SKIP $_CP - not cached + OFFLINE (restore continues)"; _CP_MISS="$_CP_MISS $_CP"
    fi
  done
  echo "  [CROSS-PACKAGES] Done: installed $_CP_OK | already-installed $_CP_SKIP | missing:$_CP_MISS"
  log_msg "Cross packages: installed=$_CP_OK already=$_CP_SKIP missing=$_CP_MISS"
  return 0
}
cross_image_restore_plugins() {
  [ -d "$CROSS_SRC_PLUGINS" ] || { echo "[CROSS] No Plugins backup in source: $CROSS_SRC_PLUGINS"; return 1; }
  setup_reboot_guard "Cross-Image Plugins SMART"
  cross_image_snapshot
  # V3.6: NO merge, NO Unified - Cross reads ONLY its own cache (portable + global).
  # V33 FIX: old trigger counted ONLY .ipk - one cached .ipk skipped ALL package downloads. Now: preload if packages OR plugins are missing.
  if check_net 2>/dev/null; then
    _PC_PKG_HAVE="$(ls "$(cross_cache_src_dir)/packages/"*.ipk "$(cross_cache_dir)/packages/"*.ipk 2>/dev/null | wc -l)"
    _PC_PKG_NEED="$(echo "$PACKAGESPY3" | wc -w)"
    _PC_IPK_HAVE="$(ls "$(cross_cache_dir)"/*.ipk "$(cross_cache_src_dir)"/*.ipk 2>/dev/null | wc -l)"
    if [ "$_PC_PKG_HAVE" -lt "$_PC_PKG_NEED" ] || [ "$_PC_IPK_HAVE" = "0" ]; then echo "[CROSS] Cache incomplete (packages $_PC_PKG_HAVE/$_PC_PKG_NEED, .ipk $_PC_IPK_HAVE) - preloading Packages + Plugins first (online)..."; cross_preload_cache; else echo "[CROSS] Cache complete (packages $_PC_PKG_HAVE/$_PC_PKG_NEED) - no preload needed"; fi
  fi
  # V33: install system packages FIRST (cached or feed) - Plugins + All both come through here. Files Only does NOT call this fn.
  cross_install_cached_packages
  line; info "Cross-Image Plugins SMART: $CROSS_SRC_IMAGE -> $IMAGE (Python $PY_MM) - incompatible = DOWNLOAD, compatible = COPY"
  # --- Classify ---
  _SRC_LIST="$CROSS_SRC_PLUGINS/plugins_extensions.txt"
  _PLUGS=""; if [ -f "$_SRC_LIST" ]; then _PLUGS="$(cat "$_SRC_LIST")"; elif [ -f "$CROSS_SRC_PLUGINS/plugins.tar.gz" ]; then _PLUGS="$(tar -tzf "$CROSS_SRC_PLUGINS/plugins.tar.gz" 2>/dev/null | cut -d/ -f2 | sort -u)"; fi
  [ -z "$(echo "$_PLUGS" | tr -d ' \n')" ] && { echo "[CROSS] No plugins found in source"; return 1; }
  _COPY=""; _DOWNLOAD=""; _SYS=""
  for _PL in $_PLUGS; do
    case "$_PL" in *SystemPlugins*|*systemplugins*) _SYS="$_SYS $_PL"; _DOWNLOAD="$_DOWNLOAD $_PL"; continue;; esac
    if cross_plugin_needs_download "$_PL" "$CROSS_SRC_PLUGINS"; then _DOWNLOAD="$_DOWNLOAD $_PL"; else _COPY="$_COPY $_PL"; fi
  done
  echo "  [SMART] COPY (safe, pure-py):$(echo "$_COPY" | wc -w) -> $_COPY"
  echo "  [SMART] DOWNLOAD (feed/installer):$(echo "$_DOWNLOAD" | wc -w) -> $_DOWNLOAD"
  if [ -n "$_SYS" ]; then echo "  [SMART] SystemPlugins (feed only, never copied): $_SYS"; fi
  if ! check_net 2>/dev/null && ! offline_is_on 2>/dev/null; then
    echo "[SMART-WARN] No net - downloads impossible. COPY set will be restored, DOWNLOAD set will be SKIPPED (not copied broken)."
    echo "  Re-run with net to download the rest."
  fi
  # --- Phase 1: COPY set via SAME normal restore logic, on a FILTERED temp backup ---
  _FILT="/tmp/cross_filtered_$$"; rm -rf "$_FILT"; mkdir -p "$_FILT"
  cp -a "$CROSS_SRC_PLUGINS/." "$_FILT/" 2>/dev/null
  if [ -n "$_DOWNLOAD" ] && [ -f "$_FILT/plugins.tar.gz" ]; then
    mkdir -p /tmp/cross_filt_$$ && tar -xzf "$_FILT/plugins.tar.gz" -C /tmp/cross_filt_$$ 2>/dev/null
    for _DP in $_DOWNLOAD; do rm -rf "/tmp/cross_filt_$$/$_DP" "/tmp/cross_filt_$$"/*/$_DP 2>/dev/null; find /tmp/cross_filt_$$ -maxdepth 3 -type d -name "$_DP" -exec rm -rf {} + 2>/dev/null; done
    (cd /tmp/cross_filt_$$ && tar -czf "$_FILT/plugins.tar.gz" . 2>/dev/null); rm -rf /tmp/cross_filt_$$
  fi
  if [ -f "$_FILT/plugins_opkg.txt" ]; then
    : > "$_FILT/plugins_opkg.filtered"
    while read -r _OLINE; do _OPKG="$(echo "$_OLINE" | awk '{print $1}')"; _SKIP=0
      for _DP in $_DOWNLOAD; do case "$(echo "$_OPKG" | tr 'A-Z' 'a-z')" in *"$(echo "$_DP" | tr 'A-Z' 'a-z')"*) _SKIP=1;; esac; done
      [ "$_SKIP" = "0" ] && echo "$_OLINE" >> "$_FILT/plugins_opkg.filtered"
    done < "$_FILT/plugins_opkg.txt"
    mv "$_FILT/plugins_opkg.filtered" "$_FILT/plugins_opkg.txt" 2>/dev/null
    : > "$_FILT/plugins_extensions.txt"; for _CP in $_COPY; do echo "$_CP" >> "$_FILT/plugins_extensions.txt"; done
  fi
  _PRC=0
  if [ -n "$_COPY" ]; then
    cross_image_stop_enigma
    CROSS_PLUGINS_OVERRIDE="$_FILT"; PLUGINS_BKDIR="$_FILT"
    FULL_AUTO=1; RESTORE_BATCH=1; restore_plugins_with_extras; _PRC=$?
    FULL_AUTO=0; RESTORE_BATCH=0; CROSS_PLUGINS_OVERRIDE=""; PLUGINS_BKDIR="$(get_plugins_backup_dir)"
    echo "[CROSS-SMART] COPY phase done: rc=$_PRC"
  else echo "[CROSS-SMART] COPY phase: nothing safe to copy - all plugins go to DOWNLOAD"; fi
  # --- Phase 2: DOWNLOAD set ---
  _DL_OK=""; _DL_FAIL=""
  if [ -n "$_DOWNLOAD" ]; then
    if check_net 2>/dev/null || offline_is_on 2>/dev/null; then
      for _DP in $_DOWNLOAD; do
        _DPKG="$(grep -i -m1 "$_DP" "$CROSS_SRC_PLUGINS/plugins_opkg.txt" 2>/dev/null | awk '{print $1}')"
        if cross_download_plugin "$_DP" "$_DPKG"; then _DL_OK="$_DL_OK $_DP"; else _DL_FAIL="$_DL_FAIL $_DP"; fi
      done
    else echo "[SMART-SKIP] DOWNLOAD phase skipped (no net) - skipped plugins were NOT copied, so image stays safe"; _DL_FAIL="$_DOWNLOAD"; fi
  fi
  rm -rf "$_FILT"
  echo "  [SMART-REPORT] COPIED: $(echo "$_COPY" | wc -w) | DOWNLOADED-OK: $(echo "$_DL_OK" | wc -w) -> $_DL_OK | FAILED/SKIPPED: $(echo "$_DL_FAIL" | wc -w) -> $_DL_FAIL"
  cross_image_verify
  # verify_after_force already reinstalled compile-failed COPY plugins from installers; any remaining fail is in _DL_FAIL
  if [ -n "$_DL_FAIL" ]; then echo "[CROSS-SMART] Done with warnings - failed plugins were SKIPPED, not copied broken (rc=0, image safe)"; return 0; fi
  return $_PRC
}

cross_image_restore_plugins_samelogic() {
  [ -d "$CROSS_SRC_PLUGINS" ] || { echo "[CROSS] No Plugins backup in source: $CROSS_SRC_PLUGINS"; return 1; }
  setup_reboot_guard "Cross-Image Plugins"
  cross_image_snapshot
  # --- V24.1: EXACT same logic as normal plugins restore ---
  # Normal chain (restore_plugins_with_extras) =
  #   restore_plugins_only (manifest copy + deps from feed/cache + MD5 + py_compile + reinstall failed)
  #   -> force_restore_plugins_tarball (+skins)
  #   -> verify_after_force_plugins (MD5 + py_compile + reinstall failed)
  #   -> force_reinstall_footonsat (cache first, then download)
  # Cross only changes ONE thing: PLUGINS_BKDIR points to SOURCE backup.
  # Everything else (commands, order, verify, tarball, FootOnSat) is identical.
  # WARNING: this DOES copy .py files from source, like normal restore does.
  # That is what you asked to try. If Python differs, py_compile will catch
  # broken plugins and reinstall them from their installers.
  _SRC_PYNUM=$(echo "$CROSS_SRC_PY" | sed 's/Python//')
  if [ "$_SRC_PYNUM" != "$PY_MM" ]; then
    echo "[CROSS-WARN] Python differs: source $_SRC_PYNUM vs current $PY_MM"
    echo "[CROSS-WARN] Trying EXACT same logic anyway - broken plugins will be reinstalled by verify step"
  else echo "[CROSS] Python MATCH ($PY_MM) - same-logic restore"; fi
  echo "[CROSS] Source plugins dir: $CROSS_SRC_PLUGINS"
  echo "[CROSS] Current image feed will be used for missing deps (same as normal restore)"
  cross_image_stop_enigma
  CROSS_PLUGINS_OVERRIDE="$CROSS_SRC_PLUGINS"
  PLUGINS_BKDIR="$CROSS_SRC_PLUGINS"
  FULL_AUTO=1; RESTORE_BATCH=1
  restore_plugins_with_extras
  _PRC=$?
  FULL_AUTO=0; RESTORE_BATCH=0
  CROSS_PLUGINS_OVERRIDE=""
  PLUGINS_BKDIR="$(get_plugins_backup_dir)"
  echo "[CROSS] Plugins (same-logic) done: rc=$_PRC"
  cross_image_verify
  return $_PRC
}


cross_image_backup() {
  setup_reboot_guard "Cross-Image Backup"
  _XDEST="$UPANEL_ROOT/CrossImage-Backup-$IMAGE-Python$PY_MM"
  line; info "Cross-Image Backup - Portable - $IMAGE / Python $PY_MM"
  echo "  Dest: $_XDEST"
  echo "  Portable = SAFE to restore on another image (system plugins / skin / network / softcam binaries excluded)"
  printf "Create Cross-Image Backup now? (y/n): "; read _xb; case "$_xb" in y|Y) ;; *) echo "Cancelled."; return 0;; esac
  check_hdd_space "Cross-Image Backup" || return 1
  rm -rf "$_XDEST.tmp.$$"; mkdir -p "$_XDEST.tmp.$$/plugins" "$_XDEST.tmp.$$/files"
  _OLD_PLUGINS_BKDIR="${PLUGINS_BKDIR:-}"
  backup_plugins_only; _BRC=$?
  if [ "$_BRC" != "0" ]; then echo "[CROSS-BACKUP] Normal plugins backup failed (rc=$_BRC) - aborting portable copy"; return 1; fi
  _SRC_PLUGINS="$(get_plugins_backup_dir)"
  cp -a "$_SRC_PLUGINS/manifest.csv" "$_SRC_PLUGINS/plugins_opkg.txt" "$_SRC_PLUGINS/plugins_extensions.txt" "$_SRC_PLUGINS/plugins_info.txt" "$_XDEST.tmp.$$/plugins/" 2>/dev/null
  if [ -f "$_SRC_PLUGINS/plugins.tar.gz" ]; then mkdir -p /tmp/cross_plug_$$ && tar -xzf "$_SRC_PLUGINS/plugins.tar.gz" -C /tmp/cross_plug_$$ --exclude='*/SystemPlugins/*' 2>/dev/null && (cd /tmp/cross_plug_$$ && find . -name '*.so' -delete 2>/dev/null; tar -czf "$_XDEST.tmp.$$/plugins/plugins.tar.gz" . 2>/dev/null); rm -rf /tmp/cross_plug_$$; fi
  if [ -f "$_XDEST.tmp.$$/plugins/plugins_opkg.txt" ]; then grep -v -F -f /dev/stdin "$_XDEST.tmp.$$/plugins/plugins_opkg.txt" > "$_XDEST.tmp.$$/plugins/plugins_opkg.tmp" <<_EOF_BL
enigma2-plugin-systemplugins-softwaremanager
enigma2-plugin-systemplugins-videomode
enigma2-plugin-systemplugins-networkbrowser
enigma2-plugin-systemplugins-positionersetup
enigma2-plugin-systemplugins-satfinder
enigma2-plugin-systemplugins-wirelesslan
enigma2-plugin-systemplugins-hdmicec
_EOF_BL
    mv "$_XDEST.tmp.$$/plugins/plugins_opkg.tmp" "$_XDEST.tmp.$$/plugins/plugins_opkg.txt" 2>/dev/null; fi
  _SF="$_XDEST.tmp.$$/files"
  mkdir -p "$_SF/enigma2" "$_SF/tuxbox/config"
  for _f in lamedb lamedb5 bouquets.tv bouquets.radio userbouquet.* blacklist whitelist parental; do cp -a /etc/enigma2/$_f "$_SF/enigma2/" 2>/dev/null; done
  if [ -f /etc/enigma2/settings ]; then grep -E "$CROSS_SETTINGS_ALLOW" /etc/enigma2/settings > "$_SF/enigma2/settings" 2>/dev/null; fi
  for _k in SoftCam.Key oscam.server oscam.user oscam.conf CCcam.cfg newcamd.list mg_cfg; do find /etc/tuxbox /usr/keys /etc/enigma2 -maxdepth 3 -name "$_k" -type f 2>/dev/null | while read -r _kf; do cp -a "$_kf" "$_SF/tuxbox/config/" 2>/dev/null; done; done
  find /etc/enigma2 -iname '*playlist*' -type f 2>/dev/null | while read -r _pf; do cp -a "$_pf" "$_SF/enigma2/" 2>/dev/null; done
  # --- V28 CROSS-CACHE inside the portable backup: pre-cache .ipk for every DOWNLOAD-set plugin ---
  # While we are still ON the source image (online, plugins installed), rebuild .ipk for each plugin that
  # the target will have to DOWNLOAD (.so / SystemPlugin / Python-sensitive). Target then restores from
  # <backup>/cross-cache/ with NO net. Plugins that are pure COPY need no cache.
  mkdir -p "$_XDEST.tmp.$$/cross-cache"
  if [ -f "$_SRC_PLUGINS/plugins_opkg.txt" ]; then
    _CB_SAVED=0
    for _CB_PKG in $(awk '{print $1}' "$_SRC_PLUGINS/plugins_opkg.txt" 2>/dev/null); do
      _CB_PLUG="$(echo "$_CB_PKG" | sed 's/^enigma2-plugin-extensions-//;s/^enigma2-plugin-systemplugins-//;s/^enigma2-plugin-//')"
      # Only cache what SMART would DOWNLOAD on the target: SystemPlugins + .so plugins + known-installer plugins
      _CB_NEED=0
      case "$_CB_PKG" in *systemplugins*) _CB_NEED=1;; esac
      cross_plugin_has_so "$_CB_PLUG" "$_SRC_PLUGINS" 2>/dev/null && _CB_NEED=1
      cross_plugin_known_num "$_CB_PLUG" >/dev/null 2>&1 && _CB_NEED=1
      [ "$_CB_NEED" = "1" ] || continue
      _CB_TMP="/tmp/cross_bk_ipk_$$.ipk"; rm -f "$_CB_TMP"
      if rebuild_ipk_from_installed "$_CB_PKG" "$_CB_TMP" >/dev/null 2>&1 && [ -f "$_CB_TMP" ]; then
        _CB_N="$(cross_cache_name "$_CB_PLUG")"; cp -a "$_CB_TMP" "$_XDEST.tmp.$$/cross-cache/$_CB_N.ipk" 2>/dev/null
        echo "$_CB_N,$_CB_PKG,$(md5sum "$_CB_TMP" 2>/dev/null | cut -d' ' -f1),$(date +%Y-%m-%d)" >> "$_XDEST.tmp.$$/cross-cache/manifest.csv" 2>/dev/null
        _CB_SAVED=$((_CB_SAVED+1))
      fi; rm -f "$_CB_TMP"
    done
    # Also copy any already-cached global .ipk (from previous SMART restores) into the portable backup
    if [ -d "$(cross_cache_dir)" ]; then cp -a "$(cross_cache_dir)"/*.ipk "$_XDEST.tmp.$$/cross-cache/" 2>/dev/null; cp -a "$(cross_cache_dir)/manifest.csv" "$_XDEST.tmp.$$/cross-cache/manifest.csv.global" 2>/dev/null; fi
    echo "  [CROSS-CACHE] Portable cache in backup: $_CB_SAVED .ipk rebuilt + $(ls "$_XDEST.tmp.$$/cross-cache/"*.ipk 2>/dev/null | wc -l) total .ipk"
  fi
  # --- V29: carry the Cross Setup-Cache (per-plugin installers) inside the portable backup ---
  # NOTE: we deliberately do NOT copy the source image's Setup-Cache as-is (label collision: myinstaller.sh
  # belongs to many plugins). Only the per-plugin Cross Setup-Cache (saved after verified downloads) travels.
  mkdir -p "$_XDEST.tmp.$$/cross-cache/setup-installers"
  if [ -d "$(cross_cache_dir)/setup-installers" ]; then cp -a "$(cross_cache_dir)"/setup-installers/*.sh "$_XDEST.tmp.$$/cross-cache/setup-installers/" 2>/dev/null; cp -a "$(cross_cache_dir)"/setup-installers/*.sha256 "$_XDEST.tmp.$$/cross-cache/setup-installers/" 2>/dev/null; echo "  [CROSS-SETUP-CACHE] Portable setup-installers in backup: $(ls "$_XDEST.tmp.$$/cross-cache/setup-installers/"*.sh 2>/dev/null | wc -l)"; fi
  { echo "CrossImage-Backup - $(date)"; echo "Source Image: $IMAGE"; echo "Source Box: $BOX"; echo "Source Python: $PYTHON_V (Python$PY_MM)"; echo "Portable: YES - restore on any image via Cross-Image Restore"; } > "$_XDEST.tmp.$$/cross_info.txt"
  rm -rf "$_XDEST"; mv "$_XDEST.tmp.$$" "$_XDEST"
  PLUGINS_BKDIR="$_OLD_PLUGINS_BKDIR"
  ok "Cross-Image Backup Done: $_XDEST"
  echo "  Files (safe-only): $(find "$_XDEST/files" -type f 2>/dev/null | wc -l) files"
  echo "  Next: on the OTHER image -> Main Menu -> Cross-Image Restore -> Pick Source -> pick this folder"
  log_msg "Cross-Image Backup done: $_XDEST"
}
# ===== Smart Restore - V 3.5 : Cross-Image Restore + Smart Restore MERGED =====
# ONE menu instead of main-menu 7) Smart Restore + 9) Cross-Image Restore.
# The MENU merged - the restore LOGIC did not change: FULL mode calls the
# exact same functions Smart Restore always called (personal_full_restore,
# restore_files_setup, restore_plugins_with_extras); SAFE mode calls the
# exact same Cross functions (cross_image_restore_files/plugins).
# MODE detection (smart_restore_detect_mode), conservative by design:
#   FULL only if ALL hold: source folder is NOT a CrossImage-Backup,
#   source layout is NOT flat/portable, source image name matches the
#   current image (date prefix stripped, substring either way, like the
#   old "same image" note), AND source Python == current Python.
#   ANY doubt -> SAFE. Portable CrossImage-Backup folders are ALWAYS SAFE.
# OVERRIDE is SAFE-only: S) forces SAFE on a same-image source. There is NO
# way to force FULL on a cross-image source - that is the guarantee that
# kept images safe, and the merge does not break it.
# FULL-mode note: like Smart Restore before it, FULL restores from the
# same-image backup (latest) - the picked source confirms the MODE.
smart_restore_detect_mode() {
  SMART_MODE="SAFE"; SMART_MODE_WHY=""
  if [ -n "$SMART_FORCE_SAFE" ]; then SMART_MODE_WHY="forced SAFE (you pressed S)"; return 0; fi
  _SRB=$(basename "$CROSS_SRC_ROOT")
  case "$_SRB" in CrossImage-Backup*|*CrossImage*|*cross-image*) SMART_MODE_WHY="portable CrossImage-Backup - always SAFE"; return 0 ;; esac
  if [ "$CROSS_SRC_PY" = "__FLAT__" ]; then SMART_MODE_WHY="flat/portable backup layout - always SAFE"; return 0; fi
  if [ -z "$CROSS_SRC_IMAGE" ]; then SMART_MODE_WHY="source image unknown - SAFE"; return 0; fi
  # Strip date prefix AND suffix (backup folders are <date>-<image> or <image>-<date>)
  _SRC_NORM=$(echo "$CROSS_SRC_IMAGE" | sed -E -e 's/^[0-9]{6,8}[-_ ]*//' -e 's/[-_ ]*[0-9]{6,8}$//' | tr 'A-Z' 'a-z' | tr -d ' _-')
  _CUR_NORM=$(echo "$IMAGE" | tr 'A-Z' 'a-z' | tr -d ' _-')
  _SRC_PYNUM=""; case "$CROSS_SRC_PY" in Python*) _SRC_PYNUM=$(echo "$CROSS_SRC_PY" | sed 's/Python//') ;; esac
  # V3.8 RULE: image = NAME ONLY, and the name must be EXACTLY the same
  # (strict equality - NO "contains": OpenATV vs OpenPLi is a DIFFERENT image,
  # even with the same Python, and one name inside another never counts).
  # Version digits + dots are stripped (OpenATV 8.0 vs 8.1 = same name).
  # PYTHON is the hard rule: same name + same Python -> FULL, anything else -> SAFE.
  _SRC_NAMEONLY=$(echo "$_SRC_NORM" | tr -d '0-9.')
  _CUR_NAMEONLY=$(echo "$_CUR_NORM" | tr -d '0-9.')
  _NAME_MATCH=0
  if [ -n "$_SRC_NAMEONLY" ] && [ "$_SRC_NAMEONLY" = "$_CUR_NAMEONLY" ]; then _NAME_MATCH=1; fi
  if [ "$_NAME_MATCH" = "1" ] && [ -n "$_SRC_PYNUM" ] && [ "$_SRC_PYNUM" = "$PY_MM" ]; then
    SMART_MODE="FULL"; SMART_MODE_WHY="same image name ($CROSS_SRC_IMAGE) + same Python ($PY_MM) - image version ignored"; return 0
  fi
  SMART_MODE_WHY="source $CROSS_SRC_IMAGE ($CROSS_SRC_PY) != current $IMAGE (Python $PY_MM) - SAFE"
}
# V4.25: YES confirmations now accept YES / Yes / yes / y / Y (spaces ignored) everywhere - Factory Reset, Smart Restore, Switch Slot, Restore-to-Slot, Delete Backup - via one is_yes() helper; WIPE/FLASH accept lowercase too
# V4.24: Custom Restore menu cleaned - choices are now plain (Restore Plugins / Restore Files / All), no explanatory text beside them, logic unchanged
# V4.23: Multiboot Manager gains 10) Wipe Slot - erases the image on a slot completely (subdir = delete subdir only, partition = mkfs ext4), running slot always refused, STARTUP kept so slot stays Empty, WIPE twice to confirm
# V4.22: Smart Restore = LATEST BACKUP ONLY
smart_restore_pick_latest_backup() {
  _SR_CANDS=""
  for _d in "$UPANEL_ROOT"-Backup-* "$BACKUP_ROOT"/U-Panel-Backup-* "$BACKUP_ROOT"/U-Panel-Plugins-Backup-* "$BACKUP_ROOT"/CrossImage-Backup-*; do
    [ -d "$_d" ] || continue
    case "$_d" in *.tmp.*) continue ;; esac
    _SR_CANDS="$_SR_CANDS $_d"
  done
  _SR_ROOTS=""
  for _c in $_SR_CANDS; do
    _R="$_c"
    case "$_c" in */Python*) _R=$(echo "$_c" | sed 's|/Python[^/]*.*||') ;; esac
    case " $_SR_ROOTS " in *" $_R "*) ;; *) _SR_ROOTS="$_SR_ROOTS $_R" ;; esac
  done
  [ -z "$(echo "$_SR_ROOTS" | tr -d ' ')" ] && { echo "[SMART] No backups found - take a Backup first (Main Menu 5)"; return 1; }
  _SR_LATEST=$(ls -dt $_SR_ROOTS 2>/dev/null | head -1)
  [ -z "$_SR_LATEST" ] || [ ! -d "$_SR_LATEST" ] && { echo "[SMART] No backups found"; return 1; }
  CROSS_SRC_ROOT="$_SR_LATEST"
  CROSS_SRC_IMAGE=$(basename "$_SR_LATEST" | sed 's/^U-Panel-Backup-//;s/^U-Panel-Plugins-Backup-//;s/_SLOT[0-9]*$//')
  CROSS_SRC_PY=""
  for _pd in "$_SR_LATEST"/Python"$PY_MM" "$_SR_LATEST"/Python*; do [ -d "$_pd" ] && { CROSS_SRC_PY=$(basename "$_pd"); break; }; done
  if [ -z "$CROSS_SRC_PY" ]; then if [ -d "$_SR_LATEST/plugins" ] || [ -d "$_SR_LATEST/files" ]; then CROSS_SRC_PY="__FLAT__"; else echo "[SMART] No Python* folder inside $_SR_LATEST"; return 1; fi; fi
  if [ "$CROSS_SRC_PY" = "__FLAT__" ]; then _SR_BASE="$_SR_LATEST"; else _SR_BASE="$_SR_LATEST/$CROSS_SRC_PY"; fi
  if [ -d "$_SR_BASE/plugins" ]; then CROSS_SRC_PLUGINS="$_SR_BASE/plugins";
  elif [ -d "$_SR_BASE" ] && [ -f "$_SR_BASE/plugins_opkg.txt" ]; then CROSS_SRC_PLUGINS="$_SR_BASE"; else CROSS_SRC_PLUGINS="$_SR_BASE/plugins"; fi
  if [ -d "$_SR_BASE/files" ]; then CROSS_SRC_FILES="$_SR_BASE/files";
  elif [ -d "$_SR_BASE" ] && [ -f "$_SR_BASE/files_manifest.csv" ]; then CROSS_SRC_FILES="$_SR_BASE"; else CROSS_SRC_FILES="$_SR_BASE/files"; fi
  echo "[SMART] Latest backup: $(basename "$_SR_LATEST") / $CROSS_SRC_PY"
  return 0
}
smart_restore_menu() {
  SMART_FORCE_SAFE=""
  SMART_PRELOAD_DONE_FOR=""
  smart_restore_pick_latest_backup || { printf "Press ENTER... "; read _b; return 0; }
  smart_restore_detect_mode
  echo "MODE: $SMART_MODE - $SMART_MODE_WHY"
  while true; do
    show_banner; menu_head_box_c "SMART RESTORE"
    menu_head "Smart Restore - LATEST BACKUP ONLY - mode auto-detected: SAME NAME + SAME PYTHON = FULL, else SAFE"
    menu_head "BootLogo: in All only, for the CURRENT image (FULL = same image, SAFE = new image)"
    menu_head "Preload is AUTOMATIC after picking a source (SAFE mode, net ON) - each flow uses its OWN cache"
    menu_item "1) Packages and Plugins"
    menu_item "2) Files Only"
    menu_item "3) All - Packages + Plugins + Files + BootLogo"
    menu_item "M) Main Menu"
    menu_bot
    if [ -n "$CROSS_SRC_ROOT" ]; then
      smart_restore_detect_mode
      echo "  Source: $CROSS_SRC_IMAGE / $CROSS_SRC_PY"; echo "  Files: $CROSS_SRC_FILES"; echo "  Plugins: $CROSS_SRC_PLUGINS"
      echo "  MODE: $SMART_MODE - $SMART_MODE_WHY"
    else echo "  Source: (none)"; fi
    printf "Your choice: "; read _cx || return 0
    case "$_cx" in
      2)          smart_restore_detect_mode
         if [ "$SMART_MODE" = "FULL" ]; then
           echo "FULL Files: full files restore from the same-image backup (latest), like Smart Restore."
           printf "Type YES / y to continue: "; read _CF; is_yes "$_CF" || { echo "Cancelled."; continue; }
           FULL_AUTO=1; restore_files_setup; _RC=$?; verify_files_restore; FULL_AUTO=0
           echo "Smart Restore Files done (rc=$_RC)"
           printf "Press ENTER... "; read _b
         else
           echo "SAFE Files: channels + oscam CONFIG + keys + timers + allowlist settings. NEVER: skin/binary/softcam/*.emu/smb.conf/full settings."
           printf "Type YES / y to continue: "; read _CF; is_yes "$_CF" || { echo "Cancelled."; continue; }
           CROSS_ENIGMA_STOPPED=0; cross_image_restore_files; ask_retrieve_enigma; printf "Press ENTER... "; read _b
         fi ;;
      1)          smart_restore_detect_mode
         if [ "$SMART_MODE" = "FULL" ]; then
           echo "FULL Packages + Plugins: system packages first, then full plugins restore (same name + same Python)."
           printf "Type YES / y to continue: "; read _CF; is_yes "$_CF" || { echo "Cancelled."; continue; }
           FULL_AUTO=1; RESTORE_BATCH=1; install_packages; restore_plugins_with_extras; _RC=$?; FULL_AUTO=0; RESTORE_BATCH=0
           echo "Smart Restore Packages + Plugins done (rc=$_RC)"
           ask_retrieve_enigma; printf "Press ENTER... "; read _b
         else
           echo "SAFE Packages + Plugins: Cross packages from Cross cache first, then plugins (COPY compatible / DOWNLOAD incompatible). SystemPlugins never copied."
           printf "Type YES / y to continue: "; read _CF; is_yes "$_CF" || { echo "Cancelled."; continue; }
           CROSS_ENIGMA_STOPPED=0; cross_image_restore_plugins; ask_retrieve_enigma; printf "Press ENTER... "; read _b
         fi ;;
      3)          smart_restore_detect_mode
         if [ "$SMART_MODE" = "FULL" ]; then
           echo "FULL All: Smart Restore flow - Packages -> Plugins + Files -> BootLogo Auto."
           printf "Type YES / y to continue: "; read _CF; is_yes "$_CF" || { echo "Cancelled."; continue; }
           personal_full_restore
         else
           echo "SAFE All: Plugins (feed/cache/installer) THEN Files (safe only) THEN BootLogo Auto for CURRENT image. Enigma stopped once."
           printf "Type YES / y to continue: "; read _CF; is_yes "$_CF" || { echo "Cancelled."; continue; }
           CROSS_ENIGMA_STOPPED=0; RESTORE_BATCH=1
           cross_image_restore_plugins; _PRC=$?
           cross_image_restore_files; _FRC=$?
           RESTORE_BATCH=0
           echo "Smart Restore All done: Plugins rc=$_PRC Files rc=$_FRC"
           if [ "$_PRC" = "0" ] && [ "$_FRC" = "0" ]; then line; info "SAFE All - BootLogo Auto for CURRENT image ($IMAGE)"; install_bootlogo_auto; else echo "BootLogo skipped (a restore step failed)"; fi
           ask_retrieve_enigma; printf "Press ENTER... "; read _b
         fi ;;
      m|M) return 0 ;;
      *) wrong_choice ;;
    esac
  done
}
# Back-compat: anything that called the old Cross menu still works
cross_image_menu() { smart_restore_menu; }


# V34: one-time move of legacy top-level files into U-Panel/ (safe: mv only, nothing deleted)
UPANEL_ROOT="$BACKUP_ROOT/U-Panel"; mkdir -p "$UPANEL_ROOT" 2>/dev/null; upanel_migrate_to_folder; BKDIR="$(get_files_backup_dir)"; LOG="$UPANEL_ROOT/Unversal_AllScript_V2-log.txt"; FAV_FILE="$UPANEL_ROOT-Favourite-$BK.conf"
# V4.14: headless auto-refresh (called by cron) - runs BEFORE lock check / main menu
