web_image_links_list() {
  rm -f /tmp/novaler_links.txt; touch /tmp/novaler_links.txt
  if is_novaler; then
    _SLUG=$(novaler_image_slug); [ -z "$_SLUG" ] && { echo "[FAIL] Could not detect your Novaler model." >&2; return 1; }
    extract_zips_from_page "https://images.mynonpublic.com/openatv/index.php?v=8.1&open=$_SLUG" "https://images.mynonpublic.com/openatv/8.1/" "OpenATV 8.1" >> /tmp/novaler_links.txt
    extract_zips_from_page "https://images.mynonpublic.com/openatv/index.php?v=8.0&open=$_SLUG" "https://images.mynonpublic.com/openatv/8.0/" "OpenATV 8.0" >> /tmp/novaler_links.txt
    extract_zips_from_page "https://image.egami-image.com/11.0/index.php?open=$_SLUG" "https://image.egami-image.com/11.0/" "Egami 11.0" >> /tmp/novaler_links.txt
    novaler_page_links >> /tmp/novaler_links.txt
    openbh_links >> /tmp/novaler_links.txt
    extract_zips_from_page "https://www.pur-e2.club/OU/images/index.php?dir=7.6/$_SLUG/" "https://www.pur-e2.club/OU/images/" "PurE2 7.6" >> /tmp/novaler_links.txt
    extract_zips_from_page "https://www.pur-e2.club/OU/images/index.php?dir=7.6/$_SLUG" "https://www.pur-e2.club/OU/images/" "PurE2 7.6" >> /tmp/novaler_links.txt
  else
    _DM=$(device_image_exact_model); _DBRAND="${_DM%%:*}"; _DMODEL="${_DM##*:}"
    if [ "$_DMODEL" = "AMBIG" ] || [ -z "$_DMODEL" ]; then _DMODEL=$(device_model_saved "$_DBRAND"); fi
    if [ "$_DMODEL" = "AMBIG" ] || [ -z "$_DMODEL" ] || [ "$_DBRAND" = "unknown" ]; then
      _UM=$(user_links_match_brand)
      if [ -n "$_UM" ]; then
        user_links_entries | awk -F'|' -v b="$_UM" '$1==b' | while IFS='|' read -r _B _S _L _T _PG _BS; do extract_image_zips_generic "$_PG" "$_BS" "$_T" "$_S" >> /tmp/novaler_links.txt; done
      else echo "[FAIL] Could not detect your box brand." >&2; return 1; fi
    else
      _P=$(device_image_source_params "$_DBRAND:$_DMODEL"); [ -z "$_P" ] && { echo "[FAIL] No image sources known for $_DBRAND/$_DMODEL." >&2; return 1; }
      _ATV=$(echo "$_P" | cut -d'|' -f1); _EGAMI=$(echo "$_P" | cut -d'|' -f2); _PLI=$(echo "$_P" | cut -d'|' -f3)
      _VIX=$(echo "$_P" | cut -d'|' -f4); _BH=$(echo "$_P" | cut -d'|' -f5); _PURE2=$(echo "$_P" | cut -d'|' -f6)
      _VIXFILE=$(echo "$_P" | cut -d'|' -f7)
      extract_zips_from_page "https://images.mynonpublic.com/openatv/index.php?v=8.1&open=$_ATV" "https://images.mynonpublic.com/openatv/8.1/" "OpenATV 8.1" >> /tmp/novaler_links.txt
      extract_zips_from_page "https://images.mynonpublic.com/openatv/index.php?v=8.0&open=$_ATV" "https://images.mynonpublic.com/openatv/8.0/" "OpenATV 8.0" >> /tmp/novaler_links.txt
      extract_zips_from_page "https://image.egami-image.com/11.0/index.php?open=$_EGAMI" "https://image.egami-image.com/11.0/" "Egami 11.0" >> /tmp/novaler_links.txt
      openpli_links "$_PLI" "$_ATV" >> /tmp/novaler_links.txt
      openvix_links "$_VIX" "$_VIXFILE" >> /tmp/novaler_links.txt
      openbh_brand_links "$_BH" "$_ATV" >> /tmp/novaler_links.txt
      extract_zips_from_page "https://www.pur-e2.club/OU/images/index.php?dir=7.6/$_PURE2/" "https://www.pur-e2.club/OU/images/" "PurE2 7.6" >> /tmp/novaler_links.txt
      extract_zips_from_page "https://www.pur-e2.club/OU/images/index.php?dir=7.6/$_PURE2" "https://www.pur-e2.club/OU/images/" "PurE2 7.6" >> /tmp/novaler_links.txt
      openspa_links "$_DBRAND" "$_ATV" >> /tmp/novaler_links.txt
      openhdf_links "$_DBRAND" "$_ATV" >> /tmp/novaler_links.txt
    fi
  fi
  grep -E '^[^|]+\|https?://[^|]*(_multi|_usb|_mmc|_multiboot)\.zip$' /tmp/novaler_links.txt | grep -vi 'recovery' > /tmp/novaler_links_clean.txt 2>/dev/null || : > /tmp/novaler_links_clean.txt
  sort -u /tmp/novaler_links_clean.txt > /tmp/novaler_links_dedup.txt
  rm -f /tmp/novaler_links.txt; touch /tmp/novaler_links.txt
  cut -d'|' -f1 /tmp/novaler_links_dedup.txt | sort -u > /tmp/novaler_labels.txt
  while IFS= read -r _LBL; do
    [ -z "$_LBL" ] && continue
    grep -F "$_LBL|" /tmp/novaler_links_dedup.txt | sort -t'|' -k2 | while IFS='|' read -r _L _U; do _D=$(echo "$_U" | grep -oE '[0-9]{8}' | sort -n | tail -1); [ -z "$_D" ] && _D="00000000"; echo "$_D|$_L|$_U"; done | sort -r | head -1 | cut -d'|' -f2- >> /tmp/novaler_links.txt
  done < /tmp/novaler_labels.txt
  sort -u /tmp/novaler_links.txt -o /tmp/novaler_links.txt
  awk -F'|' '!seen[$2]++' /tmp/novaler_links.txt > /tmp/novaler_links2.txt && mv /tmp/novaler_links2.txt /tmp/novaler_links.txt
  cat /tmp/novaler_links.txt
}
