# V4.15: autorefresh auto-installs on the receiver - runs BEFORE lock check / main menu
epg_cron_autoinstall
# V5.90: webserver auto-start on port 8080 - no prompt. Runs here (after --web-* dispatch) so web jobs never restart their own server.
web_ensure_running
while true; do
  show_banner
# V4.0: lock + integrity check runs BEFORE the main menu
lock_startup_check
  menu_head_box_c "MAIN MENU"
  menu_section "INSTALLATION" "$C_TITLE_INSTALL"
  menu_item "1) Setup your Enigma"
  menu_item "2) Ur Favourite Setup"
  menu_item "3) Plugins Manual"
  menu_item "4) Packages Only"
  menu_sep
  menu_section "BACKUP AND RESTORE" "$C_TITLE_BACKUP"
  menu_item "5) Backup Ur Data"
  menu_item "6) Backup Ur Files"
  menu_item "7) Smart Restore"
  menu_item "8) Custom Restore"
  menu_sep
  menu_section "ENIGMA UI" "$C_TITLE_TOOLS"
  menu_item "9) U-Panel Channel Editor"
  menu_item "10) U-Panel Streaming"
  menu_item "11) U-Panel Picons"
  menu_item "12) U-Panel EPG"
  menu_item "13) Skin Changer"
  menu_sep
  menu_section "TOOLS & MANAGEMENT" "$C_TITLE_TOOLS"
  menu_item "14) Multiboot Manager"
  menu_item "15) Image Update"
  menu_item "16) Download Image"
  menu_item "17) Backup Image"
  menu_item "18) Backup Manager"
  menu_item "19) Enigma Tools"
  menu_item "20) U-Panel Setting"; menu_item "21) Image Build with Essentials"
  menu_item "e) End"
  menu_bot
  printf "Your choice: "; read CHOICE
  case "$CHOICE" in
    1) personal_setup ;;
    2) favourite_setup ;;
    3) plugins_manual ;;
    4) packages_only_menu ;;
    5) backup_plugins_then_files; printf "Press ENTER to return... "; read _back ;;
    6) backup_files; printf "Press ENTER to return... "; read _back ;;
    7) smart_restore_menu ;;
    8) selective_restore_menu ;;
    9) channel_editor_menu ;;
    10) streaming_menu ;;
    11) download_picons_menu ;;
    12) emoati_epg_menu ;;
    13) skin_changer_menu ;;
    14) boot_slot_manager ;;
    15) image_update_menu ;;
    16) download_image_menu ;;
    17) backup_full_image; printf "Press ENTER to return... "; read _back ;;
    18) show_backup_manager ;;
    19) show_tools_menu ;;
    20) enigma_setting_menu ;;
    21) image_build_essentials ;;
    e|E) ask_reboot_optional ;;
    *) wrong_choice ;;
  esac
done
